import{c as d}from"./language-LB0IZvVG.js";const i=[{id:"2026-09-29-class-gear-sets",date:"2026-09-29",time:"07:01",title:"แต่ละอาชีพมีชุดอุปกรณ์ของตัวเอง",lines:["เปลี่ยนอาชีพแล้ว ของที่สวมอยู่จะค้างไว้กับอาชีพเดิม อาชีพใหม่เริ่มช่องว่างให้หาของมาใส่ สลับกลับมาเมื่อไรก็สวมชุดเดิมให้ทันที","ก้าวแรกจาก Novice ไปอาชีพแรกยังพาของติดตัวไปด้วยเหมือนเดิม","ของที่ค้างกับอาชีพอื่นยังอยู่ในกระเป๋า มีป้ายชื่ออาชีพที่มุมช่อง ขาย ทิ้ง เทรด ฝากคลัง ตั้งขาย และหลอมไม่ได้ · ดับเบิลคลิกเพื่อย้ายมาสวมกับอาชีพปัจจุบัน","ถอดแถบบันทึกชุด (Loadout) 5 ช่องในหน้าต่างอุปกรณ์ออกแล้ว"]},{id:"2026-09-29-aurelia-npc-spread",date:"2026-09-29",time:"06:59",title:"Aurelia: ย้าย NPC 5 ตัวไปประจำลานต่างๆ ในเมือง",lines:["นายหน้าตลาด ย้ายจากบันไดวิหารไปลานตลาด Macellum ข้างศาลาทรงกลม (ตะวันออกเฉียงเหนือ)","เจ้าหน้าที่คลังเก็บของ ย้ายไปบันไดวิหาร ที่เดิมของนายหน้าตลาด","อาจารย์รีเซ็ต (Stat Master) ย้ายไปลานหน้าโรงละคร ฝั่งตะวันตกของลาน Forum","ช่างตีบวก ย้ายไปลานบ่อน้ำทางใต้ฝั่งตะวันออก","ช่างหลอมรวม ย้ายขึ้นไปลานน้ำพุหัวสิงห์ ทางเหนือของลาน Forum","คลิกที่ NPC จากที่ไกลตัวละครจะเดินไปหาเองเหมือนเดิม · พ่อค้าอยู่ที่เดิม"]},{id:"2026-09-29-party-guild-chat-unread",date:"2026-09-29",time:"06:56",title:"แชทปาร์ตี้และกิลมีตัวเลขแจ้งเตือนเหมือนกระซิบ",lines:["มีคนพิมพ์ในปาร์ตี้หรือกิลตอนที่เปิดแท็บอื่นอยู่ แท็บ ปาร์ตี้ / กิล จะขึ้นเลขสีแดงบอกจำนวนข้อความที่ยังไม่ได้อ่าน เหมือนแท็บกระซิบ","พับแชทไว้ ปุ่มแชทจะนับรวมข้อความกระซิบ ปาร์ตี้ และกิลที่ยังไม่อ่าน","เปิดแท็บนั้นหรือแท็บ ทั้งหมด แล้วเลขหายไปเอง · ข้อความที่ตัวเองพิมพ์ไม่นับ · ปาร์ตี้กับกิลไม่มีเสียงเตือนและไม่มีป๊อปอัปเหมือนกระซิบ จะได้ไม่รบกวนตอนตี้คุยกันเยอะ"]},{id:"2026-09-29-monster-damage-accuracy",date:"2026-09-29",time:"06:41",title:"มอนตีเบาลง ไม่โดนทีเดียวตายอีก แต่หลบยากขึ้น",lines:["ดาเมจมอนสเตอร์ลดลงตามเลเวล: Lv.100 ขึ้นไปตีเหลือราวครึ่งหนึ่งของเดิม Lv.200 ขึ้นไปเหลือราว 35–40% ส่วนแมพต้นๆ เบาลง 20–30% · มอนตีธรรมดาครั้งละไม่เกินราว 1 ใน 4 ของหลอด HP แม้สาย VIT น้อย ดื่มยาทันแล้ว สกิลธาตุและ Elite ก็ไม่ทีเดียวตาย","บอส Crowned ตีแรง ×2 ของมอนสายพันธุ์เดียวกัน (เดิม ×2.5) · สกิลวงใหญ่ของบอสยังแรงเท่าเดิม ต้องเดินออกจากวง","มอนตีแม่นขึ้น: FLEE หลบการโจมตีมอนได้สูงสุด 50% (เดิม 95%) และหลบบอสได้สูงสุด 40% (เดิม 87%) · สาย AGI ราว 40 ขึ้นไปจะโดนตีประมาณครึ่งหนึ่ง สาย AGI น้อยโดนเกือบทุกครั้งเหมือนเดิม","มีผลกับมอนทุกตัวทันทีหลังอัปเดต · PVP ยังคิดหลบแบบเดิม"]},{id:"2026-09-29-keybinds-gamepad",date:"2026-09-29",time:"06:33",title:"ตั้งค่าปุ่มลัดเองได้ + รองรับจอยเกม",lines:['หน้าตั้งค่ามีหัวข้อใหม่ "ตั้งค่าปุ่มลัด (คีย์บอร์ด / จอยเกม)" เปลี่ยนปุ่มได้ทุกอย่าง ทั้งเดิน โจมตี Auto นั่ง ดื่มยา ช่องลัด 1–9 เปิดหน้าต่างต่างๆ และมินิแมพ · กดช่องแล้วกดปุ่มใหม่ Backspace เพื่อล้าง ถ้าเลือกปุ่มที่ใช้อยู่แล้วจะสลับกันให้',"เสียบหรือจับคู่จอย (Xbox, PlayStation, จอยบลูทูธ) แล้วเล่นได้เลย สติ๊กซ้ายใช้เดิน ปุ่มเริ่มต้น: A โจมตี/คุย/เก็บของ · X Y B LB RB ช่องลัด 1–5 · LT ดื่มยา · RT Auto · L3 นั่ง · Select กระเป๋า · R3 แผนที่ · Start ปิดหน้าต่าง/ตั้งค่า","ปุ่มคีย์บอร์ดเริ่มต้นยังเหมือนเดิมทุกปุ่ม · ค่าที่ตั้งเก็บไว้ในเครื่องที่เล่น · Esc กับ Enter สงวนไว้ปิดหน้าต่างและเปิดแชทเหมือนเดิม"]},{id:"2026-09-29-storage-rarity-tiles",date:"2026-09-29",time:"06:29",title:"คลังเก็บของมีกรอบสีตามความหายากแล้ว",lines:["ช่องไอเทมในคลังมีสีตามความหายากเหมือนในกระเป๋า: เขียว ฟ้า ม่วง ทอง ตามระดับของอุปกรณ์","การ์ดเป็นกรอบสีม่วงเหมือนในกระเป๋า · ของธรรมดายังเป็นช่องสีครีมเหมือนเดิม","ดูออกทันทีว่าชิ้นไหนหายาก ไม่ต้องเปิดดูทีละชิ้น"]},{id:"2026-09-29-screen-shake-setting",date:"2026-09-29",time:"06:15",title:"ตั้งค่า: ปิดจอสั่นได้แล้ว",lines:['เพิ่มช่อง "จอสั่นตอนระเบิด / สกิลบอส" ในหน้าตั้งค่า ใต้เอฟเฟกต์สกิล',"เอาติ๊กออกแล้วจอไม่สั่นตอน Big Kaboom ของ Nekobaku ระเบิด และตอนบอสปล่อยสกิลใหญ่ สำหรับคนที่เล่นแล้วเวียนหัว","ค่าเริ่มต้นยังสั่นเหมือนเดิม เอฟเฟกต์อื่นยังแสดงครบ"]},{id:"2026-09-29-bot-long-cooldown-first",date:"2026-09-29",time:"06:05",title:"บอท: ใช้สกิลคูลดาวน์ยาวก่อนเมื่อพร้อม",lines:["ลำดับสกิลของบอทเลือกสกิลที่พร้อมใช้และคูลดาวน์ยาวที่สุดก่อนทุกครั้ง สกิลที่ใช้ได้เร็วเท่าความเร็วโจมตี (เช่น Fizz Flask, Twin Shot) จะใช้แทรกตอนสกิลอื่นยังคูลดาวน์อยู่","แก้ปัญหาบอทใช้แต่ Fizz Flask ทุกจังหวะจน Big Kaboom กับ Tar Flask ไม่เคยได้ออก","สกิลที่คูลดาวน์เท่ากันยังใช้ตามลำดับที่ตั้งไว้ · บัฟยังใช้เมื่อหมดเวลาเหมือนเดิม"]},{id:"2026-09-29-boss-every-channel",date:"2026-09-29",time:"06:02",title:"บอสเกิดครบทุกช่องทุกแมพ",lines:["ทุกแมพล่ามีบอส Crowned ช่องละ 1 ตัว ครบทุกช่องและทุกภูมิภาค (เดิมมีสูงสุด 5 ตัวต่อแมพ กระจายสุ่มตามช่อง)","ล้มแล้วเกิดใหม่ในช่องเดิมหลัง 1 ชั่วโมง ในรังที่สุ่มใหม่","บอสที่ยังไม่ได้เกิดในช่องไหนจะเกิดทันทีหลังอัปเดตนี้"]},{id:"2026-09-29-inspect-equipment-frame",date:"2026-09-29",time:"05:57",title:"หน้าต่างส่องของใช้ดีไซน์เดียวกับหน้าอุปกรณ์",lines:["ส่องของผู้เล่นอื่นแล้วเห็นกรอบเดียวกับหน้าไอเทมที่สวมใส่ ช่องเรียงตำแหน่งเดียวกัน และมีตัวละครตามอาชีพตรงกลาง",'แถวล่างแสดงชื่อและสเตตัสของชิ้นที่เลือก กดช่องหรือปุ่ม "ดูรายละเอียด" เพื่อเปิดการ์ดไอเทม']},{id:"2026-09-29-status-cards",date:"2026-09-29",time:"05:55",title:"หน้าต่างสถานะ: ค่าสถานะและความสามารถโฉมใหม่",lines:["ค่าหลัก (ATK, MATK, HIT, CRITICAL ฯลฯ) เป็นการ์ดขอบทองพร้อมไอคอนใหญ่ คริเวทมีไอคอนของตัวเอง","ค่าพิเศษ (เจาะเวท ดูดเลือด กันแข็ง ความเร็ววิ่ง ฯลฯ) แยกอยู่ใต้เส้นคั่น เป็นการ์ดแถบฟ้าพร้อมไอคอนทุกค่า ไม่เบียดกับค่าหลักอีก"]},{id:"2026-09-29-divine-wings-1-in-100k",date:"2026-09-29",time:"05:50",title:"ปีกทอง Divine Wings ออกง่ายขึ้น 10 เท่า",lines:["โอกาสได้ Divine Wings จาก Mystery Relic Box เพิ่มจาก 1 ใน 1,000,000 กล่อง เป็น 1 ใน 100,000 กล่อง"]},{id:"2026-09-29-remove-spell-total",date:"2026-09-29",time:"05:45",title:"เอาป้าย TOTAL ของสกิลเวทออก",lines:["ป้ายสีเหลือง TOTAL ... · ... HIT ที่ลอยเหนือมอนตอนร่ายเวทถูกเอาออกแล้ว หน้าจอตอนตีมอนจะโล่งขึ้น","ตัวเลขดาเมจแต่ละฮิตยังเด้งขึ้นเหมือนเดิม"]},{id:"2026-09-29-aurelia-town-v2",date:"2026-09-29",time:"05:39",title:"เมือง Aurelia โฉมใหม่: เมืองโรมันมีกำแพงล้อม",lines:["เมืองขยายใหญ่ขึ้น ถนนใหญ่สองสายตัดกันที่ลาน Forum มีน้ำพุรูปปั้นอยู่กลาง ประตูเมืองสี่ทิศพาไปป่าเริ่มต้น (ใต้) ช่องเขาหิมะ (เหนือ) ทะเลทราย (ตะวันออก) และหนองน้ำ (ตะวันตก) เหมือนเดิม","NPC ทั้ง 6 ตัวอยู่ในลาน Forum ใกล้จุดเกิด: พ่อค้า ช่างตีบวก เจ้าหน้าที่คลัง อาจารย์สเตตัส ช่างหลอมรวม และนายหน้าตลาดบนบันไดวิหาร","มีวิหาร Jupiter โรงอาบน้ำ ตลาด Macellum โรงละครกลางแจ้งพร้อมถนนโค้งรอบ ลานบ่อน้ำ และสวนมะกอก","เดินไปหลังอาคาร ต้นไม้ หรือรูปปั้น จะโปร่งให้เห็นตัวละคร","ใครออกเกมค้างไว้ในเมือง จะเริ่มที่จุดเกิดกลางลาน Forum หนึ่งครั้ง"]},{id:"2026-09-29-two-handed-x2",date:"2026-09-29",time:"05:18",title:"อาวุธสองมือได้สเตตัส ×2",lines:["Staff, Quarterstaff, Dagger Pair และ Hammer ได้สเตตัสของอาวุธ ×2 (เดิม ×1.5) รวมออปชันพิเศษด้วย เช่น คริดาเมจ 20% นับเป็น 40% · ค่าสูงสุดของแต่ละออปชันยังเท่าเดิม","ชดเชยมือซ้ายที่ใส่โล่ ออร์บ หรือซองธนูไม่ได้ · อาวุธสองมือยังฝังการ์ดได้ 2 ใบเหมือนเดิม","มีผลกับอาวุธที่มีอยู่แล้วทุกชิ้นทันที ไม่ต้องทำอะไร · Bow ยังเป็นอาวุธมือเดียว สเตตัสเท่าเดิม"]},{id:"2026-09-29-monster-walk-frames",date:"2026-09-29",time:"05:14",title:"มอนสเตอร์ทุกตัวมีท่าเดินแล้ว",lines:["มอนทุกตัวมีท่าเดินที่วาดใหม่ 2 ท่า เล่นสลับกับท่ายืนเป็นจังหวะก้าว 4 จังหวะ แทนการเด้งตัวขึ้นลงแบบเดิม","สัตว์สี่ขาก้าวขาไขว้ ตัวสองขาก้าวสลับ ตัวที่กระโดดย่อแล้วดีดตัว ตัวที่ไม่มีขาบิดตัว และตัวที่บินกระพือปีก","ก้าวตามระยะที่เดินได้จริง ตอนมอนวิ่งไล่จึงก้าวถี่กว่าตอนเดินเล่น"]},{id:"2026-09-29-google-link-confirm",date:"2026-09-29",time:"04:55",title:"ผูก Google ต้องกดยืนยันก่อน ตัวละครไม่ไปติดบัญชีผิดอีก",lines:["เดิมถ้าเล่น Guest อยู่แล้วกด Sign in with Google ตัวละคร Guest จะถูกผูกกับ Google บัญชีที่เลือกทันที ถ้าเผลอเลือกบัญชีผิดก็เปลี่ยนเองไม่ได้ ตอนนี้เกมจะถามก่อนทุกครั้ง พร้อมแสดงอีเมล Google และชื่อ/เลเวลตัวละครที่จะผูก","เลือกได้ว่าจะผูกกับบัญชีนี้ ใช้ Google บัญชีอื่น เริ่มตัวละครใหม่ใน Google นี้ หรือยังไม่ผูกแล้วเล่น Guest ต่อ","หน้าตั้งชื่อตัวละครของ Google บัญชีใหม่บอกว่ากำลังใช้อีเมลไหน และมีปุ่มเข้าด้วย Google บัญชีอื่น สำหรับคนที่มีตัวละครอยู่แล้ว","หน้าเข้าเกมบอกตรงๆ ว่าตัวละคร Guest อยู่ในเบราว์เซอร์นั้นเท่านั้น ล้างคุกกี้หรือเปลี่ยนเครื่องแล้วจะเข้าตัวเดิมไม่ได้ · Guest เลเวล 5 ขึ้นไปจะเห็นข้อความเตือนให้ผูก Google ในแชทระบบทุกครั้งที่เข้าเกม"]},{id:"2026-09-29-nekobaku-skill-effects",date:"2026-09-29",time:"04:41",title:"Nekobaku: เอฟเฟกต์สกิลใหม่ทั้งชุด",lines:["Fizz Flask ขวดแตกเป็นน้ำกระจาย มีวงคลื่นน้ำแผ่ออกเท่าระยะที่โดนหมู่","Tar Flask ราดน้ำมันดินสีดำเงาเต็มพื้นที่ และมีน้ำมันกับโคลนกระเด็นตอนขวดแตก","Big Kaboom ระเบิดเป็นลูกไฟพร้อมเศษถังไม้ปลิวกระจาย","Catalyst Brew มีขวดยาหูแมวลอยเหนือหัว และฟองสีม่วงฟ้าลอยขึ้นรอบตัว"]},{id:"2026-09-29-monster-wander-emotes",date:"2026-09-29",time:"04:32",title:"มอนเดินกว้างขึ้นและแสดงอีโมต",lines:["มอนที่ว่างอยู่เดินสุ่มได้ไกลจากจุดเกิดขึ้น จาก ±65 เป็น ±100 พิกเซล","นานๆ ครั้ง (ราว 30 วินาที) มอนจะแสดงอีโมตบนหัว เช่น สงสัย ร้องเพลง หัวใจ หรือหัวเราะ"]},{id:"2026-09-29-chat-kept-on-device",date:"2026-09-29",time:"04:30",title:"กระซิบ ปาร์ตี้ กิล แมพ และข้อความระบบ ไม่หายตอนรีเฟรชแล้ว",lines:["รีเฟรชหน้าเกม หลุดแล้วเข้าใหม่ หรือปิดเกมแล้วเปิดใหม่ แชทกระซิบ ปาร์ตี้ กิล แมพ และข้อความระบบยังอยู่ครบ เรียงตามเวลาปนกับแชทโลกเหมือนเดิม","เก็บไว้ในเครื่องที่เล่นเท่านั้น แยกตามตัวละคร ย้อนหลังได้ไม่เกิน 7 วัน แท็บละ 100 ข้อความล่าสุด · เปลี่ยนเครื่องแล้วจะไม่เห็นของเครื่องเดิม","แชทโลกยังดึงประวัติจากเซิร์ฟเหมือนเดิม ส่วนแท็บ EXP ไม่ได้เก็บ"]},{id:"2026-09-29-nekobaku-skill-rework",date:"2026-09-29",time:"04:22",title:"Nekobaku: ปรับสกิลให้ตีหมู่แรงขึ้นและใช้ถี่ขึ้น",lines:["Fizz Flask โดนทุกตัวรอบเป้าหมายในรัศมี 1.5 ช่อง ดาเมจเท่ากับเป้าหลักทุกตัว (เดิมตัวรอบๆ โดนครึ่งเดียว) และเป็นธาตุน้ำ","Tar Flask เป็นธาตุดิน คูลดาวน์ 0.5 วินาที (เดิม 3 วินาที) แต่ไม่เร็วกว่าความเร็วโจมตี","Big Kaboom ธาตุไฟ คูลดาวน์ 1 วินาที (เดิม 5 วินาที) แต่ไม่เร็วกว่าความเร็วโจมตี","Catalyst Brew เพิ่ม CRIT +4 ต่อระดับ (ระดับ 10 = +40) มีผลทั้งตีธรรมดาและคริของสกิล"]},{id:"2026-09-29-lock-allows-refine-market",date:"2026-09-29",time:"04:04",title:"ของที่ล็อกไว้ ตีบวกและขายในตลาดกลางได้เลย",lines:["ไอเทมและอุปกรณ์ที่ล็อกไว้ยังกันขายให้ NPC กันทิ้ง กันทำลาย และกันหลอมเหมือนเดิม","ตีบวกอุปกรณ์ที่ล็อกได้ทันทีไม่ต้องปลดล็อก · ถ้าตีบวกล้มเหลวโดยไม่ใช้ Protection Stone อุปกรณ์แตกได้เหมือนชิ้นอื่น","ตั้งขายของที่ล็อกในตลาดกลางได้ทันทีไม่ต้องปลดล็อก · ผู้ซื้อได้รับอุปกรณ์แบบไม่ล็อก","อุปกรณ์จากร้าน Cash ยังผูกกับตัวละครและตั้งขายไม่ได้เหมือนเดิม"]},{id:"2026-09-29-bot-instant-next-target",date:"2026-09-29",time:"03:48",title:"บอท: ฆ่ามอนตัวนึงจบ ตีตัวต่อไปทันที",lines:["บอทเคยยืนเฉยได้ถึงเกือบ 1 วินาทีหลังมอนตาย ก่อนหาตัวใหม่ ตอนนี้เลือกตัวต่อไปทันทีที่เห็นว่ามอนตาย","สกิลแรกใส่ตัวใหม่ออกทันที และถ้าสกิลเพิ่งพ้นคูลดาวน์ก็ใช้ได้เลย ไม่ต้องรอรอบโจมตีถัดไป ตีต่อเนื่องลื่นขึ้นทุกอาชีพ"]},{id:"2026-09-29-bot-approach-skill-resend",date:"2026-09-29",time:"03:33",title:"บอท: เดินถึงระยะแล้วใช้สกิลทันที ไม่ยืนเดินตามมอนเฉยๆ",lines:["บอทที่ใช้สกิลใส่มอนที่อยู่ไกลเกินระยะ (เช่น Fizz Flask ของ Nekobaku) เคยเดินเข้าไปถึงระยะแล้วยืนเดินตามมอนเฉยๆ ได้ถึง 3 วินาทีก่อนจะใช้สกิล ตอนนี้ถึงระยะเมื่อไหร่ใช้สกิลทันที"]},{id:"2026-09-29-portal-depth-retry",date:"2026-09-29",time:"03:13",title:"แก้บัคเดินเข้าวาร์ปแล้วเด้งกลับที่เดิม",lines:["ช่วงคนเยอะ เดินเข้าวาร์ปบางครั้งเซิร์ฟส่งตัวละครไปแมพใหม่ไม่ได้ หลุดแล้วกลับมาอยู่แมพเดิม ตอนนี้ตอนเชื่อมต่อกลับ เซิร์ฟจะส่งตัวละครไปแมพที่เดินเข้าไปให้ต่อเลย"]},{id:"2026-09-29-gold-exchange-closes-before-launch",date:"2026-09-29",time:"03:13",title:"ตลาด Gold ปิดพร้อมตอนปิดเซิร์ฟก่อนเปิดจริง",lines:["ยังไม่ได้กำหนดวันเปิดจริง · เมื่อประกาศวันแล้ว หน้าต่างตลาด Gold จะบอกเวลาปิดล่วงหน้า และตลาดจะปิดอัตโนมัติพร้อมตอนปิดเซิร์ฟเพื่อล้างข้อมูล","ตอนปิด คำสั่งซื้อขาย Gold ที่ค้างอยู่ทุกรายการถูกยกเลิก Gold ที่ตั้งขายคืนเข้ากล่องจดหมาย (แล้วยกไปเซิร์ฟใหม่พร้อม Gold ที่เหลือ) ส่วน Silver ที่ตั้งรับซื้อก็คืนเข้ากล่องจดหมายเช่นกัน","หลังเปิดเซิร์ฟใหม่ ตลาด Gold กลับมาเปิดตามปกติ"]},{id:"2026-09-29-zoom-view-once",date:"2026-09-29",time:"02:52",title:"แก้ต้นเหตุหลุดบ่อยตอนซูมกล้องออก",lines:["ถ้าซูมกล้องออก เกมเคยส่งขนาดมุมมองไปเซิร์ฟทุกเฟรม ถี่จนเซิร์ฟเคยเตะหลุด ตอนนี้ส่งครั้งเดียวตอนเข้า map"]},{id:"2026-09-29-socket-budget-no-kick",date:"2026-09-29",time:"02:41",title:"แก้บัคหลุดบ่อย",lines:["ตัวละครที่ส่งคำสั่งเดิน/ตี/หันหน้าถี่ๆ (เจอบ่อยตอนเปิดบอท) เคยถูกเซิร์ฟเตะหลุดทันที ชั่วโมงละหลายหมื่นครั้ง ตอนนี้เซิร์ฟไม่เตะแล้ว แต่รับคำสั่งล่าสุดไปทำแทน"]},{id:"2026-09-29-launch-gold-carry",date:"2026-09-29",time:"02:28",title:"วันเปิดเซิร์ฟจริง Gold ที่เหลือจะยกไปด้วย",lines:["ยังไม่ได้ล้างเซิร์ฟตอนนี้ และยังไม่ได้กำหนดวันเปิดจริง เป็นการแจ้งล่วงหน้าว่าเปลี่ยนกติกาวันล้างเซิร์ฟ","วันเปิดจริง Gold ที่ยังเหลืออยู่จะยกไปใช้ต่อในเซิร์ฟใหม่ ทั้ง Gold ในตัวละคร ในจดหมายที่ยังไม่กดรับ และที่ตั้งขายค้างไว้ในตลาด Gold ส่งเข้ากล่องจดหมายเป็นจดหมายที่ไม่มีวันหมดอายุ เหมือนวัน Premium ที่ยกไปอยู่แล้ว","ส่วนเลเวล ไอเทม Silver ของในตลาด และกิลด์จะเริ่มใหม่ทั้งหมด · Gold ที่ใช้ไปแล้วจะไม่ได้คืน (รวม Gold ที่ใช้สร้างกิลด์)","บัญชีผูกกับบัญชี Google ไม่ได้ผูกกับชื่อตัวละคร · เข้าเกมครั้งแรกหลังล้างเซิร์ฟจะได้ตั้งชื่อตัวละครใหม่ และได้รับ Gold กับวัน Premium ที่เหลือในกล่องจดหมาย","ข้อตกลงการใช้บริการข้อ 6 และนโยบายการคืนเงินปรับตามแล้ว"]},{id:"2026-09-29-splash-kill-keeps-target",date:"2026-09-29",time:"02:24",title:"แก้บัคตีๆ อยู่แล้วหยุดตี ยืนจ่อมอน",lines:["สกิลกระเซ็นหรือสกิลวงกว้าง (เช่น Fizz Flask, Big Kaboom) ฆ่ามอนตัวข้างๆ ได้ ตัวละครเคยเลิกตีมอนตัวที่ตีอยู่แล้วยืนนิ่ง ตอนนี้ตีตัวเดิมต่อจนตาย","เจอบ่อยสุดกับ Nekobaku แต่แก้ให้ทุกอาชีพที่มีสกิลโดนหลายตัว"]},{id:"2026-09-29-fusion-picker-right",date:"2026-09-29",time:"01:53",title:"ช่างหลอมรวม: รายการเลือกอุปกรณ์ย้ายไปด้านขวา",lines:['หน้าต่างช่างหลอมรวมเป็นแนวนอนแบบเดียวกับหน้าตีบวก หม้อหลอม ปุ่มยืนยัน และโอกาสที่จะได้อยู่ด้านซ้าย ส่วน "เลือกอุปกรณ์ 5 ชิ้น" กับ "เลือกอุปกรณ์ที่ต้องการ" อยู่ด้านขวา แต่ละรายการเลื่อนดูในกรอบของตัวเอง ไม่ต้องเลื่อนทั้งหน้าต่างลงไปหา']},{id:"2026-09-29-inspect-privacy-on-equipment",date:"2026-09-29",time:"01:48",title:"ช่องปิดการส่องของย้ายไปหน้าอุปกรณ์",lines:['ช่อง "ให้ผู้เล่นอื่นส่องของได้" ย้ายจากตั้งค่ามาอยู่มุมซ้ายบนของหน้าต่างอุปกรณ์สวมใส่ ข้างป้ายอาชีพ',"กดติ๊กเปิด/ปิดได้ตรงนั้นเลย ค่าเดิมที่ตั้งไว้ยังอยู่ครบ"]},{id:"2026-09-29-nekobaku-matk-basic",date:"2026-09-29",time:"01:47",title:"Nekobaku ตีธรรมดาใช้ MATK แล้ว",lines:["ตีธรรมดาด้วย Neko Flask คิดดาเมจจาก MATK แทน ATK สาย INT ตีธรรมดาแรงขึ้นมาก","ยังทอย HIT และคริเหมือนตีธรรมดาทุกแบบ (HIT มาจาก DEX, คริมาจาก LUK) และได้โบนัสจังหวะ ASPD เกิน 170 เหมือนเดิม","ดาเมจเป็นเวท: มอนสเตอร์และผู้เล่นใช้ MDEF รับแทน DEF ส่วนเจาะเกราะเวท (mpierce) ใช้ได้กับการตีธรรมดาด้วย · ใน PVP ยังหลบได้ด้วย FLEE"]},{id:"2026-09-29-kensei-new-animations",date:"2026-09-29",time:"01:45",title:"Kensei แอนิเมชันใหม่ทั้งชุด",lines:["วาดตัวละคร Kensei ใหม่หมด ชุดยูนิฟอร์มคาดผ้าที่เอว ถือคาตานะสองมือ ครบ 8 ทิศ","ท่ายืน เดิน ฟันดาบ ก้มเก็บของ นั่ง และล้มตายเป็นแอนิเมชันใหม่ทุกท่า รูปในหน้าต่างเปลี่ยนอาชีพและหน้าโปรไฟล์ก็เปลี่ยนตาม","ความแรงและสกิลของ Kensei ไม่ได้เปลี่ยน"]},{id:"2026-09-29-nekobaku-orb",date:"2026-09-29",time:"01:30",title:"Nekobaku ถือ Orb ได้แล้ว",lines:["Orb (ออร์บเวท) ใส่มือซ้ายของ Nekobaku ได้แล้ว ถือคู่กับ Neko Flask ได้เลย","Orb เพิ่ม MATK/INT/DEX ไม่ลด ASPD เหมือนโล่ และตีบวกแล้วได้ MATK เพิ่มเหมือนของ Mage"]},{id:"2026-09-29-quiver-archer-only",date:"2026-09-29",time:"00:28",title:"ซองธนู (Quiver) ใช้ได้เฉพาะ Archer",lines:["ซองธนูทุกชิ้นขึ้นว่าใช้ได้โดย Archer แทน ทุกอาชีพ ทั้งในกระเป๋า ตลาด และหน้าหลอม เพราะซองธนูใส่ได้เฉพาะคู่กับ Bow ซึ่งมีแค่ Archer ที่ถือได้","อาชีพอื่นกดสวมซองธนูไม่ได้ ถ้ามีซองธนูสวมอยู่ในอาชีพอื่น ระบบจะถอดกลับเข้ากระเป๋าให้ ไอเทมไม่หาย"]},{id:"2026-09-29-gear-marks-everywhere",date:"2026-09-29",time:"00:10",title:"ทุกหน้าต่างแสดงเลขตีบวกและสีสเตตัสค่าสูงสุด",lines:["ไอคอนอุปกรณ์ที่ตีบวกแล้วมีป้าย +N สีทองแบบในกระเป๋า ครบทุกที่: หน้าต่างหลอมรวม (รายการและในหม้อ), หน้าฝังการ์ด, กระเป๋าสัตว์เลี้ยง, รายการขายของร้านค้า, แบนเนอร์ได้ของ และหน้า Explorer","สเตตัสที่ออกค่าสูงสุดของ Tier ขึ้นสีส้มในทุกที่ที่แสดงสเตตัส: บรรทัดใต้ชื่อในหน้ารายละเอียดไอเทม, ช่องเทียบกับที่สวมอยู่, มุมมองรายการในกระเป๋า, หน้าต่างอุปกรณ์, ช่างตีบวก, หลอมรวม, ฝังการ์ด, หน้าต่างแลกเปลี่ยน, แบนเนอร์ได้ของ และหน้า Explorer","แบนเนอร์ได้ของไม่เขียน +N ซ้ำสองครั้ง และหน้า Explorer ก็เช่นกัน"]},{id:"2026-09-28-two-handed-special-option",date:"2026-09-28",time:"23:55",title:"อาวุธสองมือ: ออปชันพิเศษได้ ×1.5 ด้วย",lines:["ออปชันพิเศษบนอาวุธสองมือ (Staff, Quarterstaff, Dagger Pair, Hammer) นับ ×1.5 เหมือนสเตตัสอื่นของอาวุธ เช่น Staff คริดาเมจ 20% นับเป็น 30% เจาะเวท 15% นับเป็น 23%","ชดเชยที่ถือ Orb หรือโล่ไม่ได้ เพดานรวมของแต่ละออปชันยังเท่าเดิม (คริดาเมจรวมสูงสุด 60%) · มีผลกับอาวุธที่มีอยู่แล้วทันที"]},{id:"2026-09-28-party-finder-size",date:"2026-09-28",time:"23:50",title:"รายการปาร์ตี้ที่เปิดรับแสดงจำนวนสมาชิก",lines:["แต่ละปาร์ตี้ในหน้าต่างปาร์ตี้แสดงจำนวนคน เช่น 10/12 แทนอาชีพของหัวหน้าปาร์ตี้ ปาร์ตี้ที่เต็มแล้วตัวเลขเป็นสีแดง","ชื่อแมพและ Channel ของปาร์ตี้แสดงครบ ไม่ถูกตัดท้ายแล้ว"]},{id:"2026-09-28-fusion-picked-top",date:"2026-09-28",time:"23:40",title:"ช่างหลอมรวม: ชิ้นที่เลือกเด่นขึ้นและขึ้นบนสุด",lines:["อุปกรณ์ที่เลือกใส่หม้อหลอมเป็นกรอบสีทองเข้ม พื้นเหลือง และมีเครื่องหมาย ✓ เห็นชัดว่าชิ้นไหนเลือกแล้ว","ชิ้นที่เลือกจะเลื่อนขึ้นไปอยู่บนสุดของรายการตามลำดับที่เลือก","อุปกรณ์ที่ล็อกไว้ไม่แสดงในรายการให้เลือกแล้ว"]},{id:"2026-09-28-inspect-privacy",date:"2026-09-28",time:"23:24",title:"ปิดการส่องของได้แล้ว",lines:['ตั้งค่า → บัญชีผู้เล่น มีช่อง "ให้ผู้เล่นอื่นส่องของได้" เอาเครื่องหมายออกแล้วผู้เล่นคนอื่นจะกดส่องของดูอุปกรณ์ที่คุณสวมไม่ได้ รวมถึงปุ่มดูโปรไฟล์ในตลาด',"ค่านี้บันทึกไว้กับตัวละคร ย้ายแมพหรือเปลี่ยนเครื่องก็ยังปิดอยู่ ติ๊กกลับเมื่อไรก็ส่องได้ตามเดิม"]},{id:"2026-09-28-bow-one-handed",date:"2026-09-28",time:"23:11",title:"Bow กลับเป็นอาวุธมือเดียว ฝังการ์ดได้ 1 ใบ",lines:["Bow เป็นอาวุธมือเดียวเหมือน Knife และ Sword มือซ้ายใส่ซองธนู (Quiver) หรือโล่ก็ได้","ฝังการ์ดได้ 1 ใบตามอาวุธมือเดียวทั้งหมด Bow ที่ฝังไว้ 2 ใบจะเก็บการ์ดใบแรกไว้ ส่วนใบที่สองคืนเข้ากระเป๋าเป็นการ์ด ไม่หายไปไหน","อาวุธสองมือตอนนี้มี Staff, Quarterstaff, Dagger Pair และ Hammer ยังได้สเตตัส ×1.5 และการ์ด 2 ใบเหมือนเดิม"]},{id:"2026-09-28-quiver-rename",date:"2026-09-28",time:"22:58",title:"Feather Arrow เปลี่ยนเป็นซองธนู (Quiver)",lines:["อุปกรณ์มือซ้ายของสายธนูที่เคยชื่อ Feather Arrow เปลี่ยนชื่อเป็น Quiver พร้อมไอคอนใหม่เป็นซองธนูหนังสะพายข้าง","ของที่มีอยู่แล้วในกระเป๋า คลัง ตลาด และจดหมาย เปลี่ยนชื่อให้เองทั้งหมด ขั้น ค่าสถานะ ตีบวก และการ์ดยังอยู่ครบ ไม่ต้องทำอะไรเพิ่ม"]},{id:"2026-09-28-bag-card-tab",date:"2026-09-28",time:"22:38",title:"กระเป๋า: แยกแท็บการ์ดออกจากของอื่นๆ",lines:['แถบหมวดด้านซ้ายของกระเป๋าเปลี่ยนแท็บ "Material วัตถุดิบ" เป็น "Card การ์ด" กดแล้วเห็นเฉพาะการ์ดมอนสเตอร์','แท็บ "Etc. อื่นๆ" แสดงวัตถุดิบและของดรอปจากมอนสเตอร์ ไม่มีการ์ดปนแล้ว']},{id:"2026-09-28-bot-auto-coat-fix",date:"2026-09-28",time:"22:33",title:"บอท: แก้ใช้ใบเคลือบธาตุอัตโนมัติไม่ทำงาน",lines:['แก้บัคติ๊ก "ใช้ใบเคลือบอาวุธ/เกราะอัตโนมัติ" แล้วบอทไม่ใช้ใบเคลือบให้ — เกิดเมื่อติ๊กใช้ยาเร่ง ASPD อัตโนมัติไว้ด้วยแต่ไม่มียาเร่งในกระเป๋า ตอนนี้บอทจะเคลือบธาตุที่เลือกให้ตามปกติ']},{id:"2026-09-28-field-corner-gates",date:"2026-09-28",time:"21:32",title:"ป่าเริ่มต้น: ย้ายประตูสนาม PVP และลานฝึกไปมุมแมพ",lines:["ประตูสนาม PVP ย้ายไปมุมซ้ายบนของป่าเริ่มต้น และประตูลานฝึกหุ่นฟางย้ายไปมุมขวาบน มีทางดินจากถนนประตูเมืองพาเดินไปถึงทั้งสองจุด","ออกจากสนามหรือลานฝึกจะกลับมาโผล่บนทางเดินหน้าประตูที่มุมนั้น ไม่เดินผ่านหน้าประตูเมืองแล้ววาร์ปเข้าโดยไม่ตั้งใจอีก"]},{id:"2026-09-28-market-sell-stats-view",date:"2026-09-28",time:"21:31",title:'ตลาดกลาง: หน้าขายสินค้ามีมุมมอง "ดูสเตตัส"',lines:["หน้าขายสินค้ามีปุ่มสลับมุมมอง ไอคอน / ดูสเตตัส ข้างช่องเรียงลำดับ","มุมมองดูสเตตัสเขียนค่าของทุกชิ้นให้เห็นเลยโดยไม่ต้องเอาเมาส์ชี้ ทั้งช่องที่ใส่ อาชีพและเลเวลที่ใช้ได้ สเตตัสทุกบรรทัด (ค่าที่ออกสูงสุดเป็นสีส้ม) และค่าที่เพิ่ม/ลดเทียบกับของที่สวมอยู่","เหมาะกับคนเล่นบน iPad และมือถือที่ชี้ค้างดูรายละเอียดไม่ได้ · เกมจำมุมมองที่เลือกไว้ให้"]},{id:"2026-09-28-pet-bag-top-roll",date:"2026-09-28",time:"21:26",title:"กระเป๋าสัตว์เลี้ยงแสดงสีสเตตัสค่าสูงสุด",lines:["รายการอุปกรณ์ในกระเป๋าสัตว์เลี้ยงแสดงสเตตัสที่ออกค่าสูงสุดของ Tier และออปชันพิเศษเป็นตัวสีส้ม เหมือนหน้ารายละเอียดไอเทมและตลาด ไม่ต้องคลิกเข้าไปดูทีละชิ้น"]},{id:"2026-09-28-auto-bot-lock",date:"2026-09-28",time:"21:24",title:"ปุ่มล็อกบอท กันเผลอแตะแล้ว Auto หยุด",lines:["มีปุ่มกุญแจเล็กๆ เหนือปุ่ม AUTO กดให้เป็นกุญแจสีทองเพื่อล็อกบอท","ระหว่างล็อก แตะพื้น ลากจอยสติ๊ก แตะมินิแมพ กดปุ่ม AUTO หรือปุ่ม F จะไม่หยุดบอทแล้ว ปุ่มกุญแจจะสั่นเตือนแทน","จะหยุดบอท ให้กดปุ่มกุญแจปลดล็อกก่อน แล้วค่อยกด AUTO หรือแตะพื้นตามปกติ (ปุ่มหยุดในหน้าต่างตั้งค่าบอทยังหยุดได้เสมอ) · เกมจำไว้ว่าล็อกหรือไม่บนเครื่องนั้น"]},{id:"2026-09-28-weight-badge-contrast",date:"2026-09-28",time:"21:19",title:"ป้าย % น้ำหนักบนปุ่มกระเป๋าอ่านง่ายขึ้น",lines:["ตัวเลข % น้ำหนักบนปุ่มกระเป๋าและปุ่มสัตว์เลี้ยงเคยเป็นตัวขาวบนพื้นสีส้มอ่อน แทบมองไม่เห็น ตอนนี้ช่วง 70–89% เป็นตัวเลขสีเข้มบนพื้นเหลืองทอง ส่วนสีเขียวและสีแดงเข้มขึ้นและตัวเลขมีขอบดำ"]},{id:"2026-09-28-oboro-ranbu-stuck-fix",date:"2026-09-28",time:"21:00",title:"Kensei: แก้ยืนค้างหลังใช้ Oboro Ranbu",lines:["แก้บัคหลังร่าย Oboro Ranbu แล้วตัวละครบางครั้งยืนนิ่ง ไม่ตีต่อ ไม่ใช้สกิลต่อ จนโดนมอนตีตาย — เกิดเมื่อบอทสั่งเก็บของหรือผู้เล่นคลิกเดินระหว่างร่าย ตอนนี้ร่ายจบแล้วจะเดินไปเก็บของหรือเดินต่อตามปกติ","Oboro Ranbu จะไม่วาร์ปไปลงในต้นไม้หรือในพื้นที่ปิดที่เดินออกไม่ได้อีกแล้ว"]},{id:"2026-09-28-megaphone-world-chat-whisper",date:"2026-09-28",time:"20:39",title:"โทรโข่ง: ขึ้นในแชทโลก และคลิกชื่อเพื่อกระซิบได้",lines:["ข้อความโทรโข่งขึ้นในแชทแท็บ ทั้งหมด และ โลก ด้วย มีป้าย [โทรโข่ง] สีชมพูนำหน้า เลื่อนกลับมาอ่านย้อนหลังได้ (เดิมขึ้นแค่แท็บ ระบบ)","คลิกชื่อคนประกาศบนแถบโทรโข่งเพื่อกระซิบหาได้ทันที · คลิกขวา (มือถือกดค้าง) ที่ชื่อบนแถบหรือในแชทเพื่อเปิดเมนู กระซิบ เพิ่มเพื่อน ชวนปาร์ตี้ บล็อกแชท รีพอร์ต"]},{id:"2026-09-28-market-return-outbox",date:"2026-09-28",time:"18:25",title:"ตลาดกลางไม่ค้างเป็นช่วง ๆ แล้ว",lines:["ตลาดกลางเคยหยุดตอบทุกคนพร้อมกันทุกไม่กี่วินาที ระหว่างรอส่งของที่ประกาศขายหมดเวลาคืนเข้ากล่องจดหมาย และถ้าส่งไม่ผ่าน คำสั่งซื้อขายที่รออยู่จะล้มพร้อมกันหมด ตอนนี้ของที่หมดเวลาจะถูกเอาลงจากกระดานทันที แล้วจดหมายคืนของจะตามไปถึงกล่องจดหมายภายในไม่กี่วินาที","ของที่หมดเวลาอาจค้างบนกระดานเกินเวลาได้ไม่เกิน 30 วินาที"]},{id:"2026-09-28-market-page-stall",date:"2026-09-28",time:"16:48",title:"ตลาดกลาง: เปลี่ยนหน้าไม่ค้างแล้ว และลื่นขึ้นช่วงคนเยอะ",lines:["เวลาตลาดกลางตอบช้า เซิร์ฟเวอร์เคยหันไปโหลดรายการขายทั้งตลาดมาเองทีละหลาย MB ทำให้ตลาดยิ่งช้าลงไปอีกและหน่วงทั้งเซิร์ฟเวอร์ ตอนนี้จะถามเฉพาะหน้าที่เปิดดูอยู่ซ้ำแทน","กดเปลี่ยนหน้า ค้นหา หรือเปลี่ยนตัวกรองแล้วคำตอบยังมาไม่ถึง รายการจะจางลงพร้อมขึ้นว่า กำลังโหลด… และถามใหม่ให้เองจนกว่าจะได้หน้าที่กด เดิมเลขหน้าเปลี่ยนแต่รายการค้างอยู่หน้าเก่า"]},{id:"2026-09-28-party-sync-patch",date:"2026-09-28",time:"16:32",title:"ปาร์ตี้: เข้าปาร์ตี้แล้วเห็นทันทีว่าเพื่อนอยู่แมพไหน CH อะไร",lines:["ตอนเข้าปาร์ตี้ รับสมาชิกใหม่ หรือสมาชิกเปลี่ยน รายชื่อปาร์ตี้จะบอกแมพและ CH ของทุกคนทันที ไม่ต้องรอให้เพื่อนเดินย้ายแมพหรือกดเปิดหน้าต่างปาร์ตี้ก่อน","ปรับการส่งข้อมูลปาร์ตี้ในเซิร์ฟเวอร์ให้ส่งเฉพาะปาร์ตี้ที่เปลี่ยน แทนการส่งปาร์ตี้ทั้งเซิร์ฟเวอร์ทุกครั้ง ลดภาระเซิร์ฟเวอร์กลางช่วงคนเยอะ"]},{id:"2026-09-28-socket-worn-first",date:"2026-09-28",time:"16:25",title:"หน้าฝังการ์ด: อุปกรณ์ที่สวมอยู่ขึ้นบนสุด",lines:["รายการเลือกอุปกรณ์ตอนฝังการ์ด เรียงชิ้นที่สวมอยู่ไว้บนสุดก่อน แล้วตามด้วยของในกระเป๋า ไม่ต้องเลื่อนหาชิ้นที่ใส่อยู่อีก"]},{id:"2026-09-28-mail-refine-chip",date:"2026-09-28",time:"16:24",title:"จดหมายบอกระดับตีบวกของอุปกรณ์ที่แนบมาแล้ว",lines:["อุปกรณ์ที่แนบมากับจดหมาย (เช่นของที่ขายได้หรือเก็บคืนจากตลาด) มีป้าย +N สีทองต่อจากไอคอน และชื่อขึ้นการ์ดที่ใส่ไว้ด้วย เดิมจดหมายแสดงแค่ชื่ออุปกรณ์ ไม่บอกระดับตีบวก"]},{id:"2026-09-28-forge-worn-first",date:"2026-09-28",time:"16:23",title:"หน้าตีบวก: อุปกรณ์ที่สวมอยู่ขึ้นบนสุด",lines:["รายการเลือกอุปกรณ์ในหน้าต่างช่างตีบวก เรียงชิ้นที่สวมอยู่ไว้บนสุดก่อน แล้วตามด้วยของในกระเป๋า ไม่ต้องเลื่อนหาชิ้นที่ใส่อยู่อีก"]},{id:"2026-09-28-skill-tree-six-actives",date:"2026-09-28",time:"16:22",title:"หน้าอัปสกิลของ Cleric ไม่ซ้อนกันแล้ว",lines:["Cleric มีสกิลใช้งาน 6 อันหลังจาก Sanctity of Life กลายเป็นสกิลใช้งาน การ์ดใบที่ 4 ตกลงไปแถวล่างและซ้อนทับการ์ดสกิลพาสซีฟ","ตอนนี้การ์ดสกิลใช้งานทั้ง 6 ใบเรียงอยู่แถวเดียวกัน กดเพิ่ม/ลดแต้มได้ครบทุกใบ"]},{id:"2026-09-28-chat-link-refine-chip",date:"2026-09-28",time:"16:20",title:"ลิงก์ไอเทมในแชทโชว์ระดับตีบวกเป็นป้ายทอง",lines:["อุปกรณ์ที่ตีบวกแล้วแชร์ในแชท มีป้าย +N สีทองต่อจากไอคอน แล้วตามด้วยชื่อไอเทม เห็นระดับตีบวกชัดแม้ไอคอนในแชทจะเล็ก"]},{id:"2026-09-28-share-card-refine-badge",date:"2026-09-28",time:"15:54",title:"การ์ดไอเทมที่แชร์โชว์ระดับตีบวกบนรูปแล้ว",lines:["คลิกไอเทมที่แชร์ในแชท การ์ดรายละเอียดมีป้าย +N สีทองที่มุมขวาบนของรูปอุปกรณ์ การ์ดรายละเอียดอุปกรณ์จากหน้าต่างอื่นก็มีป้ายนี้ด้วย"]},{id:"2026-09-28-merchant-basket-touch",date:"2026-09-28",time:"15:50",title:"ร้านพ่อค้า Silver: ปุ่ม + / − และช่องจำนวนกดติดแล้วบน iPad และมือถือ",lines:["ระหว่างที่ตัวละครเก็บของเข้ากระเป๋า รายการที่จะขายและรายการที่จะซื้อถูกวาดใหม่ทุกครั้ง ทำให้กดปุ่ม + / − ไม่ติด และคีย์บอร์ดตัวเลขปิดเองตอนพิมพ์จำนวน","ตอนนี้แถวในรายการคงอยู่ที่เดิม อัปเดตแค่ตัวเลข กดปรับจำนวนหรือพิมพ์จำนวนได้ตามปกติแม้กำลังเก็บของอยู่"]},{id:"2026-09-28-trade-refine-badge",date:"2026-09-28",time:"15:52",title:"หน้าแลกเปลี่ยนไอเทมบอกระดับตีบวกแล้ว",lines:["อุปกรณ์ที่ใส่ในข้อเสนอแลกเปลี่ยนมีป้าย +N สีทองที่มุมขวาบนของไอคอน และชื่อขึ้น +N กับการ์ดที่ใส่ไว้เหมือนในกระเป๋า เห็นระดับตีบวกของทั้งสองฝั่งชัดเจนก่อนกดยืนยัน"]},{id:"2026-09-28-forge-refine-badge",date:"2026-09-28",time:"15:46",title:"หน้าตีบวกโชว์ระดับตีบวกบนไอคอนแล้ว",lines:["หน้าต่างช่างตีบวกมีป้าย +N สีทองที่มุมขวาบนของไอคอน ทั้งในรายการอุปกรณ์และชิ้นที่วางบนทั่ง ตีบวกสำเร็จแล้วป้ายเปลี่ยนเป็นระดับใหม่ทันที"]},{id:"2026-09-28-inspect-refine-badge",date:"2026-09-28",time:"15:15",title:"หน้าส่องอุปกรณ์โชว์ระดับตีบวกบนไอคอนแล้ว",lines:["เวลาส่องอุปกรณ์ผู้เล่นอื่น ชิ้นที่ตีบวกไว้มีป้าย +N สีทองที่มุมขวาบนของไอคอน แบบเดียวกับหน้าต่างสวมใส่ของตัวเอง"]},{id:"2026-09-28-equip-refine-badge",date:"2026-09-28",time:"15:12",title:"หน้าต่างสวมใส่โชว์ระดับตีบวกบนไอคอนแล้ว",lines:["อุปกรณ์ที่สวมอยู่และตีบวกไว้มีป้าย +N สีทองที่มุมขวาบนของไอคอนในหน้าต่างสวมใส่ แบบเดียวกับในกระเป๋า คลังเก็บของ และตลาดกลาง"]},{id:"2026-09-28-market-refine-badge",date:"2026-09-28",time:"15:08",title:"ตลาดกลางโชว์ระดับตีบวกบนไอคอนแล้ว",lines:["อุปกรณ์ที่ตีบวกไว้มีป้าย +N สีทองที่มุมขวาบนของไอคอนในตลาดกลาง ทั้งในกระดานซื้อขาย ช่องเลือกของตั้งขาย และรายการของฉัน แบบเดียวกับในกระเป๋าและคลังเก็บของ"]},{id:"2026-09-28-fusion-odds",date:"2026-09-28",time:"15:02",title:"ช่างหลอมรวมบอกโอกาสที่จะได้",lines:['เลือกอุปกรณ์ที่ต้องการแล้ว หน้าต่างช่างหลอมรวมมีหัวข้อ "โอกาสที่จะได้" บอกทุกค่าที่ชิ้นใหม่สุ่มได้ ช่วงตัวเลข และโอกาสเป็น % เช่น HIT 50% สเตตัสสุ่มเพิ่มอีก 1 อย่าง 25% ออปชั่นพิเศษแต่ละแบบกี่ % ตามกฎเดียวกับของดรอปจากมอนสเตอร์']},{id:"2026-09-28-challenging-range-270",date:"2026-09-28",time:"14:52",title:"Swordsman · Challenging ยั่วยุได้ไกลขึ้น",lines:["Challenging เพิ่มระยะยั่วยุจาก 170 เป็น 270 ดึงมอนสเตอร์ที่อยู่ไกลขึ้นให้หันมาตีผู้ใช้ได้ในครั้งเดียว · ในอารีน่า PVP ใช้ระยะเดียวกัน","ดาเมจ ผลลด ATK / รับดาเมจเพิ่ม ระยะเวลา SP และคูลดาวน์เท่าเดิม"]},{id:"2026-09-28-fusion-socket-remove-lock",date:"2026-09-28",time:"14:55",title:"ช่างหลอมรวม: กดชิ้นในหม้อเพื่อนำออกหรือล็อก",lines:['กดที่อุปกรณ์ในช่องหม้อหลอม 5 ช่องด้านบน จะมีปุ่ม "นำออก" ให้ถอดชิ้นนั้นออกไปเลือกชิ้นใหม่ และปุ่ม "ล็อก" ให้ล็อกชิ้นนั้นไว้ในกระเป๋า กันเผลอเอาไปหลอม']},{id:"2026-09-28-storage-refine-badge",date:"2026-09-28",time:"14:51",title:"คลังเก็บของโชว์ระดับตีบวกแล้ว",lines:["อุปกรณ์ที่ตีบวกไว้ในคลังเก็บของมีป้าย +N สีทองที่มุมขวาบนของช่อง แบบเดียวกับในกระเป๋า"]},{id:"2026-09-28-skill-rebalance-cleric-sword-kensei",date:"2026-09-28",time:"14:38",title:"ปรับสมดุลสกิล Swordsman · Cleric · Kensei และสกิลชุบชีวิตใหม่",lines:["Swordsman · Flame Burst เปลี่ยนเป็น Flame Smash: ปักดาบลงพื้นแล้วเสาไฟพุ่งขึ้นรอบตัว 3 ฮิต ฮิตละ 125% ATK ที่ระดับ 1 ถึง 225% ที่ระดับ 10 · ระยะ 100 · SP 2 ต่อระดับ (สูงสุด 20) · คูลดาวน์ 2 วินาที · ทุกฮิตมีโอกาส 37% ติดเผาไหม้ 5 วินาที HP −5% ต่อวินาที · ไอคอนใหม่เป็นดาบปักพื้นกลางเปลวไฟ","Swordsman · Blade Mastery: ถืออาวุธประชิดได้ ASPD +2% ต่อระดับด้วย (สูงสุด +20%) เพิ่มจาก ATK +4% ต่อระดับเดิม","Cleric · Fiend Slayer เปลี่ยนชื่อเป็น Sacred & Divine: DEF และ MDEF +2% ต่อระดับ และ ATK และ MATK +2% ต่อระดับ (สูงสุด +20% ทั้งหมด) · ไอคอนใหม่เป็นโล่กางเขนศักดิ์สิทธิ์กับกระบองทอง","Cleric · Sacred Ward เปลี่ยนเป็นสกิลกดใช้ Sanctity of Life: เลือกผู้เล่นที่หมดสติแล้วกด ชุบให้ลุกขึ้นตรงจุดเดิมพร้อม HP 10% ต่อระดับ (ระดับ 10 = เต็ม) · ใช้ SP 25% ของ SP สูงสุด และ Sacred Feather 1 อัน · ระยะ 150 · คูลดาวน์ 10 วินาที · ใช้ในอารีน่าไม่ได้ · ระดับที่เคยอัป Sacred Ward ไว้ย้ายมาเป็นระดับของสกิลนี้","ไอเท็มใหม่ Sacred Feather ขายที่พ่อค้า 500 Silver · สกิล Sanctity of Life ได้ไอคอนใหม่เป็นอังค์ทองมีปีกกับขนนกศักดิ์สิทธิ์","Cleric · Divine Boon: นอกจาก STR/AGI/INT/DEX +2 ถึง +11 แล้ว ยังเพิ่ม ATK, MATK, FLEE และความเร็ววิ่ง 0.5% ต่อระดับ และลดเวลาร่ายกับคูลดาวน์ 0.5% ต่อระดับ (ระดับ 10 = 5%) · 75 วินาที","Cleric · Radiant Light: ตอนตีเบิ้ลหลายฮิต ตัวเลขดาเมจแต่ละฮิตไล่ขึ้นเป็นขั้นให้เห็นครบทุกฮิต และตัวนับ TOTAL นับจำนวนฮิตจริง","Kensei · Meikyo Shisui: เพิ่มดาเมจคริติคอล +1% ต่อระดับ (ระดับ 10 = ASPD +20% · CRIT +20 · ดาเมจคริ +10%) · SP 15 ที่ระดับ 1 ถึง 30 ที่ระดับ 10 · 45 วินาที · คูลดาวน์ 30 วินาที"]},{id:"2026-09-28-bag-refine-badge",date:"2026-09-28",time:"14:28",title:"กระเป๋าโชว์ระดับตีบวกแล้ว",lines:["อุปกรณ์ที่ตีบวกไว้มีป้าย +N สีทองที่มุมขวาบนของช่องในกระเป๋า ดูได้ทันทีว่าชิ้นไหน +7 ชิ้นไหน +3 ไม่ต้องกดเปิดดูทีละชิ้น"]},{id:"2026-09-28-arrow-buy-100k",date:"2026-09-28",time:"12:47",title:"ซื้อลูกธนูกดทีละ 10k และ 100k ได้",lines:["ตะกร้าซื้อลูกธนูที่พ่อค้า Silver มีปุ่ม ±10k และ ±100k เพิ่ม แบ่งเป็นสองแถว แถวบนลด แถวล่างเพิ่ม","ซื้อลูกธนูได้สูงสุด 999,999 ดอกต่อครั้ง (ของอื่นยังสูงสุด 9,999)"],en:{title:"Buy arrows 10k and 100k at a time",lines:["The Silver merchant's arrow basket adds ±10k and ±100k buttons, on two lines: decreases above, increases below","One arrow purchase can take up to 999,999 (other items stay at 9,999)"]}},{id:"2026-09-28-kensei-no-air-swing",date:"2026-09-28",time:"12:44",title:"Kensei ไม่ฟันลมแล้ว",lines:["Kensei ที่ความเร็วโจมตีสูงมาก (โดยเฉพาะตอนเปิด Meikyo Shisui) เคยเล่นท่าฟันเปล่า ๆ แทรกระหว่างดาบที่โดนจริง ไม่มีตัวเลขดาเมจและไม่ขึ้น MISS ตอนนี้ท่าฟันบนจอตรงกับดาบที่ฟันจริงทุกครั้ง","ดาเมจ ความเร็วโจมตีจริง และจำนวนครั้งที่ฟันโดนไม่ได้เปลี่ยน แก้แค่ท่าที่เล่นเกินมา อาชีพอื่นที่ตีเร็วมากก็ได้ผลเดียวกัน"],en:{title:"Kensei no longer cuts thin air",lines:["A Kensei at very high attack speed (especially under Meikyo Shisui) used to play empty swings between the real blows, with no damage number and no MISS. Every swing on screen now matches a real blow.","Damage, the real attack speed and the number of blows are unchanged; only the extra animation is gone. Other very fast attackers get the same fix."]}},{id:"2026-09-28-shard-market-memory",date:"2026-09-28",time:"12:37",title:"ลดอาการหลุดและปิงกระโดดเป็นช่วง ๆ",lines:["ตลาดกลางคัดหน้ากระดานที่คุณเปิดดูให้เองแล้วส่งมาเฉพาะหน้านั้น ห้องแผนที่ไม่ต้องเก็บกระดานทั้งหมดกว่า 25,000 ชิ้นไว้อีก เดิมหน่วยความจำเต็ม เซิร์ฟเวอร์จึงรีสตาร์ทหลายห้องพร้อมกันเป็นระยะ ผู้เล่นในห้องนั้นหลุดหรือเห็นปิงพุ่ง","การค้นหา ตัวกรอง และการเรียงในหน้าต่างตลาดยังใช้ได้เหมือนเดิม"],en:{title:"Fewer disconnects and ping spikes",lines:["The market now picks out the page of the board you are looking at and sends just that page, so map channels no longer hold all 25,000+ pieces. They used to run out of memory, and the server kept restarting several channels at once, dropping or lagging everyone in them","Search, filters and sorting in the market window work as before"]}},{id:"2026-09-28-repair-price-tenth",date:"2026-09-28",time:"12:30",title:"ค่าซ่อมอุปกรณ์ลดลง 10 เท่า",lines:["ค่าซ่อมที่ช่างตีบวกเหลือ 1 ใน 10 ของเดิม ซ่อมเต็มจาก 0% ชิ้น +0 ราคา Tier I 100 · Tier II 250 · Tier III 450 · Tier IV 650 · Tier V 900 Silver","แต่ละขั้นตีบวกยังเพิ่มค่าซ่อม 3% และจ่ายตามสัดส่วนความทนทานที่หายไปเหมือนเดิม"],en:{title:"Gear repair now costs a tenth as much",lines:["Repairs at the Blacksmith cost a tenth of before. A full repair of a +0 piece from 0% is Tier I 100 · Tier II 250 · Tier III 450 · Tier IV 650 · Tier V 900 Silver","Each refine level still adds 3%, and you still pay only for the share of durability lost"]}},{id:"2026-09-28-broken-gear-equip-window",date:"2026-09-28",time:"12:24",title:"หน้าต่างสวมใส่บอกแล้วว่าชิ้นไหนพัง",lines:['ช่องในหน้าต่างไอเทมที่สวมใส่ขึ้นกรอบแดง ไอคอนเป็นสีเทา และเขียนว่า "พัง · ซ่อมที่ช่างตีบวก" เมื่อชิ้นนั้นความทนทานหมด ชิ้นที่พังยังสวมอยู่แต่ไม่ให้ค่าสถานะและการ์ด ถ้าเป็นอาวุธจะตีและเปิด Auto ไม่ได้จนกว่าจะซ่อม',"ชิ้นที่ความทนทานเหลือไม่ถึง 20% ขึ้นกรอบสีส้ม เหมือนในกระเป๋า"],en:{title:"The equipment window now shows which pieces are broken",lines:['A worn-out piece in the equipment window gets a red frame, a greyed icon and "Broken · repair at the Blacksmith". A broken piece stays on but gives no stats or card bonuses, and a broken weapon cannot attack or run Auto until it is repaired',"Pieces under 20% durability get an amber frame, as in the bag"]}},{id:"2026-09-28-kensei-head-oboro-guard",date:"2026-09-28",time:"12:10",title:"Kensei: หัวเต็มแล้ว และ Oboro Ranbu เป็นอมตะระหว่างร่าย",lines:["แก้สไปรต์ Kensei ที่หัวด้านบนแบนเหมือนโดนตัด ตอนนี้หัวกลมเต็มทุกทิศทุกท่า รวมรูปในหน้าต่างเปลี่ยนอาชีพ","ระหว่างร่าย Oboro Ranbu (1.5 วินาที) Kensei ไม่ถูกโจมตี ไม่ได้รับดาเมจ และไม่ติดสถานะผิดปกติ มอนสเตอร์จะเลิกเล็งจนกว่าจะโดนตีใหม่ · จบท่าแล้วกลับมาโดนตีได้ทันที"],en:{title:"Kensei: full head sprite, and Oboro Ranbu makes her invulnerable",lines:["Fixed the Kensei sprite whose head looked cut flat at the top: the head is now round in every direction and pose, including the Change Class portrait","During Oboro Ranbu (1.5 seconds) the Kensei cannot be targeted, takes no damage and cannot be afflicted; monsters stop targeting her until hit again · She can be hit again as soon as the dance ends"]}},{id:"2026-09-28-arrows-weightless",date:"2026-09-28",time:"12:09",title:"ลูกธนูไม่มีน้ำหนักแล้ว",lines:["ลูกธนู (Arrow) ไม่นับน้ำหนักในกระเป๋าอีกต่อไป พกไปล่าเท่าไหร่ก็ไม่ทำให้น้ำหนักเกิน ยังใช้ช่องกระเป๋า 1 ช่องเหมือนเดิม"]},{id:"2026-09-28-arrow-buy-1000",date:"2026-09-28",time:"12:08",title:"ซื้อลูกธนูกดทีละ 1,000 ได้",lines:["ตะกร้าซื้อของพ่อค้า Silver มีปุ่ม −1000 และ +1000 สำหรับลูกธนู เพิ่มจาก ±1 / ±10 / ±100"],en:{title:"Buy arrows 1,000 at a time",lines:["The Silver merchant's basket has −1000 and +1000 buttons for Arrows, next to ±1 / ±10 / ±100"]}},{id:"2026-09-28-kensei-twin-strike",date:"2026-09-28",time:"11:47",title:"Kensei: ตีปกติเบิ้ลได้ด้วย Twin Strike ของโจร",lines:["Kensei ที่ถือคาตานะ ตีปกติมีโอกาสเบิ้ลสองครั้งจากพาสซีฟ Twin Strike ของ Thief เหมือนโจร (5% ต่อระดับ สูงสุด 50%)","ใช้ระดับ Twin Strike ที่เรียนไว้ตอนเล่น Thief (การปลดล็อก Kensei ต้องมี Thief Job 50 อยู่แล้ว) ถ้ายังไม่ได้เรียน ให้เปลี่ยนกลับไปเป็น Thief แล้วอัป Twin Strike"],en:{title:"Kensei: basic attacks can double-strike with the Thief's Twin Strike",lines:["A Kensei holding a katana now gets the Thief's Twin Strike passive on basic attacks: a chance to strike twice, like a Thief (5% per level, up to 50%)","It uses the Twin Strike level learned as a Thief (unlocking the Kensei already needs Thief Job 50). If you never learned it, switch back to Thief and put points into Twin Strike"]}},{id:"2026-09-28-oboro-ranbu-faster",date:"2026-09-28",time:"11:46",title:"Kensei: Oboro Ranbu เร็วและแรงขึ้น",lines:["Oboro Ranbu ฟัน 20 ครั้งใน 1.5 วินาที (จากเดิม 5 วินาที) ครั้งละ 500% ATK ที่ระดับ 10 (จากเดิม 250%) · ระดับละ 50%","ยังวาร์ปไปฟันศัตรูรอบตัวแบบสุ่มเหมือนเดิม ตัวเดิมโดนซ้ำได้ และระหว่างร่ายใช้สกิลอื่นหรือตีปกติไม่ได้ ซึ่งตอนนี้เหลือแค่ 1.5 วินาที"],en:{title:"Kensei: Oboro Ranbu is faster and stronger",lines:["Oboro Ranbu now lands its 20 cuts in 1.5 seconds (was 5) at 500% ATK each at level 10 (was 250%) · 50% per level","It still teleports between random nearby enemies and can hit the same one again, and she still cannot use other skills or basic attacks during it, which now lasts only 1.5 seconds"]}},{id:"2026-09-28-kensei-saya",date:"2026-09-28",time:"11:42",title:"อุปกรณ์มือซ้ายของ Kensei: Saya ฝักดาบคาตานะ",lines:["Saya (ฝักดาบ) อุปกรณ์มือซ้ายของ Kensei ใส่ช่องโล่ แต่ไม่ใช่โล่ ไม่ทำให้โจมตีช้าลง","สายกายภาพล้วน: ATK และ CRIT ติดทุกชิ้น (CRIT ตามระดับ +2 / +4 / +6 / +8 / +10) พร้อม HIT และ STR / AGI / DEX ไม่มี DEF หรือเวท · ออปชันพิเศษ ATK%, เจาะกาย, คริดาเมจ, โจมตีติดสตัน","ตีบวกแล้วได้ ATK เพิ่มเหมือน Shuriken ของ Mamushi · ดรอปจากมอนสเตอร์แบบมีระดับ (tier) เหมือน Shuriken"],en:{title:"Kensei left-hand gear: the Saya katana scabbard",lines:["The Saya (katana scabbard) is the Kensei's left-hand piece. It goes in the shield slot but is not a shield, so it does not slow her attacks","Physical stats only: every Saya carries ATK and CRIT (CRIT by tier: +2 / +4 / +6 / +8 / +10), plus HIT and STR / AGI / DEX, never DEF or magic · Special options: ATK%, Pierce, Critical Damage, Stun on hit","Refining adds ATK, like the Mamushi's Shuriken · Drops from monsters by tier, like the Shuriken"]}},{id:"2026-09-28-arrows-return",date:"2026-09-28",time:"11:46",title:"ลูกธนูกลับมาแล้ว",lines:["Bow ใช้ลูกธนู 1 ดอกทุกครั้งที่ยิงธรรมดาและทุกครั้งที่ใช้สกิลโจมตี ลูกธนูหมดจะยิงไม่ได้ (Auto Play จะหยุดเอง) · Viper Kunai และขวดของ Nekobaku ไม่ต้องใช้","ซื้อลูกธนู (Arrow) ได้ที่พ่อค้า Silver ดอกละ 0.1 Silver (10 ดอก = 1 Silver) คลิกหนึ่งครั้งเพิ่มทีละ 100 ดอก · หนักดอกละ 0.01 · ขายคืนพ่อค้าไม่ได้","ลากลูกธนูไปไว้ที่ Shortcut เพื่อดูจำนวนที่เหลือได้"]},{id:"2026-09-28-rude-words-no-mute",date:"2026-09-28",time:"11:30",title:"พิมพ์คำหยาบไม่โดนพักแชทแล้ว",lines:["คำไม่สุภาพยังถูกเซ็นเซอร์เป็น *** และระบบจะแจ้งว่าข้อความมีคำไม่สุภาพ แต่จะไม่พักแชทอีกต่อไป ไม่ว่าจะพิมพ์กี่ครั้ง","การพักแชท 10 นาทีเมื่อผู้เล่น 3 คนรีพอร์ตคนเดียวกันภายใน 30 นาทียังเหมือนเดิม"],en:{title:"Rude words no longer pause your chat",lines:["Rude words are still censored as *** and you are told the message had them, but your chat is no longer paused for it, however often it happens","The 10-minute chat pause when 3 players report the same person within 30 minutes stays as before"]}},{id:"2026-09-28-sp-drain-like-lifesteal",date:"2026-09-28",time:"11:16",title:"ดูด SP ทำงานเหมือนดูดเลือดแล้ว",lines:["ออปชันดูด SP ดูดได้ทุกการโจมตีรวมสกิล เหมือนดูดเลือด (เดิมดูดเฉพาะตีปกติ)","ทุกครั้งที่โจมตีโดนได้ SP คืนอย่างน้อย 1 แม้ดาเมจน้อย และยังฟื้นไม่เกิน 2% ของ MaxSP ต่อครั้ง"],en:{title:"SP Drain now works like Lifesteal",lines:["The SP Drain option now drains on every attack including skills, like Lifesteal (it used to work on basic attacks only)","Every landed hit restores at least 1 SP even when the damage is low, still capped at 2% of MaxSP a hit"]}},{id:"2026-09-28-guild-hotkey-g",date:"2026-09-28",time:"11:03",title:"กด G เปิดหน้าต่างกิลด์",lines:["กดปุ่ม G บนคีย์บอร์ดเพื่อเปิดหรือปิดหน้าต่างกิลด์ได้ทันที ไม่ต้องคลิกปุ่ม Guild บนแถบเมนู"],en:{title:"Press G to open the Guild window",lines:["Press G on the keyboard to open or close the Guild window without clicking the Guild button on the menu bar"]}},{id:"2026-09-28-nekobaku-class",date:"2026-09-28",time:"10:47",title:"อาชีพใหม่ Nekobaku แมวนักปรุงยาสายปาระเบิด 🐱",lines:["อาชีพที่ 9 · ปลดล็อกเมื่อตัวละครเดียวกันมี Merchant Job Lv.50 และ Mamushi Job Lv.50 แล้วจ่าย 120,000 Silver ครั้งเดียวที่หน้าต่างเปลี่ยนอาชีพ (ปุ่ม Class) จากนั้นสลับไปมาได้ฟรี · โบนัส INT +3 AGI +2 · ขว้างขวดเวทจากระยะไกล ดาเมจเป็นเวท (MATK) และยิ่ง ASPD สูงยิ่งขว้างถี่ จึงเน้น AGI กับ INT","Fizz Flask (Job 1): ขวดเวทใส่เป้าหมายเดียว 300% MATK กดรัวได้ตามความเร็วโจมตี กระเซ็นใส่มอนรอบ ๆ ในรัศมี 1.5 ช่องอีกครึ่งหนึ่ง",'Tar Flask (Job 3): ขวดน้ำมันลงพื้น 400% MATK ติด "ชุ่มน้ำมัน" 6 วินาที มอนเดินช้าลง 30% · Big Kaboom (Job 5): ถังระเบิดธาตุไฟ 800% MATK เป็นวง โดนเป้าที่ชุ่มน้ำมันแรงขึ้น 50% และมีโอกาสติดไฟ',"Catalyst Brew (Job 7): ASPD +20% นาน 45 วินาที · พาสซีฟ Alchemy Mastery (MATK +50%) · Feline Reflex (ASPD +10% และ MATK เพิ่มตาม AGI) · Nine Lives (Job 4): โดนมอนตีจนควรตายจะรอดแล้วฟื้น HP สูงสุด 30% ทุก 5 นาทีที่ระดับ 10","อาวุธประจำอาชีพ Neko Flask (MATK 5 · INT 1) ซื้อจากร้านค้า NPC ได้ 100 Silver และดรอปจากมอนสเตอร์ · Starter Pack มี Lumina Flask เพิ่มสำหรับผู้ซื้อใหม่"],en:{title:"New class: Nekobaku, the bomb-throwing alchemist cat 🐱",lines:["The 9th class · Unlock it once the same character has Merchant Job Lv.50 and Mamushi Job Lv.50, then pay 120,000 Silver once in the Change Class window (Class button); switching back and forth is free after that · INT +3, AGI +2 · Lobs magic flasks from range: its damage is magic (MATK) and it throws faster the higher its ASPD, so it builds AGI and INT","Fizz Flask (Job 1): a magic flask at one target for 300% MATK that repeats at your attack speed, splashing half of that on monsters within 1.5 cells","Tar Flask (Job 3): an oil flask on the ground for 400% MATK that leaves monsters Oiled for 6 seconds, 30% slower · Big Kaboom (Job 5): an 800% MATK fire barrel bomb over an area, 50% harder on oiled targets, with a chance to burn","Catalyst Brew (Job 7): ASPD +20% for 45 seconds · Passives Alchemy Mastery (MATK +50%) and Feline Reflex (ASPD +10% and MATK from AGI) · Nine Lives (Job 4): a monster blow that would kill you leaves you standing, healed up to 30% HP, every 5 minutes at level 10","Its own weapon, the Neko Flask (MATK 5 · INT 1), is sold by the NPC shop for 100 Silver and drops from monsters · The Starter Pack now includes a Lumina Flask for new buyers"]}},{id:"2026-09-28-kensei-class",date:"2026-09-28",time:"10:33",title:"อาชีพใหม่: Kensei สาวดาบคาตานะ",lines:["อาชีพที่ 8 มาแล้ว! Kensei (เคนเซย์) สาวดาบคาตานะ เคลื่อนที่ว่องไว ฟันเร็วดุจสายฟ้า ปลดล็อกเมื่อตัวละครเดียวกันมี Swordsman Job Lv.50 และ Thief Job Lv.50 แล้วจ่าย 120,000 Silver ครั้งเดียวที่หน้าต่างเปลี่ยนอาชีพ จากนั้นสลับไปมาได้ฟรี","Iaigiri ชักดาบฟันเป้าหมายเดียว ใช้ได้เร็วเท่าความเร็วโจมตี · Oboro Ranbu วาร์ปไปมาฟันศัตรูรอบตัวแบบสุ่ม 20 ครั้งใน 5 วินาที (ตัวเดิมโดนซ้ำได้) · Issen พุ่งเข้าหาเป้าหมายในพริบตา ฟันทุกตัวตามแนวที่พุ่งผ่าน · Meikyo Shisui บัฟ ASPD +20% และ CRIT +20 นาน 45 วินาที","พาสซีฟ: Katana Mastery (ATK +40% และ CRIT +10 เมื่อถือคาตานะ) · Shukuchi (วิ่งเร็วขึ้น 20% และ FLEE +10%) · Zanshin (ดาเมจคริติคอล +30% และ ATK ตาม AGI)","อาวุธประจำอาชีพ Katana ซื้อได้ที่ร้านค้า 100 Silver และดรอปจากมอนสเตอร์ทุกตัวแบบมีระดับ (tier) เหมือนอาวุธอาชีพอื่น","Starter Pack มี Lumina Katana เพิ่มสำหรับ Kensei ใครซื้อ Starter Pack ไปแล้วจะได้รับทางจดหมาย 1 ชิ้นเมื่อเข้าเกมครั้งถัดไป"],en:{title:"New class: Kensei, the katana swordswoman",lines:["The eighth class is here! Kensei, a katana swordswoman who moves swiftly and strikes like lightning. Unlock her once the same character has Swordsman Job Lv.50 and Thief Job Lv.50, then pay 120,000 Silver once in the Change Class window; switching back and forth is free after that","Iaigiri is a quick-draw cut on one target that recycles at attack speed · Oboro Ranbu teleports between random nearby enemies for 20 cuts in 5 seconds (the same enemy can be hit again) · Issen dashes to the target in a flash and cuts everything along the path · Meikyo Shisui gives ASPD +20% and CRIT +20 for 45 seconds","Passives: Katana Mastery (ATK +40% and CRIT +10 with a katana) · Shukuchi (20% faster running and FLEE +10%) · Zanshin (critical damage +30% and ATK from AGI)","Her own weapon, the Katana, is sold in the shop for 100 Silver and drops from every monster by tier like the other classes' weapons","The Starter Pack now includes a Lumina Katana for the Kensei; players who already bought it receive one by mail on their next login"]}},{id:"2026-09-28-in-game-patch-notes-english",date:"2026-09-28",time:"10:15",title:"แจ้งอัปเดตในเกมแสดงภาษาอังกฤษตามภาษาที่เลือก",lines:["แถบแจ้งอัปเดตด้านบนและหัวข้ออัปเดตในแชทระบบ แสดงเป็นภาษาอังกฤษเมื่อเลือกภาษาอื่นที่ไม่ใช่ไทย เลือกภาษาไทยก็ยังเป็นภาษาไทยเหมือนเดิม"],en:{title:"In-game update notices follow your language",lines:["The update bar at the top and the patch-note headlines in system chat now show in English when any language other than Thai is selected; Thai stays Thai."]}},{id:"2026-09-28-skill-sounds",date:"2026-09-28",time:"10:11",title:"ทุกสกิลมีเสียงของตัวเอง",lines:["สกิลที่กดใช้ได้ทั้ง 31 สกิลมีเสียงเฉพาะที่เข้ากับสกิล เช่น Flame Burst ดังตูมพร้อมเสียงไฟปะทุ, Frost Area เสียงน้ำแข็งแตก, Stormbreak ฟ้าผ่าคำราม, Gold Strike มีเสียงเหรียญกริ๊ง, Dokugiri เสียงพ่นหมอกพิษ","แยกออกได้ด้วยหูว่าใครใช้สกิลอะไร แทนเสียงเดียวที่สกิลโจมตีทุกตัวใช้ร่วมกันก่อนหน้านี้","เสียงสกิลของตัวเองดังเต็มที่เสมอ แม้เป้าหมายจะอยู่ไกล"],en:{title:"Every skill has its own sound",lines:["All 31 active skills now have their own sound to match: Flame Burst booms with crackling fire, Frost Area cracks like ice, Stormbreak rolls with thunder, Gold Strike clinks with coins, Dokugiri hisses with poison mist, and more.","You can tell by ear who used which skill, instead of every attack skill sharing one sound.","Your own skills always play at full volume, even when the target is far away."]}},{id:"2026-09-28-patch-notes-english",date:"2026-09-28",time:"10:09",title:"บันทึกการอัปเดตภาษาอังกฤษครบทุกรายการ",lines:["หน้าบันทึกการอัปเดตเมื่อเลือกภาษาอังกฤษ แสดงเป็นภาษาอังกฤษครบทุกอัปเดตย้อนหลังแล้ว ไม่มีรายการที่ยังเป็นภาษาไทยปนอยู่"],en:{title:"Every patch note now reads in English",lines:["With English selected, the Patch Notes page now shows every past update in English, with no entries left in Thai."]}},{id:"2026-09-28-skill-rush-all-classes",date:"2026-09-28",time:"10:02",title:"สกิลโจมตีเป้าหมายเดียวทุกอาชีพ วิ่งเข้าหาเร็ว 2 เท่า",lines:["กดสกิลโจมตีเป้าหมายเดียวใส่มอนสเตอร์ที่อยู่ไกล ตัวละครจะวิ่งเข้าหาเร็ว 2 เท่า ได้ทุกอาชีพ ไม่ใช่แค่ Twin Fang","คำอธิบายสกิลเหล่านี้เขียนบอกไว้แล้ว"],en:{title:"Every class rushes in at double speed with single-target skills",lines:["Use a single-target attack skill on a distant monster and your character runs to it at double speed. This now works for every class, not just Twin Fang.","The descriptions of these skills now say so."]}},{id:"2026-09-28-twin-fang-rush",date:"2026-09-28",time:"09:55",title:"เผยความลับของ Twin Fang",lines:["กด Twin Fang ใส่มอนสเตอร์ที่อยู่ไกล ตัวละครจะวิ่งเข้าหาเร็ว 2 เท่า ความสามารถนี้มีอยู่แล้ว ตอนนี้เขียนไว้ในคำอธิบายสกิลด้วย"],en:{title:"Twin Fang's secret revealed",lines:["Use Twin Fang on a distant monster and your character runs to it at double speed. This already worked; the skill description now says so."]}},{id:"2026-09-28-checkout-game-name",date:"2026-09-28",time:"09:31",title:"หน้าชำระเงินขึ้นชื่อ Lumivara Online",lines:["หน้าจ่ายเงินของร้านแสดงชื่อ Lumivara Online พร้อมไอคอนเกมที่ด้านบน แทนชื่อบัญชีผู้รับเงิน จะได้มั่นใจว่ากำลังจ่ายให้เกม","ใบเสร็จและเงื่อนไขการชำระเงินยังระบุชื่อผู้ขายตามกฎหมายเหมือนเดิม"],en:{title:"Checkout now shows Lumivara Online",lines:["The shop's checkout page now shows Lumivara Online with the game's icon at the top instead of the payee account name, so you can be sure you're paying the game.","The receipt and payment terms still show the legal seller name as before."]}},{id:"2026-09-28-google-pay",date:"2026-09-28",time:"09:08",title:"จ่ายเงินในร้านด้วย Google Pay ได้แล้ว",lines:["หน้าชำระเงินของร้านมีปุ่ม Google Pay สำหรับผู้เล่นที่ใช้ Chrome หรือ Android และผูกบัตรไว้กับบัญชี Google แล้ว กดจ่ายได้ทันทีโดยไม่ต้องพิมพ์เลขบัตร","บัตรเครดิต/เดบิต PromptPay และ Apple Pay ยังใช้ได้เหมือนเดิม"],en:{title:"Pay in the shop with Google Pay",lines:["The shop's checkout page now has a Google Pay button for players on Chrome or Android with a card saved to their Google account — pay instantly without typing a card number.","Credit/debit cards, PromptPay and Apple Pay still work as before."]}},{id:"2026-09-28-loot-skip-disconnect",date:"2026-09-28",time:"08:55",title:"แก้หลุดวนทุก 2 วินาที เมื่อติ๊กไม่เก็บไอเท็มใน Auto Play เยอะ",lines:["ผู้เล่นที่เอาติ๊กออกในรายการเก็บไอเท็มของ Auto Play เกินประมาณ 58 ชิ้น จะหลุดแล้วเชื่อมต่อใหม่วนไปเรื่อย ๆ (code 1008 · Invalid message)","ตอนนี้เซิร์ฟเวอร์รับรายการไม่เก็บได้ครบทุกชิ้นแล้ว ไม่ต้องติ๊กกลับ"],en:{title:"Fixed disconnecting every 2 seconds with many Auto Play loot items unticked",lines:["Players who unticked more than about 58 items in the Auto Play loot list would get disconnected and keep reconnecting in a loop (code 1008 · Invalid message).","The server now accepts the full skip list with no limit, so nothing needs to be re-ticked."]}},{id:"2026-09-28-guild-notice",date:"2026-09-28",time:"08:40",title:"หน้ากิลมีช่องประกาศกิล วางลิงก์ Discord ได้",lines:['หัวหน้ากิลกดปุ่ม "แก้ไข" ที่ช่องประกาศกิลในหน้ากิล เพื่อเขียนข้อความถึงสมาชิกได้สูงสุด 300 ตัวอักษร 6 บรรทัด เช่น ลิงก์ Discord ของกิลหรือเวลานัดล่าบอส',"ลิงก์ที่ขึ้นต้นด้วย https:// กดเปิดได้ทันที สมาชิกทุกคนเห็นประกาศเมื่อเปิดหน้ากิล","ลบข้อความทั้งหมดแล้วกดบันทึกเพื่อปิดประกาศ · คำหยาบนอกลิงก์จะถูกเซ็นเซอร์เหมือนในแชท"],en:{title:"Guild page gets a guild notice box, links included",lines:['The guild leader can press "Edit" on the guild notice box in the guild page to write a message to members, up to 300 characters and 6 lines — for example a guild Discord link or a boss hunt schedule.',"A link starting with https:// can be tapped open directly, and every member sees the notice when they open the guild page.","Clear the text and press Save to take the notice down · Rude words outside a link are censored just like in chat."]}},{id:"2026-09-28-refine-list-right",date:"2026-09-28",time:"08:27",title:"ช่างตีบวก: รายการอุปกรณ์ย้ายไปด้านขวา พร้อมสเตตัส",lines:['หน้าต่างช่างตีบวกกว้างขึ้น ทั่งตีบวกอยู่ด้านซ้าย รายการ "เลือกอุปกรณ์" อยู่ด้านขวา',"อุปกรณ์แต่ละชิ้นในรายการแสดงสเตตัส การ์ดที่ใส่ และค่าตีบวกไว้ใต้ชื่อ เหมือนกระเป๋าแบบรายการ เทียบได้โดยไม่ต้องเปิดดูทีละชิ้น"],en:{title:"Blacksmith: the gear list moves to the right, with stats",lines:['The Blacksmith window is wider now, with the anvil on the left and the "Choose gear" list on the right.',"Each piece in the list now shows its stats, socketed card and refine level under its name, like the bag's list view, so you can compare pieces without opening each one."]}},{id:"2026-09-28-rome-stepped-shadows",date:"2026-09-28",time:"07:55",title:"เมือง Aurelia มีเงาแดดแบบพิกเซล",lines:["ต้นไซเปรส ธง รูปปั้น และของประดับในเมือง Aurelia ทอดเงาสีน้ำเงินม่วงไปทางขวาล่าง ขอบเป็นขั้นแบบพิกเซลอาร์ต","แสงแดดมาจากทิศเดียวกันทั้งเมือง มินิแมปก็เห็นเงาเหมือนกัน","เงาวาดไว้ตั้งแต่ตอนเข้าเมือง จึงไม่ทำให้เกมหน่วงลง"],en:{title:"Aurelia Forum gets pixel-art sun shadows",lines:["Cypress trees, banners, statues and decorations in Aurelia Forum now cast blue-purple shadows toward the bottom-right, with stepped pixel-art edges.","The sunlight comes from the same direction across the whole town, and the shadows show on the minimap too.","The shadows are baked in when you enter the town, so they don't slow the game down."]}},{id:"2026-09-28-bag-rarity-name-contrast",date:"2026-09-28",time:"07:53",title:"ชื่ออุปกรณ์ในกระเป๋าอ่านง่ายขึ้น",lines:["ชื่ออุปกรณ์ในกระเป๋าแบบรายการใช้สีระดับโทนเข้มขึ้น ชื่อสีทองบนแถบสีทองไม่จมหายแล้ว สีเขียว ฟ้า ม่วง ก็อ่านชัดขึ้นเช่นกัน"],en:{title:"Gear names in the bag are easier to read",lines:["Gear names in the bag's list view now use darker rarity colors, so a gold name on a gold bar no longer disappears, and green, blue and purple read more clearly too."]}},{id:"2026-09-28-relic-box-open-all",date:"2026-09-28",time:"07:48",title:"Mystery Relic Box: ปุ่มเปิดทั้งหมด",lines:['หน้าต่างรายละเอียดของ Mystery Relic Box มีปุ่ม "เปิดทั้งหมด" เปิดทุกกล่องในกองได้ในครั้งเดียว (สูงสุดครั้งละ 500 กล่อง)',"โอกาสได้ของต่อกล่องเท่าเดิมทุกอย่าง ถ้ากระเป๋าเต็มหรือน้ำหนักเกินจะหยุดเปิด กล่องที่เหลือยังอยู่ในกระเป๋า","ของที่ได้ทั้งหมดแสดงในแชทระบบ ส่วนการ์ดและอุปกรณ์ขึ้นป้ายแจ้งเตือนเหมือนเดิม"],en:{title:"Mystery Relic Box: an Open all button",lines:['The Mystery Relic Box detail window has an "Open all" button that opens every box in the stack at once (up to 500 boxes per click).',"The drop odds per box are unchanged. If the bag fills up or gets overweight, opening stops and the remaining boxes stay in the bag.","Everything received is listed in the system chat, and cards and gear still show their usual alert popup."]}},{id:"2026-09-28-bag-list-stats",date:"2026-09-28",time:"07:45",title:"กระเป๋าแบบรายการโชว์สเตตัสอุปกรณ์",lines:["เปิดกระเป๋าแบบรายการ (ปุ่มลิสต์) อุปกรณ์ทุกชิ้นจะมีสเตตัสบรรทัดเล็กใต้ชื่อ เช่น CRIT +15 · HIT +20 · AGI +5 เหมือนกระเป๋ากระต่าย รวมการ์ดที่ฝังอยู่ด้วย ไม่ต้องกดเปิดดูทีละชิ้น"],en:{title:"Bag's list view shows gear stats",lines:["Open the bag's list view (the list button) and every piece shows a small stat line under its name, e.g. CRIT +15 · HIT +20 · AGI +5, like the rabbit bag, including any socketed card — no need to open each piece to check."]}},{id:"2026-09-28-bot-skill-order-only",date:"2026-09-28",time:"07:38",title:"สกิลอัตโนมัติเหลือแบบตั้งลำดับเองอย่างเดียว",lines:['หน้าต่าง Auto Play › สกิลอัตโนมัติ ไม่มีตารางติ๊กสกิลและช่อง "ตั้งลำดับสกิลเอง" แล้ว บอทร่ายไล่ตามลำดับที่ตั้งไว้แล้ววนซ้ำเสมอ',"ใครเคยใช้แบบติ๊กไว้ สกิลที่ติ๊กจะถูกเรียงเป็นลำดับให้อัตโนมัติ (ฮีล → บัฟ → สกิลวงกว้าง → สกิลเป้าเดียว) · ตัวละครใหม่ได้สกิลโจมตีทุกอันของอาชีพใส่ไว้ในลำดับตั้งแต่แรก","ลำดับที่เคยตั้งไว้แล้วยังอยู่ครบ · โหมดบัฟอย่างเดียว ถ้าลำดับไม่มีฮีล/บัฟเลย จะใช้ฮีลและบัฟทุกอันของอาชีพ"],en:{title:"Auto skills now use only a custom order",lines:[`The Auto Play › Auto skills window no longer has a skill tick table or a "Custom skill order" checkbox — the bot always casts through the order you've set and loops it.`,"If you used the tick table before, your ticked skills were automatically arranged into an order (heal → buff → AoE skill → single-target skill) · New characters start with every attack skill of their class already in the order.","Any order you had already set is kept in full · in buff-only mode, if the order has no heal or buff at all, every heal and buff of your class is used instead."]}},{id:"2026-09-28-bag-rarity-tint",date:"2026-09-28",time:"07:41",title:"ช่องไอเท็มในกระเป๋าแสดงสีระดับชัดขึ้น",lines:["อุปกรณ์ระดับ ดี · หายาก · ยอดเยี่ยม · ตำนาน ระบายสีเขียว ฟ้า ม่วง ทอง เต็มช่อง พร้อมขอบสีทึบรอบช่อง แยกกันได้ในแวบเดียว ไม่ใช่แค่ขอบจาง ๆ แบบเดิม","ของตำนานมีแสงทองรอบช่องเพิ่ม · ไอเท็มธรรมดายังเป็นช่องสีกระดาษเหมือนเดิม","มุมมองแบบรายการก็ระบายสีตามระดับเช่นกัน"],en:{title:"Bag slots show rarity colors more clearly",lines:["Good, Rare, Epic and Legendary gear now fill the whole slot with green, blue, purple or gold and add a solid border around it, so you can tell them apart at a glance instead of just a faint edge like before.","Legendary items also get a gold glow around the slot · Common items still keep their plain paper-colored slot.","The list view is tinted by rarity too."]}},{id:"2026-09-28-bot-loot-fold",date:"2026-09-28",time:"07:38",title:"รายการเลือกไอเท็มของ Auto Play ย่อ/ขยายได้",lines:['ในหน้าตั้งค่า Auto Play ส่วน "เลือกทีละชิ้น" กดหัวข้อ Consumption หรือ ETC เพื่อย่อหรือขยายรายการได้ ไม่ต้องเลื่อนผ่านวัตถุดิบยาวทั้งหมด',"หัวข้อบอกจำนวนที่เลือกเก็บไว้ เช่น เก็บ 58/60 และเกมจำว่าเปิดหมวดไหนไว้"],en:{title:"Auto Play's item pick list can collapse and expand",lines:[`In the Auto Play settings, the "Pick individually" section lets you press the Consumption or ETC heading to collapse or expand that list, so you don't have to scroll past a long list of materials.`,"Each heading shows how many items are set to keep, e.g. Keep 58/60, and the game remembers which category you left open."]}},{id:"2026-09-28-market-premium-badge-result",date:"2026-09-28",time:"07:37",title:"ป้าย Premium ในตลาดไม่ทับข้อความผลซื้อขาย",lines:['ซื้อหรือขายในตลาดแล้ว ข้อความผลลัพธ์ขึ้นแทนที่ป้าย "Premium - ซื้อขายได้จากทุกที่" ชั่วคราว อ่านได้ครบ ไม่ถูกแถบสีน้ำเงินบัง',"ผ่านไป 8 วินาทีป้าย Premium กลับมาเหมือนเดิม ข้อความยังดูย้อนหลังได้ที่ปุ่ม ประวัติซื้อขาย"],en:{title:"The Premium badge no longer covers market trade results",lines:['After buying or selling on the market, the result message now temporarily replaces the "Premium - trade from anywhere" badge, so you can read it in full instead of it being hidden behind the blue bar.',"After 8 seconds the Premium badge returns as before, and you can still look back at the message from the Trade history button."]}},{id:"2026-09-28-ranking-mamushi-icon",date:"2026-09-28",time:"07:30",title:"ไอคอนอาชีพ Mamushi ในหน้าอันดับ EXP",lines:["หน้าต่างอันดับ EXP แสดงรูปคุไนหน้าอาชีพ Mamushi แล้ว เดิมขึ้นเป็นรูปเสีย"],en:{title:"Mamushi class icon on the EXP ranking page",lines:["The EXP ranking window now shows a kunai icon in front of the Mamushi class name, instead of a broken image."]}},{id:"2026-09-28-overweight-auto-stays",date:"2026-09-28",time:"07:23",title:"น้ำหนักเกิน 90% Auto Play หยุดอยู่กับที่ ไม่บินกลับเมืองเอง",lines:["เมื่อน้ำหนักเกิน 90% Auto Play จะหยุดและตัวละครยืนอยู่ที่เดิม ไม่ใช้ Butterfly Wing กลับเมืองเองหลังนับถอยหลังอีกต่อไป","หน้าต่างแจ้งเตือนยังมีปุ่ม กลับเมืองตอนนี้ ถ้ามี Butterfly Wing ติดตัว จะบินกลับก็ต่อเมื่อกดเองเท่านั้น"],en:{title:"Over 90% weight, Auto Play now stops in place instead of flying home",lines:["When weight goes over 90%, Auto Play now stops and your character stays put, instead of using a Butterfly Wing to fly home on its own after a countdown.","The warning window still has a Return to town now button — if you're carrying a Butterfly Wing, it only flies you home when you press it yourself."]}},{id:"2026-09-28-ring-compare-slot",date:"2026-09-28",time:"07:14",title:"หน้าต่างแหวนบอกช่องที่จะใส่ถูกต้อง",lines:['แหวนทุกวงเขียนตำแหน่งเป็น "เครื่องประดับ 1 / เครื่องประดับ 2" ให้รู้ว่าใส่ได้ทั้งสองช่อง','ส่วนเทียบกับของที่สวมอยู่บอกช่องที่แหวนจะลงจริง เดิมแหวน Ruby ขึ้นว่า "เครื่องประดับ 1" ตลอด แม้ตัวเลขสีแดงจะเป็นค่าของแหวนในช่อง 2',"แหวนที่สวมทั้งสองช่องยังนับค่าเต็มทั้งคู่เหมือนเดิม"],en:{title:"The ring window now names the right slot",lines:[`Every ring's slot now reads "Accessory 1 / Accessory 2", so you know it can go in either slot.`,'The comparison against your worn gear now names the slot the ring would actually go into. Before, a Ruby Ring always showed "Accessory 1", even when the red numbers were for the ring in slot 2.',"Rings worn in both slots still count their full value in each, as before."]}},{id:"2026-09-28-world-map-refresh",date:"2026-09-28",time:"07:12",title:"แผนที่โลกแสดงภาพใหม่ทันที",lines:["ภาพ World Map ที่มีโคลอสเซียมและลานหุ่นฟางโหลดใหม่ทันทีหลังรีเฟรช ไม่ค้างภาพเก่าในเครื่อง",'ป้าย "คุณอยู่ที่นี่" ขึ้นทับป้ายแมพข้างเคียงแล้ว ไม่ถูกบังตอนอยู่ช่องเขาหิมะ และขยับป้าย Stormcrest Peaks ออกให้อ่านง่ายขึ้น'],en:{title:"World Map shows the new painting right away",lines:["The World Map painting with the colosseum and dummy yard now loads right after a refresh instead of an old cached copy.",'The "you are here" badge now sits above neighbouring map plates, so Frostveil Pass no longer hides it, and the Stormcrest Peaks plate moves aside to stay readable.']}},{id:"2026-09-28-dex-matk-1",date:"2026-09-28",time:"07:07",title:"ปรับ DEX เป็น MATK +1 ต่อแต้ม",lines:["DEX ทุกแต้มให้ MATK +1 (จากรอบก่อน +2 ต่อแต้ม) ทุกอาชีพได้เหมือนกัน รวม DEX จากอุปกรณ์และบัฟด้วย","ยังคูณกับ Mage Mastery เหมือน MATK จาก INT · มีผลทันที ไม่ต้องรีเซ็ตสเตตัส"],en:{title:"DEX now gives MATK +1 per point",lines:["Every point of DEX now gives MATK +1 (down from +2 per point last update), the same for every class, including DEX from gear and buffs.","It still multiplies with Mage Mastery like MATK from INT · takes effect immediately, no stat reset needed."]}},{id:"2026-09-28-mall-card-price-wrap",date:"2026-09-28",time:"07:04",title:"แก้ข้อความการ์ด Item Mall ล้นกรอบ",lines:["การ์ดชุดลดราคาใน Item Mall (เช่น Gym Pass 10 ใบ) ไม่ตัดข้อความกลางประโยคแล้ว ราคาเดิมที่ขีดฆ่าขึ้นบรรทัดใหม่เมื่อที่ไม่พอ"],en:{title:"Fixed Item Mall card text overflowing its box",lines:["Bundle discount cards in the Item Mall (like the 10-pack Gym Pass) no longer cut text off mid-sentence — the struck-through original price now wraps to a new line when there isn't enough room."]}},{id:"2026-09-28-megaphone-mall",date:"2026-09-28",time:"06:46",title:"โทรโข่งวางขายใน Item Mall · โปรเปิดตัวลดสูงสุด 30%",lines:["Item Mall มีหน้าใหม่ Megaphone: 1 อัน 10 Gold · 5 อัน 45 Gold (-10%) · 10 อัน 80 Gold (-20%) · 30 อัน 210 Gold (-30%)","ดับเบิลคลิกโทรโข่งในแท็บ Cash ของกระเป๋า หรือกดปุ่ม 📢 ข้างแชท แล้วพิมพ์ข้อความ · มีโทรโข่งในกระเป๋าจะใช้โทรโข่งก่อน ไม่มีค่อยจ่าย 10 Gold","ส่งไม่สำเร็จ (คิวเต็ม ข้อความไม่สุภาพ หรือเซิร์ฟเวอร์ไม่ตอบ) ได้โทรโข่งหรือ Gold คืนอัตโนมัติ","โทรโข่งผูกกับตัวละคร ขายและเทรดไม่ได้"],en:{title:"Megaphone now sold in the Item Mall · launch deal up to -30%",lines:["The Item Mall has a new Megaphone page: 1 for 10 Gold · 5 for 45 Gold (-10%) · 10 for 80 Gold (-20%) · 30 for 210 Gold (-30%).","Double-click a Megaphone on the bag's Cash tab, or press the 📢 button beside chat, then type your message · If you have one in your bag it's used first; without one, it costs 10 Gold instead.","If a shout fails to send (full queue, rude words, or the server not answering), your Megaphone or Gold is refunded automatically.","Megaphones are character-bound and cannot be sold or traded."]}},{id:"2026-09-28-rename-card-1700",date:"2026-09-28",time:"06:41",title:"Rename Card ราคาใหม่ 1,700 Gold",lines:["Rename Card ใน Item Mall ปรับราคาจาก 300 เป็น 1,700 Gold ต่อใบ","การ์ดที่ซื้อไว้แล้วยังใช้เปลี่ยนชื่อได้ตามปกติ"],en:{title:"Rename Card's new price: 1,700 Gold",lines:["The Rename Card in the Item Mall now costs 1,700 Gold per card, up from 300.","Cards you already bought still work as normal for renaming."]}},{id:"2026-09-28-megaphone",date:"2026-09-28",time:"06:33",title:"โทรโข่ง 📢 ประกาศถึงทุกคนทุกภูมิภาค",lines:["กดปุ่ม 📢 ข้างช่องพิมพ์แชท พิมพ์ข้อความ (สูงสุด 80 ตัวอักษร) แล้วส่ง · ใช้ 10 Gold ต่อครั้ง ข้อความขึ้นจอผู้เล่นทุกคนทุกภูมิภาค 20 วินาที พร้อมเสียงเตือน","ถ้ามีคนใช้อยู่ ข้อความใหม่จะต่อคิว รอให้ข้อความก่อนหน้าครบ 20 วินาทีแล้วค่อยขึ้น · หน้าต่างส่งบอกจำนวนคิวและเวลารอ","Gold ถูกหักเมื่อข้อความเข้าคิวสำเร็จเท่านั้น · ข้อความมีคำไม่สุภาพหรือคิวเต็มจะไม่เสีย Gold",'ไม่อยากเห็น: ตั้งค่า › การเล่นเกม › ปิด "แสดงโทรโข่ง" · ปิดเฉพาะเสียงได้ที่ ตั้งค่า › เสียง › โทรโข่ง',"แถบประกาศด้านบนเลื่อนลงมาอยู่ใต้แถวเมนู ไม่บังปุ่มเมนูแล้ว"],en:{title:"Megaphone 📢 shouts to everyone in every region",lines:["Press the 📢 button beside the chat box, type your message (up to 80 characters) and send · It costs 10 Gold per shout, and the message shows on every player's screen in every region for 20 seconds, with an alert sound.","If someone else is already shouting, your new message joins the queue and waits until the previous one finishes its 20 seconds · The send window shows the queue length and the wait time.","Gold is only deducted once your message joins the queue successfully · A message with rude words or a full queue costs no Gold.",`Don't want to see them: Settings › Gameplay › turn off "Show Megaphone" · To mute just the sound, go to Settings › Sound › Megaphone.`,"The announcement bar at the top has moved down below the menu row, so it no longer covers the menu buttons."]}},{id:"2026-09-28-dex-matk-2",date:"2026-09-28",time:"06:29",title:"DEX เพิ่ม MATK 2 ต่อแต้ม",lines:["DEX ทุกแต้มให้ MATK +2 (เดิมทุก 5 DEX ได้ MATK +1) ทุกอาชีพได้เหมือนกัน รวม DEX จากอุปกรณ์และบัฟด้วย","ยังคูณกับ Mage Mastery เหมือน MATK จาก INT · มีผลทันที ไม่ต้องรีเซ็ตสเตตัส"],en:{title:"DEX now adds MATK 2 per point",lines:["Every point of DEX now gives MATK +2 (previously +1 for every 5 DEX), the same for every class, including DEX from gear and buffs.","It still multiplies with Mage Mastery like MATK from INT · takes effect immediately, no stat reset needed."]}},{id:"2026-09-28-donation-target-1m",date:"2026-09-28",time:"06:15",title:"ระดมทุน EXP ลดเป้าเหลือ 1,000,000 Silver",lines:["เป้าระดมทุน EXP ทั้งเซิร์ฟลดจาก 20,000,000 เหลือ 1,000,000 Silver ครบเป้าเมื่อไหร่ได้ EXP x1.5 ทั้งเซิร์ฟเวอร์ 2 ชั่วโมงเหมือนเดิม","ยอดที่บริจาคไว้แล้วยังนับต่อ ครบเป้าซ้อนกันได้ เวลาสะสมสูงสุด 12 ชั่วโมง"],en:{title:"Server EXP Fund goal lowered to 1,000,000 Silver",lines:["The Server EXP Fund goal is down from 20,000,000 to 1,000,000 Silver. Reaching it still gives the whole server EXP x1.5 for 2 hours, as before.","Silver already donated still counts, the goal can be reached again to stack the bonus, and the accumulated time caps at 12 hours."]}},{id:"2026-09-28-party-merge",date:"2026-09-28",time:"06:01",title:"หัวหน้าปาร์ตี้ขอรวมปาร์ตี้ได้",lines:['หัวหน้าปาร์ตี้กด "ขอรวมปาร์ตี้" ใน Party Finder หรือ "ขอเข้าปาร์ตี้" จากชื่อผู้เล่นในแชท เพื่อขอพาทั้งปาร์ตี้ไปรวมกับอีกปาร์ตี้ได้แล้ว',"หัวหน้าอีกฝ่ายเห็นว่ามีกี่คนขอเข้ามา กดรับแล้วสมาชิกทุกคนย้ายเข้าปาร์ตี้นั้นทันที หัวหน้าและการตั้งค่าเป็นของปาร์ตี้ที่รับ","ถ้ารวมกันแล้วเกิน 12 คน ระบบไม่ส่งคำขอ และแจ้งกลับทันทีว่ารวมกันแล้วกี่คน เกินสูงสุดเท่าไร"],en:{title:"Party leaders can now request a party merge",lines:[`A party leader can press "Request merge" in Party Finder, or "Request to join" from a player's name in chat, to ask to bring their whole party into another one.`,"The other leader sees how many players are asking to join, and once they accept, every member moves into that party immediately — the leader and settings stay whichever party accepted.","If the combined parties would exceed 12 members, the request isn't sent, and you're told right away how many that would be and by how much it's over the limit."]}},{id:"2026-09-28-boost-scroll-pause-offline",date:"2026-09-28",time:"05:56",title:"EXP / Drop Scroll ไม่เสียเวลาตอนออฟไลน์",lines:["เวลาของ EXP Scroll และ Drop Scroll เดินเฉพาะตอนอยู่ในเกม ออกจากเกม เน็ตหลุด หรือเซิร์ฟเวอร์รีสตาร์ท เวลาที่เหลือจะหยุดไว้ แล้วนับต่อเมื่อกลับเข้าเกม","ข้อนี้ใช้กับเวลาที่เหลืออยู่ตอนออกจากเกมครั้งถัดไปเป็นต้นไป"],en:{title:"EXP / Drop Scroll no longer burns time while offline",lines:["EXP Scroll and Drop Scroll time now only counts down while you're in the game. Logging out, losing connection or a server restart pauses the remaining time, and it resumes when you're back in.","This applies to whatever time you still have left, starting from your next time leaving the game."]}},{id:"2026-09-28-mage-freeze-stun-20",date:"2026-09-28",time:"05:50",title:"ลดโอกาสแช่แข็งและสตันของสกิลนักเวท",lines:["Frost Area: โอกาสแช่แข็งต่อเกล็ดน้ำแข็งแต่ละลูกลดจาก 50% เหลือ 20%","Stormbreak: โอกาสสตันต่อสายฟ้าแต่ละลูกลดจาก 50% เหลือ 20%","ระยะเวลาแช่แข็ง/สตันและโบนัสดาเมจเวทใส่เป้าที่แข็งอยู่เท่าเดิม"],en:{title:"Lower freeze and stun chance for Mage skills",lines:["Frost Area: the freeze chance per ice shard is down from 50% to 20%.","Stormbreak: the stun chance per lightning bolt is down from 50% to 20%.","The freeze/stun duration and the magic damage bonus against a frozen/stunned target are unchanged."]}},{id:"2026-09-28-party-finder-stuck-loading",date:"2026-09-28",time:"05:44",title:'แก้ Party Finder ค้าง "กำลังโหลดรายการปาร์ตี้…"',lines:["ถ้าโหลดรายการปาร์ตี้ไม่สำเร็จ หน้าต่างจะบอกว่าโหลดไม่ได้ให้กดรีเฟรช แทนที่จะค้างคำว่ากำลังโหลดไปตลอด · รอเกิน 10 วินาทีก็นับว่าโหลดไม่สำเร็จเช่นกัน",'ติ๊ก "ประกาศปาร์ตี้นี้" แล้วระบบไม่ตอบ ช่องจะกลับเป็นสถานะจริง ไม่ค้างเป็นติ๊กทั้งที่ยังไม่มีปาร์ตี้',"ข้อมูลในเกมจุดเดียวที่ผิดพลาดจะไม่ทำให้ข้อความอื่นที่มาพร้อมกัน เช่น รายการปาร์ตี้หรือผลการเทรด หายไปด้วยอีก"],en:{title:'Fixed Party Finder stuck on "Loading parties…"',lines:[`If the party list fails to load, the window now says it couldn't load and to press refresh, instead of staying on "Loading" forever · Waiting more than 10 seconds also counts as a failed load.`,'If ticking "List this party" gets no response, the checkbox now reverts to its real state, instead of staying ticked while no party actually exists.',"A single piece of bad game data no longer takes down other messages that arrive alongside it, such as the party list or trade results."]}},{id:"2026-09-28-max-level-aura-red",date:"2026-09-28",time:"05:45",title:"ออร่าเลเวลสูงสุดเปลี่ยนเป็นสีแดง",lines:["ออร่ารอบตัวละครที่ถึงเลเวลสูงสุดเปลี่ยนจากสีทองเป็นสีแดง ทั้งวงแหวน ลำแสง ประกาย และเงาเรืองรอบตัว","แยกออกจากแสงทองของอาวุธตีบวก +10 ได้ชัดขึ้น"],en:{title:"Max-level aura is now red",lines:["The aura around a max-level character is now red instead of gold — the ring, beams, sparkles and the glow around the body all change.","This makes it easier to tell apart from the gold glow of a +10 refined weapon."]}},{id:"2026-09-28-premium-storage-anywhere",date:"2026-09-28",time:"05:42",title:"Premium เปิดคลังได้ทุกที่ และย้าย Shop เข้าเมนู Premium",lines:["เมนู Premium (ปุ่มมงกุฎ) มีปุ่มคลังเก็บของใหม่ ผู้เล่น Premium ฝาก–ถอนของได้จากทุกแมพ ไม่ต้องเดินกลับไปหาเจ้าหน้าที่คลัง","เปิดคลังค้างไว้ระหว่างบอททำงานได้ บอทยังล่ามอนและเก็บของต่อ ฝาก–ถอนแล้วตัวละครไม่หยุด","ค่าเปิดคลัง 100 Silver จ่ายครั้งเดียวต่อการเข้าแมพ","ปุ่ม Shop ย้ายจากแถบเมนูเข้าไปอยู่ในเมนู Premium แถบเมนูจึงสั้นลงอีกช่อง"],en:{title:"Premium opens Storage anywhere, and Shop moves into the Premium menu",lines:["The Premium menu (the crown button) has a new Storage button. Premium players can deposit and withdraw from any map, without walking back to the Storage Keeper.","You can leave Storage open while Auto Play keeps running — it keeps hunting and looting, and depositing or withdrawing doesn't stop your character.","Opening Storage costs 100 Silver, paid once per map visit.","The Shop button has moved from the menu bar into the Premium menu, so the menu bar is one slot shorter."]}},{id:"2026-09-28-mob-element-icon",date:"2026-09-28",time:"05:35",title:"ชี้มอนเห็นไอคอนธาตุหน้าชื่อ",lines:["เอาเมาส์ชี้มอนสเตอร์ ป้ายชื่อจะมีไอคอนธาตุนำหน้า (🔥ไฟ 💧น้ำ 🌀ลม 🍃ดิน ☀แสง ☾มืด) ดูได้ทันทีว่าควรใช้สกิลธาตุไหน"],en:{title:"Monster element icon on hover",lines:["Hovering a monster now shows its element icon (🔥 fire, 💧 water, 🌀 wind, 🍃 earth, ☀ light, ☾ dark) in front of its name, so you can pick the right elemental skill at a glance."]}},{id:"2026-09-28-spell-total-per-caster",date:"2026-09-28",time:"05:36",title:"TOTAL ดาเมจเวทรวมเป็นก้อนเดียว",lines:["ป้าย TOTAL สีเหลืองของสกิลเวทรวมดาเมจทุกฮิต ทุกสกิล และทุกเป้าหมายของเราไว้ในป้ายเดียว แทนที่จะแยกเป็นหลายป้ายซ้อนกันตามการร่ายแต่ละครั้งและมอนแต่ละตัว","ร่ายต่อเนื่องตัวเลขก็บวกต่อไปเรื่อย ๆ หยุดโดนเกิน 1.4 วินาทีป้ายจึงหายแล้วเริ่มนับใหม่ · ป้ายอยู่กับที่ ไม่กระโดดตามมอนแต่ละตัว","เมจคนอื่นแยกป้ายของใครของมันเหมือนเดิม"],en:{title:"Spell TOTAL damage now combines into one number",lines:["The yellow TOTAL popup for magic skills now adds up every hit, every skill and every target of yours into one number, instead of stacking several separate popups per cast and per monster.","Casting back to back keeps adding to the same total; go more than 1.4 seconds without a hit and it disappears, then starts over · The popup stays put instead of jumping between monsters.","Other Mages still get their own separate popup, as before."]}},{id:"2026-09-28-mentality-dex-matk",date:"2026-09-28",time:"05:31",title:"Mentality: DEX เพิ่ม MATK มากขึ้น 3 เท่า",lines:["พาสซีฟ Mentality ของ Mage ให้ MATK เพิ่มเท่ากับ 10.5% ของ DEX ต่อระดับ (เดิม 3.5%) ระดับ 10 ได้ 105% ของ DEX (เดิม 35%)","ส่วน MATK จาก SP สูงสุดยังเท่าเดิม 1.5% ต่อระดับ (สูงสุด 15%) · มีผลทันทีกับทุกคนที่ลงสกิลไว้แล้ว ไม่ต้องรีเซ็ตสกิล"],en:{title:"Mentality: DEX gives 3x more MATK",lines:["The Mage passive Mentality now gives MATK equal to 10.5% of DEX per rank (up from 3.5%) — at rank 10 that's 105% of DEX (up from 35%).","The MATK from MaxSP is unchanged, at 1.5% per rank (up to 15%) · This takes effect immediately for anyone who already put points into the skill, no skill reset needed."]}},{id:"2026-09-28-bot-hp-potion-tiers",date:"2026-09-28",time:"05:25",title:"บอทเลือกได้ว่าจะใช้ยา HP ขวดไหน",lines:['หน้าต่าง Auto Play › ยาอัตโนมัติ มีช่องติ๊ก Red / Orange / Yellow / White Potion ใต้ "ใช้ยา HP อัตโนมัติ" บอทจะดื่มเฉพาะขวดที่ติ๊กไว้ เช่น ติ๊ก White Potion ออกเพื่อเก็บไว้ตีบอส',"บอทดื่มขวดเล็กสุดที่ติ๊กไว้และยังเหลือก่อน ถ้าขวดที่ติ๊กหมด บอทจะหยุดใช้ยา HP ไม่หยิบขวดที่ติ๊กออก","ค่าเริ่มต้นติ๊กครบทุกขวด บอทจึงทำงานเหมือนเดิมจนกว่าจะเปลี่ยน · ปุ่ม H และช่องยาในฮอตบาร์ยังใช้ขวดเล็กสุดเหมือนเดิม"],en:{title:"Choose which HP Potion tiers the bot uses",lines:[`The Auto Play › Auto potions window has Red / Orange / Yellow / White Potion checkboxes under "Auto-use HP Potions" — the bot only drinks the tiers you've ticked, so you could untick White Potion to save it for a boss fight.`,"The bot drinks the smallest ticked tier it still has first. If every ticked tier runs out, the bot stops using HP Potions instead of reaching for an unticked one.","By default every tier is ticked, so the bot behaves exactly as before until you change it · The H key and the potion hotbar slot still use the smallest tier as always."]}},{id:"2026-09-28-world-map-training",date:"2026-09-28",time:"05:16",title:"World Map แสดง Training Grounds และสนาม PVP",lines:["เพิ่ม Training Grounds บน World Map ทางตะวันออกของป่าเริ่มต้น คู่กับ Aurelia Arena ทางตะวันตก กดเลือกแล้วเดินทางไปลานฝึกหุ่นฟางได้เหมือนแมพอื่น",'เปิด World Map ขณะอยู่ในลานฝึกจะขึ้น "คุณอยู่ที่นี่" ที่ลานฝึก และหน้าข้อมูลโลกแสดงเลเวลแนะนำถึง Lv.270 ตามแมพล่าสุด',"ภาพแผนที่โลกมีโคลอสเซียมของสนาม PVP และลานหุ่นฟางวาดเพิ่มข้างป่าเริ่มต้น เลือกแล้ววงแสงจะล้อมรอบจุดนั้นพอดี"],en:{title:"Training Grounds and the arena on the World Map",lines:["Training Grounds now appears on the World Map east of Verdant Forest, opposite Aurelia Arena to the west. Select it to travel to the dummy yard like any other map.","Opening the World Map inside the yard marks it as your location, and World Info now lists recommended levels up to Lv.270.","The World Map painting now shows the arena colosseum and the dummy yard beside Verdant Forest, and selecting either circles its landmark."]}},{id:"2026-09-28-gym-pass-bundles",date:"2026-09-28",time:"05:06",title:"Gym Pass มีชุด 5 และ 10 ใบ ราคาถูกลง",lines:["Item Mall ขาย Gym Pass เป็นชุดเหมือน Scroll: 5 ใบ 1,215 Gold (-10%) และ 10 ใบ 2,160 Gold (-20%) ใบเดียวยังคง 270 Gold","ชุดที่จะทำให้เกินเพดาน 10 ใบต่อตัวละคร (นับทั้งที่ใช้แล้วและที่ถืออยู่) จะกดซื้อไม่ได้"],en:{title:"Gym Pass now comes in 5- and 10-packs, cheaper",lines:["The Item Mall now sells Gym Pass in bundles like Scrolls: 5 for 1,215 Gold (-10%) and 10 for 2,160 Gold (-20%). A single pass is still 270 Gold.","A bundle that would push you over the 10-per-character limit (counting both used and held passes) can't be bought."]}},{id:"2026-09-28-chat-map-trade-lfg",date:"2026-09-28",time:"05:04",title:"แชทใหม่: แมพ · เทรด · หาปาร์ตี้",lines:["กล่องแชทมีแท็บใหม่ 3 ช่อง: แมพ (คุยกับคนที่อยู่แมพและแชนแนลเดียวกัน), เทรด (ประกาศซื้อ ขาย แลกของ) และหาปาร์ตี้ (ชวนเข้าตี้ หาทีม)","เลือกแท็บแล้วพิมพ์ได้เลย หรือพิมพ์ /m /t /lfg ตามด้วยข้อความจากแท็บไหนก็ได้ · เทรดและหาปาร์ตี้ส่งถึงห้องแชทภาษาเดียวกับแชทโลก","ตั้งค่า → แท็บแชทที่แสดง: ติ๊กเลือกได้ว่าจะให้แท็บไหนโชว์ แท็บที่ซ่อนไว้ ข้อความคุยยังขึ้นในแท็บทั้งหมดตามปกติ","แท็บเยอะเกินความกว้างกล่องแชท เลื่อนแถบแท็บไปด้านข้างได้ (ปัดนิ้ว หรือหมุนลูกกลิ้งเมาส์)"],en:{title:"New chat tabs: Map · Trade · LFG",lines:["The chat box has 3 new tabs: Map (talk to players on the same map and channel), Trade (buy, sell and swap posts) and LFG (invite to a party, look for a team).","Pick a tab and type, or type /m, /t or /lfg followed by your message from any tab · Trade and LFG reach the same language chat room as World chat.","Settings → Chat tabs shown: tick which tabs to show. Messages still arrive in every tab as normal even when a tab is hidden.","When there are more tabs than the chat box is wide, you can scroll the tab bar sideways (swipe, or scroll the mouse wheel)."]}},{id:"2026-09-28-training-reopen",date:"2026-09-28",time:"05:05",title:"เปิดลานฝึกหุ่นฟางอีกครั้ง",lines:["Training Grounds กลับมาเปิดแล้ว ออกเมืองทางใต้เข้าป่าเริ่มต้น ประตูลานฝึกอยู่ด้านขวาของทางเข้าป่า ส่วนประตูสนาม PVP อยู่ทางแยกด้านซ้าย","ในลานฝึกมีหุ่นฟาง Lv.1–250 ให้ทดสอบดาเมจ ไม่ได้ EXP หรือไอเท็ม"],en:{title:"Training Grounds reopened",lines:["Training Grounds is open again. Leave town to the south into Verdant Forest — the training yard's gate is on the right of the forest entrance, while the PVP Arena gate is at the fork on the left.","Inside are straw dummies from Lv.1–250 to test your damage on — no EXP or items."]}},{id:"2026-09-28-effects-setting",date:"2026-09-28",time:"04:50",title:"ตั้งค่าใหม่: ปิดเอฟเฟกต์สกิลได้",lines:['หน้าตั้งค่า › การเล่นเกม มีตัวเลือก "เอฟเฟกต์สกิล" สำหรับเครื่องที่แลคตอนคนเยอะหรือตอนตีบอส',"แสดงทั้งหมด = เหมือนเดิม · เฉพาะของตัวเอง = ซ่อนเอฟเฟกต์สกิล ยา และเลเวลอัพของผู้เล่นคนอื่นกับสกิลมอนสเตอร์ · ปิดเอฟเฟกต์ = ซ่อนทั้งหมด รวมออร่าเลเวลสูงสุด","วงเตือนสกิลบอส แถบร่ายเวท ไอคอนสถานะบนมอน และตัวเลขดาเมจยังแสดงเสมอ ส่วนสกิลธนูที่มีลูกธนูพิเศษจะยิงเป็นลูกธนูธรรมดาแทน"],en:{title:"New setting: turn off skill effects",lines:['The Settings › Gameplay page has a new "Skill effects" option, for devices that lag with a crowd or during a boss fight.',"Show all = the same as before · Mine only = hides other players' skill, potion and level-up effects, and monster skill effects · Effects off = hides everything, including the max-level aura.","Boss skill warning rings, the casting bar, status icons on monsters and damage numbers always still show. Bow skills with a special arrow effect fire a plain arrow instead."]}},{id:"2026-09-28-arena-walk-in",date:"2026-09-28",time:"04:48",title:"สนาม PVP เดินเข้าจากป่าเริ่มต้น",lines:["สนาม Aurelia Arena เป็นแมพที่เดินเข้าได้เหมือนแมพทั่วไป ไม่มีมอนสเตอร์ ออกเมืองทางใต้เข้าป่าเริ่มต้น แล้วเลี้ยวซ้ายตามทางแยกใกล้ประตูเหนือจะเจอประตูสนาม","เอาปุ่ม PVP ออกจากเมนูหลัก เข้าสนามได้ด้วยการเดินเท่านั้น หรือเลือก Aurelia Arena ใน World แล้วกดเดินทาง","ประตูออกจากสนามพากลับมาที่ป่าเริ่มต้น ใกล้ทางเข้าเมือง"],en:{title:"Walk into the PVP Arena from Verdant Forest",lines:["Aurelia Arena is now a map you can walk into like any other, with no monsters. Leave town to the south into Verdant Forest, then turn left at the fork near the north gate to find the arena gate.","The PVP button has been removed from the main menu — the only way in now is on foot, or by selecting Aurelia Arena on World Map and traveling there.","The exit gate from the arena leads back to Verdant Forest, near the town entrance."]}},{id:"2026-09-28-revive-here",date:"2026-09-28",time:"04:37",title:"ปุ่มใหม่: เกิดจุดเดิมทันที",lines:['หน้าต่างหมดสติมีปุ่ม "เกิดจุดเดิม" ลุกขึ้นตรงที่ล้มได้ทันที HP เต็ม ไม่ต้องรอนับถอยหลังและไม่ต้องเดินกลับจากเมือง',"เกิดจุดเดิมแล้วได้สถานะ 🛡 อมตะ 30 วินาที มอนไม่เล็งและไม่โดนดาเมจ · หายทันทีเมื่อเริ่มโจมตีหรือใช้สกิลใส่ศัตรู","ค่าบริการ 10,000 Silver ที่แมพสูงสุด (ยอดเขาพายุ Lv.250–270) แมพเลเวลต่ำกว่าลดราคาตามสัดส่วน เช่น ป่าเริ่มต้น 750 · ช่องเขาหิมะ 1,670 · ทะเลทราย 2,600 · หนองน้ำ 3,520 Silver",'ล้มในเมืองหรือโรงเตี๊ยม เกิดจุดเดิมฟรี · ปุ่ม "กลับเมือง" ยังฟรีเหมือนเดิม'],en:{title:"New button: Revive here instantly",lines:['The unconscious window now has a "Revive here" button — stand back up right where you fell, with full HP, no need to wait out the countdown or walk back from town.',"Reviving here grants 🛡 Invulnerable for 30 seconds — monsters won't target you and you take no damage · it ends immediately once you attack or use a skill on an enemy.","The fee is 10,000 Silver at the highest map (Stormcrest Peaks, Lv.250–270), scaling down for lower-level maps — e.g. Verdant Forest 750 · Frostveil Pass 1,670 · Sunscar Desert 2,600 · Mirewillow Marsh 3,520 Silver.",'Falling in town or at the inn makes reviving here free · the "Return to town" button is still free as always.']}},{id:"2026-09-28-auto-caster-distance",date:"2026-09-28",time:"04:35",title:"ออโต้นักเวทยืนร่ายจากระยะไกล ไม่เดินเข้าไปชิดมอน",lines:["Auto Play ของนักเวทยืนร่ายห่างมอนประมาณ 200 พิกเซล เท่าระยะร่ายจริงของ Ember Bolt, Frost Area และ Stormbreak ไม่เดินเข้าไปชิดจนโดนมอนตีก่อนร่ายเสร็จ","เดิมบอทนับรัศมีวงระเบิดของ Frost Area กับ Stormbreak เป็นระยะยืน ทั้งที่สองสกิลนี้ร่ายลงตัวเป้าหมายได้ไกลกว่านั้นมาก","โหมดตีปกติ: ระหว่างที่ยังมีสกิลเวทพร้อมร่าย บอทจะยืนร่ายจากระยะไกล เมื่อ SP หมดหรืออยู่ในช่วงพักระหว่างสกิลที่ตั้งไว้ จึงเดินเข้าไปตีปกติเหมือนเดิม","โหมดใช้แต่สกิล: บอทยืนตามระยะของสกิลที่ไกลที่สุดที่ร่ายได้ตอนนั้น ถ้า SP ไม่พอก็ยืนรออยู่ห่างๆ ไม่เดินเข้าไปใกล้"],en:{title:"Mage Auto Play now casts from range instead of walking up to monsters",lines:["Mage Auto Play now stands about 200 pixels from monsters to cast, matching the real cast range of Ember Bolt, Frost Area and Stormbreak, instead of walking in close enough to get hit before the cast finishes.","Before, the bot used Frost Area's and Stormbreak's blast radius as its standing range, even though both skills can be cast on a target from much farther away.","Normal-attack mode: while a magic skill is still ready to cast, the bot stands and casts from range; once SP runs out or it's between skills in the set order, it walks in to attack normally as before.","Skill-only mode: the bot stands at the range of the farthest-reaching skill it can currently cast. If SP is too low, it waits at a distance instead of walking in closer."]}},{id:"2026-09-28-etc-price-half",date:"2026-09-28",time:"04:30",title:"ราคาขายวัตถุดิบ ETC ลดลงครึ่งหนึ่ง",lines:["วัตถุดิบ ETC ที่ดรอปจากมอนขายให้ร้านค้าได้สูงสุด 50 Silver (เดิม 100) ที่มอน Lv.270 และลดหลั่นตามเลเวลมอนเหมือนเดิม","ตัวอย่าง: Wolf Fang (Lv.100) 11 · Drake Scale (Lv.145) 20 · Shade Feather (Lv.200) 32 · Tempest Dragon Scale (Lv.270) 50 Silver","ของจากแมพแรก ๆ ยังขายได้ 1 Silver เท่าเดิม"],en:{title:"ETC sell prices halved",lines:["Monster ETC items now sell to the merchant for at most 50 Silver (was 100) at Lv.270, still scaling down with monster level.","Examples: Wolf Fang (Lv.100) 11 · Drake Scale (Lv.145) 20 · Shade Feather (Lv.200) 32 · Tempest Dragon Scale (Lv.270) 50 Silver.","Items from the first maps still sell for 1 Silver."]}},{id:"2026-09-28-fusion-auto-pick",date:"2026-09-28",time:"04:24",title:"ปุ่มเลือกอัตโนมัติในหน้าหลอมรวม",lines:['หน้าช่างหลอมรวมมีปุ่ม "เลือกอัตโนมัติ" เลือกอาวุธหรือชุดเกราะให้ครบ 5 ชิ้นในครั้งเดียว ไม่ต้องกดทีละชิ้น',"ถ้ายังไม่ได้เลือกอะไร จะเลือกจาก Tier ต่ำสุดที่มีครบ 5 ชิ้น · ถ้าเลือกไว้บางชิ้นแล้ว จะเติมจาก Tier เดียวกันจนครบ","ไม่เลือกชิ้นที่มีการ์ด ตีบวกแล้ว สวมอยู่ หรือล็อกไว้ (ชิ้นที่มีการ์ดหรือตีบวกยังกดเลือกเองได้)","หลังหลอมเสร็จ กดเลือกอัตโนมัติต่อได้เลย และจะจำอุปกรณ์ที่ต้องการชิ้นล่าสุดไว้ให้ถ้า Tier เดียวกัน"],en:{title:"Auto pick for Fusion",lines:['The Fusion Master window has an "Auto pick" button that fills all 5 pieces at once.',"With nothing chosen it picks from the lowest tier that has 5 pieces; with some chosen it tops up from the same tier.","Pieces with cards, a refine, worn or locked are never picked automatically (carded or refined pieces can still be added by hand).","After a fusion, press Auto pick again to go straight to the next one; the last chosen result is kept when the tier matches."]}},{id:"2026-09-28-premium-menu-drawer",date:"2026-09-28",time:"04:15",title:"ปุ่ม Premium ใหม่ข้างปุ่มเพิ่มเติม รวมเมนู Premium ไว้ที่เดียว",lines:["แถบเมนูมีปุ่ม Premium (รูปมงกุฎ) ต่อจากปุ่มบอท กดแล้วจะเปิดเมนูของ Premium: ตลาดกลาง ร้านค้า Silver สัตว์เลี้ยง และช่างหลอมรวม","ย้ายปุ่มสัตว์เลี้ยงจากแถบเมนู และย้ายปุ่มตลาดกลาง ร้านค้า Silver ช่างหลอมรวม ออกจากปุ่มเพิ่มเติม มาไว้ในเมนูนี้ ปุ่มลัด P ยังเปิดสัตว์เลี้ยงได้เหมือนเดิม","% น้ำหนักกระเป๋าสัตว์เลี้ยงแสดงบนปุ่ม Premium แทน ดูได้ระหว่างล่ามอนสเตอร์"],en:{title:"New Premium button beside More, gathering the Premium menu in one place",lines:["The menu bar has a new Premium button (a crown icon) after the bot button. Pressing it opens the Premium menu: Market, Silver Shop, Pet and the Fusion Master.","The Pet button has moved out of the menu bar, and the Market, Silver Shop and Fusion Master buttons out of the More menu, into this new menu. The P shortcut still opens Pet as before.","The pet bag's weight % now shows on the Premium button instead, so you can check it while hunting."]}},{id:"2026-09-28-mage-mastery-buff",date:"2026-09-28",time:"04:11",title:"Mage Mastery แรงขึ้น: MATK +6% ต่อระดับ",lines:["พาสซีฟ Mage Mastery เพิ่ม MATK จาก 2% เป็น 6% ต่อระดับ ระดับ 10 ได้ MATK +60% (เดิม +20%)","ส่วนลด SP ที่สกิลใช้ยังเท่าเดิม 1% ต่อระดับ (สูงสุด 10%) · มีผลทันทีกับทุกคนที่ลงสกิลไว้แล้ว ไม่ต้องรีเซ็ตสกิล"],en:{title:"Mage Mastery gets stronger: MATK +6% per rank",lines:["The Mage Mastery passive now gives MATK +6% per rank, up from 2% — at rank 10 that's MATK +60% (up from +20%).","The SP cost reduction is unchanged, at 1% per rank (up to 10%) · This takes effect immediately for anyone who already put points into the skill, no skill reset needed."]}},{id:"2026-09-28-chat-share-full-card",date:"2026-09-28",time:"04:03",title:"อุปกรณ์ที่แชร์ลงแชทเปิดดูได้ครบเหมือนในกระเป๋า",lines:["คลิกชื่ออุปกรณ์ที่คนอื่นแชร์ในแชท จะเห็นการ์ดเต็มแบบเดียวกับที่เจ้าของเห็น: คำอธิบาย การ์ดที่ฝังพร้อมโบนัส ผู้ค้นพบ ความทนทาน ระยะโจมตี ความเร็วโจมตี และการถือ","เดิมแชทส่งได้แค่ข้อความสั้น ๆ ที่พอดีความยาวแชท รายละเอียดท้าย ๆ จึงหายไป ตอนนี้ส่งตัวอุปกรณ์ไปให้เกมสร้างการ์ดเอง (ต้องแชร์ใหม่หลังอัปเดต ของที่แชร์ไว้ก่อนหน้ายังแสดงแบบเดิม)","ช่องการ์ดของอาวุธสองมือแสดงจำนวนช่องถูกต้อง (เช่น 2/2 แทน 2/1)","Bow มีคำอธิบายของตัวเองแล้ว เดิมขึ้นคำอธิบายของดาบ"],en:{title:"Gear shared in chat now opens with the full card, like in the bag",lines:["Clicking gear someone else shared in chat now shows the same full card the owner sees: description, socketed card with its bonus, discoverer, durability, attack range, attack speed and hand requirement.","Before, chat could only send a short summary that fit chat's length limit, so the later details were cut off. It now sends the actual item and lets the game build the card itself (share it again after this update — items shared before still display the old way).","A two-handed weapon's card slots now show the correct count (e.g. 2/2 instead of 2/1).","The Bow now has its own description, instead of showing the Sword's."]}},{id:"2026-09-28-worn-card-stays-open",date:"2026-09-28",time:"03:58",title:"แก้การ์ดไอเท็มจากหน้าอุปกรณ์สวมใส่ปิดเองทันที",lines:["คลิกช่องอุปกรณ์ที่สวมอยู่ในหน้าต่างอุปกรณ์ ตอนกระเป๋าเปิดแท็บอื่นที่ไม่ใช่ ทั้งหมด/อุปกรณ์/Cash การ์ดรายละเอียดจะเด้งขึ้นแล้วปิดเองในเสี้ยววินาที ตอนนี้เปิดค้างไว้ได้ตามปกติแล้ว"],en:{title:"Fixed the item card from the equip window closing itself instantly",lines:["Clicking a worn slot in the equipment window, while the bag was open on a tab other than All/Gear/Cash, would pop up the detail card and close it again in a split second. It now stays open normally."]}},{id:"2026-09-28-hub-junk-requests",date:"2026-09-28",time:"03:55",title:"กันคำขอขยะไม่ให้ถ่วงเซิร์ฟเวอร์กลาง",lines:["คืนนี้มีสคริปต์ยิงคำขอไปยังที่อยู่ที่ไม่มีอยู่จริงในเกมหลายหมื่นครั้ง ทุกคำขอไปต่อคิวที่เซิร์ฟเวอร์กลางตัวเดียวกับที่ดูแลการล็อกอิน แชท และการย้ายแมพ ตอนนี้คำขอพวกนี้ถูกตีกลับตั้งแต่ขอบเครือข่าย ไม่ไปถึงเซิร์ฟเวอร์กลางแล้ว","ข้อมูลกองทุน EXP ที่ทุกเครื่องเช็กเป็นระยะ อ่านจากแคชที่ขอบเครือข่าย (ช้าได้ไม่เกิน 5 วินาที) ลดงานของเซิร์ฟเวอร์กลางลงอีก"],en:{title:"Blocking junk requests from bogging down the central server",lines:["Tonight a script fired tens of thousands of requests at addresses that don't exist in the game. Every one of them queued on the same central server that handles login, chat and map transfers. These requests are now rejected at the network edge and never reach the central server.","EXP Fund data, which every client polls periodically, is now read from an edge cache (up to 5 seconds stale), cutting the central server's load further."]}},{id:"2026-09-28-equip-slot-short-tip",date:"2026-09-28",time:"03:40",title:"คำอธิบายตอนชี้ช่องสวมใส่สั้นลง",lines:["ชี้เมาส์ที่ช่องในหน้าสวมใส่ จะเห็นแค่ช่อง ชื่อไอเทม และวิธีถอด ไม่ยาวล้นจอแล้ว · สเตตัสและการ์ดดูได้ที่แผงรายละเอียดด้านล่างเหมือนเดิม"],en:{title:"Equip-slot tooltips are shorter",lines:["Hovering a slot on the equip page now shows just the slot, item name and how to unequip it, instead of overflowing the screen · Stats and cards are still shown in the detail panel below, as before."]}},{id:"2026-09-28-spell-crit-haste",date:"2026-09-28",time:"03:25",title:"สายเวทได้รางวัลจากการทำของตรงสายมากขึ้น",lines:['สกิลเวท (MATK) ติดคริติคอลได้แล้ว ด้วย "คริเวท" = LUK/3 + CRIT จากอุปกรณ์และการ์ด ไม่นับส่วนที่ได้จากเลเวล จึงไม่มีผลกับคนที่ไม่ได้ทำของสายคริ · คริเวทใช้ดาเมจคริเดียวกับสายกายภาพ (2 เท่า + คริดาเมจจากอุปกรณ์) และแสดงในหน้าสถานะเมื่อมีค่า',"DEX ที่เกิน 150 ไม่เสียเปล่าอีกต่อไป: ทุกแต้มที่เกินทำให้สกิลเวทหลายฮิต เช่น Ember Bolt, Stormbreak, Tierra ยิงแต่ละฮิตถี่ขึ้น 0.6% สูงสุด 60% ที่ DEX 250 · DEX ไม่ถึง 150 ทุกอย่างเหมือนเดิม",'อาวุธสายเวทและ Orb ที่ดรอปใหม่มีโอกาสได้ออปชันพิเศษ "คริดาเมจ" เพิ่มเข้ามา'],en:{title:"Spell builds get more reward for gearing on-path",lines:[`Magic skills (MATK) can now crit, with their own "spell critical" = LUK/3 + CRIT from gear and cards, not counting the share from level, so it has no effect on a build that doesn't gear for crit · Spell critical uses the same crit damage as physical skills (2x plus crit damage from gear), and shows on the stats page whenever it has a value.`,"DEX past 150 is no longer wasted: every point beyond it makes multi-hit magic skills like Ember Bolt, Stormbreak and Tierra fire each hit 0.6% faster, up to 60% at DEX 250 · Below 150 DEX, everything works as before.",'Newly dropped spell weapons and Orbs now have a chance to roll the special "crit damage" option.']}},{id:"2026-09-28-bow-two-cards",date:"2026-09-28",time:"03:26",title:"Bow ฝังการ์ดได้ 2 ใบ และเห็น ×1.5 ของอาวุธสองมือ",lines:["Bow ฝังการ์ดได้ 2 ใบแล้ว เท่ากับอาวุธสองมืออื่น (Staff, Quarterstaff, Dagger Pair, Hammer) · Bow ที่มีการ์ดอยู่ 1 ใบ ฝังใบที่ 2 ได้เลยโดยไม่ทับของเดิม","สเตตัสของ Bow ยังเท่าเดิม ไม่คูณ 1.5 เพราะ Bow ยังใส่ลูกธนูที่มือซ้ายได้ · อาวุธสองมืออื่นที่ใส่อะไรที่มือซ้ายไม่ได้ยังได้สเตตัส ×1.5 ตามเดิม","หน้ารายละเอียดอาวุธสองมือที่ได้ ×1.5 มีป้าย (×1.5) ท้ายสเตตัสที่คูณแล้ว ตัวเลขที่เห็นคือค่าหลังคูณ ใช้จริงตามนั้น"],en:{title:"Bow now takes 2 cards, and two-handed ×1.5 is shown",lines:["The Bow now takes 2 cards, same as other two-handed weapons (Staff, Quarterstaff, Dagger Pair, Hammer) · A Bow with 1 card already socketed can take a second one without overwriting it.","The Bow's own stats are unchanged and still don't get the ×1.5, since a Bow can still hold arrows in its left hand · Other two-handed weapons that can't hold anything in the left hand still get ×1.5 stats as before.","The detail page of a two-handed weapon that gets ×1.5 now marks each multiplied stat with (×1.5) — the number shown is the value after multiplying, and that's what actually applies."]}},{id:"2026-09-28-aura-crash-fix",date:"2026-09-28",time:"03:22",title:"แก้แมพกระตุกและหลุดบ่อยหลังอัปเดตคอมโบธาตุ",lines:["หลังอัปเดตคอมโบธาตุรอบล่าสุด มอนบางตัวที่ติดธาตุค้างมาจากก่อนอัปเดตทำให้เซิร์ฟเวอร์ของแมพนั้นล้มทุกครั้งที่มีคนตีด้วยอาวุธเคลือบธาตุหรือสกิลธาตุ ผู้เล่นทั้งแมพจึงหลุดและต่อใหม่วนไปเรื่อย ๆ เจอหนักที่ Emberfall Caldera, Crystal, Glacier, Dunes และ Wildwood","ตอนนี้ธาตุค้างแบบเก่าถูกแปลงให้ใช้ได้ตามปกติ และตีแล้วไม่ทำให้เซิร์ฟเวอร์ล้มอีก"],en:{title:"Fixed frequent map stutter and disconnects after the elemental combo update",lines:["After the latest elemental combo update, some monsters still carrying an element from before the update caused that map's server to crash every time someone hit them with an elemental weapon coating or an elemental skill. This disconnected everyone on the map in a repeating loop, hitting Emberfall Caldera, Crystal, Glacier, Dunes and Wildwood the hardest.","The old leftover elements are now converted to work normally, and hitting them no longer crashes the server."]}},{id:"2026-09-28-reactions-every-clash",date:"2026-09-28",time:"03:09",title:"คอมโบธาตุติดทุกครั้งที่ธาตุคู่กันปะทะกัน",lines:["เดิมคอมโบติดได้แค่ครั้งเดียวทุก 2.5 วินาทีต่อมอน และติดแล้วธาตุบนตัวมอนหายไป ตีสลับกันจึงติดแค่ราว 1 ใน 10 ครั้ง","ตอนนี้มอนเก็บได้หลายธาตุพร้อมกัน (ไอคอนขึ้นเหนือหัวครบทุกธาตุ) แต่ละธาตุอยู่ 6 วินาที และคอมโบไม่กินธาตุ ทุกครั้งที่ตีด้วยธาตุที่เข้าคู่กับธาตุบนตัวมอนจะติดคอมโบทันที","ถ้ามีธาตุคู่หลายธาตุ จะติดกับธาตุที่โดนล่าสุด","การแช่แข็งยังติดได้ทุก 6 วินาทีต่อมอน (แข็ง 2 วินาที) ไม่ให้มอนโดนแช่แข็งค้างตลอด และโล่ผลึกยังได้ใหม่ทุก 8 วินาทีต่อคนเหมือนเดิม"],en:{title:"Elemental combos now trigger on every matching clash",lines:["Before, a combo could trigger only once every 2.5 seconds per monster, and triggering it removed the element from the monster — so alternating hits only landed a combo about 1 in 10 times.","Monsters can now carry several elements at once (an icon shows above their head for each one), each lasting 6 seconds, and triggering a combo no longer consumes the element — every hit with an element that pairs with one already on the monster triggers a combo immediately.","If more than one pairing is available, it triggers with whichever element landed most recently.","Freeze can still trigger once every 6 seconds per monster (frozen for 2 seconds), so a monster can't be kept frozen forever, and Crystal Shield still refreshes every 8 seconds per player, as before."]}},{id:"2026-09-28-card-socket-brackets",date:"2026-09-28",time:"03:02",title:"ป้ายช่องการ์ดท้ายชื่ออุปกรณ์บอกจำนวนช่อง",lines:["ท้ายชื่ออุปกรณ์แสดงช่องการ์ดทีละช่อง: [] คือช่องว่าง · [Card] คือช่องที่มีการ์ดแล้ว (เลิกใช้คำว่า [Empty])","อาวุธสองมือที่ใส่การ์ดได้ 2 ใบ (Staff, Quarterstaff, Dagger Pair, Hammer) ขึ้นเป็น [][] ตอนยังว่าง และ [Card][] เมื่อใส่ไปแล้ว 1 ใบ"],en:{title:"Card slot tags after gear names show the slot count",lines:['Gear names now show card slots one at a time: [] is an empty slot · [Card] is a slot with a card already in it ("[Empty]" is no longer used).',"Two-handed weapons that take 2 cards (Staff, Quarterstaff, Dagger Pair, Hammer) show [][] when empty, and [Card][] once one card is socketed."]}},{id:"2026-09-28-drain-effect",date:"2026-09-28",time:"02:43",title:"ดูดเลือดและดูด SP มีเอฟเฟกต์ให้เห็นแล้ว",lines:["ทุกครั้งที่ดูดเลือดหรือดูด SP ได้ จะมีลูกแสงไหลจากเป้าหมายเข้าตัวผู้ตี สีแดงคือดูดเลือด สีฟ้าคือดูด SP","ตัวเลข +HP / +SP ที่ดูดได้ลอยขึ้นเหนือตัวเราเอง ผู้เล่นรอบข้างเห็นเฉพาะลูกแสง","ถ้า HP หรือ SP เต็มอยู่แล้วจะไม่ดูดและไม่มีเอฟเฟกต์ ดูด SP ยังมีผลเฉพาะการตีปกติ ค่าที่ดูดได้เหมือนเดิมทุกอย่าง"],en:{title:"Life drain and SP drain now have a visible effect",lines:["Every time you drain HP or SP, a light orb now streams from the target into the attacker — red for HP drain, blue for SP drain.","The +HP / +SP numbers you drain float up above yourself; players nearby only see the light orb.","If HP or SP is already full, nothing is drained and there's no effect. SP drain still only works on normal attacks, and the amounts drained are unchanged."]}},{id:"2026-09-28-bag-left-hand-chip",date:"2026-09-28",time:"02:35",title:'รวมโล่และซองธนูเป็นหมวด "มือซ้าย"',lines:['ในกระเป๋า แท็บอุปกรณ์ ปุ่มกรอง "โล่" กับ "ลูกธนู" รวมเป็นปุ่มเดียวชื่อ "มือซ้าย" แสดงโล่ ออร์บ และซองธนูทุกชิ้นที่ใส่มือซ้ายได้',"กดช่องมือซ้ายบนตัวละครจะเปิดกระเป๋าที่หมวดมือซ้ายให้ทันที",'ตัวกรองตอนขายของให้พ่อค้าก็รวมเป็นหมวด "มือซ้าย" เหมือนกัน'],en:{title:'Shields and quivers merged into a "Left hand" category',lines:[`In the bag's Gear tab, the "Shield" and "Arrows" filter buttons are now merged into one button called "Left hand", showing every Shield, Orb and quiver that goes in the left hand.`,"Pressing the left-hand slot on your character now opens the bag straight to the Left hand category.",'The sell-to-merchant filter is merged into a "Left hand" category the same way.']}},{id:"2026-09-28-rings-either-slot",date:"2026-09-28",time:"02:32",title:"แหวนใส่ได้ทั้ง 2 ช่องเครื่องประดับ",lines:["ช่องเครื่องประดับ 1 และ 2 รับแหวนได้ทุกแบบแล้ว ทั้ง Ruby Ring, Sapphire Ring และ Clip จะใส่แหวนแบบเดียวกัน 2 วงก็ได้ เช่น Ruby Ring 2 วง","กดสวมใส่แหวนจะลงช่องที่ว่างให้เอง ถ้าเต็มทั้งสองช่อง ให้ลากแหวนไปวางบนช่องที่จะเปลี่ยน หรือคลิกเลือกช่องนั้นก่อนแล้วค่อยกดสวมใส่","ลากแหวนที่สวมอยู่ไปวางอีกช่องเพื่อสลับข้างได้ ชุดอุปกรณ์ที่บันทึกไว้จำข้างของแหวนแต่ละวงด้วย","ค่าสุ่มของแหวนยังเป็นแบบเดิม Ruby Ring ยังเป็นสายกายภาพ และ Sapphire Ring ยังเป็นสายเวท"],en:{title:"Rings now fit either accessory slot",lines:["Accessory slots 1 and 2 now accept every kind of ring — Ruby Ring, Sapphire Ring and Clip alike — so you can even wear two of the same ring, like two Ruby Rings.","Pressing Equip on a ring puts it in whichever slot is free. If both slots are full, drag the ring onto the slot you want to replace, or click that slot first and then press Equip.","Drag a worn ring onto the other slot to swap sides. A saved gear set also remembers which side each ring was on.","Ring stat rolls are unchanged — the Ruby Ring is still for physical builds, and the Sapphire Ring is still for spell builds."]}},{id:"2026-09-28-physical-skill-crit",date:"2026-09-28",time:"02:31",title:"สกิลกายภาพทุกสกิลติดคริติคอลได้แล้ว",lines:["สกิลโจมตีสาย ATK ทุกสกิล เช่น Power Strike, Flame Burst, Twin Shot, Arrow Rain, Gold Strike, Quake Hammer, Shadow Burst และสกิลของ Mamushi ติดคริติคอลได้ตามค่าคริของตัวละคร ใช้ดาเมจคริเท่ากับการตีปกติ และคริแล้วตีโดนเสมอ","สกิลที่ตีหลายฮิตหรือโดนหลายตัว สุ่มคริแยกกันทุกฮิต · สกิลเวท (MATK) และดาเมจต่อเนื่องยังไม่ติดคริ","Twin Fang เปลี่ยนจากคริคงที่ 35% มาใช้ค่าคริของตัวละครเหมือนสกิลอื่น"],en:{title:"Every physical skill can now crit",lines:["Every ATK-based attack skill — Power Strike, Flame Burst, Twin Shot, Arrow Rain, Gold Strike, Quake Hammer, Shadow Burst and Mamushi's skills among them — can now crit based on your character's crit rate, use the same crit damage as a normal hit, and a crit always lands.","A skill that hits multiple times or multiple targets rolls crit separately for each hit · Magic skills (MATK) and damage-over-time still cannot crit.","Twin Fang no longer has a fixed 35% crit chance — it now uses your character's crit rate like every other skill."]}},{id:"2026-09-28-crystal-shield-party",date:"2026-09-28",time:"02:21",title:"โล่ผลึกแชร์ทั้งปาร์ตี้ แสดงบนแถบ HP และดาเมจคอมโบมีสี",lines:["โล่ผลึกจากปฏิกิริยาตกผลึกแสดงเป็นแถบสีม่วงอ่อนต่อท้ายแถบ HP พร้อมตัวเลข +โล่ที่เหลือ ลดลงตามดาเมจที่รับ ทั้งแถบ HP มุมจอและแถบใต้ตัวละคร","ขนาดโล่คิดจากพลังของการโจมตีที่จุดคอมโบ สายกายภาพใช้ ATK สายเวทใช้ MATK (เดิมใช้ MATK อย่างเดียว สายตีจึงได้โล่เล็กมาก) ไม่เกิน 30% ของ MaxHP","โล่แจกให้คนจุดคอมโบและเพื่อนปาร์ตี้ที่อยู่ใกล้ ๆ ทุกคน ได้โล่ใหม่ได้ทุก 8 วินาที และโล่ที่อ่อนกว่าจะไม่ทับโล่ที่แรงกว่า","ตัวเลขดาเมจของการโจมตีที่จุดคอมโบเป็นสีของปฏิกิริยานั้น เช่น ระเหยสีส้ม แช่แข็งสีฟ้า สุริยุปราคาสีทอง","แก้บัค: ตีคู่ของ Double Attack, ลูกธนูคู่ที่สองของ Twin Shot และการสะท้อนของ Radiant Light ได้โบนัสคอมโบซ้ำ ตอนนี้โบนัสอยู่ที่ครั้งที่จุดคอมโบเท่านั้น"],en:{title:"Crystal Shield shared with the party, shown on the HP bar, and combo damage gets color",lines:["Crystal Shield from the Crystallize reaction now shows as a pale purple bar tacked onto the HP bar, with a +shield number for what's left, shrinking as damage lands — on both the corner HP bar and the bar under your character.","The shield's size is based on the power of the hit that triggered the combo — physical builds use ATK, spell builds use MATK (before it always used MATK, so melee builds got a tiny shield), capped at 30% of MaxHP.","The shield goes to whoever triggered the combo and every nearby party member, refreshes every 8 seconds, and a weaker shield never overwrites a stronger one.","The damage number for the hit that triggers a combo is colored for that reaction — orange for Vaporize, blue for Frozen, gold for Eclipse.","Fixed a bug where Double Attack's second hit, Twin Shot's second arrow and Radiant Light's bounce got the combo bonus twice — the bonus now applies only to the hit that actually triggers the combo."]}},{id:"2026-09-28-skill-tooltip-short",date:"2026-09-28",time:"02:15",title:"คำอธิบายสกิลบนแถบ Shortcut สั้นลง",lines:["กล่องคำอธิบายตอนชี้สกิลไม่ยืดเต็มจอแล้ว ตัดขึ้นบรรทัดใหม่ในกรอบกว้างพอดีอ่าน","ตัดข้อความซ้ำออก: ระยะและคูลดาวน์ขึ้นแค่ครั้งเดียว","Stormbreak / Frost Area: ข้อความโบนัสคอมโบแปลครบทุกภาษาแล้ว"],en:{title:"Skill tooltips on the Shortcut bar are shorter",lines:["The tooltip box when hovering a skill no longer stretches across the whole screen — it wraps within a box sized for comfortable reading.","Removed duplicate text: range and cooldown now show only once.","Stormbreak / Frost Area: the combo bonus text is now translated in every language."]}},{id:"2026-09-28-aura-icon-fix",date:"2026-09-28",time:"01:57",title:"แก้ไอคอนธาตุไม่ขึ้นบนหัวมอน",lines:["ธาตุที่ติดบนตัวมอนจากสกิลธาตุหรืออาวุธเคลือบธาตุ ตอนนี้ขึ้นเป็นไอคอนเหนือหัวมอนแล้ว (ก่อนหน้านี้ระบบคอมโบทำงาน แต่ไอคอนไม่แสดง)"],en:{title:"Fixed element icons not showing above monsters",lines:["An element applied to a monster by an elemental skill or weapon coating now shows as an icon above its head (the combo system was already working before — the icon just wasn't showing)."]}},{id:"2026-09-28-element-aura-art",date:"2026-09-28",time:"01:41",title:"ไอคอนธาตุบนหัวมอนเป็นภาพใหม่",lines:["ธาตุที่ติดอยู่บนตัวมอน (รอจุดคอมโบ) แสดงเป็นไอคอนภาพพิกเซลของแต่ละธาตุแทนอีโมจิ ไฟ น้ำ ลม ดิน แสง มืด แยกกันได้ชัดขึ้น","โล่ผลึกจากปฏิกิริยาตกผลึกก็มีไอคอนของตัวเองแล้ว"],en:{title:"New artwork for element icons above monsters",lines:["An element on a monster (waiting for a combo) now shows as a pixel-art icon for that element instead of an emoji — fire, water, wind, earth, light and dark are easier to tell apart.","Crystal Shield from the Crystallize reaction now has its own icon too."]}},{id:"2026-09-28-coat-reactions",date:"2026-09-28",time:"01:36",title:"ม้วนเคลือบอาวุธจุดคอมโบธาตุได้แล้ว",lines:["อาวุธที่เคลือบธาตุไว้ ตีปกติและสกิลไร้ธาตุจะทิ้งธาตุบนตัวมอนและจุดปฏิกิริยาได้เหมือนสกิลธาตุ","จัดปาร์ตี้ให้ธาตุเข้าคู่กันได้เลย เช่น นักดาบเคลือบไฟ + Mage ใช้ Frost Area = ระเหย ×1.5 · สายตีเคลือบดิน + เพื่อนเคลือบน้ำ = ตกผลึก ได้โล่","มอนแต่ละตัวยังเกิดปฏิกิริยาได้ทุก 2.5 วินาทีเหมือนเดิม ตีรัวแค่ไหนก็ไม่ถี่ขึ้น"],en:{title:"Weapon-coating scrolls can now trigger elemental combos",lines:["A weapon with an elemental coating now leaves its element on a monster and can trigger a reaction from normal attacks and elementless skills, just like an elemental skill.","Now you can build a party around pairing elements, e.g. a swordsman coated in fire + a Mage's Frost Area = Vaporize ×1.5, or a melee build coated in earth + a friend coated in water = Crystallize for a shield.","Each monster can still only react once every 2.5 seconds, as before — attacking faster doesn't trigger it more often."]}},{id:"2026-09-28-repair-price-table",date:"2026-09-28",time:"01:34",title:"ปรับค่าซ่อมอุปกรณ์ตาม Tier",lines:["ค่าซ่อมเต็ม (ความทนทานเหลือ 0%) ของอุปกรณ์ +0: Tier I 1,000 · Tier II 2,500 · Tier III 4,500 · Tier IV 6,500 · Tier V 9,000 Silver ต่อชิ้น อุปกรณ์ที่ไม่มี Tier คิดเท่า Tier I","ตีบวกแล้วค่าซ่อมแพงขึ้น 3% ต่อระดับ เช่น +10 แพงขึ้น 30%","ซ่อมก่อนพังจ่ายตามสัดส่วนความทนทานที่หายไป เช่นเหลือ 50% จ่ายครึ่งราคา"],en:{title:"Repair cost now scales with gear Tier",lines:["The full repair cost (at 0% durability) for +0 gear is: Tier I 1,000 · Tier II 2,500 · Tier III 4,500 · Tier IV 6,500 · Tier V 9,000 Silver per piece. Gear with no Tier is priced as Tier I.","Refining raises the repair cost by 3% per level, so +10 costs 30% more.","Repairing before it breaks costs a fraction of the price based on the durability lost — e.g. at 50% remaining, you pay half price."]}},{id:"2026-09-28-elemental-reactions",date:"2026-09-28",time:"01:25",title:"ปฏิกิริยาธาตุ: ใช้สกิลต่างธาตุต่อกันเกิดคอมโบ",lines:["สกิลที่มีธาตุ (Ember Bolt, Flame Burst, Frost Area, Stormbreak, Tierra, Radiant Light, Shadow Burst) จะทิ้งธาตุไว้บนตัวมอน 6 วินาที ไอคอนธาตุขึ้นเหนือหัวมอน ถ้าโดนสกิลธาตุคู่กันภายในเวลานั้นจะเกิดปฏิกิริยา","💧+🔥 ระเหย ดาเมจครั้งนั้น ×1.5 · 💧+🌀 แช่แข็ง 2 วินาที และโดนเวทแรงขึ้น 55% · 🔥+🌀 ไฟลาม เผามอนทุกตัวรอบ ๆ 2 ช่อง","🍃+🔥 ลาวา เผาไหม้และมอนตีเบาลง 25% · 🍃+💧 หรือ 🍃+🌀 ตกผลึก ได้โล่ดูดซับดาเมจเท่ากับ MATK (ไม่เกิน 30% ของ MaxHP) · ☀+☾ สุริยุปราคา ดาเมจ ×2 และระเบิดโดนมอนรอบ ๆ 2 ช่อง","มอนแต่ละตัวเกิดปฏิกิริยาได้ทุก 2.5 วินาที บอสโลกได้ผลน้อยลงและไม่โดนแช่แข็ง ตีปกติ ธาตุจากม้วนเคลือบอาวุธ และการดวลไม่เกิดปฏิกิริยา · ปาร์ตี้ต่างอาชีพช่วยกันจุดคอมโบได้"],en:{title:"Elemental reactions: chaining different elements triggers a combo",lines:["Elemental skills (Ember Bolt, Flame Burst, Frost Area, Stormbreak, Tierra, Radiant Light, Shadow Burst) leave their element on a monster for 6 seconds, with an icon above its head. Hitting it with a pairing element within that time triggers a reaction.","💧+🔥 Vaporize — that hit deals ×1.5 damage · 💧+🌀 Frozen for 2 seconds and takes 55% more magic damage · 🔥+🌀 Wildfire — burns every monster within 2 tiles.","🍃+🔥 Lava — burns, and the monster's own attacks are 25% weaker · 🍃+💧 or 🍃+🌀 Crystallize — grants a shield absorbing damage equal to MATK (up to 30% of MaxHP) · ☀+☾ Eclipse — ×2 damage and it explodes onto monsters within 2 tiles.","Each monster can react once every 2.5 seconds. World bosses take reduced effects and cannot be frozen. Normal attacks, elements from weapon-coating scrolls, and duels do not trigger reactions · Mixed-class parties can combine to trigger combos together."]}},{id:"2026-09-28-broken-weapon-no-fight",date:"2026-09-28",time:"01:11",title:"อาวุธพังแล้วโจมตีไม่ได้",lines:["เมื่ออาวุธที่ถืออยู่พัง (ความทนทานหมด) จะโจมตีปกติ ดวล และใช้สกิลโจมตีไม่ได้จนกว่าจะซ่อมที่ช่างตีบวก Auto Play จะหยุดเองพร้อมบอกเหตุผล","สกิลฮีลและบัฟยังใช้ได้ตามปกติ ส่วนชุดเกราะหรืออุปกรณ์อื่นที่พังยังเหมือนเดิม คือไม่ให้ค่าสถานะจนกว่าจะซ่อม"],en:{title:"A broken weapon can no longer attack",lines:["When your equipped weapon breaks (durability hits zero), you can no longer attack normally, duel, or use attack skills until it's repaired at the Blacksmith — Auto Play stops itself and tells you why.","Heal and buff skills still work normally. Broken armor or other gear behaves as before — it just gives no stats until repaired."]}},{id:"2026-09-28-durability-back",date:"2026-09-28",time:"01:01",title:"ระบบซ่อมอุปกรณ์กลับมาแล้ว (ทนนานขึ้น 10 เท่า)",lines:["อุปกรณ์ที่สวมอยู่สึกหรอลงทุกครั้งที่ล่ามอนอีกครั้ง แต่ทนได้ 30,000 ตัว (เดิม 3,000) — ล่าต่อเนื่องไม่หยุดประมาณ 2 วันถึงจะพัง","ความทนทานเหลือไม่ถึง 20% จะมีข้อความเตือน ถ้าพังแล้วอุปกรณ์ยังสวมอยู่แต่ไม่ให้ค่าสถานะจนกว่าจะซ่อม","ซ่อมทุกชิ้นได้ที่ช่างตีบวก ค่าซ่อมคิดตามส่วนที่สึกไป ดูความทนทานได้ที่หน้ารายละเอียดอุปกรณ์"],en:{title:"Gear durability and repair is back (lasts 10x longer)",lines:["Worn gear wears down with every monster you hunt again, but now lasts 30,000 kills (up from 3,000) — roughly 2 days of nonstop hunting before it breaks.","You get a warning once durability drops below 20%. Once broken, the gear stays equipped but gives no stats until repaired.","Every piece can be repaired at the Blacksmith, priced by how much durability was lost. You can check durability on the gear's detail page."]}},{id:"2026-09-28-legal-short-links",date:"2026-09-28",time:"00:53",title:"ลิงก์สั้นไปหน้าข้อตกลงและนโยบายความเป็นส่วนตัว",lines:["เปิด lumivaraonline.com/terms และ /privacy ได้แล้ว ระบบพาไปยังหัวข้อนั้นในหน้าเอกสารทางกฎหมายโดยตรง (/refund สำหรับนโยบายคืนเงิน)"],en:{title:"Short links to the Terms and Privacy Policy pages",lines:["You can now open lumivaraonline.com/terms and /privacy — they jump straight to that section of the legal document page (/refund for the refund policy)."]}},{id:"2026-09-28-wiki-crit-pierce",date:"2026-09-28",time:"00:49",title:"อัปเดต Wiki: อธิบายคริติคอลกับเจาะเกราะให้ครบ",lines:['หน้าค่าสถานะในเกมมีหัวข้อใหม่ "คริติคอลและเจาะเกราะ" — คริติคอลตีโดนเสมอ ดาเมจคูณ 2 แต่ไม่ทะลุ DEF%/MDEF% ของมอนสเตอร์เหมือนเกมอื่น (ต่างจาก Ragnarok)',"มีตัวอย่างคำนวณดาเมจกับมอนเลเวลลึกที่มี DEF% เต็มเพดาน และอธิบายว่าเจาะกาย/เจาะเวทยังช่วยเพิ่มดาเมจคริติคอลได้ ทั้งใส่มอนและใน PVP"],en:{title:"Wiki update: critical vs. armor pierce explained in full",lines:[`The stats page has a new "Critical & Pierce" section — a critical always lands and doubles damage, but does not ignore a monster's DEF%/MDEF% like some other games (unlike Ragnarok)`,"It walks through a damage example against a deep monster at the DEF% cap, and explains that armor/magic pierce still adds damage on a critical, both against monsters and in PVP"]}},{id:"2026-09-28-gear-wear-requirement",date:"2026-09-28",time:"00:46",title:"บอกเงื่อนไขสวมใส่อุปกรณ์ให้ครบ",lines:['การ์ดไอเท็มทุกหน้าต่างบอกทั้งอาชีพและเลเวลที่ต้องใช้คู่กัน เช่น V Feather Arrow แสดง "ทุกอาชีพ · Lv.80+" แทนที่จะบอกแค่ใช้ได้ทุกอาชีพ',"ตลาดแจ้งเตือนสีแดงก่อนกดซื้อ ถ้าตัวละครที่เล่นอยู่ยังสวมชิ้นนั้นไม่ได้ พร้อมบอกเหตุผล (อาชีพไม่ตรงหรือเลเวลไม่ถึง)","สมุดไอเทมบอกอาชีพและเลเวลตามขั้นของอุปกรณ์ที่ดรอป · อาวุธใน Starter Pack บอกอาชีพที่ใช้ได้"],en:{title:"Gear requirements now shown in full",lines:['Every item card now states both the class and level requirement together, e.g. V Feather Arrow shows "All classes · Lv.80+" instead of just saying every class can use it.',"The market shows a red warning before you buy, if your current character can't wear that piece yet, and says why (wrong class or level too low).","The item book states the class and level of the tier the dropped gear belongs to · Starter Pack weapons state which class can use them."]}},{id:"2026-09-28-quest-desc-fit",date:"2026-09-28",time:"00:19",title:"บันทึกเควส: คำอธิบายเควสไม่ล้นกรอบแล้ว",lines:["คำอธิบายเควสล่ารายวันเคยยาวเกินกรอบ บรรทัดแรกโดนตัดหายไป ตอนนี้ตัวอักษรจะย่อลงให้พอดีกรอบเอง","ใช้กับคำอธิบายไกด์เควสและทุกภาษาด้วย"],en:{title:"Quest Journal: quest descriptions no longer overflow",lines:["The daily hunt description ran past its box and lost its first line; the text now shrinks to fit","The same goes for guide quest hints, in every language"]}},{id:"2026-09-28-quest-journal-exchange",date:"2026-09-28",time:"00:10",title:"บันทึกเควส: เอาหน้าบันทึกการออกล่าออก ให้แท็บแลกของเด่นขึ้น",lines:['จบไกด์เควสครบแล้ว แท็บ "กำลังทำ" กับ "จบแล้ว" จะหายไป เหลือแค่ รายวัน กับ แลกของ ที่กว้างขึ้นอ่านง่าย',"แท็บแลกของเป็นสีทอง มีตัวเลขบอกว่ามีธาตุไหนแลกใบเคลือบได้แล้วกี่ธาตุ และเรืองแสงเมื่อแลกได้","เปิดบันทึกเควสแล้วจะไปที่แท็บแลกของให้เลย ถ้ามีของพอแลกและไม่มีรางวัลล่ารายวันค้างรับ"],en:{title:"Quest Journal: Hunting Journal page removed, Exchange stands out",lines:["Once every guide quest is done, the In progress and Done tabs go away, leaving wider Daily and Exchange tabs","The Exchange tab is gold, shows how many elements are ready to trade for a coating scroll, and glows while one is","The journal opens on Exchange when a scroll is ready to trade and no daily hunt reward is waiting"]}},{id:"2026-09-28-cleric-party-wide-buffs",date:"2026-09-28",time:"00:09",title:"Cleric บัฟได้ทั้งปาร์ตี้ทั่วแมพ",lines:["Holy Guard, Divine Boon และ Remedy Light ส่งถึงสมาชิกปาร์ตี้ทุกคนที่อยู่แมพเดียวกัน ไม่ต้องยืนใกล้กันแล้ว (เดิมต้องอยู่ในระยะราว 150–170)","Divine Boon ยังให้ตัวละครที่ยืนรอบตัว Cleric ด้วยเหมือนเดิม ส่วน Holy Guard และ Remedy Light ให้เฉพาะในปาร์ตี้","เลือกเพื่อนร่วมปาร์ตี้ที่อยู่ไกลแล้วร่าย Divine Boon ได้เลย ไม่ขึ้นว่าอยู่ไกลเกินระยะ · สมาชิกที่อยู่แมพอื่นหรือช่องอื่นยังไม่ได้รับ","Heal ยังรักษาเฉพาะรอบตัวเหมือนเดิม"],en:{title:"Cleric buffs now reach the whole party, anywhere on the map",lines:["Holy Guard, Divine Boon and Remedy Light now reach every party member on the same map — no need to stand close together anymore (previously required being within about 150–170 range).","Divine Boon still also affects any character standing near the Cleric, as before, while Holy Guard and Remedy Light only affect the party.","You can select a far-away party member and cast Divine Boon on them directly — it no longer says they're out of range · Members on a different map or channel still don't receive it.","Heal still only heals around yourself, as before."]}},{id:"2026-09-28-revive-stuck-countdown",date:"2026-09-28",time:"00:05",title:'แก้บัคปุ่ม "กลับเมือง" ค้างนับถอยหลังนาน',lines:['บางคนหมดสติแล้วปุ่ม "กลับเมือง" ขึ้นนับถอยหลังหลายพันวินาทีจนกดไม่ได้ แม้ออกแล้วเข้าเกมใหม่ก็ไม่หาย',"ตอนนี้หน้าต่างหมดสตินับถอยหลังไม่เกิน 2 วินาทีเสมอ แล้วกดกลับเมืองได้ทันที","ตัวละครที่ค้างอยู่ในสภาพนี้ เข้าเกมใหม่แล้วจะฟื้นที่เมืองให้เอง"],en:{title:'Fixed the "Return to town" button getting stuck on a long countdown',lines:[`For some players, going unconscious made the "Return to town" button show a countdown of several thousand seconds, leaving it unpressable, and logging out and back in didn't fix it.`,"The unconscious window's countdown is now always at most 2 seconds, and you can press Return to town right after.","Any character still stuck in this state will be revived in town automatically the next time they log in."]}},{id:"2026-09-28-loot-protect-longer",date:"2026-09-28",time:"00:02",title:"เพิ่มเวลาคุ้มครองของที่ตีตก",lines:["ของที่มอนสเตอร์ดรอปจะสงวนไว้ให้เจ้าของ (คนที่ทำดาเมจมากที่สุด) นานขึ้น 50% จาก 15 เป็น 22.5 วินาที ผู้เล่นอื่นและกระต่ายเก็บของของคนอื่นเก็บไม่ได้จนกว่าจะหมดเวลา","สมาชิกปาร์ตี้ที่เปิดแชร์ของยังเก็บของกันเองได้ทันทีเหมือนเดิม"],en:{title:"Longer loot protection for dropped items",lines:["Items a monster drops are reserved for their owner (whoever dealt the most damage) 50% longer, up from 15 to 22.5 seconds. Other players and loot rabbits cannot pick it up until that time runs out.","Party members with loot sharing on can still pick each other's drops up immediately, as before."]}},{id:"2026-09-28-skill-only-bot-no-air-throw",date:"2026-09-28",time:"00:00",title:"บอทโหมดใช้แต่สกิล ไม่ทำท่าตีลมแล้ว",lines:["เปิดบอทแบบใช้สกิลอย่างเดียว ตัวละครที่ถือคุไนหรือธนูจะไม่เล่นท่าปา/ยิงเปล่า ๆ ใส่มอนสเตอร์ระหว่างรอสกิลคูลดาวน์อีกต่อไป เพราะท่านั้นไม่ได้โจมตีจริงและไม่มีดาเมจ","ตัวละครจะยืนรอในระยะ แล้วร่ายสกิลเมื่อพร้อม ความแรงและระยะของสกิลไม่ได้เปลี่ยน"],en:{title:"Skill-only bot mode no longer swings at air",lines:["With the skill-only bot mode on, a character holding kunai or a bow no longer throws or shoots an empty animation at monsters while waiting for skills to come off cooldown, since that motion never actually attacked or dealt damage.","The character now just waits in range and casts once a skill is ready. Skill power and range are unchanged."]}},{id:"2026-09-27-equipment-tabs-repeat",date:"2026-09-27",time:"23:58",title:"หน้าต่างอุปกรณ์: แถบ อุปกรณ์/สกิน ไม่ซ้ำเต็มจอแล้ว",lines:["หลังย้ายแมพหรือเชื่อมต่อใหม่หลายครั้ง แถบสลับ อุปกรณ์/สกิน บนหน้าต่างอุปกรณ์เคยงอกซ้ำจนล้นเป็นแถวยาวทั่วจอ ตอนนี้มีแถบเดียวเสมอ"],en:{title:"Equipment window: the Gear/Skin tabs no longer repeat across the screen",lines:["After changing maps or reconnecting several times, the Gear/Skin toggle on the equipment window used to keep duplicating into a long row across the screen. There's now always just one."]}},{id:"2026-09-27-camera-zoom-out",date:"2026-09-27",time:"23:44",title:"ซูมกล้องออกได้กว้างขึ้นอีก 50%",lines:["หมุนลูกกลิ้งเมาส์ลง (หรือหุบสองนิ้วบนมือถือ) ต่อจากมุมมองปกติ จะซูมออกได้อีก เห็นแผนที่กว้างขึ้นสูงสุด 1.5 เท่าในแต่ละด้าน","มุมมองปกติยังเป็นค่าเริ่มต้นเหมือนเดิม ซูมเข้าได้สูงสุด 2 เท่าเหมือนเดิม","ตอนซูมออก มอนสเตอร์และผู้เล่นที่ขอบจอจะแสดงครบ ไม่โผล่กลางจอ"],en:{title:"Camera can now zoom out 50% farther",lines:["Scroll the mouse wheel down (or pinch in on mobile) past the normal view to zoom out further, showing up to 1.5x more map on each side.","The normal view is still the default, and you can still zoom in up to 2x as before.","While zoomed out, monsters and players at the edge of the screen now render fully, instead of popping in near the center."]}},{id:"2026-09-27-portal-ground-tint",date:"2026-09-27",time:"23:41",title:"แท่นวาปเปลี่ยนสีตามพื้นของแต่ละแมพ",lines:["แท่นวาปทุกแมพย้อมสีหิน หญ้า และรากไม้ให้เข้ากับพื้นที่ตั้งอยู่ เช่น เมือง Aurelia เป็นหินปูพื้นสีเทา ธารน้ำแข็งเป็นสีขาวน้ำแข็ง ปล่องภูเขาไฟเป็นสีเถ้าเข้ม","วงวาปสีฟ้าตรงกลางยังคงสีเดิม มองเห็นจุดวาปได้ชัดเหมือนเดิม"],en:{title:"Warp pads now match each map's ground color",lines:["Every warp pad now tints its stone, grass and roots to match the ground it sits on — for example, gray paving stone in Aurelia Forum, icy white in Frostfang Glacier, and dark ash in the volcanic caldera.","The blue warp ring at the center keeps its original color, so the warp point is still easy to spot."]}},{id:"2026-09-27-socket-from-item-card",date:"2026-09-27",time:"23:30",title:"ฝังการ์ดจากหน้ารายละเอียดไอเทมได้เลย",lines:['หน้ารายละเอียดของอุปกรณ์มีปุ่ม "ฝังการ์ด" แล้ว กดแล้วเลือกการ์ดในกระเป๋าที่ใส่ชิ้นนั้นได้ทันที ไม่ต้องไปเริ่มจากตัวการ์ด',"ใช้ได้ทั้งของในกระเป๋าและของที่สวมอยู่ ช่องเต็มแล้วก็เลือกใส่ทับได้ (การ์ดเดิมหายถาวร ระบบจะถามยืนยันก่อน)"],en:{title:"Socket a card straight from the item detail page",lines:['The gear detail page now has a "Socket card" button — press it to pick a card from your bag and socket it right away, without having to start from the card itself.',"Works for gear in your bag or already worn. Even if the slot is full, you can choose to overwrite it (the old card is destroyed permanently — you'll be asked to confirm first)."]}},{id:"2026-09-27-guild-remove-fit",date:"2026-09-27",time:"23:18",title:"หน้ากิลปุ่มเชิญออกไม่ล้น และทั้งเกมไม่มีแถบเลื่อนแล้ว",lines:["ตัวอักษรบนปุ่มเชิญออกในรายชื่อสมาชิกกิลอยู่ในกรอบปุ่มแล้ว ทุกภาษา","ทุกหน้าต่างและรายการในเกมไม่แสดงแถบเลื่อน (scroll bar) แล้ว ยังเลื่อนดูได้ตามปกติด้วยนิ้ว ล้อเมาส์ หรือการลาก"],en:{title:"Guild page's Remove button no longer overflows, and scrollbars are gone game-wide",lines:["The text on the Remove button in the guild member list now fits inside the button, in every language.","No window or list in the game shows a scroll bar anymore — you can still scroll normally with a finger, the mouse wheel or by dragging."]}},{id:"2026-09-27-relic-box-gear-5",date:"2026-09-27",time:"23:16",title:"Mystery Relic Box: โอกาสได้อุปกรณ์เหลือ 5%",lines:["เปิด Mystery Relic Box มีโอกาสได้อุปกรณ์สุ่ม Tier I–V รวม 5% (เดิม 10%) หรือ Tier ละ 1%","โอกาสได้การ์ด ใบเคลือบธาตุ ของ ETC และปีกทองเท่าเดิม ส่วนที่ลดลงไปเพิ่มให้ยาและวัตถุดิบทั่วไป"],en:{title:"Mystery Relic Box: gear odds down to 5%",lines:["Opening a Mystery Relic Box now has a combined 5% chance of random Tier I–V gear (down from 10%), or 1% per tier.","The odds for cards, elemental coating scrolls, ETC items and Divine Wings are unchanged — the reduced share goes to potions and general materials instead."]}},{id:"2026-09-27-relic-box-etc",date:"2026-09-27",time:"23:12",title:"Mystery Relic Box: มีของดรอปมอนสเตอร์ (ETC) แล้ว",lines:["เปิด Mystery Relic Box มีโอกาส 10% ได้ของดรอปประจำมอนสเตอร์ (ETC) 1 ชิ้น สุ่มเท่ากันทุกชนิด เช่น Wolf Fang, Drake Scale, Tempest Dragon Scale","โอกาสได้อุปกรณ์ การ์ด ใบเคลือบธาตุ และปีกทองเท่าเดิม ส่วนที่ลดลงคือยาและวัตถุดิบทั่วไป"],en:{title:"Mystery Relic Box now drops monster items (ETC)",lines:["Opening a Mystery Relic Box now has a 10% chance of 1 monster ETC drop, with every type equally likely — for example Wolf Fang, Drake Scale or Tempest Dragon Scale.","The odds for gear, cards, elemental coating scrolls and Divine Wings are unchanged — potions and general materials take the reduction."]}},{id:"2026-09-27-party-head-two-rows",date:"2026-09-27",time:"23:07",title:"แถบปาร์ตี้แคบลง พอดีกับเนื้อหา",lines:["แถบปาร์ตี้ด้านซ้ายหดความกว้างให้พอดีกับชื่อสมาชิกและปุ่ม ไม่กินพื้นที่จอเกินจำเป็น (กว้างสุดเท่าเดิม ชื่อยาวจะถูกตัดด้วย …)","หัวแถบแบ่งเป็น 2 บรรทัด: ชื่อปาร์ตี้กับจำนวนสมาชิกด้านบน ป้ายโบนัส EXP/Drop กับปุ่ม ↻ ด้านล่าง"],en:{title:"Party bar narrower, sized to fit its content",lines:["The party bar on the left now shrinks to fit member names and buttons, instead of taking up more screen than it needs (the max width is unchanged; long names are truncated with …).","The bar's header now splits into 2 lines: the party name and member count on top, the EXP/Drop bonus badge and the ↻ button below."]}},{id:"2026-09-27-changelog-new-badge",date:"2026-09-27",time:"23:02",title:'ป้าย "ใหม่" บนปุ่มบันทึกอัปเดต',lines:['ทุกครั้งที่มีแพตช์ใหม่ ปุ่มอัปเดตในเมนู ☰ จะมีป้ายแดง "ใหม่" และปุ่ม ☰ จะขึ้นเครื่องหมายเตือน ชวนให้เข้าไปอ่านว่ามีอะไรเปลี่ยน',"ป้ายจะหายเมื่อเปิดหน้าบันทึกการอัปเดต และจะกลับมาอีกครั้งเมื่อมีแพตช์ถัดไป"],en:{title:'"New" badge on the patch notes button',lines:['Whenever a new patch ships, the update button in the ☰ menu gets a red "New" badge, and the ☰ button itself shows a notice dot, inviting you to go read what changed.',"The badge clears once you open the patch notes page, and comes back again with the next patch."]}},{id:"2026-09-27-death-cause",date:"2026-09-27",time:"22:55",title:"หน้าต่างหมดสติบอกสาเหตุการเสียชีวิต",lines:["หน้าต่างหมดสติแสดงว่าล้มเพราะอะไร เช่น มอนสเตอร์ตัวไหนโจมตี ใช้สกิลอะไร หรือพิษ/ไฟเผาจากใคร"],en:{title:"The unconscious window shows your cause of death",lines:["The unconscious window now shows what took you down, such as which monster attacked, which skill it used, or whose poison/burn finished you off."]}},{id:"2026-09-27-mamushi-shuriken",date:"2026-09-27",time:"22:48",title:"ของมือซ้ายใหม่: Shuriken ของ Mamushi",lines:["เพิ่ม Shuriken (ดาวกระจาย) อุปกรณ์มือซ้ายสำหรับ Mamushi โดยเฉพาะ ถือคู่กับ Viper Kunai ดรอปจากมอนสเตอร์ในช่องโล่","Shuriken เป็นสายความเร็วโจมตีกายภาพล้วน: มี ASPD ติดมาทุกชิ้น (+1 ถึง +3 ตาม tier) พร้อม ATK, HIT, AGI และ DEX (ออปชันพิเศษมีได้แค่ ATK%, เจาะเกราะ, คริดาเมจ หรือเลือดออก) ไม่มี DEF หรือค่าเวท","Shuriken ที่ดรอปมีโอกาสได้ถึง 6 แถว เหมือน Orb ของเมจ และไม่ทำให้ความเร็วโจมตีลดเหมือนโล่","ตีบวก Shuriken แล้วได้ ATK เพิ่มบนไอเทม แทนการลดดาเมจแบบโล่","คำอธิบายบนการ์ดไอเทมของ Viper Kunai, Orb และ Shuriken บอกตรงกับของจริงแล้ว (เดิมขึ้นเป็นคำอธิบายดาบและโล่)"],en:{title:"New left-hand item: Mamushi's Shuriken",lines:["Added Shuriken, a left-hand item made specifically for Mamushi to pair with Viper Kunai. It drops from monsters in the shield slot.","Shuriken is a purely physical attack-speed item: every piece comes with ASPD (+1 to +3 by tier) plus ATK, HIT, AGI and DEX (special options are limited to ATK%, armor pierce, crit damage or bleed). It has no DEF or magic stats.","Dropped Shuriken can roll up to 6 stat lines, like a mage's Orb, and it doesn't slow your attack speed the way a shield does.","Refining a Shuriken adds ATK to the item, instead of the damage reduction a shield gets.","The item card descriptions for Viper Kunai, Orb and Shuriken now match what they actually are (they used to show sword and shield descriptions)."]}},{id:"2026-09-27-market-search-enter",date:"2026-09-27",time:"22:45",title:"ตลาดกลาง: กด Enter หรือปุ่มค้นหาเพื่อค้น",lines:["ช่องค้นหาในหน้าซื้อสินค้าไม่ค้นเองระหว่างพิมพ์แล้ว พิมพ์เสร็จกด Enter หรือกดปุ่ม ค้นหา (หรือแว่นขยาย)","ช่องค่าขั้นต่ำของตัวกรองสเตตัสก็ใช้ค่าเมื่อกด Enter หรือกดออกจากช่อง","ตัวกรองแบบกดเลือก (หมวด คุณภาพ อาชีพ การเรียง) ยังทำงานทันทีเหมือนเดิม"],en:{title:"Market: press Enter or the search button to search",lines:["The search box on the Buy page no longer searches as you type. Finish typing and press Enter or the Search button (the magnifying glass).","The minimum-value field in the stat filter also applies its value when you press Enter or click away from the box.","Click-to-select filters (category, quality, class, sort order) still apply immediately, as before."]}},{id:"2026-09-27-explorer-rare-items",date:"2026-09-27",time:"22:33",title:"Explorer: แท็บใหม่ ไอเทมหายาก",lines:['หน้า Explorer มีแท็บ "ไอเทมหายาก" ดูได้ว่าปีกทอง (Divine Wings) มีอยู่ในโลกกี่ชิ้น ใครถืออยู่บ้าง และใครเป็นผู้ค้นพบแต่ละชิ้น',"นับจากกระเป๋า ของที่สวมอยู่ คลัง และกระเป๋าสัตว์เลี้ยง ไม่นับของที่ตั้งขายในตลาดหรือยังค้างในจดหมาย · ตัวเลขอัปเดตทุกไม่กี่นาทีหลังตัวละครบันทึก","กดชื่อผู้ถือเพื่อเปิดหน้าตัวละครนั้นได้เลย"],en:{title:"Explorer: new Rare Items tab",lines:['The Explorer page has a "Rare Items" tab showing how many Divine Wings exist in the world, who currently holds each one, and who discovered it.',"It counts items in bags, equipped, in storage and in pet bags, but not ones listed on the Market or still sitting in mail · numbers update every few minutes after a character saves.","Click a holder's name to open that character's page directly."]}},{id:"2026-09-27-guild-lists-fit",date:"2026-09-27",time:"22:30",title:"หน้ากิล: ตารางคำขอเข้ากิลและรายชื่อสมาชิกไม่ล้นแล้ว",lines:["ปุ่มปฏิเสธในตารางคำขอเข้ากิล และปุ่มจัดการในตารางสมาชิก เคยถูกตัดขอบขวา ตอนนี้เห็นครบทุกปุ่ม","อาชีพและเลเวลย้ายไปอยู่ใต้ชื่อผู้เล่น ชื่อที่ยาวเกินจะย่อเป็น …"],en:{title:"Guild page: join request and member tables no longer overflow",lines:["The Reject button in the join requests table, and the manage button in the member table, used to get clipped at the right edge. All buttons are fully visible now.","Class and level have moved below the player's name, and names that are too long are now truncated with …"]}},{id:"2026-09-27-market-paged-board",date:"2026-09-27",time:"22:28",title:"ตลาดกลางเปิดเร็วขึ้นมาก",lines:["หน้าซื้อสินค้าโหลดทีละหน้าจากเซิร์ฟเวอร์แล้ว เดิมต้องโหลดทุกรายการในตลาดทีเดียว (หลายหมื่นรายการ หลาย MB) ทุกครั้งที่เปิด","ค้นหา กรองหมวด/คุณภาพ/อาชีพ/สเตตัส เรียงราคา และเปลี่ยนหน้า ทำที่เซิร์ฟเวอร์ทั้งหมด ผลลัพธ์เหมือนเดิม","ระหว่างรอข้อมูลหน้าแรกจะขึ้นว่า กำลังโหลด… แทนการโชว์ของเก่าค้างไว้"],en:{title:"The Market opens much faster",lines:["The Buy page now loads one page at a time from the server. It used to load every listing in the Market at once (tens of thousands of them, several MB) every time you opened it.","Search, category/quality/class/stat filters, price sorting and page changes are all handled server-side now, with the same results as before.",'While waiting for the first page of data, it shows "Loading…" instead of leaving stale results on screen.']}},{id:"2026-09-27-bot-auto-coat",date:"2026-09-27",time:"22:15",title:"บอทใช้ใบเคลือบธาตุเองได้",lines:['หน้าตั้งค่าบอท หมวดยาอัตโนมัติ มีช่องติ๊ก "ใช้ใบเคลือบอาวุธอัตโนมัติ" และ "ใช้ใบเคลือบเกราะอัตโนมัติ" พร้อมเลือกธาตุได้ทั้ง 6 ธาตุ',"บอทจะใช้ใบเคลือบธาตุที่เลือกเมื่อตัวละครยังไม่ได้เคลือบธาตุนั้น เช่นตอนเริ่มบอทหรือตอนเวลาเคลือบหมด ต้องมีใบในกระเป๋า","ถ้ากำลังเคลือบธาตุอื่นอยู่ บอทจะใช้ใบธาตุที่เลือกแทนที่ · ปิดไว้เป็นค่าเริ่มต้น"],en:{title:"The bot can use elemental coating scrolls on its own",lines:['The bot settings page, in the auto-potion section, has checkboxes for "Auto-use weapon coating" and "Auto-use armor coating", with a choice of all 6 elements.',"The bot uses the chosen coating whenever your character isn't already coated with that element, such as when the bot starts or when the coating runs out. You need the scroll in your bag.","If you're already coated with a different element, the bot will replace it with the chosen one · off by default."]}},{id:"2026-09-27-card-window-mobile-fit",date:"2026-09-27",time:"22:12",title:"หน้าฝังการ์ดบนมือถือ: ปิดได้และเลื่อนได้แล้ว",lines:["บนมือถือ หน้าต่างฝังการ์ดเคยล้นขึ้นไปเหนือจอ จนมองไม่เห็นหัวหน้าต่างและปุ่ม × ปิดไม่ได้ และเลื่อนดูรายการอุปกรณ์ไม่สะดวก","ตอนนี้หน้าต่างอยู่กลางจอพอดีทุกขนาดหน้าจอ ปุ่ม × อยู่ในจอเสมอ และเลื่อนดูรายการอุปกรณ์ได้ครบ"],en:{title:"Card socketing window on mobile: closeable and scrollable now",lines:["On mobile, the card socketing window used to overflow above the screen, hiding its header and × button so it couldn't be closed, and made scrolling through the equipment list awkward.","The window now sits centered on screen at every screen size, the × button always stays on screen, and you can scroll through the full equipment list."]}},{id:"2026-09-27-class-picker",date:"2026-09-27",time:"22:07",title:"หน้าต่างเปลี่ยนอาชีพ: เลือกอาชีพจากการ์ดรูปตัวละคร",lines:["กดการ์ด TARGET จะเปิดแผงเลือกอาชีพแบบใหม่ เห็นรูปตัวละครของทุกอาชีพพร้อม Job Lv. เรียงเป็นตาราง แทนรายการตัวหนังสือแบบเดิม",'อาชีพที่เลือกไว้มีกรอบทองและเครื่องหมายถูก อาชีพปัจจุบันเป็นสีเทาพร้อมป้าย "ปัจจุบัน" · กดนอกแผง กด × หรือ Esc เพื่อปิด'],en:{title:"Class change window: pick a class from character portrait cards",lines:["Clicking the TARGET card now opens a new class picker panel showing every class's character portrait with its Job Lv. laid out in a grid, instead of the old text list.",'The selected class gets a gold border and a checkmark, and your current class is greyed out with a "Current" badge · click outside the panel, press × or Esc to close it.']}},{id:"2026-09-27-bot-sp-floor-overlap",date:"2026-09-27",time:"22:05",title:"หน้าตั้งค่าบอท: ตัวอักษรช่องสำรอง SP ไม่ทับกันแล้ว",lines:['ช่อง "สำรอง SP ไว้บัฟ/ฮีล" กับแถบเลื่อน "สกิลโจมตีเมื่อ SP ≥" ไม่ซ้อนทับกันอีก (เห็นชัดตอนเลือกภาษาอังกฤษ) ถ้าหน้าต่างแคบ แถบเลื่อนจะขึ้นบรรทัดใหม่แทน'],en:{title:"Bot settings: the SP reserve field text no longer overlaps",lines:['The "Reserve SP for buff/heal" field and the "Attack skill when SP ≥" slider no longer overlap each other (most noticeable with English selected). If the window is narrow, the slider now wraps to a new line instead.']}},{id:"2026-09-27-site-links-new-window",date:"2026-09-27",time:"22:00",title:"Wiki และบันทึกอัปเดตเปิดเป็นหน้าต่างใหม่",lines:["กดลิงก์ Wiki, บันทึกอัปเดต, FAQ, Explorer หรือหน้าข้อตกลงจากในเกม จะเปิดเป็นหน้าต่างเบราว์เซอร์แยก ไม่ใช่แท็บใหม่ วางไว้ข้างเกมแล้วดูไปเล่นไปได้","กดลิงก์เดิมซ้ำจะใช้หน้าต่างเดิม ไม่เปิดซ้อน ถ้าเบราว์เซอร์บล็อกป๊อปอัปจะเปิดเป็นแท็บเหมือนเดิม"],en:{title:"Wiki and patch notes open in a new window",lines:["Clicking the Wiki, patch notes, FAQ, Explorer or terms links from in-game now opens a separate browser window instead of a new tab, so you can place it beside the game and read while you play.","Clicking the same link again reuses that window instead of opening another one. If your browser blocks pop-ups, it falls back to opening a tab as before."]}},{id:"2026-09-27-no-email-name",date:"2026-09-27",time:"21:56",title:"ความเป็นส่วนตัว: ชื่อตัวละครไม่ถูกสร้างจากอีเมลอีก",lines:["เกมไม่เคยส่งอีเมลของผู้เล่นไปให้ผู้เล่นคนอื่น คนที่เจอกันในเกมเห็นเฉพาะชื่อตัวละคร","ระบบเดิมมีจุดเล็ก ๆ ที่ถ้าชื่อบัญชี Google ไม่มีตัวอักษรอังกฤษ จะใช้ส่วนหน้า @ ของอีเมลเป็นชื่อสำรอง ตอนนี้เอาออกแล้ว ถ้าไม่มีชื่อที่ใช้ได้จะใช้ชื่อ Player_xxxxxx แทน"],en:{title:"Privacy: character names are no longer built from your email",lines:["The game has never sent a player's email address to other players. Anyone you meet in-game only ever sees your character name.","There used to be a small edge case where, if your Google account name had no English letters, the part of your email before @ was used as a fallback name. That's been removed; if no usable name is available, it now uses Player_xxxxxx instead."]}},{id:"2026-09-27-two-hand-balance",date:"2026-09-27",time:"21:51",title:"อาวุธสองมือ: ลูกธนูใส่ได้เฉพาะ Bow และอาวุธสองมืออื่นได้ชดเชย",lines:["ลูกธนู (Feather Arrow) ใส่มือซ้ายได้เฉพาะตอนถือ Bow · ใครที่ใส่ลูกธนูคู่กับอาวุธอื่นอยู่ ลูกธนูจะกลับเข้ากระเป๋าเมื่อเข้าเกม · ถอด Bow แล้วลูกธนูถอดตามด้วย","อาวุธสองมือที่ไม่ใช่ Bow (Staff, Quarterstaff, Dagger Pair, Hammer) ใส่อะไรที่มือซ้ายไม่ได้เลย จึงได้ชดเชย: สเตตัสของอาวุธนับ ×1.5 (ค่าคงที่ เช่น ATK, MATK, INT · % ออปชันพิเศษคงเดิม) และฝังการ์ดได้ 2 ใบ","อาวุธที่มีการ์ดอยู่แล้ว 1 ใบ ฝังใบที่ 2 ได้เลยโดยไม่ทับของเดิม · ถ้าครบ 2 ใบแล้ว หน้าฝังการ์ดจะให้เลือกว่าจะทับใบไหน"],en:{title:"Two-handed weapons: arrows only fit a Bow, other two-handers get compensation",lines:["Feather Arrow can only go in the left hand while wielding a Bow · if you had arrows equipped alongside a different weapon, they'll return to your bag on login · unequipping the Bow also unequips the arrows.","Two-handed weapons other than a Bow (Staff, Quarterstaff, Dagger Pair, Hammer) can't equip anything in the left hand at all, so they get compensation: the weapon's flat stats count ×1.5 (fixed values like ATK, MATK, INT · % special options stay the same), and it can socket 2 cards.","A weapon that already has 1 card socketed can have a second one added without overwriting the first · once both slots are full, the socketing window lets you choose which one to replace."]}},{id:"2026-09-27-mailbox-load-retry",date:"2026-09-27",time:"21:52",title:"กล่องจดหมายโหลดไม่ค้างแล้ว",lines:['เปิดกล่องจดหมายแล้วส่งคำขอทันที ไม่ต้องรอครึ่งวินาทีเหมือนเดิม และระหว่างรอขึ้นว่า "กำลังโหลด…" แทนคำว่ายังไม่มีจดหมาย',"ถ้าเซิร์ฟเวอร์ตอบช้าหรือโหลดไม่สำเร็จ ระบบลองโหลดใหม่ให้เองทุก 3 วินาทีระหว่างที่หน้าต่างยังเปิดอยู่ ไม่ต้องปิดแล้วเปิดใหม่"],en:{title:"The mailbox no longer gets stuck loading",lines:[`Opening the mailbox now sends the request immediately, instead of the old half-second delay, and shows "Loading…" while waiting instead of saying there's no mail.`,"If the server responds slowly or the load fails, it now retries automatically every 3 seconds while the window stays open, so you don't have to close and reopen it."]}},{id:"2026-09-27-channel-grid-count",date:"2026-09-27",time:"21:48",title:"จำนวนคนในช่องไม่ทับเลขช่องแล้ว",lines:['หน้าเลือกเซิร์ฟเวอร์ ตารางช่องแสดงจำนวนคนเป็นตัวเลขหลังไอคอนคน แทนคำว่า "คน" ตัวเลขไม่ล้นไปทับเลขช่องอีก แม้เล่นภาษาอังกฤษหรือช่องมีคนหลักร้อย'],en:{title:"Channel player counts no longer overlap the channel number",lines:['On the server select page, the channel grid now shows the player count as a number after a person icon, instead of the word "players". The count no longer overflows onto the channel number, even in English or with a channel in the hundreds.']}},{id:"2026-09-27-relic-box-coatings",date:"2026-09-27",time:"21:29",title:"Mystery Relic Box: มีใบเคลือบธาตุแล้ว",lines:["เปิด Mystery Relic Box มีโอกาส 5% ได้ใบเคลือบธาตุ 1 ใบ สุ่มเท่ากันทั้ง 12 แบบ (เคลือบอาวุธ / เคลือบเกราะ อย่างละ 6 ธาตุ) แบบละประมาณ 0.42%","โอกาสได้อุปกรณ์สุ่ม (10%) การ์ด (1%) และปีกทองไม่เปลี่ยน · ยาและของใช้อื่นในหีบออกน้อยลงเล็กน้อยตามสัดส่วนเดิม"],en:{title:"Mystery Relic Box now includes elemental coatings",lines:["Opening a Mystery Relic Box now has a 5% chance to give 1 elemental coating scroll, rolled evenly across all 12 kinds (weapon coating / armor coating, 6 elements each) at about 0.42% each.","The chances of random equipment (10%), a card (1%) and Divine Wings are unchanged · potions and other consumables in the box drop slightly less often, in the same proportions as before."]}},{id:"2026-09-27-lighter-network",date:"2026-09-27",time:"21:27",title:"เกมใช้เน็ตน้อยลงเกือบครึ่ง",lines:["เซิร์ฟเวอร์ส่งข้อมูลรอบตัว 15 ครั้งต่อวินาที (เดิม 20) และส่งเฉพาะผู้เล่นกับมอนสเตอร์ที่ขยับหรือเปลี่ยน ตัวที่ยืนนิ่งไม่ถูกส่งซ้ำ","ของที่ตกบนพื้นส่งครั้งเดียวตอนตก ไม่ส่งซ้ำทุกรอบ แมพที่มีของกองอยู่เยอะจึงเบาลงมาก","แมพที่คนเยอะใช้เน็ตลดลงราว 40% เหมาะกับการเล่นผ่านเน็ตมือถือ การเคลื่อนไหวยังลื่นเหมือนเดิม","รีโหลดหน้าเกมหนึ่งครั้งเพื่อใช้ระบบใหม่"],en:{title:"The game now uses almost half the data",lines:["The server now sends nearby updates 15 times a second (was 20), and only for players and monsters that move or change; ones standing still aren't sent again.","Items lying on the ground are sent once, when they drop, instead of every tick, so maps with a lot of loot piled up are much lighter now.","Crowded maps use about 40% less data, which is easier on a mobile connection, while movement stays just as smooth.","Reload the game page once to pick up the new system."]}},{id:"2026-09-27-coat-exchange",date:"2026-09-27",time:"21:27",title:"ใบเคลือบธาตุ: เลิกขายในร้าน แลกด้วยของดรอปมอนสเตอร์แทน",lines:['พ่อค้า Silver ไม่ขายใบเคลือบธาตุแล้ว หน้าต่างเควส (กด Q) มีแท็บใหม่ "แลกของ" ให้แลกแทน',"ใช้ของดรอปจากมอนสเตอร์ธาตุเดียวกัน 50 ชิ้น แลกใบเคลือบอาวุธหรือเกราะ 1 ใบ ผสมหลายชนิดได้ เช่น ใบธาตุไฟใช้ Wisp Ember กับ Drake Scale รวมกัน · แลกได้ไม่จำกัดจากทุกที่","ระบบใช้ชิ้นที่เลเวลต่ำก่อน ของที่ล็อกไว้ในกระเป๋าจะไม่ถูกใช้ · ชี้ที่ชื่อธาตุเพื่อดูว่ามอนตัวไหนดรอปของธาตุนั้น","ใบเคลือบที่ซื้อไว้แล้วยังใช้ได้ตามปกติ · ขายคืนร้านได้ใบละ 10 Silver"],en:{title:"Elemental coatings: no longer sold in shops, traded for monster drops instead",lines:['The Silver Shop no longer sells elemental coatings. The Quest window (press Q) has a new "Exchange" tab to trade for them instead.',"Turn in 50 drops from monsters of the same element for 1 weapon or armor coating. You can mix item types, e.g. a fire coating can use Wisp Ember and Drake Scale combined · you can exchange any number of times, from anywhere.","The lowest-level items are used first, and locked items in your bag are never spent · hover an element's name to see which monsters drop items of that element.","Coatings you already bought still work as normal · you can sell them back to the shop for 10 Silver each."]}},{id:"2026-09-27-rename-card",date:"2026-09-27",time:"21:17",title:"Rename Card: เปลี่ยนชื่อตัวละครได้แล้ว",lines:["Item Mall มีบัตรเปลี่ยนชื่อ (Rename Card) ขายใบละ 300 Gold อยู่หน้าใหม่ Rename Card","บัตรอยู่ในแท็บ Cash ของกระเป๋า ดับเบิลคลิกแล้วพิมพ์ชื่อใหม่ บัตรถูกใช้เมื่อเปลี่ยนชื่อสำเร็จเท่านั้น ถ้าชื่อซ้ำจะไม่เสียบัตร","ชื่อเดิมถูกจองไว้ให้เจ้าของ 30 วัน คนอื่นตั้งชื่อนี้ไม่ได้ เพื่อไม่ให้มีใครสวมรอยรับกระซิบหรือคำเชิญแทน","เพื่อน กิลด์ ปาร์ตี้ จดหมาย Gold และของทุกชิ้นยังอยู่ครบ รายชื่อกิลด์และปาร์ตี้เปลี่ยนเป็นชื่อใหม่ทันที"],en:{title:"Rename Card: you can now change your character's name",lines:["The Item Mall now sells a Rename Card for 300 Gold, on its own new Rename Card page.","The card sits in the Cash tab of your bag; double-click it and type your new name. It's only consumed once the rename succeeds, so a duplicate name won't cost you the card.","Your old name is reserved for you for 30 days, and no one else can take it, so nobody can impersonate you to receive whispers or invites in your place.","Friends, guild, party, mail, Gold and every item stay intact. Guild and party lists update to your new name right away."]}},{id:"2026-09-27-explorer-stat-fit",date:"2026-09-27",time:"21:25",title:"ตัวเลขสรุปหน้า Explorer ไม่ล้นกรอบ",lines:["ยอด Silver และ Gold หมุนเวียนรวมบนหน้า Explorer ย่อขนาดตัวอักษรให้พอดีกรอบเมื่อตัวเลขยาว ไม่ล้นออกนอกช่องอีก"],en:{title:"Explorer summary numbers no longer overflow their box",lines:["Total Silver and Gold in circulation on the Explorer page now shrink to fit the box when the number gets long, instead of overflowing it."]}},{id:"2026-09-27-silver-shop-qty-header",date:"2026-09-27",time:"21:09",title:"ร้านพ่อค้า Silver: หัวคอลัมน์จำนวนไม่ทับราคาแล้ว",lines:['หัวตารางกระเป๋าในร้านพ่อค้า Silver คำว่า "จำนวน" ไม่ซ้อนทับกับ "ราคา NPC" อีก (เห็นชัดตอนเลือกภาษาอังกฤษ)'],en:{title:"Silver Shop: the Qty column header no longer overlaps the price",lines:[`In the Silver Shop's bag table header, "Qty" no longer overlaps "NPC Price" (most noticeable with English selected).`]}},{id:"2026-09-27-chat-own-line-echo",date:"2026-09-27",time:"21:06",title:"แชทโลก: ข้อความที่ส่งแล้วขึ้นให้ตัวเองเห็นทุกครั้ง",lines:["บางครั้งข้อความแชทโลกส่งถึงคนอื่นแล้ว แต่ไม่ขึ้นในกล่องแชทของคนพิมพ์เอง โดยเฉพาะตอนเพิ่งย้ายแมพหรือเซิร์ฟเวอร์ช้า ทำให้ต้องพิมพ์ซ้ำ 2–3 รอบ","ตอนนี้ข้อความที่ส่งสำเร็จจะขึ้นให้เห็นทันทีเสมอ และไม่ซ้ำเป็น 2 บรรทัด"],en:{title:"World chat: your own sent messages always show up now",lines:["Sometimes a world chat message reached everyone else but never appeared in the sender's own chat box, especially right after changing maps or when the server was slow, forcing you to retype it 2-3 times.","Every message that sends successfully now always shows up right away, and never appears twice."]}},{id:"2026-09-27-silver-shop-filter-row",date:"2026-09-27",time:"20:58",title:"ร้านพ่อค้า Silver: ตัวกรองรวมเป็นแถวเดียว",lines:["ตัวกรอง หมวดหมู่ · อาชีพ · ระดับใช้งาน · คุณภาพ · สเตตัส · ราคา NPC เปลี่ยนจากป้ายชื่อเป็นไอคอน แล้วเรียงรวมกับปุ่มกรองด่วนในแถวเดียว","ถ้าจอแคบจนไม่พอ เลื่อนแถวตัวกรองซ้าย–ขวาได้ ชี้เมาส์ค้างที่ตัวกรองเพื่อดูว่ากรองอะไร · รายการของในกระเป๋ามีที่แสดงมากขึ้น"],en:{title:"Silver Shop: filters combined into a single row",lines:["The Category · Class · Level · Quality · Stat · NPC Price filters have switched from text labels to icons, and now sit in one row together with the quick filter buttons.","If the screen is too narrow to fit them, the filter row scrolls left and right; hover over a filter to see what it filters by · the bag list now has more room to show items."]}},{id:"2026-09-27-explorer-flow-labels",date:"2026-09-27",time:"21:10",title:"Explorer: ชื่อแถวในตาราง Silver เข้า-ออก อ่านชัดแล้ว",lines:["ชื่อแถวด้านซ้ายของตาราง Silver เข้า-ออก (เช่น ขายของให้ NPC, ค่าตีบวก) เคยเป็นตัวอักษรสีจางบนพื้นสีครีมจนแทบมองไม่เห็น ตอนนี้เป็นตัวเข้มอ่านง่าย"],en:{title:"Explorer: row labels in the Silver in/out table are readable now",lines:[`The row labels on the left of the Silver in/out table (such as "sold to NPC" or "refine cost") used to be faint text on a cream background that was almost unreadable. They're bold and easy to read now.`]}},{id:"2026-09-27-silver-shop-icon-toggles",date:"2026-09-27",time:"20:53",title:"ร้านพ่อค้า Silver: ปุ่มกรองด่วนเหลือแค่ไอคอน",lines:["ปุ่มกรองด่วน ขายได้ · ล็อกไว้ · ของหายาก · มีการ์ด · ตีบวก เหลือเป็นไอคอนเล็กเรียงบรรทัดเดียว ชี้เมาส์ค้างเพื่อดูว่าปุ่มไหนกรองอะไร"],en:{title:"Silver Shop: quick filter buttons are icons only now",lines:["The quick filter buttons — Sellable · Locked · Rare · Carded · Refined — are now small icons in a single row; hover over one to see what it filters."]}},{id:"2026-09-27-bot-order-walk-in",date:"2026-09-27",time:"16:48",title:"ลำดับสกิลบอท: สกิลระยะสั้นไม่ถูกข้ามแล้ว",lines:["ตั้งลำดับสกิลเองแล้ว สกิลที่ระยะสั้นกว่าจุดที่ยืนยิง เช่น Leap Shot ของอาร์เชอร์ (ระยะ 170) จะไม่ถูกข้ามไปใช้ Twin Shot ตลอดอีก บอทจะเดินเข้าไปใกล้แล้วร่ายตามลำดับ","ระหว่างเดินเข้าไป บอทจะรอให้สกิลนั้นออกก่อนค่อยไปขั้นถัดไป ถ้าเข้าไม่ถึงภายใน 3 วินาทีจะข้ามไปขั้นต่อไป"],en:{title:"Bot skill order: short-range skills no longer get skipped",lines:["With a custom skill order set, a shorter-range skill than where you're standing to shoot — like an Archer's Leap Shot (range 170) — no longer gets skipped in favor of always casting Twin Shot. The bot will now walk in closer and cast it in order.","While walking in, the bot waits for that skill to fire before moving to the next step. If it can't get in range within 3 seconds, it skips to the next step."]}},{id:"2026-09-27-boost-icons-redrawn",date:"2026-09-27",time:"16:47",title:"รูปใหม่ของ EXP Scroll และ Drop Scroll",lines:["EXP Scroll และ Drop Scroll เป็นม้วนคัมภีร์แบบกางออกแนวตั้ง มีแกนม้วนบนล่าง ไม่สับสนกับ Warp Scroll และ Return Scroll ที่ม้วนนอนอีกแล้ว","EXP Scroll แกนสีน้ำเงิน มีมงกุฎใบลอเรลทองคำกลางม้วน · Drop Scroll แกนสีเขียว มีเขาแห่งความอุดมสมบูรณ์ที่อัญมณีและเหรียญทะลักออกมา","ผลของไอเทมเหมือนเดิมทุกอย่าง"],en:{title:"New artwork for EXP Scroll and Drop Scroll",lines:["EXP Scroll and Drop Scroll are now unrolled scrolls held vertically, with rolled ends at top and bottom, so they're no longer easy to mistake for the horizontally rolled Warp Scroll and Return Scroll.","EXP Scroll has blue ends with a gold laurel crown in the middle · Drop Scroll has green ends with a cornucopia spilling out gems and coins.","The item's effect is unchanged."]}},{id:"2026-09-27-element-coatings",date:"2026-09-27",time:"16:27",title:"ใบเคลือบธาตุ อาวุธและเกราะ",lines:["พ่อค้าขายใบเคลือบธาตุใหม่ 12 แบบ: เคลือบอาวุธ และเคลือบเกราะ อย่างละ 6 ธาตุ (🔥ไฟ 💧น้ำ 🌀ลม 🍃ดิน ☀แสง ☾มืด) ใบละ 400 Silver","เคลือบอาวุธ: การตีปกติและสกิลไร้ธาตุกลายเป็นธาตุนั้น ชนะทางได้ 125% แพ้ทางเหลือ 75% (สกิลที่มีธาตุของตัวเองยังใช้ธาตุเดิม)","เคลือบเกราะ: ตัวเราเป็นธาตุนั้นเวลาโดนตี ทั้งจากมอนสเตอร์ บอส และคู่ดวล เลือกธาตุที่ชนะทางมอนในแมพจะโดนเบาลง แต่ถ้าเลือกผิดจะโดนแรงขึ้น","ใช้ 1 ใบอยู่ได้ 30 นาที ใช้ธาตุเดิมซ้ำเพื่อต่อเวลาได้สูงสุด 5 ชั่วโมง ใช้ธาตุอื่นจะแทนที่ของเดิมทันที · ตายแล้วไม่หาย","ดูธาตุและจุดแพ้ทางของมอนแต่ละตัวได้ในสมุดมอนสเตอร์"],en:{title:"Elemental coatings for weapons and armor",lines:["The merchant now sells 12 new elemental coating scrolls: weapon coating and armor coating, 6 elements each (🔥 fire, 💧 water, 🌀 wind, 🍃 earth, ☀ light, ☾ dark), at 400 Silver each.","Weapon coating: your basic attacks and elementless skills take on that element, dealing 125% against a weaker element and only 75% against a stronger one (skills with their own element keep their original element).","Armor coating: you take on that element when hit, whether by a monster, a boss or a duel opponent. Picking an element that beats the map's monsters means you take less damage, but the wrong pick means you take more.","One scroll lasts 30 minutes. Using the same element again extends it up to a maximum of 5 hours; using a different element replaces it immediately · it survives death.","You can check each monster's element and weakness in the Monster Book."]}},{id:"2026-09-27-elite-twohand-english",date:"2026-09-27",time:"16:15",title:"แปลภาษาอังกฤษ: ตัวเลือก Elite ของบอท และช่องมือซ้ายตอนถืออาวุธสองมือ",lines:['ช่อง "ตีมอนสเตอร์ Elite ★ ด้วย" ในหน้าตั้งค่าบอท และข้อความอาวุธสองมือที่ช่องมือซ้าย แสดงเป็นภาษาอังกฤษแล้วเมื่อเลือกภาษาอังกฤษ'],en:{title:"English translation: the bot's Elite option and the left-hand slot with two-handed weapons",lines:['The "Also attack Elite ★ monsters" checkbox on the bot settings page, and the two-handed weapon message on the left-hand slot, now display in English when English is selected.']}},{id:"2026-09-27-two-hand-left-slot",date:"2026-09-27",time:"16:10",title:"ช่องมือซ้ายแสดงอาวุธสองมือ",lines:["สวม Staff, Bow, Quarterstaff, Dagger Pair หรือ Hammer แล้ว ช่องมือซ้ายในหน้าสวมใส่จะแสดงอาวุธชิ้นเดียวกันด้วย ให้เห็นชัดว่ามือซ้ายไม่ว่าง","กดช่องมือซ้ายจะเห็นรายละเอียดอาวุธ และกดถอดจะถอดอาวุธสองมือออก"],en:{title:"The left-hand slot now shows two-handed weapons",lines:["With a Staff, Bow, Quarterstaff, Dagger Pair or Hammer equipped, the left-hand slot on the equipment page now shows the same weapon too, making it clear the left hand isn't free.","Clicking the left-hand slot shows the weapon's details, and clicking unequip removes the two-handed weapon."]}},{id:"2026-09-27-divine-elements",date:"2026-09-27",time:"15:58",title:"ระบบธาตุเทพเจ้า: มอนสเตอร์ทุกตัวมีธาตุแล้ว",lines:["มอนสเตอร์ทุกตัวมีธาตุประจำเทพ 6 ธาตุ: 🔥ไฟ (Hephaestus) 💧น้ำ (Poseidon) 🌀ลม (Aeolus) 🍃ดิน (Gaia) ☀แสง (Apollo) ☾มืด (Chaos)","วงจรแพ้ทาง: ลม > น้ำ > ไฟ > ดิน > ลม ฝั่งที่ชนะทำดาเมจ 125% ฝั่งที่แพ้ 75%","แสงกับมืดตีกัน 150% · แสง/มืดตี 4 ธาตุหลักได้ 100% แต่ 4 ธาตุหลักตีแสง/มืดได้แค่ 75%","สกิลที่มีธาตุ: Ember Bolt, Flame Burst (ไฟ) · Frost Area (น้ำ) · Stormbreak (ลม) · Tierra Sharp Spear (ดิน) · Radiant Light (แสง) · Shadow Burst (มืด) · การโจมตีปกติและสกิลอื่นไร้ธาตุ ได้ 100% เสมอ","ดูธาตุและจุดแพ้ทางของมอนแต่ละตัวได้ในสมุดมอนสเตอร์ และคำอธิบายสกิลบอกธาตุของสกิลแล้ว"],en:{title:"Divine Elements: every monster now has an element",lines:["Every monster now has one of the 6 divine elements: 🔥 fire (Hephaestus), 💧 water (Poseidon), 🌀 wind (Aeolus), 🍃 earth (Gaia), ☀ light (Apollo), ☾ dark (Chaos).","The weakness cycle is wind > water > fire > earth > wind; the winning side deals 125% damage, the losing side 75%.","Light and dark deal 150% against each other · light/dark deal 100% against the 4 core elements, but the 4 core elements only deal 75% against light/dark.","Skills with an element: Ember Bolt, Flame Burst (fire) · Frost Area (water) · Stormbreak (wind) · Tierra Sharp Spear (earth) · Radiant Light (light) · Shadow Burst (dark) · basic attacks and every other elementless skill always deal 100%.","You can check each monster's element and weakness in the Monster Book, and skill descriptions now state each skill's element."]}},{id:"2026-09-27-status-name-translate",date:"2026-09-27",time:"15:37",title:"ชื่อสถานะที่ลอยขึ้นบนหัวแปลตามภาษาที่เลือกแล้ว",lines:["ตอนมอนสเตอร์ติดสถานะ (พิษ สตัน แช่แข็ง เผาไหม้ ตาพร่า ฯลฯ) ชื่อสถานะที่เด้งขึ้นเหนือหัวมอนเคยเป็นภาษาไทยเสมอ ตอนนี้แสดงตามภาษาที่เลือกในตั้งค่า","ข้อความที่ลอยขึ้นเหนือตัวละครของเราเอง เช่น ติดสถานะ สถานะหมด หรือบัฟที่ได้รับ ก็แปลตามภาษาที่เลือกด้วย"],en:{title:"Status names floating above heads now follow your language",lines:["When a monster gets a status effect (poison, stun, freeze, burn, blind, etc.), the status name that pops up above its head used to always show in Thai. It now follows the language chosen in settings.","Text floating above your own character, such as gaining a status, a status wearing off, or a buff you receive, is also translated to your chosen language."]}},{id:"2026-09-27-bot-skip-elite",date:"2026-09-27",time:"15:33",title:"บอท: เลือกได้ว่าจะตีมอนสเตอร์ Elite หรือไม่",lines:['หน้าตั้งค่าบอท หัวข้อ "มอนสเตอร์ที่โจมตี" มีช่อง "ตีมอนสเตอร์ Elite ★ ด้วย" เพิ่มมา ติ๊กไว้ให้อยู่แล้ว บอทจึงตี Elite เหมือนเดิม',"เอาติ๊กออกแล้วบอทจะข้ามร่าง Elite ของทุกชนิด ตีเฉพาะตัวปกติที่ติ๊กไว้ · ถ้าไม่ได้ติ๊กมอนชนิดไหนไว้ บอทก็ไม่ตีร่าง Elite ของชนิดนั้นเหมือนกัน"],en:{title:"Bot: choose whether to attack Elite monsters",lines:[`The bot settings page, under "Monsters to attack", now has a "Also attack Elite ★ monsters" checkbox. It's checked by default, so the bot attacks Elites as before.`,"Uncheck it and the bot will skip Elite forms of every monster type, attacking only the normal ones you've checked · if a monster type isn't checked at all, the bot skips its Elite form too."]}},{id:"2026-09-27-silver-shop-sell-all-button",date:"2026-09-27",time:"15:16",title:'ร้านพ่อค้า Silver: ปุ่ม "ขายทั้งหมด" ทุกแถว',lines:['ปุ่ม + ท้ายแถวในกระเป๋าเปลี่ยนเป็น "ขายทั้งหมด" กดทีเดียวใส่ทั้งกองที่เหลือลงรายการที่จะขาย',"คลิกที่ชื่อหรือตัวแถวยังเพิ่มทีละ 1 ชิ้นเหมือนเดิม",'ปุ่ม "ขายทั้งหมด" แยกตามชนิด (วัตถุดิบ · ของใช้ · การ์ด · อุปกรณ์) กลับมาอยู่ใต้รายการกระเป๋าแล้ว อุปกรณ์ที่ตีบวกหรือฝังการ์ดยังไม่ถูกใส่ให้อัตโนมัติ'],en:{title:'Silver Shop: a "Sell all" button on every row',lines:['The + button at the end of each bag row now becomes "Sell all" — one click adds the entire remaining stack to the sell list.',"Clicking the item's name or the row itself still adds 1 at a time, as before.",`The "Sell all" buttons split by type (materials · consumables · cards · equipment) are back below the bag list. Refined or carded equipment still isn't added automatically.`]}},{id:"2026-09-27-silver-shop-no-spinner",date:"2026-09-27",time:"14:59",title:"ร้านพ่อค้า Silver: ของที่จะขายย้ายไปฝั่งขวา และช่องจำนวนไม่มีลูกศรแล้ว",lines:["ช่องจำนวนในรายการที่จะขายและที่จะซื้อ เอาลูกศรขึ้น/ลงเล็กๆ ออกแล้ว ตัวเลขไม่โดนบัง ใช้ปุ่ม − / + หรือพิมพ์จำนวนเองได้เหมือนเดิม","ใส่ของลงรายการที่จะขายแล้ว ของจะย้ายออกจากกระเป๋าฝั่งซ้าย: เหลือเฉพาะจำนวนที่ยังไม่ได้ใส่ และถ้าใส่ครบทั้งกองแถวนั้นจะหายไป กด × ฝั่งขวาเพื่อคืนกลับ"],en:{title:"Silver Shop: sell list moved to the right, and the quantity field lost its spinner arrows",lines:["The quantity field in the sell and buy lists has had its small up/down arrows removed, so the number is no longer hidden. You can still use the − / + buttons or type the quantity in directly.","Once an item is added to the sell list, it's removed from the bag on the left: only the amount not yet added remains, and if the whole stack is added the row disappears. Press × on the right to return it."]}},{id:"2026-09-27-arrow-rain-wider-circle",date:"2026-09-27",time:"14:57",title:"Arrow Rain วงกว้างขึ้น",lines:["วงกลมของสกิล Arrow Rain ขยายจากกว้าง 5 ช่องเป็นกว้าง 7 ช่อง (รัศมี 3.5 ช่อง) ครอบคลุมมากกว่าสี่เหลี่ยม 5x5 แบบเดิมเกือบเท่าตัว","ความแรง จำนวนฮิต และคูลดาวน์ไม่เปลี่ยน"],en:{title:"Arrow Rain's circle is wider",lines:["The Arrow Rain circle has grown from 5 tiles wide to 7 tiles wide (radius 3.5 tiles), covering nearly double the area of the old 5x5 square.","Power, hit count and cooldown are unchanged."]}},{id:"2026-09-27-arrow-rain-circle",date:"2026-09-27",time:"14:45",title:"Arrow Rain ตกเป็นวงกลม",lines:["พื้นที่สกิล Arrow Rain เปลี่ยนจากสี่เหลี่ยม 5x5 ช่องเป็นวงกลมกว้าง 5 ช่อง ทั้งกรอบบนพื้น ลูกธนูที่ตก และมอนสเตอร์ที่โดน","ความแรง จำนวนฮิต และคูลดาวน์ไม่เปลี่ยน"],en:{title:"Arrow Rain now falls in a circle",lines:["Arrow Rain's area has changed from a 5x5 tile square to a circle 5 tiles wide — the ground outline, the falling arrows, and which monsters get hit.","Power, hit count and cooldown are unchanged."]}},{id:"2026-09-27-card-weight-tenth",date:"2026-09-27",time:"14:41",title:"การ์ดเบาลง: หนักใบละ 0.1",lines:["การ์ดทุกใบหนัก 0.1 จากเดิม 1 ทั้งการ์ดในกระเป๋า คลัง กระเป๋าสัตว์เลี้ยง และการ์ดที่ฝังอยู่ในอุปกรณ์","เก็บการ์ดไว้เยอะแค่ไหนก็แทบไม่กินน้ำหนักแล้ว น้ำหนักรวมในกระเป๋าอาจแสดงเป็นทศนิยม 1 ตำแหน่ง"],en:{title:"Cards are lighter: 0.1 weight each",lines:["Every card now weighs 0.1, down from 1 — in your bag, storage, pet bags, and cards socketed into equipment.","Holding onto a large card collection barely costs any weight now. Your total bag weight may display with 1 decimal place."]}},{id:"2026-09-27-silver-shop-landscape",date:"2026-09-27",time:"14:37",title:"ร้านพ่อค้า Silver: หน้าต่างแนวนอนแบบใหม่",lines:["หน้าต่างร้านพ่อค้า Silver เปลี่ยนเป็นแนวนอน: กระเป๋าพร้อมตัวกรองอยู่ซ้าย รายการที่จะขายอยู่ขวา",'ทุกแถวบอกหมวดหมู่และประเภทไอเท็ม เช่น "อาวุธ / พลอง" หรือ "ของใช้ / ยา"',"ปุ่ม ขายของ / ซื้อของ ย้ายมาอยู่กลางแถบ Silver · ปุ่ม + บนหัวตารางกระเป๋าเพิ่มทุกรายการที่กรองไว้ลงรายการขาย","หน้าต่างไม่ล้นจอโน้ตบุ๊ก และบนมือถือยังเรียงเป็นคอลัมน์เดียว"],en:{title:"Silver Shop: new landscape window",lines:["The Silver Shop window is now landscape: your bag with its filters on the left, the sell list on the right.",`Every row now shows the item's category and type, e.g. "Weapon / Staff" or "Consumable / Potion".`,"The Sell / Buy buttons have moved to the middle of the Silver bar · the + button on the bag table header adds every filtered item to the sell list.","The window no longer overflows a laptop screen, and still lays out as a single column on mobile."]}},{id:"2026-09-27-elite-monsters",date:"2026-09-27",time:"14:35",title:"มอนสเตอร์ Elite ★ โผล่ในทุกแผนที่ล่า",lines:["มอนสเตอร์ธรรมดาทุกตัวมีโอกาส 10% เกิดใหม่เป็นร่าง Elite — ชื่อสีส้มมี ★ Elite นำหน้า ตัวใหญ่ขึ้นและสีอุ่นขึ้น","Elite มี HP x4 และตีแรง x2 ของตัวปกติ ความยากอยู่กลางระหว่างมอนธรรมดากับบอส ควรพกยาหรือไปเป็นปาร์ตี้","ล้ม Elite ได้ EXP x4 และโอกาสดรอปของทุกชิ้น x4 (การ์ด อุปกรณ์ Relic Box หิน Refine) พอตายแล้วเกิดใหม่จะสุ่มใหม่ว่าเป็น Elite หรือไม่","บอสมงกุฎไม่มีร่าง Elite"],en:{title:"Elite ★ monsters now appear on every hunting map",lines:["Every normal monster now has a 10% chance to spawn as an Elite form — an orange name with a ★ Elite prefix, bigger and with warmer coloring.","An Elite has x4 the HP and hits x2 as hard as its normal form, sitting in difficulty between a normal monster and a boss — bring potions or go as a party.","Killing an Elite gives x4 EXP and x4 the drop chance for everything (cards, equipment, Relic Box, Refine Stones). When it respawns after dying, whether it's Elite is rolled again.","Crowned bosses have no Elite form."]}},{id:"2026-09-27-storage-fee-reopen",date:"2026-09-27",time:"14:28",title:"แก้เปิดคลังไม่ได้ทั้งที่มี Silver พอ",lines:['เดินออกจากเจ้าหน้าที่คลังแล้วกลับมาโดยไม่ได้ปิดหน้าต่างคลัง ฝาก–ถอนของจะขึ้นว่า "เปิดคลังก่อน (ค่าบริการ 100 Silver)" ตลอด แม้มี Silver เหลือเฟือ',"ตอนนี้ฝาก–ถอนได้เลย ระบบหักค่าเปิดคลัง 100 Silver ให้อัตโนมัติครั้งเดียวต่อการมาใช้คลังหนึ่งรอบ"],en:{title:"Fixed: storage wouldn't open even with enough Silver",lines:['Walking away from the storage clerk and back without closing the storage window meant deposits and withdrawals always showed "Open storage first (100 Silver fee)", even with plenty of Silver to spare.',"You can now deposit and withdraw right away; the 100 Silver storage fee is deducted automatically, once per storage visit."]}},{id:"2026-09-27-monster-etc-items",date:"2026-09-27",time:"13:58",title:"มอนทุกชนิดดรอปวัตถุดิบ ETC ของตัวเอง",lines:["มอนสเตอร์ทั้ง 47 ชนิดดรอปวัตถุดิบประจำตัวแทน Spirit Shard เช่น Drake Scale จาก Sand Drake, Wolf Fang จาก Forest Wolf, Tempest Dragon Scale จาก Tempest Drake · โอกาสดรอป 30% เท่าเดิม","ทุกชิ้นหนัก 1 ราคาขายให้ร้านค้าไล่ตามเลเวลมอน: มอนแมพแรกขายได้ 1–2 Silver ไปจนถึง 100 Silver ที่มอน Lv.270","บอส Crowned ดรอปวัตถุดิบของมอนร่างนั้น ×5 · ดูรายการทั้งหมดได้ในสมุดมอนสเตอร์และ Wiki","Spirit Shard เลิกดรอปแล้ว ชิ้นที่มีอยู่ยังขายร้านค้าได้ 8 Silver เหมือนเดิม","อัปเลเวลกิลใช้ EXP กิลอย่างเดียว ไม่ต้องใช้ Spirit Shard แล้ว (เติมเร็วขึ้นด้วย Silver ได้เหมือนเดิม) · สร้างกิลเหลือ 800 Gold + 200,000 Silver","เอาเควสถวาย Spirit Shard รายวันออก · เควสล่ารายวัน 100 ตัวยังได้ Refine Stone 3 ก้อนเหมือนเดิม"],en:{title:"Every monster now drops its own ETC material",lines:["All 47 monster types now drop their own signature material instead of Spirit Shard, e.g. Drake Scale from Sand Drake, Wolf Fang from Forest Wolf, Tempest Dragon Scale from Tempest Drake · drop chance stays at 30%.","Every item weighs 1, and its sell price to the shop scales with monster level: from 1-2 Silver on the first maps up to 100 Silver at Lv.270 monsters.","A Crowned boss drops that monster's material ×5 · see the full list in the Monster Book and the Wiki.","Spirit Shard no longer drops. Any you already have still sell to the shop for 8 Silver, as before.","Leveling up a guild now only uses Guild EXP; Spirit Shard is no longer needed (you can still speed it up with Silver, as before) · founding a guild now costs 800 Gold + 200,000 Silver.","The daily Spirit Shard donation quest has been removed · the daily 100-kill quest still gives 3 Refine Stones, as before."]}},{id:"2026-09-27-silver-shop-half-size",date:"2026-09-27",time:"14:02",title:"ร้านพ่อค้า Silver: ย่อหน้าต่างเหลือครึ่ง",lines:["หน้าต่างร้านพ่อค้า Silver เล็กลงครึ่งหนึ่ง ไม่ล้นขอบจอ และยังเห็นช่องค้นหา ตัวกรอง รายการที่จะขาย กับปุ่มยืนยันขายครบในหน้าเดียว","แถบหัวหน้าต่างกลับมาเรียบร้อย ชื่อร้าน ปุ่มปิด และแถบ Silver ไม่ทับกันแล้ว ตัวกรองเรียงชิดกันขึ้น"],en:{title:"Silver Shop: window shrunk to half size",lines:["The Silver Shop window is now half the size, no longer overflowing the screen edge, while still fitting the search box, filters, sell list and confirm-sell button all on one screen.","The window's title bar is tidy again: the shop name, close button and Silver bar no longer overlap, and the filters sit closer together."]}},{id:"2026-09-27-silver-shop-sell-filters",date:"2026-09-27",time:"13:40",title:"ร้านพ่อค้า Silver โฉมใหม่: ค้นหาและกรองของที่จะขาย",lines:["ฝั่งของในกระเป๋ามีช่องค้นหา (ชื่อ ประเภท สเตตัส หรือชื่อการ์ดที่ฝัง) และตัวกรอง หมวดหมู่ · อาชีพ · ระดับใช้งาน · คุณภาพ · สเตตัส · เรียงตามราคา NPC",'ปุ่มกรองด่วน ขายได้ · ล็อกไว้ · ของหายาก · มีการ์ด · ตีบวก และแถบตัวกรองที่เลือกอยู่ กด × เพื่อเอาออก หรือ "ล้างทั้งหมด"','ปุ่ม "เพิ่มทั้งหมด: ที่แสดงอยู่" ใส่ทุกรายการที่กรองไว้ลงรายการขายในครั้งเดียว (ข้ามอุปกรณ์ที่ตีบวกหรือฝังการ์ด)',"รายการที่จะขายปรับจำนวนด้วย − / + ได้ในแถว แสดงราคาต่อชิ้นและราคารวม คลิกแถวเพื่อเลือก 1 · 10 · ครึ่ง · ทั้งหมด ได้ด้านล่าง","ชี้เมาส์ที่ไอเท็มทุกแถว (ทั้งในกระเป๋า รายการขาย และกล่องที่เลือก) ดูรายละเอียดได้ครบ รวมราคาต่อชิ้น ราคารวมทั้งกอง และจำนวนที่ใส่ในรายการขายแล้ว"],en:{title:"Silver Shop redesigned: search and filter what you're selling",lines:["The bag side now has a search box (by name, type, stat, or socketed card name) and filters for Category · Class · Level · Quality · Stat · sort by NPC Price.",'Quick filter buttons — Sellable · Locked · Rare · Carded · Refined — and a chip strip for active filters; click × to remove one, or "Clear all".','The "Add all: shown" button adds every filtered item to the sell list in one click (skipping refined or carded equipment).',"The sell list lets you adjust quantity with − / + right in the row, showing per-item and total price. Click a row to pick 1 · 10 · half · all from the options below.","Hovering an item in any row (in the bag, the sell list, or the selection box) shows its full details, including per-item price, total stack price, and how much is already in the sell list."]}},{id:"2026-09-27-melee-ranged-flee",date:"2026-09-27",time:"13:31",title:"ปรับสมดุล: มอนหลบตีใกล้กับยิงไกลไม่เท่ากัน",lines:["มอนสเตอร์มี FLEE สองค่า: หลบการตีระยะประชิด (ดาบ มีด มือเปล่า) = 100 + เลเวล และหลบการโจมตีระยะไกล (ธนู คุไน) = 100 + 2 × เลเวล เท่าเดิม","สายตีใกล้ไม่ต้องอัด DEX เพื่อให้ตีโดนอีกแล้ว ไม่มี DEX เลยก็ตีมอนเลเวลเท่าตัวเองโดนราว 90% เอาแต้มไปลงค่าอื่นได้ ส่วนแมพลึกใช้ DEX/LUK/HIT จากของนิดหน่อยก็พอ","สายธนูและคุไนยังต้องใช้ DEX สูงเหมือนเดิม ซึ่งเป็นค่าหลักที่ให้ ATK อยู่แล้ว · สกิลเวท (MATK) ยังโดนเสมอ","สมุดมอนสเตอร์แสดง FLEE และ HIT ที่ต้องใช้แยกระยะประชิดกับระยะไกล"],en:{title:"Balance: monsters dodge melee and ranged attacks differently",lines:["Monsters now have two FLEE values: dodge against melee attacks (sword, dagger, bare hands) = 100 + level, and dodge against ranged attacks (bow, kunai) = 100 + 2 × level, unchanged.","Melee builds no longer need to stack DEX just to land hits — with zero DEX you'll still hit a monster of your own level about 90% of the time, so you can put those points elsewhere. On deep maps, just a little DEX/LUK/HIT from gear is enough.","Bow and kunai builds still need high DEX as before, which is already their main ATK stat · magic skills (MATK) still always land.","The Monster Book now shows FLEE and the HIT needed, split between melee and ranged."]}},{id:"2026-09-27-remote-shop-keeps-bot",date:"2026-09-27",time:"13:29",title:"ซื้อของร้าน Silver แล้วบอทไม่หยุดตีมอน",lines:["ซื้อของจากพ่อค้า Silver ระหว่างอยู่ในแมพ (ร้านระยะไกลของ Premium) เคยทำให้บอทหยุดโจมตีและต้องกดเปิดใหม่ ตอนนี้บอทยังตีมอนต่อตามปกติ"],en:{title:"Buying from the Silver Shop no longer stops the bot from attacking",lines:["Buying from the Silver Shop while out on a map (the Premium remote shop) used to stop the bot from attacking, requiring you to turn it back on. The bot now keeps attacking normally."]}},{id:"2026-09-27-guild-offline-for",date:"2026-09-27",time:"13:27",title:"กิล: ดูได้ว่าสมาชิกออฟไลน์ไปนานเท่าไร",lines:['รายชื่อสมาชิกกิลบอกเวลาใต้คำว่า "ออฟไลน์" ว่าออกจากเกมไปกี่นาที กี่ชั่วโมง หรือกี่วันแล้ว (คลาดเคลื่อนได้ไม่เกินราว 5 นาที)','สมาชิกที่ไม่มีบันทึกการเล่นล่าสุดจะแสดงแค่ "ออฟไลน์" เหมือนเดิม'],en:{title:"Guild: see how long a member has been offline",lines:[`The guild member list now shows, under "Offline", how many minutes, hours or days it's been since they logged out (accurate to within about 5 minutes).`,'Members with no recent play record still just show "Offline", as before.']}},{id:"2026-09-27-weapon-luk-roll",date:"2026-09-27",time:"13:21",title:"อาวุธดรอปสุ่ม LUK ได้แล้ว",lines:["อาวุธที่ดรอปจากมอนสเตอร์ทุกชนิด (ทั้งสายตี สายเวท และกึ่งเวท) มีโอกาสสุ่มได้สเตตัส LUK แล้ว จากเดิมที่สุ่มไม่ได้เลย","อาวุธที่ดรอปก่อนหน้านี้ไม่เปลี่ยนแปลง"],en:{title:"Dropped weapons can now roll LUK",lines:["Weapons dropped from every monster type (melee, magic and hybrid alike) can now roll a LUK stat, where before it could never appear at all.","Weapons dropped before this change are unaffected."]}},{id:"2026-09-27-party-exp-log-chat-all",date:"2026-09-27",time:"13:20",title:'แท็บ EXP เห็น EXP ที่แชร์จากปาร์ตี้ และแท็บ "ทั้งหมด" เหลือแค่แชทผู้เล่น',lines:["EXP ที่ได้จากเพื่อนร่วมปาร์ตี้ตีมอนสเตอร์ที่อยู่ไกลออกไปในแมพเดียวกัน ขึ้นในแท็บ EXP แล้ว (เดิมได้ EXP จริงแต่ไม่ขึ้นบรรทัดในแท็บ)",'แท็บ "ทั้งหมด" ในแชทแสดงเฉพาะข้อความที่ผู้เล่นคุยกัน: โลก ปาร์ตี้ กิล และกระซิบ · ข้อความระบบดูได้ที่แท็บ "ระบบ"'],en:{title:'EXP tab now shows party-shared EXP, and the "All" tab is player chat only',lines:["EXP earned from a party member killing a monster elsewhere on the same map now shows up in the EXP tab (you actually got the EXP before too, it just never logged a line).",'The "All" chat tab now shows only messages between players: world, party, guild and whispers · system messages are on the "System" tab.']}},{id:"2026-09-27-chat-unsent-retry",date:"2026-09-27",time:"13:03",title:"แชท: ส่งไม่ผ่านแล้วลองใหม่ได้ทันที",lines:['เดิมถ้าเซิร์ฟเวอร์แชทตอบช้า ระบบจะบอกว่าข้อความไม่ถูกส่ง แต่พอกดส่งซ้ำกลับขึ้นว่า "ข้อความเดิมเพิ่งส่งไปแล้ว" ทำให้ส่งไม่ได้จนต้องรอ',"ตอนนี้ข้อความที่ส่งไม่ผ่านจะถูกส่งซ้ำให้อัตโนมัติหนึ่งครั้ง ถ้ายังไม่ผ่านจะแจ้งเตือนและใส่ข้อความกลับในช่องพิมพ์ กด Enter ส่งใหม่ได้เลย","ข้อความที่ส่งซ้ำจะไม่ขึ้นซ้ำสองบรรทัดในแชท"],en:{title:"Chat: retry immediately after a failed send",lines:[`If the chat server responded slowly before, you'd be told the message failed to send, but resending it triggered "You just sent that message", leaving you stuck waiting.`,"A failed message is now retried automatically once. If it still fails, you'll get a notice and the text is put back in the input box, so pressing Enter sends it again right away.","A retried message won't appear twice in the chat."]}},{id:"2026-09-27-wiki-guild-exp-level",date:"2026-09-27",time:"13:17",title:"อัปเดต Wiki: วิธีอัปเลเวลกิลแบบใหม่ (EXP กิล)",lines:["หัวข้อระบบกิลใน Wiki เคยบอกแค่ว่าอัปเลเวลด้วย Spirit Shard และ Silver ล้วน ๆ ตอนนี้อัปเดตให้ตรงกับระบบปัจจุบัน: ต้องเติมทั้งกองทุน Spirit Shard และกองทุน EXP กิล (มาจาก Base EXP ที่สมาชิกแบ่งให้อัตโนมัติสูงสุด 50% ต่อครั้ง บวก Silver แปลงเป็น EXP กิลตอนอัปเลเวล) พร้อมตารางค่าใช้จ่ายและโบนัส EXP ครบทุกเลเวล 1–20 และเรื่องเชิญเข้ากิลตรง ๆ กับโอนหัวกิล"],en:{title:"Wiki update: the new way to level up a guild (Guild EXP)",lines:["The guild system section of the Wiki used to say leveling up was purely Spirit Shard and Silver. It's now updated to match the current system: you need to fund both the Spirit Shard pool and the Guild EXP pool (from Base EXP members auto-contribute, up to 50% per kill, plus Silver converted to Guild EXP when leveling up), with a full cost and EXP bonus table for levels 1-20, and coverage of direct guild invites and transferring guild leadership."]}},{id:"2026-09-27-market-sell-panel-fit",date:"2026-09-27",time:"12:49",title:"ตลาด: กรอบตั้งขายไม่เลื่อนซ้ายขวาแล้ว",lines:["กรอบรายละเอียดด้านขวาในหน้าขายสินค้าเคยเลื่อนซ้ายขวาได้จนเนื้อหาเบี้ยว และมีช่องว่างยาวจนต้องเลื่อนลงไปไกลกว่าจะเจอยอดเงิน ตอนนี้กรอบล็อกแนวนอนแล้ว เลื่อนได้แค่ขึ้นลง",'ยอด "จะได้รับเมื่อขายหมด" ย้ายไปติดอยู่เหนือปุ่มตั้งขายท้ายกรอบ เห็นตลอดไม่ต้องเลื่อนหา'],en:{title:"Market: the listing panel no longer scrolls sideways",lines:["The details panel on the right of the Sell page used to scroll horizontally, throwing off the layout, and had a long blank gap before you'd finally scroll down far enough to find the total. The panel is now locked horizontally and only scrolls up and down.",`The "You'll receive when fully sold" total has moved to sit right above the list button at the bottom of the panel, always visible without scrolling to find it.`]}},{id:"2026-09-27-sell-list-hover",date:"2026-09-27",time:"12:35",title:"ดูรายละเอียดของในรายการที่จะขาย",lines:["เอาเมาส์ชี้ของในรายการที่จะขายที่พ่อค้า จะเห็นรายละเอียดเหมือนตอนชี้ในกระเป๋า (ค่าสถานะ การ์ด ระดับตีบวก) บนมือถือกดค้างเพื่อเปิดการ์ดรายละเอียดได้ ตรวจของก่อนกดขายได้ง่ายขึ้น"],en:{title:"See item details in the sell list",lines:["Hovering an item in the merchant's sell list now shows the same details as hovering it in your bag (stats, cards, refine level). On mobile, press and hold to open the details card, making it easier to check items before selling."]}},{id:"2026-09-27-market-stat-filter-translate",date:"2026-09-27",time:"11:55",title:"แปลช่องกรองสเตตัสในตลาด",lines:['ช่อง "+ กรองสเตตัส" และหัวข้อกลุ่ม (สเตตัสหลัก ค่าต่อสู้ ออปชันพิเศษ) ในหน้าซื้อสินค้าแสดงตามภาษาที่เลือกแล้ว ไม่ขึ้นเป็นภาษาไทยอีก'],en:{title:"Market stat filter translated",lines:['The "+ Filter by stat" box and its group headings (Main Stats, Combat Stats, Special Options) on the Buy page now display in the chosen language, instead of always showing in Thai.']}},{id:"2026-09-27-momentum-10s",date:"2026-09-27",time:"11:18",title:"Momentum อยู่ได้นานขึ้นเป็น 10 วินาที",lines:["ชั้น Momentum ของการตีปกติจะหายเมื่อไม่ได้ตีโดน 10 วินาที (จากเดิม 3 วินาที) เปลี่ยนเป้า เดินหามอน หรือเก็บของได้โดยไม่เสียชั้น","ใช้สกิลโจมตียังทำให้ชั้นหายหมดเหมือนเดิม · ไม่มีผลใน PVP เหมือนเดิม"],en:{title:"Momentum now lasts up to 10 seconds",lines:["Basic-attack Momentum stacks now clear after 10 seconds without landing a hit (up from 3 seconds), so you can switch targets, walk to find a monster, or pick up loot without losing your stacks.","Using an attack skill still clears every stack, as before · it still has no effect in PVP."]}},{id:"2026-09-27-job-outfit-after-class-switch",date:"2026-09-27",time:"11:17",title:"แก้ชุดอาชีพกลายเป็นชุดโนวิส",lines:["สลับอาชีพไปมาแล้วเปลี่ยนแมพ บางครั้งตัวละครค้างเป็นชุดโนวิสทั้งที่อาชีพเป็น Mamushi หรือ Merchant — ตอนนี้ชุดอาชีพโหลดกลับมาแสดงถูกต้องแล้ว"],en:{title:"Fixed: class outfit reverting to the Novice outfit",lines:["Switching classes back and forth and then changing maps sometimes left your character stuck in the Novice outfit even though your class was Mamushi or Merchant — the class outfit now loads back correctly."]}},{id:"2026-09-27-announce-ticker",date:"2026-09-27",time:"11:09",title:"แถบประกาศข้อความวิ่ง",lines:["ประกาศสำคัญจากทีมงาน (เช่น ปิดปรับปรุง หรือกิจกรรม) จะวิ่งเป็นแถบข้อความด้านบนกลางจอ และขึ้นในแชทระบบหนึ่งครั้งให้ย้อนอ่านได้","กด × ที่ท้ายแถบเพื่อปิดประกาศนั้นได้ ประกาศใหม่จะขึ้นมาอีกครั้งตามปกติ"],en:{title:"Scrolling announcement ticker",lines:["Important announcements from the team (such as maintenance or an event) now scroll as a ticker across the top center of the screen, and also post once in System chat so you can look back at it.","Click × at the end of the ticker to dismiss that announcement; a new one will still show up normally."]}},{id:"2026-09-27-live-drop-event",date:"2026-09-27",time:"10:58",title:"กิจกรรม Drop x2 ทั้งเซิร์ฟ",lines:["กิจกรรมของเซิร์ฟเวอร์เพิ่มโอกาสดรอปไอเท็มได้แล้ว นอกจาก EXP ช่วงที่เปิด Drop x2 ของทุกอย่างที่มอนสเตอร์ทิ้ง (อุปกรณ์ การ์ด ยา หิน Refine และกล่อง) มีโอกาสร่วงเป็นสองเท่า","ใช้ซ้อนกับม้วน Drop x2 และโบนัสดรอปปาร์ตี้ได้ ดูเวลาที่เหลือได้จากไอคอน 🎉 กิจกรรมข้างการ์ดตัวละคร"],en:{title:"Server-wide Drop x2 event",lines:["Server events can now boost item drop rates too. On top of EXP, during a Drop x2 event, everything a monster drops (equipment, cards, potions, Refine Stones and boxes) has double the chance to drop.","It stacks with a Drop x2 scroll and party drop bonuses. Check the time remaining from the 🎉 event icon next to your character card."]}},{id:"2026-09-27-wings-bag-icon",date:"2026-09-27",time:"10:57",title:"ปีก Divine Wings ในกระเป๋าไม่กลายเป็นช่องขาวแล้ว",lines:["สวมหรือถอดสกินปีกแล้ว ช่องปีกในกระเป๋า (แท็บ Cash) เคยกลายเป็นกล่องขาวมีตัว E จนมองไม่เห็นรูปปีก ตอนนี้รูปปีกแสดงตามปกติ และตัว E เล็ก ๆ ที่มุมซ้ายบนขึ้นหรือหายทันทีที่สวมหรือถอด"],en:{title:"Divine Wings in your bag no longer turn into a blank slot",lines:["Equipping or unequipping the wings skin used to turn the wings' bag slot (Cash tab) into a blank white box with an E on it, hiding the wings' icon. The wings icon now displays normally, and the small E in the top-left corner appears or disappears immediately when you equip or unequip."]}},{id:"2026-09-27-durability-sell-budget-off",date:"2026-09-27",time:"10:49",title:"ยกเลิกความทนทานอุปกรณ์ และงบขายของให้พ่อค้ารายวัน",lines:["อุปกรณ์ไม่สึกหรอจากการล่ามอนแล้ว ไม่ต้องซ่อมที่ช่างตีบวก ชิ้นที่เคยพังกลับมาให้ค่าสถานะตามปกติทันที","ขายของให้พ่อค้าได้ราคาเต็มทุกครั้ง ไม่มีการลดราคาหลังขายเกิน 100,000 Silver ต่อวันอีกต่อไป"],en:{title:"Equipment durability and the daily merchant sell budget removed",lines:["Equipment no longer wears down from hunting, so there's no need to repair it at the Blacksmith. Pieces that were previously broken now give their normal stats back immediately.","Selling to the merchant now always gets full price — the price cut after selling more than 100,000 Silver worth in a day is gone."]}},{id:"2026-09-27-market-action-button-pinned",date:"2026-09-27",time:"09:29",title:"ตลาด: ปุ่มตั้งขาย/ซื้อไม่หายตกขอบแล้ว",lines:['หน้าต่างตลาดที่เตี้ย (เช่นจอเล็กหรือไม่ได้ขยายเต็มจอ) ปุ่ม "ตั้งขาย" "ซื้อสินค้า" และ "ตั้งรับซื้อ" เคยถูกดันลงไปใต้กรอบรายละเอียดจนมองไม่เห็น ตอนนี้ปุ่มติดอยู่ท้ายกรอบเสมอ พร้อมเหตุผลถ้ากดไม่ได้',"รายละเอียดไอเทมที่ยาวเลื่อนดูได้ด้านหลังปุ่ม"],en:{title:"Market: the sell/buy button no longer disappears off screen",lines:[`On a short Market window (such as a small screen, or not maximized), the "List for sale", "Buy" and "Place buy order" buttons used to get pushed below the details panel, out of view. The button now always stays pinned at the bottom of the panel, with a reason shown if it can't be clicked.`,"Long item details can be scrolled behind the button."]}},{id:"2026-09-27-top-roll-hover-special",date:"2026-09-27",time:"09:20",title:"สเตตัสค่าสูงสุดขึ้นสีส้มตอนชี้เมาส์ และออปชันพิเศษขึ้นสีด้วย",lines:["ชี้เมาส์ที่อุปกรณ์ (กระเป๋า คลัง ตลาด ช่างตีบวก ฯลฯ) กล่องข้อความลอยจะแสดงสเตตัสที่ออกค่าสูงสุดของ Tier เป็นตัวสีส้ม เหมือนหน้ารายละเอียดไอเทม","ออปชันพิเศษ (เช่น ATK%, เจาะเกราะ, ดูดเลือด, ต้านสตัน) ขึ้นสีส้มด้วยแล้ว ทั้งตอนชี้เมาส์ หน้ารายละเอียด และตลาด"],en:{title:"Max-roll stats turn orange on hover, and special options are colored too",lines:["Hovering equipment (in your bag, storage, the Market, the Blacksmith, etc.) now shows stats that rolled their tier's maximum value in orange in the tooltip, the same as the item details page.","Special options (such as ATK%, armor pierce, life steal, stun resist) now turn orange too, on hover, on the details page, and in the Market."]}},{id:"2026-09-27-silver-sinks",date:"2026-09-27",time:"09:09",title:"ปรับเศรษฐกิจ Silver: ความทนทาน ค่าซ่อม และระดมทุน EXP",lines:['อุปกรณ์ที่สวมอยู่สึกหรอทุกครั้งที่ล่ามอน ดูได้ที่บรรทัด "ความทนทาน" บนการ์ดไอเทม เหลือไม่ถึง 20% ช่องจะขึ้นกรอบส้ม ถ้าพังช่องจะเป็นสีแดง และชิ้นนั้นไม่ให้ค่าสถานะจนกว่าจะซ่อม','ซ่อมได้ที่ช่างตีบวก ปุ่ม "ซ่อมอุปกรณ์ทั้งหมด" ค่าซ่อมคิดตามความสึก ระดับ Tier และระดับตีบวก',"ร้านพ่อค้ารับซื้ออุปกรณ์ครึ่งราคาเดิม และของอื่น 80% ของราคาเดิม","พ่อค้ามีงบรับซื้อต่อวัน: 100,000 Silver แรกได้เต็มราคา ถึง 300,000 ได้ 50% เกินจากนั้นได้ 20% เริ่มนับใหม่เที่ยงคืน ดูยอดของวันนี้ได้ในหน้าต่างขาย","ตีบวกจาก +6 ขึ้น +7 จนถึง +10 ใช้ Silver เป็น 2 เท่า","เปิดคลังครั้งละ 100 Silver เปิดซ้ำตอนยังยืนอยู่ที่เจ้าหน้าที่คลังไม่เสียเพิ่ม","ตลาด Gold เก็บค่าธรรมเนียม 0.25% จาก Silver ที่ผู้ขาย Gold ได้รับ","ใหม่: ระดมทุน EXP ทั้งเซิร์ฟ (ปุ่มใต้หน้าต่างอันดับ) บริจาค Silver ร่วมกันครบ 20,000,000 ทั้งเซิร์ฟได้ EXP x1.5 นาน 2 ชั่วโมง",'Explorer มีแท็บ "Silver เข้า-ออก" ดูได้ว่าแต่ละวันมี Silver เข้าและออกจากเกมเท่าไร มาจากช่องทางไหน'],en:{title:"Silver economy adjustments: durability, repair costs and the EXP fund",lines:['Equipped items now wear down every time you hunt, shown on the "Durability" line of the item card. Under 20% left turns the slot orange, and once broken the slot turns red and that piece gives no stats until repaired.','You can repair at the Blacksmith with the "Repair all equipment" button; the cost scales with wear, tier and refine level.',"The shop now buys equipment for half its old price, and everything else for 80% of its old price.","The merchant now has a daily buying budget: the first 100,000 Silver worth gets full price, up to 300,000 gets 50%, and beyond that gets 20%. It resets at midnight; you can check today's total in the sell window.","Refining from +6 up to +7 through +10 now costs 2x the Silver.","Opening storage now costs 100 Silver per visit; reopening it while still standing at the storage clerk doesn't cost extra.","The Gold Market now takes a 0.25% fee from the Silver a Gold seller receives.","New: server-wide EXP Fund (a button below the rankings window) — once the server together donates 20,000,000 Silver, everyone gets EXP x1.5 for 2 hours.",'Explorer now has a "Silver In/Out" tab, showing how much Silver enters and leaves the game each day, and where it comes from.']}},{id:"2026-09-27-divine-wings-finder",date:"2026-09-27",time:"09:14",title:"Divine Wings บันทึกชื่อผู้ค้นพบ",lines:['Divine Wings แต่ละคู่กลายเป็นชิ้นของตัวเองเหมือนอาวุธ และมีบรรทัด "ผู้ค้นพบ" บอกชื่อตัวละครที่เปิดได้จาก Mystery Relic Box ชื่อนี้ติดไปกับปีกเมื่อเทรด ขาย หรือฝากคลัง',"ปีกยังอยู่ในแท็บ Cash ดับเบิลคลิกเพื่อสวมหรือถอดสกินได้เหมือนเดิม ไม่ใช้ช่องอุปกรณ์และไม่มีสเตตัส","ซื้อขายปีกได้ที่กระดานอุปกรณ์ในตลาด ไม่ใช่กระดานไอเทมแบบกองอีกต่อไป","ปีกที่มีอยู่แล้วถูกแปลงเป็นชิ้นให้อัตโนมัติ แต่ไม่มีชื่อผู้ค้นพบ เพราะก่อนหน้านี้ไม่เคยบันทึกไว้"],en:{title:"Divine Wings now records who found it",lines:['Each pair of Divine Wings is now its own individual piece, like a weapon, with a "Finder" line showing the character name that opened it from a Mystery Relic Box. That name travels with the wings when traded, sold, or stored.',"The wings still stay in the Cash tab; double-click to equip or unequip the skin as before. It doesn't use an equipment slot and has no stats.","Wings are now bought and sold on the Market's equipment board, no longer the stacked-item board.","Existing wings have been converted into individual pieces automatically, but have no finder name, since it was never recorded before now."]}},{id:"2026-09-27-market-cheapest-price-shown",date:"2026-09-27",time:"09:11",title:"ตลาด: ราคาที่จ่ายจริงชัดขึ้น และไม่ขึ้น Silver ไม่พอผิด ๆ",lines:['กดซื้อการ์ดหรือของที่ซ้อนกันได้ ระบบจะซื้อจากคนที่ขายถูกที่สุดก่อนเสมอ ตอนนี้หน้ารายละเอียดและหน้ายืนยันบอกชัดว่า "มีคนขายถูกกว่าแถวนี้" พร้อมราคาที่จ่ายจริง','แก้ปัญหากดแถวราคาแพงแล้วขึ้น Silver ไม่พอ ทั้งที่ราคาที่ต้องจ่ายจริงถูกกว่ามากและมีเงินพอ ปุ่ม "สูงสุด" ก็คำนวณจากราคาที่จ่ายจริงแล้ว',"ระบบกัน Silver ไว้เท่าที่การซื้อครั้งนั้นใช้จริงเท่านั้น ถ้าของราคาถูกถูกคนอื่นซื้อไปก่อน ส่วนที่ซื้อไม่ได้จะคืน Silver ให้ ไม่ไปซื้อแพงแทน"],en:{title:`Market: the actual price you'll pay is clearer, and no more false "not enough Silver"`,lines:[`When you buy a card or another stackable item, it always buys from the cheapest seller first. The details and confirm pages now clearly state "someone is selling this cheaper", along with the actual price you'll pay.`,'Fixed clicking a more expensive listing showing "not enough Silver", even though the actual price to pay was much cheaper and you had enough. The "Max" button now also calculates from the actual price paid.',"Silver is now reserved only for what a purchase actually uses. If a cheaper listing gets bought by someone else first, the unfulfilled portion refunds your Silver instead of buying the pricier one instead."]}},{id:"2026-09-27-bot-buff-only",date:"2026-09-27",time:"09:10",title:"บอท: โหมดบัฟอย่างเดียว ไม่โจมตี",lines:['หน้าต่าง Auto Play ส่วนสกิลอัตโนมัติ มีตัวเลือกใหม่ "บัฟอย่างเดียว ไม่โจมตี" เปิดแล้วบอทจะยืนร่ายฮีลและบัฟให้ตัวเองและคนรอบตัว ไม่ตีมอนสเตอร์และไม่เดินเก็บของ',"บัฟ (เช่น Holy Guard, Divine Boon, Remedy Light ของ Cleric) จะร่ายใหม่ทันทีที่หมด ฮีลร่ายเมื่อ HP เหลือไม่เกิน 60% · ใช้ได้โดยไม่ต้องติ๊กสกิล ถ้าไม่อยากให้ร่ายอันไหนให้เอาติ๊กออก","ถ้าตั้งลำดับสกิลเองไว้ จะใช้เฉพาะขั้นที่เป็นฮีล/บัฟ · ยาอัตโนมัติและการนั่งพักยังทำงานตามปกติ"],en:{title:"Bot: buff-only mode, no attacking",lines:[`The Auto Play window's auto-skill section has a new "Buff only, don't attack" option. Turn it on and the bot will stand and cast heals and buffs on itself and nearby players, without attacking monsters or walking to loot.`,"Buffs (such as a Cleric's Holy Guard, Divine Boon, Remedy Light) re-cast as soon as they run out; heals cast when HP drops to 60% or below · this works without checking off skills — uncheck any skill you don't want cast.","If you have a custom skill order set, only the heal/buff steps are used · auto-potions and resting still work as normal."]}},{id:"2026-09-27-training-grounds-closed",date:"2026-09-27",time:"09:12",title:"ปิดลานฝึกหุ่นฟางชั่วคราว",lines:["ปิดลานฝึกหุ่นฟางไว้ก่อน ประตูในป่าเริ่มต้นถูกซ่อน","ใครที่ค้างอยู่ในลานฝึก เข้าเกมครั้งต่อไปจะไปเกิดที่เมือง Aurelia ตัวละครและของอยู่ครบ"],en:{title:"Training Grounds temporarily closed",lines:["The Training Grounds are closed for now; the gate in Verdant Forest is hidden.","Anyone still inside the dummy yard will spawn in the city of Aurelia on their next login, with their character and items intact."]}},{id:"2026-09-27-training-gate-forest",date:"2026-09-27",time:"08:54",title:"ประตูลานฝึกหุ่นฟางย้ายไปป่าเริ่มต้น",lines:["ประตูไปลานฝึกหุ่นฟางย้ายออกจากเมือง Aurelia ไปอยู่ในป่าเริ่มต้น ตรงลานหน้าประตูกลับเมือง เดินลงจากเมืองมาก็เห็นทางขวามือ","ออกจากลานฝึกจะกลับมาโผล่ในป่าเริ่มต้นใกล้ประตูเดิม"],en:{title:"Training Grounds gate moved to Verdant Forest",lines:["The gate to the Training Grounds has moved from the city of Aurelia into Verdant Forest, right by the clearing in front of the town-return gate. Walking down from town, you'll see it on your right.","Leaving the dummy yard now brings you back into Verdant Forest near that same gate."]}},{id:"2026-09-27-merchant-double-tap-stack",date:"2026-09-27",time:"07:59",title:"ขายของทั้งกอง: มือถือแตะสองครั้ง",lines:["หน้าขายของให้พ่อค้า Silver: มือถือแตะของสองครั้งติดกันเร็ว ๆ จะใส่ทั้งกองลงรายการขายทันที (แตะครั้งเดียวยังเพิ่มทีละ 1) · PC ใช้ Shift+คลิก เหมือนเดิม","หน้าขายสินค้าในตลาด: Shift+คลิก (PC) หรือแตะสองครั้ง (มือถือ) ที่ของในกระเป๋า จะเลือกของนั้นพร้อมใส่จำนวนเท่าที่มีทั้งกอง แล้วตั้งราคากดตั้งขายได้เลย","คลัง: ถอนของออกทั้งกองด้วย Shift+คลิก (PC) หรือแตะสองครั้ง (มือถือ) · แตะครั้งเดียวยังเปิดช่องเลือกจำนวนเหมือนเดิม"],en:{title:"Sell a whole stack: double-tap on mobile",lines:["On the Silver Shop's sell page: quickly double-tapping an item on mobile now adds the whole stack to the sell list at once (a single tap still adds 1 at a time) · on PC, Shift+click still works the same way.","On the Market's Sell page: Shift+click (PC) or double-tap (mobile) an item in your bag selects it and fills in the full stack quantity, so you can just set a price and list it.","Storage: withdraw a whole stack with Shift+click (PC) or double-tap (mobile) · a single tap still opens the quantity selector, as before."]}},{id:"2026-09-27-top-roll-stat-colour",date:"2026-09-27",time:"08:39",title:"สเตตัสที่ออกค่าสูงสุดขึ้นสีส้ม",lines:["ค่าสเตตัสบนอุปกรณ์ที่สุ่มได้ค่าสูงสุดของ Tier นั้น (ออฟท็อป) แสดงเป็นตัวสีส้มในหน้ารายละเอียดไอเทม ทั้งกระเป๋า คลัง และตลาด ช่วยให้คัดของได้เร็วขึ้น","อาวุธที่ตีบวกแล้วยังดูได้ถูกต้อง เพราะหักค่าที่ได้จากการตีบวกออกก่อนเทียบ","ค่าที่ตายตัวอย่าง ASPD และออปชันพิเศษไม่ขึ้นสี"],en:{title:"Max-roll stats now turn orange",lines:["A stat on equipment that rolled its tier's maximum value (a top roll) now shows in orange on the item details page, in your bag, storage, and the Market, making it faster to pick out good items.","Refined weapons still display correctly, since the refine bonus is subtracted before comparing.","Fixed values such as ASPD and special options don't get colored."]}},{id:"2026-09-27-wiki-hit-flee",date:"2026-09-27",time:"08:38",title:"อัปเดต Wiki: หน้ามอนสเตอร์มี FLEE, DEF/MDEF, ธาตุ และตัวเลข HIT/FLEE ที่ต้องมี",lines:["การ์ดและหน้ารายละเอียดของมอนแต่ละตัวมี FLEE, DEF/MDEF และธาตุ ต่อจาก HP, ATK, EXP เดิม",'กล่อง "ต้องมีค่าอะไรถึงจะตี-หลบมอนตัวนี้ได้ดี" บอก HIT ที่ต้องมีเพื่อตีโดน 80/95/100% และ FLEE ที่ต้องมีเพื่อหลบการโจมตีของมัน 50/80%/เต็มเพดาน (คำนวณจากสูตรเกมจริง จึงตรงกับตัวเลขในเกมเสมอ)','เพิ่มหัวข้อ "🎯 ตี-หลบ มอนสเตอร์" ในแท็บเรื่องน่ารู้ อธิบายสูตร HIT/FLEE เป็นภาษาไทยพร้อมตัวอย่างจริง'],en:{title:"Wiki update: monster pages now show FLEE, DEF/MDEF, element, and the HIT/FLEE you need",lines:["Each monster's card and details page now shows FLEE, DEF/MDEF and element, alongside the existing HP, ATK and EXP.",`A "What you need to hit and dodge this monster well" box shows the HIT needed to land 80/95/100% of your hits, and the FLEE needed to dodge 50/80%/the full cap of its attacks (calculated from the game's actual formulas, so it always matches the numbers in-game).`,'Added a "🎯 Hit & Dodge Monsters" section under the Good to Know tab, explaining the HIT/FLEE formula in Thai, with real examples.']}},{id:"2026-09-27-training-grounds-load-fix",date:"2026-09-27",time:"08:36",title:"แก้ลานฝึกหุ่นฟางโหลดไม่ขึ้น",lines:["ผู้เล่นที่อยู่ในลานฝึกหุ่นฟาง (Training Grounds) ค้างที่หน้าโหลดและเข้าเกมไม่ได้ ตั้งแต่อัปเดตท่ายืนมอนสเตอร์เมื่อเช้า เพราะภาพหุ่นฟางชุดใหม่หายไป ตอนนี้แก้แล้ว","ตัวละครและของทุกอย่างอยู่ครบ รีโหลดเกมแล้วเข้าได้ตามปกติ"],en:{title:"Fixed: Training Grounds failing to load",lines:["Players inside the Training Grounds (the dummy yard) got stuck on the loading screen and couldn't get in, ever since this morning's monster idle-pose update, because the new dummy artwork was missing. It's fixed now.","Your character and all your items are intact. Reload the game and you'll get in normally."]}},{id:"2026-09-27-arena-rise-guard",date:"2026-09-27",time:"08:23",title:"สนาม PVP: ลุกขึ้นแล้วได้อมตะ 3 วินาที",lines:["หมดสติในสนาม PVP แล้วลุกขึ้น จะได้สถานะ 🛡 อมตะ 3 วินาที ไม่ได้รับดาเมจและไม่ติดสถานะผิดปกติจากผู้เล่นอื่น","ระหว่าง 3 วินาทีนี้ก็ทำดาเมจผู้เล่นคนอื่นไม่ได้เช่นกัน ทั้งตีปกติและสกิล · การโจมตีไม่ทำให้สถานะหายก่อนเวลา","การดวลนอกสนามและอมตะ 30 วินาทีตอนเข้าแมพเหมือนเดิม"],en:{title:"PVP arena: rising gives 3 seconds of invincibility",lines:["Going unconscious in the PVP arena and getting back up now grants 🛡 Invincible for 3 seconds — you take no damage and can't be inflicted with debuffs by other players.","During those 3 seconds you also can't damage other players, with basic attacks or skills · attacking doesn't clear the status early.","Duels outside the arena, and the 30-second invincibility on entering a map, are unchanged."]}},{id:"2026-09-27-bot-loot-weight-cap",date:"2026-09-27",time:"08:07",title:"บอท: ตั้งน้ำหนักสูงสุดที่จะเก็บของได้",lines:['หน้าต่าง Auto Play ส่วนไอเท็มที่เก็บ มีตัวเลือกใหม่ "หยุดเก็บของเมื่อน้ำหนักถึง" ตั้งเป็น % ของน้ำหนักบรรทุกได้ (ค่าเริ่มต้น 80%)',"น้ำหนักถึงที่ตั้งไว้ บอทจะเลิกเดินไปเก็บของแต่ยังตีมอนต่อ ตั้งต่ำกว่า 90% บอทจะไม่แบกของจนโจมตีไม่ได้ เปิดทิ้งไว้ข้ามคืนก็ไม่ยืนโดนตีจนตาย","กระต่าย Premium ใช้ค่าเดียวกัน: กระเป๋ากระต่ายเต็มแล้วจะไม่ยัดของเข้ากระเป๋าเราเกินที่ตั้งไว้ · ปิดอยู่เป็นค่าเริ่มต้น เก็บของมือยังเก็บได้ตามปกติ"],en:{title:"Bot: set a maximum weight for looting",lines:[`The Auto Play window's loot section has a new "Stop looting at weight" option, set as a % of your carry weight (default 80%).`,"Once weight reaches that threshold, the bot stops walking to loot but keeps attacking. Set it below 90% and the bot will never carry so much it can't attack — leave it running overnight and it won't stand there getting hit to death.","The Premium rabbit uses the same setting: once its bag is full, it won't stuff items into yours past the limit you set · off by default. Manual looting still works normally."]}},{id:"2026-09-27-silver-gold-coin-icons",date:"2026-09-27",time:"08:00",title:"ไอคอนเหรียญ Silver สีเงิน · Gold สีทอง",lines:["Silver ได้ไอคอนเหรียญสีเงินรูปดาว ส่วน Gold เป็นเหรียญสีทองรูปมงกุฎ แยกออกจากกันชัดแม้ไอคอนเล็ก","ใช้ไอคอนชุดเดียวกันทุกที่: การ์ดตัวละคร กระเป๋า ตลาด ร้านค้า NPC จดหมาย ของรางวัลรายวัน ร้าน Gold ตลาด Gold และกิลด์","ตัวเลข Silver บนการ์ดตัวละครเปลี่ยนเป็นสีเงินให้เข้ากับไอคอน"],en:{title:"Silver coin icon in silver, Gold coin icon in gold",lines:["Silver now has a silver star-shaped coin icon, while Gold has a gold crown-shaped coin icon, clearly distinct even at small sizes.","The same icons are used everywhere: the character card, bag, Market, NPC shops, mail, daily rewards, the Gold Shop, Gold Market and guild.","The Silver number on the character card is now silver-colored to match the icon."]}},{id:"2026-09-27-overweight-90-only",date:"2026-09-27",time:"07:57",title:"น้ำหนักเหลือผลแค่อย่างเดียว: เกิน 90% โจมตีไม่ได้",lines:["น้ำหนักเกิน 90% ของลิมิต: โจมตีและใช้สกิลไม่ได้เหมือนเดิม (Auto Play หยุดและเสนอใช้ปีกกลับเมือง)","เอาผลอื่นออกหมด: น้ำหนัก 50% ขึ้นไป HP/SP ฟื้นเองตามปกติแล้ว และน้ำหนักเกินลิมิตก็เดินได้ความเร็วปกติ"],en:{title:"Overweight now has just one effect: over 90% blocks attacking",lines:["Over 90% of your weight limit: you still can't attack or use skills (Auto Play stops and offers to use wings to return to town).","Every other effect has been removed: HP/SP now regenerate normally at 50% weight and above, and even going over the weight limit lets you walk at normal speed."]}},{id:"2026-09-27-party-panel-fold",date:"2026-09-27",time:"08:03",title:"พับแถบปาร์ตี้ให้เหลือป้ายเล็กได้",lines:["แตะหัวแถบปาร์ตี้ (♛ ปาร์ตี้ 11/12 ▾) เพื่อพับ แถบจะหดเหลือป้ายเล็กมุมซ้าย ไม่บังจอด้านซ้ายบนมือถือ แตะอีกครั้งเพื่อกางกลับ","เกมจำไว้ว่าพับหรือกางไว้ เข้าเกมครั้งหน้ายังเป็นแบบเดิม"],en:{title:"Party panel can now fold into a small badge",lines:["Tap the party panel's header (♛ Party 11/12 ▾) to fold it. The panel shrinks to a small badge in the top-left corner, so it no longer covers the left side of the screen on mobile. Tap again to expand it back.","The game remembers whether it's folded or expanded, so it stays the same next time you log in."]}},{id:"2026-09-27-shop-buy-steps",date:"2026-09-27",time:"08:02",title:"ซื้อยาจากพ่อค้าได้ทีละ 10 หรือ 100",lines:["ในรายการที่จะซื้อของร้านพ่อค้า ยาและของใช้ที่ซ้อนกันได้มีปุ่ม −100 −10 − + +10 +100 ใต้ชื่อ กดเพิ่มลดจำนวนได้ทันทีเหมือนตอนนำของออกจากคลัง","ยังพิมพ์จำนวนเองในช่องได้ตามเดิม สูงสุด 9,999 ชิ้นต่อรายการ"],en:{title:"Buy potions from merchants in steps of 10 or 100",lines:["In a merchant's buy list, stackable potions and consumables now have −100 −10 − + +10 +100 buttons under the name. Adjust the quantity instantly, just like taking items out of storage.","You can still type a quantity in the field yourself, up to 9,999 per item."]}},{id:"2026-09-27-market-sell-unlock",date:"2026-09-27",time:"08:01",title:"ตลาด: ปลดล็อกไอเทมจากหน้าขายได้เลย",lines:['หน้าขายสินค้าในตลาด ของที่ล็อกไว้จะมีรูปกุญแจ 🔒 และมีปุ่ม "ปลดล็อกเพื่อตั้งขาย" ในฟอร์มขาย ไม่ต้องกลับไปปลดล็อกในกระเป๋าก่อน',"อุปกรณ์จากร้าน Cash ยังผูกกับตัวละคร ตั้งขายไม่ได้เหมือนเดิม"],en:{title:"Market: unlock an item right from the sell page",lines:[`On the market's sell page, locked items now show a 🔒 lock icon with an "Unlock to list" button in the sell form. No need to go back and unlock it in your bag first.`,"Cash shop gear is still character-bound and still cannot be listed."]}},{id:"2026-09-27-sp-drain-option",date:"2026-09-27",time:"07:44",title:"ออปชันพิเศษใหม่: ดูด SP",lines:["ดูด SP: ตีปกติโดนแล้วฟื้น SP ตามเปอร์เซ็นต์ของดาเมจ +1% ถึง +2% ตาม tier (รวมสูงสุด 5%) ฟื้นไม่เกิน 2% ของ MaxSP ต่อครั้ง","มีผลเฉพาะการตีปกติ สกิลไม่ดูด SP","สุ่มได้บนอาวุธสายกายภาพ แหวนซ้าย และผ้าคลุม (ช่องเดียวกับดูดเลือด) · ออปชันพิเศษยังมีได้ชิ้นละ 1 อย่าง ของที่ดรอปแล้วไม่เปลี่ยน"],en:{title:"New special option: SP Drain",lines:["SP Drain: recovers SP on a basic hit equal to a percentage of the damage, +1% to +2% per tier (up to 5% total), capped at 2% of MaxSP per hit.","Only works on basic attacks; skills do not drain SP.","Rolls on physical weapons, left rings, and garments (same slot as Life Drain) · Each piece can still only have 1 special option, and an item already dropped does not change."]}},{id:"2026-09-27-market-sell-sort",date:"2026-09-27",time:"07:53",title:"หน้าขายในตลาด: กรองประเภทและเรียงของได้",lines:["หน้าขายสินค้ามีตัวเลือกประเภท (อาวุธ ชุดเกราะ เครื่องประดับ ไอเทมใช้ ฯลฯ) และตัวเลือกการเรียงของในกระเป๋า","เรียงตามประเภทจะจัดของชิ้นเดียวกันไว้ติดกัน เกรดสูงก่อน หรือเลือกเรียงตามเกรดสูง→ต่ำ ต่ำ→สูง หรือตามชื่อก็ได้ เกมจำการเรียงที่เลือกไว้"],en:{title:"Market sell page: filter by type and sort your items",lines:["The sell page now has a type filter (weapons, armor, accessories, consumables, etc.) and a sort option for items in your bag.","Sorting by type groups matching items together, highest grade first, or you can sort by grade high→low, low→high, or by name. The game remembers your chosen sort."]}},{id:"2026-09-27-twin-shot-sp",date:"2026-09-27",time:"07:55",title:"Twin Shot ใช้ SP น้อยลงมาก",lines:["Twin Shot ของอาร์เชอร์ใช้ SP ลดลงจาก 1.8 ต่อระดับ เหลือ 0.7 ต่อระดับ — ระดับ 10 ใช้ 7 SP ต่อครั้ง จากเดิม 18","ใกล้เคียงกับ Viper Fang ของมามุชิ ยิงรัวตามความเร็วโจมตีได้นานขึ้นโดยไม่ต้องกินยา SP บ่อย ดาเมจและผลอื่นของสกิลเหมือนเดิม"],en:{title:"Twin Shot costs much less SP",lines:["The Archer's Twin Shot now costs less SP: down from 1.8 per level to 0.7 per level — level 10 costs 7 SP per cast, down from 18.","This brings it close to Mamushi's Viper Fang, letting you fire it at your attack speed for longer without drinking SP potions as often. The skill's damage and other effects are unchanged."]}},{id:"2026-09-27-guild-exp",date:"2026-09-27",time:"07:34",title:"อัปเลเวลกิลด้วย EXP กิล — Silver เป็นแค่ตัวเร่ง",lines:["เลเวลกิลใช้ EXP กิลแทนการจ่าย Silver อย่างเดียว (Spirit Shard ยังต้องใช้เท่าเดิม)","สมาชิกเลือกแชร์ Base EXP ที่ได้จากการล่ามอนเข้ากิลได้ 0–50% ที่หน้ากิล (ค่าเริ่มต้น 0% · Job EXP ไม่ลด)","อยากอัปไวขึ้น ใช้ Silver เร่งเติมส่วนที่ขาดได้ 1 Silver = 15 EXP กิล — ใช้ Silver อย่างเดียวก็ยังเท่าราคาเดิม","Silver ที่กิลสะสมไว้แล้วนับเป็น EXP กิลให้ครบ ไม่หาย","EXP ที่เกินเป้าจะสะสมต่อไปเลเวลถัดไป · Lv.1→20 รวมประมาณ EXP ของตัวละคร 10 ตัวจาก Lv.1 ถึง Lv.120","ตัวละครเลเวลตันแชร์ได้โดยไม่เสีย EXP อะไรเลย"],en:{title:"Guilds level up with Guild EXP — Silver is just a booster now",lines:["Guild levels now run on Guild EXP instead of Silver alone (Spirit Shards are still required as before).","Members can choose to share 0–50% of the Base EXP they earn from hunting monsters with the guild, in the guild window (default 0% · Job EXP is not reduced).","Want to level up faster? Use Silver to top up whatever's missing — 1 Silver = 15 Guild EXP — using Silver alone still costs the same as before.","Silver the guild has already collected counts in full toward Guild EXP; nothing is lost.","EXP beyond the target carries over to the next level · Lv.1→20 needs roughly as much EXP as taking 10 characters from Lv.1 to Lv.120.","Max-level characters can share EXP without losing anything at all."]}},{id:"2026-09-27-camera-zoom",date:"2026-09-27",time:"07:40",title:"ซูมกล้องเข้า–ออกได้",lines:["PC: หมุนลูกกลิ้งเมาส์บนแผนที่เพื่อซูมเข้า–ออก (ทัชแพดใช้สองนิ้วถ่างหรือหุบได้)","มือถือ: ใช้สองนิ้วถ่างบนแผนที่เพื่อซูมเข้า หุบนิ้วเพื่อซูมออก","ซูมเข้าได้สูงสุด 2 เท่า ซูมออกสุดคือมุมมองปกติเดิม เกมจำระดับซูมไว้ให้ครั้งต่อไป"],en:{title:"You can now zoom the camera in and out",lines:["PC: scroll the mouse wheel over the map to zoom in or out (on a touchpad, pinch or spread with two fingers).","Mobile: spread two fingers on the map to zoom in, pinch to zoom out.","Zoom in up to 2x; fully zoomed out is the normal view as before. The game remembers your zoom level for next time."]}},{id:"2026-09-27-bot-skill-sp-floor",date:"2026-09-27",time:"07:52",title:"บอท: สำรอง SP ไว้บัฟ/ฮีล",lines:['หน้าต่าง Auto Play ส่วนสกิลอัตโนมัติ มีตัวเลือกใหม่ "สำรอง SP ไว้บัฟ/ฮีล" ตั้งได้ว่าจะใช้สกิลโจมตีเฉพาะตอน SP เหลือตั้งแต่กี่ % ขึ้นไป',"SP ต่ำกว่าที่ตั้งไว้ บอทจะตีธรรมดาแทน (โหมดใช้แต่สกิลจะยืนรอ SP) ส่วนบัฟและฮีลยังร่ายได้ตามปกติ บัฟหมดก็มี SP ร่ายใหม่","ใช้ได้ทั้งแบบติ๊กสกิลและแบบตั้งลำดับสกิลเอง · ปิดอยู่เป็นค่าเริ่มต้น"],en:{title:"Bot: reserve SP for buffs/heals",lines:[`The Auto Play window's auto-skill section has a new "Reserve SP for buffs/heals" option, letting you set a minimum SP % before attack skills are used.`,"Below that SP threshold, the bot uses basic attacks instead (in skills-only mode it will just wait for SP); buffs and heals still cast normally, and once a buff expires it will still cast a new one.","Works with both ticked skills and a custom skill order · off by default."]}},{id:"2026-09-27-gear-tip-usable-by",date:"2026-09-27",time:"07:31",title:"ชี้ที่อุปกรณ์แล้วเห็นว่าอาชีพไหนใส่ได้",lines:['กล่องข้อความตอนชี้เมาส์ที่อุปกรณ์มีบรรทัด "ใช้ได้โดย" บอกอาชีพและเลเวลที่ใส่ได้ (ของที่ทุกอาชีพใส่ได้จะขึ้นว่า ทุกตัวละคร)',"ถ้าตัวละครที่เล่นอยู่ยังใส่ชิ้นนั้นไม่ได้ บรรทัดนี้จะเป็นสีแดง"],en:{title:"Hover gear to see which classes can wear it",lines:['The tooltip when hovering equipment now has a "Usable by" line showing the classes and level required (gear every class can wear shows "All characters").',"If your current character can't wear that piece yet, this line shows in red."]}},{id:"2026-09-27-bot-skill-delay",date:"2026-09-27",time:"07:34",title:"บอท: ตั้งเวลาหน่วงสกิลโจมตีได้",lines:['หน้าบอท → สกิลอัตโนมัติ มีแถบ "หน่วงสกิลโจมตี" ตั้งได้ 0–30 วินาที (ทีละ 0.5)',"ร่ายสกิลโจมตีแล้วบอทจะรอตามเวลาที่ตั้งก่อนร่ายอันถัดไป ระหว่างนั้นตีธรรมดาแทน ช่วยประหยัด SP ต่อการฆ่า 1 ตัว","ใช้ได้ทั้งแบบติ๊กสกิลและแบบตั้งลำดับเอง · ฮีลและบัฟไม่ถูกหน่วง · ตั้ง 0 = ร่ายทันทีที่พร้อมเหมือนเดิม"],en:{title:"Bot: set a delay for attack skills",lines:['Bot window → Auto skills now has an "Attack skill delay" slider, settable from 0–30 seconds (in 0.5 s steps).',"After casting an attack skill, the bot waits the set time before casting the next one, using basic attacks in between — helping save SP per kill.","Works with both ticked skills and a custom order · heals and buffs are never delayed · set to 0 = casts the moment it's ready, as before."]}},{id:"2026-09-27-market-stat-filter",date:"2026-09-27",time:"07:31",title:"ตลาดกรองสเตตัสได้หลายค่าพร้อมกัน",lines:['ช่อง "+ กรองสเตตัส" ในหน้าซื้อสินค้า เลือกได้ทุกค่า ทั้ง STR–LUK, ATK, MATK, DEF, MDEF, HP, SP, HIT, FLEE, CRIT, ASPD และออปชันพิเศษ เช่น เจาะกาย ดูดเลือด กันสตัน ความเร็ววิ่ง',"เลือกแล้วจะขึ้นเป็นป้ายใต้แถบค้นหา ใส่ค่าขั้นต่ำได้ เช่น ATK ≥ 50 และเลือกหลายค่าพร้อมกันได้ จะเหลือเฉพาะของที่มีครบทุกค่า กด ✕ เพื่อเอาออก","รายการเรียงตามค่าที่กรองจากมากไปน้อย หรือเปลี่ยนเป็นเรียงตามราคาได้ตามเดิม","ช่องค้นหาพิมพ์ออปชันพิเศษได้ด้วย เช่น เจาะกาย 10, pierce>10, atk% 4"],en:{title:"Filter the market by several stats at once",lines:['The "+ Filter stats" box on the buy page now covers every stat: STR–LUK, ATK, MATK, DEF, MDEF, HP, SP, HIT, FLEE, CRIT, ASPD, and special options like Pierce, Life Drain, Stun Resist, and Move Speed.',"Chosen stats show as tags under the search bar. Set a minimum value, e.g. ATK ≥ 50, and pick several at once — only items meeting every value are shown. Tap ✕ to remove one.","The list sorts by the filtered value, highest first, or you can switch back to sorting by price.","The search box also accepts special options directly, e.g. pierce 10, pierce>10, atk% 4."]}},{id:"2026-09-27-monster-idle-animation",date:"2026-09-27",time:"07:26",title:"มอนสเตอร์ทุกตัวมีท่ายืนหายใจ",lines:["มอนสเตอร์ทั้ง 47 ชนิดได้ภาพชุดใหม่: ท่ายืน 3 ภาพเล่นวนเป็นจังหวะหายใจ แทนภาพนิ่งที่เด้งขึ้นลง ตัวที่บินจะกระพือปีกหรือลอยแทน","ท่าโจมตีและท่าโดนตีวาดใหม่ในชุดเดียวกัน หน้าตามอนเหมือนเดิม ค่าสถานะ ดรอป และจุดเกิดไม่เปลี่ยน"],en:{title:"Every monster now breathes while idle",lines:["All 47 monster types got a new sprite set: a 3-frame idle loop with a breathing rhythm, instead of a static sprite bobbing up and down. Flying monsters flap their wings or hover instead.","Attack and hit poses were redrawn in the same set. Monster looks, stats, drops, and spawn points are unchanged."]}},{id:"2026-09-27-profile-card-silver",date:"2026-09-27",time:"07:21",title:"การ์ดตัวละคร: เลเวลอยู่ใต้รูป และโชว์ Silver",lines:["เลเวลย้ายไปอยู่ในป้ายสีทองใต้รูปโปรไฟล์","แถวบนเรียงเป็น อาชีพ · ชื่อ · Silver ที่มีอยู่ (ยอดเยอะจะย่อเป็น k / M ชี้ดูยอดเต็มได้)"],en:{title:"Character card: level moved under the portrait, Silver now shown",lines:["Level has moved into the gold badge under the profile portrait.","The top row now reads Class · Name · Silver on hand (large amounts shorten to k / M — hover to see the exact figure)."]}},{id:"2026-09-27-special-options-translated-again",date:"2026-09-27",time:"07:20",title:"ชื่อออปชันพิเศษกลับมาแปลตามภาษา",lines:["ชื่อออปชันพิเศษ (คริดาเมจ, เจาะกาย, ดูดเลือด ฯลฯ) กลับมาแสดงตามภาษาที่เลือกเหมือนเดิม","ค่าและผลของออปชันไม่เปลี่ยน"],en:{title:"Special option names translate again",lines:["Special option names (Crit Damage, Pierce, Life Drain, etc.) now show in your chosen language again, as before.","The values and effects of these options are unchanged."]}},{id:"2026-09-27-spawn-guard-30s",date:"2026-09-27",time:"07:03",title:"อมตะหลังเข้าเกมนานขึ้นเป็น 30 วินาที",lines:["สถานะอมตะหลังเข้าเกม เข้าแมพใหม่ หรือเชื่อมต่อใหม่ อยู่ได้ 30 วินาที (จากเดิม 5 วินาที) เริ่มนับเมื่อโหลดแผนที่เสร็จ","ถ้าเริ่มโจมตีมอนหรือผู้เล่น หรือใช้สกิลโจมตี สถานะอมตะยังหายไปทันทีเหมือนเดิม"],en:{title:"Post-login invincibility extended to 30 seconds",lines:["The invincibility you get after logging in, entering a new map, or reconnecting now lasts 30 seconds (up from 5), starting once the map finishes loading.","Attacking a monster or player, or using an attack skill, still ends the invincibility immediately, as before."]}},{id:"2026-09-27-share-card-special-option",date:"2026-09-27",time:"07:00",title:"ลิงก์ไอเทมในแชท: ออปชันพิเศษอยู่ฝั่งค่าสถานะ",lines:["เปิดดูอุปกรณ์ที่แชร์ในแชท ออปชันพิเศษ เช่น คริดาเมจ +20% แสดงในคอลัมน์ซ้ายรวมกับค่าสถานะอื่น ไม่หลุดไปอยู่ใต้ราคาขายและตำแหน่งแล้ว"],en:{title:"Item links in chat: special options now sit with the stats",lines:["Opening an item shared in chat, special options like Crit Damage +20% now show in the left column together with the other stats, instead of falling below the sell price and slot."]}},{id:"2026-09-27-blue-potion-merchant-back",date:"2026-09-27",time:"06:55",title:"Blue Potion กลับมาขายที่พ่อค้า Silver",lines:["พ่อค้า Silver ขาย Blue Potion (ยาฟ้า ฟื้น SP 60%) อีกครั้ง ราคา 50 Silver (เดิม 40)","ขายคืนพ่อค้าได้ 20 Silver เท่าเดิม · Orange / Yellow Potion ยังไม่กลับมาขายในร้าน"],en:{title:"Blue Potion is back at the Silver Merchant",lines:["The Silver Merchant sells Blue Potion (SP recovery potion, +60% SP) again, priced at 50 Silver (up from 40).","Sells back to the merchant for 20 Silver, same as before · Orange / Yellow Potion are still not sold in the shop."]}},{id:"2026-09-27-blue-potion-drop-equal",date:"2026-09-27",time:"06:45",title:"Blue Potion ดรอปบ่อยเท่ายา HP",lines:["ของใช้ที่มอนดรอป (โอกาส 15% ต่อตัวเท่าเดิม): Blue Potion เพิ่มจาก 25% เป็น 37.5% เท่ากับยา HP ของแผนที่นั้น (ลดจาก 50% เป็น 37.5%)","Fly Wing 15% และ Butterfly Wing 10% เท่าเดิม"],en:{title:"Blue Potion now drops as often as HP potions",lines:["Consumable drops from monsters (still a 15% chance per kill): Blue Potion's share rises from 25% to 37.5%, matching that map's HP potion (down from 50% to 37.5%).","Fly Wing at 15% and Butterfly Wing at 10% are unchanged."]}},{id:"2026-09-27-fatal-sense-atk-back",date:"2026-09-27",time:"06:37",title:"Fatal Sense กลับมาให้ ATK จาก AGI เหมือนเดิม",lines:["อัปเดตรอบก่อนย้ายโบนัสของ Fatal Sense ไปเป็นดาเมจตีปกติอย่างเดียว ทำให้ ATK ในหน้าสเตตัสลด และดาเมจสกิลของตัวละครที่เก็บ Fatal Sense ลดลงหลักพัน","ตอนนี้ Fatal Sense กลับมาให้ ATK เท่ากับ 5.5% ของ AGI ต่อระดับ (ระดับ 10 = 55% ของ AGI) มีผลทั้งตีปกติและสกิลเหมือนเดิม","Momentum (ตีโดนต่อเนื่อง ชั้นละ +3% สูงสุด +60%) และโบนัส ASPD เกิน 170 (+1.5% ต่อจุด) ของการตีปกติยังอยู่ครบ"],en:{title:"Fatal Sense gives ATK from AGI again",lines:["A previous update moved Fatal Sense's bonus to basic-attack damage only, which lowered ATK on the status page and cut skill damage by the thousands for characters running Fatal Sense.","Fatal Sense now grants ATK equal to 5.5% of AGI per level again (level 10 = 55% of AGI), affecting both basic attacks and skills as before.","Momentum (+3% per stack on consecutive hits, up to +60%) and the basic-attack bonus for ASPD above 170 (+1.5% per point) are both still fully intact."]}},{id:"2026-09-27-relic-box-no-clip",date:"2026-09-27",time:"06:22",title:"Mystery Relic Box: เอา Clip ค่าตายตัวออก",lines:["กล่องไม่ออก Clip แบบค่าตายตัว (SP +15 ไม่มีออปชัน) แล้ว กล่องจึงไม่มีอุปกรณ์ค่าตายตัวเหลืออยู่ อุปกรณ์จากกล่องเป็นอุปกรณ์สุ่ม Tier I–V ทั้งหมด","Clip แบบสุ่มค่าและออปชันยังดรอปจากมอนสเตอร์ได้ตามปกติ","โอกาสต่อกล่อง: อุปกรณ์สุ่ม Tier I–V 10% (อย่างละ 2%), การ์ด 1%, Divine Wings 1 ใน 1,000,000 กล่อง, Red Potion 29.3%, Orange 21.5%, Yellow 11.7%, Blue 7.8%, Warp Scroll 7.8%, Prism 4.9%, เศษวิญญาณ 3.9%, White Potion 2.0%"],en:{title:"Mystery Relic Box: removed the fixed-stat Clip",lines:["Boxes no longer drop the fixed-stat Clip (SP +15, no options), so the box no longer contains any fixed-stat gear — equipment from boxes is now entirely random Tier I–V gear.","Random-roll Clips with options still drop from monsters as usual.","Odds per box: random Tier I–V equipment 10% (2% each), card 1%, Divine Wings 1 in 1,000,000 boxes, Red Potion 29.3%, Orange 21.5%, Yellow 11.7%, Blue 7.8%, Warp Scroll 7.8%, Prism 4.9%, Spirit Shard fragment 3.9%, White Potion 2.0%"]}},{id:"2026-09-27-relic-box-no-cotton-shirt",date:"2026-09-27",time:"06:19",title:"Mystery Relic Box: เอา Cotton Shirt ออก",lines:["กล่องไม่ออก Cotton Shirt แล้ว (เสื้อ DEF +1 ไม่มีออปชัน) ยาและของอื่นในกล่องออกบ่อยขึ้นเล็กน้อยแทน","อุปกรณ์สุ่ม Tier I–V 10%, การ์ด 1% และ Divine Wings 1 ใน 1,000,000 กล่องเท่าเดิม · Cotton Shirt ยังซื้อที่พ่อค้าได้"],en:{title:"Mystery Relic Box: removed the Cotton Shirt",lines:["Boxes no longer drop the Cotton Shirt (DEF +1, no options); potions and other items in the box now drop slightly more often instead.","Random Tier I–V equipment at 10%, cards at 1%, and Divine Wings at 1 in 1,000,000 boxes are unchanged · Cotton Shirt is still sold by the merchant."]}},{id:"2026-09-27-relic-box-tier-gear",date:"2026-09-27",time:"06:08",title:"Mystery Relic Box: ลุ้นอุปกรณ์ทุก Tier",lines:["เปิดกล่องมีโอกาส 10% ได้อุปกรณ์สุ่ม แบ่งเท่ากัน Tier I ถึง V อย่างละ 2%","อุปกรณ์จากกล่องสุ่มแบบเดียวกับที่มอนสเตอร์ดรอป: สุ่มช่อง ชื่อ ค่าสเตตัส และออปชันพิเศษ (เท่ามอนเลเวลต้นของ Tier นั้น) ทุกช่องออกเท่ากัน","การ์ด 1% และ Divine Wings 1 ใน 1,000,000 กล่องเท่าเดิม ของที่เหลือในกล่องลดลงตามสัดส่วน: Red Potion 29.0%, Orange 21.3%, Yellow 11.6%, Blue 7.7%, Warp Scroll 7.7%, Prism 4.8%, เศษวิญญาณ 3.9%, White Potion 1.9%, Cotton Shirt 0.58%, Clip 0.39%"],en:{title:"Mystery Relic Box: a shot at gear from every tier",lines:["Opening a box has a 10% chance of random equipment, split evenly across Tier I through V at 2% each.","Equipment from boxes rolls the same way monster drops do: random slot, name, stats, and special options (matching that tier's starting monster level) — every slot is equally likely.","Cards at 1% and Divine Wings at 1 in 1,000,000 boxes are unchanged; everything else in the box scales down proportionally: Red Potion 29.0%, Orange 21.3%, Yellow 11.6%, Blue 7.7%, Warp Scroll 7.7%, Prism 4.8%, Spirit Shard fragment 3.9%, White Potion 1.9%, Cotton Shirt 0.58%, Clip 0.39%"]}},{id:"2026-09-27-ground-target-skills",date:"2026-09-27",time:"06:04",title:"สกิลวงร่ายลงพื้นได้: Stormbreak · Frost Area · Arrow Rain",lines:["กดสกิลแล้วคลิกพื้นตรงไหนก็ได้ วงของสกิลจะลงตรงจุดนั้น ไม่ต้องเลือกมอนก่อน ระหว่างเล็งจะเห็นวงระยะร่ายรอบตัวละคร และวงของสกิลตามเมาส์","ระยะร่าย: Stormbreak และ Frost Area 240 · Arrow Rain 280 · คลิกไกลกว่านั้นตัวละครจะเดินเข้าไปจนถึงระยะแล้วร่ายเอง","บนมือถือ แตะปุ่มสกิลแล้วแตะพื้นที่จะร่าย · กดปุ่มสกิลซ้ำ คลิกขวา หรือกด Esc เพื่อยกเลิก","บอทยังร่ายลงมอนที่กำลังตีเหมือนเดิม"],en:{title:"Ground-target skills: Stormbreak · Frost Area · Arrow Rain",lines:["Press the skill, then click anywhere on the ground and the skill's circle lands right there — no need to select a monster first. While aiming you'll see your cast range circle around your character, and the skill's circle following your mouse.","Cast range: Stormbreak and Frost Area 240 · Arrow Rain 280 · click farther than that and your character walks in until in range, then casts automatically.","On mobile, tap the skill button, then tap the ground to cast · tap the skill button again, right-click, or press Esc to cancel.","The bot still casts onto whichever monster it's currently attacking, as before."]}},{id:"2026-09-27-relic-box-cards-1pct",date:"2026-09-27",time:"06:01",title:"Mystery Relic Box: การ์ดออกยากขึ้น",lines:["โอกาสได้การ์ดจากกล่องลดจาก 11.5% เหลือ 1% ต่อกล่อง การ์ดมอนทุกใบยังมีโอกาสเท่ากัน (ใบละราว 0.02%) การ์ดบอสยังไม่ออกจากกล่อง","ส่วนที่เหลือเป็นของเดิมในสัดส่วนเดิม: Red Potion 32.3%, Orange 23.7%, Yellow 12.9%, Blue 8.6%, Warp Scroll 8.6%, Prism 5.4%, เศษวิญญาณ 4.3%, White Potion 2.2%, Cotton Shirt 0.65%, Clip 0.43%","Divine Wings ยังเป็น 1 ใน 1,000,000 กล่องเท่าเดิม"],en:{title:"Mystery Relic Box: cards are harder to get",lines:["The chance of a card from a box drops from 11.5% to 1% per box. Every monster card still has an equal chance (about 0.02% each); boss cards still never drop from boxes.","Everything else keeps the same old proportions: Red Potion 32.3%, Orange 23.7%, Yellow 12.9%, Blue 8.6%, Warp Scroll 8.6%, Prism 5.4%, Spirit Shard fragment 4.3%, White Potion 2.2%, Cotton Shirt 0.65%, Clip 0.43%","Divine Wings is still 1 in 1,000,000 boxes, unchanged."]}},{id:"2026-09-27-divine-wings-relic-box",date:"2026-09-27",time:"05:57",title:"ปีกทอง Divine Wings สุ่มได้จาก Mystery Relic Box",lines:["เปิด Mystery Relic Box มีโอกาสได้ Divine Wings (สกินปีกสีทอง) 1 ใน 1,000,000 กล่อง","Divine Wings เทรดให้ผู้เล่นอื่น ตั้งขายในตลาด และฝากคลังได้แล้ว","แต่ทิ้ง ทำลาย หรือขายให้พ่อค้าไม่ได้ ปีกจะไม่หายไปจากเกม","ถ้าเทรดหรือขายปีกที่สวมอยู่ สกินปีกจะถอดออกเอง"],en:{title:"Divine Wings can now drop from the Mystery Relic Box",lines:["Opening a Mystery Relic Box has a chance of Divine Wings (the golden wings skin), at 1 in 1,000,000 boxes.","Divine Wings can now be traded to other players, listed on the market, and deposited in storage.","It still cannot be dropped, destroyed, or sold to a merchant — the wings can never be lost from the game.","Trading or selling a worn pair of wings automatically removes the skin first."]}},{id:"2026-09-27-relic-box-cards-equal",date:"2026-09-27",time:"05:50",title:"Mystery Relic Box: การ์ดทุกใบมีโอกาสเท่ากัน",lines:["การ์ดมอนทุกใบในกล่องมีโอกาสออกเท่ากัน ใบละ 0.24% ต่อกล่อง (เดิม Hopper/Hollow 1.81%, Mushroom/Bat/Beetle/Crab 0.90%, ใบอื่น 0.23%)","โอกาสได้การ์ดใบใดใบหนึ่งต่อกล่องลดจาก 16.7% เหลือ 11.5% · การ์ดบอสยังไม่ออกจากกล่องเหมือนเดิม","ยา ม้วนวาร์ป วัตถุดิบ และอุปกรณ์ในกล่องไม่เปลี่ยน จึงออกบ่อยขึ้นเล็กน้อยตามสัดส่วน"],en:{title:"Mystery Relic Box: every card is now equally likely",lines:["Every monster card in a box now has an equal chance, 0.24% per box each (previously Hopper/Hollow 1.81%, Mushroom/Bat/Beetle/Crab 0.90%, all other cards 0.23%).","The chance of getting some card per box drops from 16.7% to 11.5% · boss cards still never drop from boxes, as before.","Potions, Warp Scrolls, materials, and equipment in the box are unchanged, so they now drop slightly more often as a proportion."]}},{id:"2026-09-27-frost-area-on-target",date:"2026-09-27",time:"05:46",title:"เมจ: Frost Area ร่ายลงบนเป้าหมายได้",lines:["Frost Area ร่ายลงที่มอนที่เลือกไว้ได้ไกล 240 เหมือน Stormbreak ไม่ต้องเดินเข้าไปยืนกลางฝูงแล้ว","ถ้าไม่ได้เลือกมอน หรือมอนอยู่ไกลเกินระยะ จะร่ายรอบตัวเหมือนเดิม"],en:{title:"Mage: Frost Area can now be cast on a target",lines:["Frost Area can now be cast on your selected monster from up to 240 range, same as Stormbreak — no more walking into the middle of a pack.","If no monster is selected, or it's out of range, it still casts around you, as before."]}},{id:"2026-09-27-merchant-drops-potions",date:"2026-09-27",time:"05:45",title:"พ่อค้า Silver เลิกขาย Orange / Yellow / Blue Potion",lines:["Orange Potion, Yellow Potion และ Blue Potion (ยาฟ้า SP) ไม่มีขายที่พ่อค้า Silver แล้ว","หาได้จากการล่ามอนสเตอร์ หรือซื้อต่อจากผู้เล่นอื่นในตลาดเท่านั้น · ยาที่มีอยู่ในกระเป๋าและคลังยังใช้ได้และขายคืนพ่อค้าได้ตามเดิม","Red Potion, ยาเร่ง และม้วนวาร์ป/กลับเมือง ยังซื้อที่พ่อค้าได้เหมือนเดิม"],en:{title:"Silver Merchant stops selling Orange / Yellow / Blue Potion",lines:["Orange Potion, Yellow Potion, and Blue Potion (the SP potion) are no longer sold by the Silver Merchant.","Get them from hunting monsters, or buy them from other players on the market instead · Potions already in your bag or storage still work and can still be sold back to the merchant, as before.","Red Potion, boost potions, and Warp/Return Scrolls are still sold by the merchant, as before."]}},{id:"2026-09-27-basic-attack-momentum",date:"2026-09-27",time:"05:31",title:"สายตีปกติ (AGI) แรงขึ้น: Momentum + จังหวะ ASPD",lines:["ทุกอาชีพ · Momentum: ตีปกติโดนแต่ละครั้งได้ +1 ชั้น ชั้นละ +3% ดาเมจตีปกติ สูงสุด 20 ชั้น (+60%) ดูจำนวนชั้นได้ที่ไอคอนบัฟ","Momentum หายหมดเมื่อใช้สกิลโจมตี หรือไม่ได้ตีโดน 3 วินาที (บัฟและฮีลไม่ทำให้หาย) · ไม่มีผลใน PVP","ทุกอาชีพ · จังหวะ ASPD: ASPD ที่เกิน 170 ทุก 1 จุด ดาเมจตีปกติ +1.5% (ASPD 193 = +34.5%)","Thief · Fatal Sense: เปลี่ยนจาก ATK +5.5% ของ AGI ต่อระดับ เป็นดาเมจตีปกติ +0.04% ต่อ AGI ต่อระดับ (ระดับ 10 กับ AGI 100 = +40%) ดาเมจคริและ ASPD เหมือนเดิม","Fatal Sense ไม่เพิ่ม ATK แล้ว สาย STR ที่ใช้ Twin Fang จะเบาลงเล็กน้อย (ประมาณ 10%)","โบนัสทั้งหมดมีผลกับการตีปกติเท่านั้น สกิลไม่ได้ เป้าคือให้สาย AGI ตีปกติสูสีกับสายสกิล ไม่ได้ตั้งใจให้แรงกว่า"],en:{title:"Basic-attack (AGI) builds hit harder: Momentum + the ASPD tier",lines:["All classes · Momentum: each basic hit that lands adds +1 stack, +3% basic-attack damage per stack, up to 20 stacks (+60%). See your stack count on the buff icon.","Momentum fully resets when you use an attack skill, or after 3 seconds without a landed hit (buffs and heals don't reset it) · has no effect in PVP.","All classes · ASPD tier: for every point of ASPD above 170, basic-attack damage +1.5% (ASPD 193 = +34.5%).","Thief · Fatal Sense: changed from ATK +5.5% of AGI per level, to basic-attack damage +0.04% per AGI per level (level 10 with 100 AGI = +40%). Critical damage and ASPD are unchanged.","Fatal Sense no longer adds ATK, so STR builds using Twin Fang will feel slightly weaker (roughly 10%).","All these bonuses only affect basic attacks, never skills. The goal is for AGI basic-attack builds to keep pace with skill builds, not outdo them."]}},{id:"2026-09-27-new-gear-options",date:"2026-09-27",time:"05:21",title:"ออปชันพิเศษใหม่บนของดรอป",lines:["คริดาเมจ: คริติคอลแรงขึ้น +4% ถึง +20% ตาม tier (รวมสูงสุด 60%) · สุ่มได้บนอาวุธสายกายภาพ ลูกธนู และแหวนซ้าย","โจมตีติดสตัน: โอกาส 2–5% ให้มอนสตัน 1.5 วิเมื่อตีปกติ บอสไม่ติด · อาวุธสายกายภาพและอาวุธลูกผสม","โจมตีเลือดไหล: โอกาส 2–6% ให้มอนเสีย HP 0.8% ของ MaxHP ทุกวินาที 5 วิ (บอสโลกโดน 1 ใน 10) · อาวุธสายกายภาพ ลูกธนู และแหวนซ้าย","โจมตีเกราะแตก: โอกาส 2–5% ให้มอนรับดาเมจ +20% 4 วิ · อาวุธสายกายภาพ อาวุธลูกผสม และลูกธนู","HP คงที่ +30 ถึง +150: สุ่มได้บนหมวก เกราะ โล่ ผ้าคลุม รองเท้า และของตกแต่งหน้า/ปาก","SP Regen +1 ถึง +3 ต่อรอบฟื้น SP: สุ่มได้บนอาวุธเวท แหวนขวา Orb และหมวก","ออปชันพิเศษยังมีได้ชิ้นละ 1 อย่าง ของที่ดรอปแล้วไม่เปลี่ยน"],en:{title:"New special options on dropped gear",lines:["Crit Damage: critical hits deal +4% to +20% more, by tier (up to +60% total) · rolls on physical weapons, bows, and left rings.","Stun on Hit: 2–5% chance to stun a monster for 1.5 s on a basic attack, bosses immune · physical and hybrid weapons.","Bleed on Hit: 2–6% chance to make a monster lose 0.8% of MaxHP per second for 5 s (world bosses take a 1-in-10 chance) · physical weapons, bows, and left rings.","Armor Break on Hit: 2–5% chance for a monster to take +20% damage for 4 s · physical weapons, hybrid weapons, and bows.","Flat HP +30 to +150: rolls on hats, armor, shields, garments, shoes, and face/mouth accessories.","SP Regen +1 to +3 per natural recovery tick: rolls on magic weapons, right rings, Orbs, and hats.","Each piece can still only have 1 special option, and an item already dropped does not change."]}},{id:"2026-09-27-mage-pair-cooldown",date:"2026-09-27",time:"05:20",title:"เมจ: Stormbreak กับ Frost Area ออกแบบให้ใช้คู่กัน",lines:["คูลดาวน์ของแต่ละสกิล = แถบร่ายของตัวเอง + แถบร่ายของอีกสกิล + 0.3 วิ ใช้สลับกันจะพอดีรอบ ไม่ต้องรอ","ใช้สกิลเดียวจะต้องยืนรอคูลดาวน์ ดาเมจจึงได้ราวครึ่งเดียวของการใช้คู่กัน","คูลดาวน์ไม่ต่ำกว่าเวลายิงชุดของสกิลนั้น (Lv.10 = 1.62 วิ) DEX สูงจึงไม่ทำให้ยิงชุดเดียวกันซ้อนกันหลายชุด"],en:{title:"Mage: Stormbreak and Frost Area are designed to be used together",lines:["Each skill's cooldown = its own cast bar + the other skill's cast bar + 0.3 s, so alternating them lines up perfectly with no waiting.","Using just one skill means waiting out its cooldown, so its damage comes out to roughly half of using both together.","The cooldown never falls below that skill's own volley duration (Lv.10 = 1.62 s), so high DEX doesn't let you stack multiple volleys of the same skill."]}},{id:"2026-09-27-spawn-guard",date:"2026-09-27",time:"04:51",title:"อมตะ 5 วินาทีหลังเข้าเกม",lines:["เข้าเกมหรือเข้าแมพใหม่ จะได้สถานะอมตะ 5 วินาที (เริ่มนับเมื่อโหลดแผนที่เสร็จ) มอนสเตอร์ไม่เล็งและทำดาเมจไม่ได้ พิษหรือสถานะผิดปกติก็ไม่ติด","ถ้าเริ่มโจมตีมอนหรือผู้เล่น หรือใช้สกิลโจมตี สถานะอมตะจะหายไปทันที"],en:{title:"5 seconds of invincibility after logging in",lines:["Logging in or entering a new map grants 5 seconds of invincibility (starting once the map finishes loading): monsters can't target or damage you, and poison or status effects can't land.","Attacking a monster or player, or using an attack skill, ends the invincibility immediately."]}},{id:"2026-09-27-mage-storm-frost-combo",date:"2026-09-27",time:"04:41",title:"เมจ: คอมโบ Stormbreak + Frost Area",lines:["Stormbreak และ Frost Area พอแถบร่ายจบก็ใช้สกิลอื่นต่อได้ทันที ลูกที่เหลือตกต่อเองจนครบ จึงร่ายสองสกิลนี้ซ้อนกันได้","Frost Area ลงบนมอนที่ติดสตันจาก Stormbreak ดาเมจ +50%","Stormbreak ลงบนมอนที่ติดแช่แข็งจาก Frost Area ดาเมจ +50% (คูณต่อจากเวทแรงขึ้น 55% ของแช่แข็งเดิม)"],en:{title:"Mage: the Stormbreak + Frost Area combo",lines:["As soon as Stormbreak or Frost Area's cast bar finishes, you can cast the other right away — the remaining hits keep landing on their own — so the two skills can now overlap.","Frost Area landing on a monster stunned by Stormbreak deals +50% damage.","Stormbreak landing on a monster frozen by Frost Area deals +50% damage (stacking on top of the existing 55% magic damage boost from being frozen)."]}},{id:"2026-09-27-guild-transfer-leader",date:"2026-09-27",time:"04:12",title:"โอนหัวกิลได้",lines:["หัวกิลกดปุ่ม ♛ ข้างปุ่มนำออก ในช่องจัดการของรายชื่อสมาชิก เพื่อโอนตำแหน่งให้สมาชิกคนนั้นได้ทันที ไม่ต้องออกจากกิล","หัวกิลคนใหม่ได้สิทธิ์รับคำขอ ชวนคนเข้ากิล และเชิญสมาชิกออก ส่วนหัวกิลคนเดิมจะเป็นสมาชิกธรรมดาและยังอยู่ในกิลตามเดิม"],en:{title:"Guild leadership can now be transferred",lines:["The guild leader can press the ♛ button next to the remove button, in the member list's manage column, to hand leadership to that member instantly — no need to leave the guild.","The new leader gets rights to accept requests, invite players, and remove members; the old leader becomes a regular member and stays in the guild as before."]}},{id:"2026-09-27-storage-item-tooltip",date:"2026-09-27",time:"03:46",title:"ชี้การ์ดในคลังเห็นความสามารถแล้ว",lines:["เอาเมาส์ชี้การ์ด ไอเทม และวัตถุดิบในคลังเก็บของ จะเห็นจำนวนและคำอธิบายเหมือนในกระเป๋า เช่น การ์ดบอกค่าที่ได้เมื่อฝัง","คลิกขวา (หรือกดค้างบนมือถือ) เพื่อเปิดการ์ดรายละเอียดของไอเทมในคลังได้"],en:{title:"Hovering cards in storage now shows their effect",lines:["Hovering cards, items, and materials in storage now shows the quantity and description, just like in your bag — for example, a card shows the stat it grants when socketed.","Right-click (or long-press on mobile) to open the detailed item card for an item in storage."]}},{id:"2026-09-27-chat-not-sent-reason",date:"2026-09-27",time:"03:33",title:"แชทบอกเหตุผลเมื่อข้อความส่งไม่ได้",lines:["ข้อความที่ส่งไม่ออก จะมีข้อความจากระบบในช่องแชทบอกเหตุผลทุกครั้ง ไม่หายไปเฉย ๆ อีกแล้ว","เช่น เซิร์ฟเวอร์แชทไม่ตอบ, ตัวละครยังโหลดไม่เสร็จ, ข้อความปาร์ตี้/กิลส่งไม่ได้, พิมพ์แค่ /p หรือ /g โดยไม่มีข้อความ, ส่งข้อความเดิมซ้ำจากปุ่มแชร์หรือแชทมือถือ, ข้อความค้างส่งเกิน 10 ข้อความ หรือการเชื่อมต่อสิ้นสุดแล้ว"],en:{title:"Chat now explains why a message didn't send",lines:["A message that failed to send now always gets a system message in the chat log explaining why — it no longer just silently disappears.","For example: the chat server isn't responding, your character hasn't finished loading, a party/guild message couldn't be delivered, you typed only /p or /g with no message, you resent the same message from a share button or mobile chat, more than 10 messages are queued, or the connection has ended."]}},{id:"2026-09-27-mage-orb",date:"2026-09-27",time:"03:31",title:"ของมือซ้ายใหม่: Orb ของเมจ",lines:["เพิ่ม Orb (ออร์บเวท) อุปกรณ์มือซ้ายสำหรับเมจ ดรอปจากมอนสเตอร์ในช่องโล่","Orb ให้แต่ค่าสายเวท: MATK, SP, MDEF, INT และ DEX (ออปชันพิเศษมีได้แค่ MATK%, เจาะเกราะเวท หรือ SP Regen) ไม่มี DEF, FLEE หรือ HIT","Orb ที่ดรอปมีโอกาสได้ถึง 6 แถว เท่ากับลูกธนูขนนก","ถือคู่กับ Rod ได้ แต่ไม่ได้กับ Staff (อาวุธสองมือ) และไม่ทำให้ความเร็วโจมตีลดเหมือนโล่","ตีบวก Orb แล้วได้ MATK เพิ่มบนไอเทม แทนการลดดาเมจแบบโล่"],en:{title:"New left-hand item: the Mage's Orb",lines:["Added the Orb (a magic orb), a left-hand item for Mages, dropping from monsters in the shield slot.","Orbs only give magic stats: MATK, SP, MDEF, INT, and DEX (special options are limited to MATK%, Magic Pierce, or SP Regen) — no DEF, FLEE, or HIT.","A dropped Orb can roll up to 6 lines, same as the Feather Arrow.","It can be held alongside a Rod, but not with a Staff (a two-handed weapon), and unlike a shield it never slows your attack speed.","Refining an Orb adds MATK directly on the item, instead of the damage reduction a shield gets."]}},{id:"2026-09-27-party-transfer-leader",date:"2026-09-27",time:"03:06",title:"โอนหัวหน้าปาร์ตี้ได้",lines:["หัวหน้าปาร์ตี้กดปุ่ม ♛ ข้างชื่อสมาชิก (ในแถบปาร์ตี้หรือหน้าต่างปาร์ตี้) เพื่อโอนหัวหน้าให้คนนั้นได้ทันที ไม่ต้องออกจากปาร์ตี้","หัวหน้าคนใหม่ได้สิทธิ์ชวน เชิญออก และตั้งค่าปาร์ตี้ทั้งหมด ส่วนการประกาศหาสมาชิกจะปิดไว้ก่อนจนกว่าหัวหน้าคนใหม่จะเปิดเอง"],en:{title:"Party leadership can now be transferred",lines:["The party leader can press the ♛ button next to a member's name (in the party panel or party window) to hand leadership to that member instantly — no need to leave the party.","The new leader gets full rights to invite, remove members, and change party settings; the party-finder listing is turned off until the new leader turns it back on."]}},{id:"2026-09-27-freeze-ice-block",date:"2026-09-27",time:"02:57",title:"สถานะแช่แข็งสวยขึ้น",lines:["มอนที่ติดแช่แข็งจะถูกห่อด้วยก้อนน้ำแข็งคริสตัลที่พอดีกับตัวมอน มองทะลุเห็นตัวมอนข้างใน และน้ำแข็งแตกกระจายตอนหายแช่แข็ง","โดนแช่แข็งซ้ำระหว่างที่ยังแข็งอยู่จะต่อเวลาก้อนเดิม ไม่ซ้อนกล่องหลายชั้นหรือขึ้นข้อความซ้ำอีกแล้ว"],en:{title:"The freeze effect looks better now",lines:["A frozen monster is now wrapped in a crystal ice block that fits its shape — you can see the monster through it — and the ice shatters when the freeze ends.","Getting frozen again while still frozen now extends the same block's duration, instead of stacking multiple layers or repeating the same message."]}},{id:"2026-09-27-frost-area-volley",date:"2026-09-27",time:"02:47",title:"เมจ: Frost Area ยิงเป็นชุด",lines:["Frost Area เปลี่ยนจากระเบิดครั้งเดียว เป็นยิงเกล็ดน้ำแข็งลงรอบตัว ระดับละ 1 ลูก (Lv.10 = 10 ลูก) ลูกละ 120% MATK","เกล็ดแต่ละลูกมีโอกาส 50% แช่แข็งมอน 1.5 วิ ระหว่างแช่แข็งมอนโดนเวทแรงขึ้น 55%","คูลดาวน์ 0.85 วิ และแถบร่ายเท่าเดิม"],en:{title:"Mage: Frost Area now fires in a volley",lines:["Frost Area changed from a single burst to firing ice shards around you, 1 per level (Lv.10 = 10 shards), each dealing 120% MATK.","Each shard has a 50% chance to freeze the monster for 1.5 s; a frozen monster still takes 55% more magic damage.","Cooldown 0.85 s, cast bar unchanged."]}},{id:"2026-09-27-frost-area-buff",date:"2026-09-27",time:"02:14",title:"เมจ: Frost Area แช่แข็งนานขึ้น",lines:["Frost Area แช่แข็งมอนนาน 1.5 วิ (จากเดิม 1 วิ) โอกาสติดยังเป็น 30% ระหว่างแช่แข็ง มอนยังโดนเวทแรงขึ้น 55%","คูลดาวน์ลดครึ่งหนึ่ง จาก 1.7 วิ เหลือ 0.85 วิ"],en:{title:"Mage: Frost Area freezes for longer",lines:["Frost Area now freezes a monster for 1.5 s (up from 1 s); the chance to land is still 30%, and a frozen monster still takes 55% more magic damage.","Cooldown cut in half, from 1.7 s to 0.85 s."]}},{id:"2026-09-27-stormbreak-buff",date:"2026-09-27",time:"02:09",title:"เมจ: Stormbreak แรงขึ้น",lines:["Stormbreak ร่ายเร็วขึ้นเท่าตัว: แถบร่ายสั้นลงครึ่งหนึ่ง (Lv.10 จาก 1.6 วิ เหลือ 0.8 วิ ก่อนหักด้วย DEX)","คูลดาวน์ลดจาก 1.1 วิ เหลือ 0.55 วิ","สายฟ้าแต่ละลูกมีโอกาส 50% ทำให้มอนติดสตัน 1.5 วิ (จากเดิม 7% นาน 1.7 วิ)"],en:{title:"Mage: Stormbreak hits harder",lines:["Stormbreak now casts twice as fast: the cast bar is cut in half (Lv.10 goes from 1.6 s to 0.8 s, before DEX reduction).","Cooldown cut from 1.1 s to 0.55 s.","Each bolt has a 50% chance to stun the monster for 1.5 s (up from 7% for 1.7 s)."]}},{id:"2026-09-27-handoff-leftover-cleanup",date:"2026-09-27",time:"01:53",title:'แก้ตัวละครเข้าเกมไม่ได้ ค้างที่ "กำลังตรวจสอบข้อมูลตัวละคร"',lines:['ถ้าย้ายแผนที่หรือเปลี่ยนช่องตอนเซิร์ฟเวอร์รีสตาร์ท ตัวละครบางตัวอาจค้างอยู่สองที่ แล้วตอนเข้าเกมครั้งถัดไปจะวนอยู่ที่หน้าโหลด "กำลังตรวจสอบข้อมูลตัวละคร" หรือเสี่ยงได้ข้อมูลฉบับเก่า · ตอนนี้ระบบจะกลับไปตรวจแล้วลบฉบับที่ค้างทิ้งให้เองภายในไม่กี่นาที โดยเก็บฉบับล่าสุดไว้เสมอ'],en:{title:'Fixed characters stuck at "Checking character data"',lines:['If you changed maps or channels during a server restart, some characters could end up recorded in two places at once, causing the next login to loop on the "Checking character data" loading screen, or risk loading an outdated save · the system now checks and cleans up any leftover copy on its own within a few minutes, always keeping the most recent one.']}},{id:"2026-09-27-worn-skin-slot",date:"2026-09-27",time:"01:40",title:"แก้ช่อง Divine Wings ในกระเป๋าตอนสวมอยู่",lines:["ตอนสวมสกินปีก ช่องไอเทม Divine Wings ในกระเป๋ากลายเป็นสีเขียวทั้งช่อง เหลือแค่ตัว E มองไม่เห็นไอคอน · ตอนนี้แสดงไอคอนปีกกับจำนวนตามปกติ และมีป้าย E เล็ก ๆ ที่มุมซ้ายบน ทั้งมุมมองตารางและรายการ"],en:{title:"Fixed the Divine Wings bag slot while worn",lines:["While wearing the wings skin, the Divine Wings item slot in your bag used to turn entirely green, leaving only a tiny E with no visible icon · it now shows the wings icon and quantity normally, with a small E badge in the top-left corner, in both grid and list view."]}},{id:"2026-09-27-wings-cash-item",date:"2026-09-27",time:"01:23",title:"Divine Wings อยู่ในกระเป๋าแท็บ Cash",lines:["Divine Wings เป็นไอเทมในกระเป๋า แท็บ Cash (ไอเทมพิเศษ) แล้ว · ดับเบิลคลิกไอเทมเพื่อสวมหรือถอดสกินปีก หรือกดปุ่มในหน้ารายละเอียดไอเทม ส่วนแท็บสกินในหน้าต่างอุปกรณ์ก็ยังใช้ได้เหมือนเดิม","ไอเทมยังเป็นสกิน: ไม่ใช้ช่องอุปกรณ์ ไม่มีผลกับค่าสเตตัส ผูกกับตัวละคร ซื้อขาย เทรด และฝากคลังไม่ได้ · สวมอยู่จะมีป้าย E ที่ช่องไอเทม","ใครมีสกิน Divine Wings อยู่แล้วจะได้ไอเทมนี้ในกระเป๋าอัตโนมัติ และยังสวมอยู่เหมือนเดิม","หันหลังให้กล้องแล้วปีกจะอยู่ด้านหน้า ทับหลังตัวละคร ไม่ถูกตัวละครบังอีกต่อไป"],en:{title:"Divine Wings now lives in the bag's Cash tab",lines:["Divine Wings is now an item in your bag's Cash tab (special items) · double-click the item to wear or remove the wings skin, or use the button on the item details page — the skin tab in the equipment window still works too, as before.","It's still a skin: it takes no equipment slot, has no effect on stats, is character-bound, and cannot be sold, traded, or stored · while worn, its bag slot shows an E badge.","Anyone who already had the Divine Wings skin gets this item in their bag automatically, and it stays worn as before.","Turn your back to the camera and the wings now sit in front, over your character, instead of being hidden behind you."]}},{id:"2026-09-27-skin-mode",date:"2026-09-27",time:"00:58",title:"โหมดสกิน · ปีกเทพเป็นสกินแล้ว",lines:["หน้าต่างอุปกรณ์มีแท็บ อุปกรณ์ / สกิน ที่ป้ายด้านบน แท็บสกินแสดงช่องสกินทางซ้าย สกินที่มีทางขวา และตัวละครตรงกลางใส่สกินให้ดู","สกินเปลี่ยนแค่หน้าตา ไม่อยู่ในกระเป๋า ไม่ใช้ช่องอุปกรณ์ และไม่มีผลกับค่าสเตตัส · เลือกสกินแล้วกด สวมสกิน หรือ ถอด (ดับเบิลคลิกก็ได้)","Divine Wings ย้ายจากช่องผ้าคลุมไปเป็นสกินปีก: ใครมีอยู่แล้ว ทั้งในกระเป๋า คลัง หรือจดหมายที่ยังไม่ได้รับ จะได้เป็นสกินและสวมให้อัตโนมัติ ช่องผ้าคลุมจึงว่างให้ใส่ผ้าคลุมจริง · Divine Wings ไม่มี DEF +2 แล้ว","Job Lv. ในหน้าต่างอุปกรณ์ย้ายไปอยู่ใต้ตัวละครตรงกลาง"],en:{title:"Skin mode · Divine Wings is now a skin",lines:["The equipment window now has Equipment / Skin tabs at the top. The Skin tab shows skin slots on the left, owned skins on the right, and your character wearing them in the middle.","Skins only change your look: they're not in your bag, take no equipment slot, and have no effect on stats · select a skin, then press Wear or Remove (double-click also works).","Divine Wings moved from the garment slot to a wings skin: anyone who already had one — in their bag, storage, or an unclaimed letter — gets it as a skin, worn automatically, freeing up the garment slot for an actual garment · Divine Wings no longer gives DEF +2.","Job Lv. in the equipment window moved to below the character in the middle."]}},{id:"2026-09-27-boost-scroll-icons",date:"2026-09-27",time:"00:50",title:"ไอคอนใหม่ของ EXP Scroll และ Drop Scroll",lines:["EXP Scroll ได้ไอคอนใหม่เป็นม้วนคัมภีร์ปลายทอง ผูกริบบิ้นสีน้ำเงิน มีตราลูกศรชี้ขึ้นสีส้มตรงกลาง","Drop Scroll เป็นม้วนคัมภีร์ปลายเงินอมเขียว ผูกริบบิ้นเขียว มีตราถุงอัญมณีตรงกลาง ไม่ต้องสับสนกับ Warp Scroll อีก","ผลของไอเทมไม่ได้เปลี่ยน"],en:{title:"New icons for EXP Scroll and Drop Scroll",lines:["EXP Scroll now has a new icon: a scroll with gilded ends and a blue ribbon, with an orange up-arrow seal in the center.","Drop Scroll is a scroll with silvery-green ends and a green ribbon, with a gem-pouch seal in the center — no more mixing it up with the Warp Scroll.","The items' effects are unchanged."]}},{id:"2026-09-27-training-grounds",date:"2026-09-27",time:"00:45",title:"ลานฝึกหุ่นฟาง ทดสอบดาเมจได้",lines:["ประตูใหม่ในเมือง Aurelia ลานฝั่งขวาล่างของน้ำพุ (ใกล้ Storage Keeper) พาไปลานฝึกหุ่นฟาง","หุ่นฟางยืนสองแถว แถวละ 6 ตัว ป้ายเหนือรั้วบอกเลเวล Lv.1 / 50 / 100 / 150 / 200 / 250 — หุ่นเลเวลสูงมีเกราะและหลบหลีกเท่ามอนสเตอร์เลเวลนั้น ส่วน Lv.1 ไม่มีเกราะ","หุ่นฟางไม่ตาย ไม่เดิน ไม่ตีกลับ และไม่ให้ EXP หรือไอเท็ม ดาเมจทุกครั้ง รวมคริติคอล Double Attack สกิล และพิษ/ไฟ คิดด้วยสูตรเดียวกับการตีมอนสเตอร์จริง","เครื่องวัดดาเมจมุมซ้ายบอก DPS เฉลี่ย, DPS 5 วินาทีล่าสุด และดาเมจรวม กดหัวข้อเพื่อดูเวลา จำนวนฮิต % คริติคอล ครั้งที่พลาด และฮิตสูงสุด · หยุดตี 4 วินาทีตัวเลขจะหยุดค้าง ตีใหม่เริ่มรอบใหม่ หรือกด เริ่มใหม่"],en:{title:"Test your damage at the straw dummy training grounds",lines:["A new gate in Aurelia, in the plaza to the lower right of the fountain (near the Storage Keeper), leads to the straw dummy training grounds.","Straw dummies stand in two rows of 6, with signs above the fence marking Lv.1 / 50 / 100 / 150 / 200 / 250 — higher-level dummies have the DEF and evasion of a monster at that level, while the Lv.1 dummy has no DEF at all.","The dummies never die, move, or hit back, and give no EXP or items. Every hit — including criticals, Double Attack, skills, and poison/burn — is calculated with the same formula as hitting a real monster.","The damage meter in the top-left shows average DPS, DPS over the last 5 seconds, and total damage. Tap a heading to see time, hit count, crit %, misses, and biggest hit · stop hitting for 4 seconds and the numbers freeze; hit again to start a new round, or press Reset."]}},{id:"2026-09-27-daily-login-mall",date:"2026-09-27",time:"00:38",title:"รางวัลล็อกอินรายวันมีของ Item Mall",lines:["ตารางล็อกอิน 30 วันแจกของจาก Item Mall เพิ่ม ของที่เคยได้อยู่แล้วยังได้เหมือนเดิม ยกเว้นวันที่ 14 กับ 21 ที่เปลี่ยนยาเป็นของ Mall: วันที่ 5 · 12 · 19 · 26 ได้ EXP Scroll เพิ่ม 1 ใบ · วันที่ 6 · 13 · 20 · 27 ได้ Protection Stone เพิ่ม 1 ก้อน · วันที่ 7 Drop Scroll 1 ใบ · วันที่ 14 EXP Scroll 2 ใบ (แทน Concentration Potion) · วันที่ 21 Protection Stone 1 ก้อน (แทน Yellow Potion) · วันที่ 28 Drop Scroll 2 ใบ","รางวัลใหญ่วันที่ 30 เพิ่ม EXP Scroll ×2, Drop Scroll ×2 และ Protection Stone ×1 และช่องวันที่ 30 แสดงของครบทุกชิ้นแล้ว","ของจาก Mall มีป้าย MALL สีชมพูในตาราง เป็นของผูกตัวละครเหมือนซื้อจาก Mall (ขายหรือเทรดไม่ได้)"],en:{title:"Daily login rewards now include Item Mall gear",lines:["The 30-day login calendar now also gives out Item Mall items. Existing rewards stay the same, except days 14 and 21, where a potion changed to a Mall item: days 5 · 12 · 19 · 26 add 1 extra EXP Scroll · days 6 · 13 · 20 · 27 add 1 extra Protection Stone · day 7 gives 1 Drop Scroll · day 14 gives 2 EXP Scrolls (replacing the Concentration Potion) · day 21 gives 1 Protection Stone (replacing the Yellow Potion) · day 28 gives 2 Drop Scrolls.","The day-30 grand reward now also adds EXP Scroll ×2, Drop Scroll ×2, and Protection Stone ×1, and the day-30 slot now shows every item it contains.","Mall items carry a pink MALL badge on the calendar, and are character-bound like anything bought from the Mall (cannot be sold or traded)."]}},{id:"2026-09-27-divine-wings",date:"2026-09-27",time:"00:29",title:"ปีกเทพ Divine Wings",lines:["เพิ่มอุปกรณ์ช่องผ้าคลุม Divine Wings: สวมแล้วมีปีกสีทองกางอยู่ด้านหลังตัวละคร กระพือช้า ๆ ตอนยืน เร็วขึ้นตอนเดิน มีประกายแสงร่วงจากขนปีก และผู้เล่นรอบข้างมองเห็นด้วย","Divine Wings เป็นของพิเศษที่ทีมงานมอบให้ทางจดหมายเท่านั้น ไม่ดรอปจากมอนสเตอร์และไม่มีขายในร้าน · ทุกอาชีพสวมได้ตั้งแต่ Lv.1 · ส่งมาพร้อมล็อกกันขายพลาด ปลดล็อกเองได้","ถ้ามีคนใส่ปีกอยู่ใกล้ ๆ หลายคน เกมจะวาดปีกให้เฉพาะ 4 คนที่อยู่ใกล้ที่สุด เพื่อไม่ให้เครื่องหน่วง"],en:{title:"Divine Wings",lines:["Added the Divine Wings garment: wear it and golden wings spread behind your character, beating slowly at rest and faster while walking, shedding motes of light — and other nearby players can see it too.","Divine Wings is a special item the team sends only by letter — it never drops from monsters and is never sold in a shop · every class can wear it from Lv.1 · it arrives locked to prevent an accidental sale, and you can unlock it yourself.","If several people nearby are wearing wings, the game only renders them for the 4 closest players, to avoid lag."]}},{id:"2026-09-27-card-any-piece-again",date:"2026-09-27",time:"00:24",title:"การ์ดกลับมาใส่ได้ทุกชิ้นเหมือนเดิม",lines:["ยกเลิกกฎการ์ดใส่ได้เฉพาะอุปกรณ์ชนิดเดียวไว้ก่อน การ์ดทุกใบกลับมาฝังในอุปกรณ์ได้ทุกชิ้นเหมือนเดิม หน้าฝังการ์ดแสดงอุปกรณ์ทุกชิ้นอีกครั้ง","การ์ดที่ฝังไว้แล้วอยู่ที่เดิมและใช้ได้ตามปกติ ไม่มีอะไรถูกถอด","ถ้ากฎนี้กลับมาใช้ในอนาคต การ์ดที่ฝังอยู่ผิดชนิดอุปกรณ์จะถูกถอดคืนเข้ากระเป๋าให้ครบทุกใบ ไม่หาย และจะแจ้งล่วงหน้าก่อน","อาวุธสองมือยังเป็นเหมือนเดิม"],en:{title:"Cards can be socketed into any piece again",lines:["The rule limiting a card to one equipment type is on hold for now — every card can once again be socketed into any piece, and the card-socketing page shows every piece of equipment again.","Cards already socketed stay exactly where they are and keep working normally; nothing was removed.","If this rule returns in the future, any card socketed into the wrong equipment type will be returned to your bag in full, never lost, with advance notice beforehand.","Two-handed weapons are unchanged."]}},{id:"2026-09-27-guild-player-search",date:"2026-09-27",time:"00:18",title:"ค้นหาชื่อผู้เล่นในคำขอเข้าร่วมและสมาชิกกิล",lines:["ตารางคำขอเข้าร่วมกับตารางสมาชิกกิลมีช่องค้นหาชื่อผู้เล่นอยู่ใต้หัวตาราง พิมพ์ชื่อบางส่วนแล้วรายชื่อจะกรองให้ทันที พร้อมบอกว่าเจอกี่คนจากทั้งหมด","ชื่อที่ตรงทั้งหมดขึ้นก่อน ตามด้วยชื่อที่ขึ้นต้นด้วยคำค้น ตัวพิมพ์เล็กใหญ่ไม่มีผล หัวกิลกดรับเข้ากิล ปฏิเสธ หรือนำออกจากผลค้นหาได้เลย"],en:{title:"Search player names in join requests and the member list",lines:["The join-request table and the member table now have a player search box under the header. Type part of a name and the list filters instantly, showing how many matches out of the total.","Exact matches show first, then names starting with the search term; case doesn't matter. The guild leader can accept, decline, or remove members straight from the search results."]}},{id:"2026-09-27-guild-invite-chat",date:"2026-09-27",time:"00:17",title:"หัวกิลชวนคนเข้ากิลจากแชทได้",lines:['หัวกิลคลิกขวา (หรือกดค้างบนมือถือ) ที่ชื่อผู้เล่นในแชท หรือที่ตัวผู้เล่นในแมพ แล้วเลือก "ชวนเข้ากิล" ได้เลย ผู้เล่นอยู่แมพไหนก็ส่งถึง','ฝั่งที่ถูกชวนจะมีหน้าต่างบอกชื่อกิลและเลเวล กด "เข้าร่วมกิล" ภายใน 1 นาทีก็เข้ากิลทันที ไม่ต้องรอหัวกิลกดรับอีกรอบ',"เมนูนี้ขึ้นเฉพาะคนที่มีสิทธิ์รับคนเข้ากิล (ตอนนี้คือหัวกิล) และหัวกิลจะได้รับข้อความเมื่ออีกฝ่ายตอบรับหรือปฏิเสธ"],en:{title:"Guild leaders can now invite players from chat",lines:[`The guild leader can right-click (or long-press on mobile) a player's name in chat, or the player on the map, and pick "Invite to guild" — it reaches them on any map.`,`The invited player gets a window showing the guild's name and level; pressing "Join guild" within 1 minute joins immediately, with no need for the leader to accept separately.`,"This menu only shows for players with rights to accept members (currently the guild leader), who also gets a message when the other side accepts or declines."]}},{id:"2026-09-27-longer-chat-history",date:"2026-09-27",time:"00:11",title:"ช่องแชทเลื่อนย้อนดูได้ยาวขึ้น",lines:["ช่องแชทเก็บข้อความย้อนหลังได้ 100 บรรทัดต่อแท็บ จากเดิมที่เลื่อนขึ้นไปดูได้แค่ 20 บรรทัด","เข้าเกมใหม่หรือเปลี่ยนห้องแชทโลก จะเห็นข้อความเก่าของห้องนั้นย้อนหลัง 100 บรรทัด จากเดิม 40","ระหว่างเลื่อนขึ้นอ่านข้อความเก่า ข้อความใหม่จะไม่ดึงกลับลงล่างสุดแล้ว เลื่อนลงล่างสุดหรือพิมพ์ส่งข้อความเมื่อไหร่ก็กลับมาตามข้อความล่าสุดตามเดิม"],en:{title:"Chat now scrolls back further",lines:["The chat box now keeps 100 lines of history per tab, up from only 20 lines of scrollback before.","Logging in again or switching world chat rooms now shows the last 100 lines of that room's history, up from 40.","While scrolled up reading old messages, new messages no longer pull you back to the bottom — scrolling to the bottom or sending a message returns you to following the latest messages, as before."]}},{id:"2026-09-27-guild-exp-buff",date:"2026-09-27",time:"00:06",title:"โบนัส EXP กิลแสดงเป็นไอคอนบัฟ",lines:["สมาชิกกิลจะเห็นไอคอนบัฟ โบนัส EXP กิล ในแถวบัฟข้างการ์ดตัวละครตลอดเวลาที่อยู่ในกิล ชี้หรือแตะที่ไอคอนเพื่อดูว่าได้ Base EXP และ Job EXP เพิ่มกี่ % และกิลเลเวลเท่าไร","ออกจากกิลแล้วไอคอนจะหายไป เมื่อกิลอัปเลเวล % ที่แสดงจะเพิ่มตาม ส่วนค่าโบนัสของแต่ละเลเวลยังเท่าเดิม"],en:{title:"The Guild EXP bonus now shows as a buff icon",lines:["Guild members now see a Guild EXP Bonus buff icon in the buff row beside their character card for as long as they're in a guild. Hover or tap the icon to see the extra Base EXP and Job EXP %, and the guild's level.","The icon disappears when you leave the guild. When the guild levels up, the shown % increases along with it, while each level's bonus amount is unchanged."]}},{id:"2026-09-27-channel-locate-self",date:"2026-09-27",time:"00:05",title:'แก้ติดหน้า "กำลังตรวจสอบข้อมูลตัวละคร" ในห้องที่ไม่ใช่ห้อง 1',lines:['ผู้เล่นที่อยู่ห้อง 2 ขึ้นไปของแต่ละแมพ บางคนเข้าเกมแล้ววนอยู่ที่หน้า "กำลังตรวจสอบข้อมูลตัวละคร" ไม่จบ สาเหตุคือตอนค้นหาตัวละคร ระบบเข้าใจผิดว่าห้องที่ถามคือห้อง 1 เลยไม่ได้ค้นในห้อง 1 จริง ๆ แต่ไปนับห้องที่ถามเองว่าเป็นที่อยู่ล่าสุด',"แก้แล้ว ตัวละครจะถูกพาไปห้องที่มีข้อมูลล่าสุดเองเมื่อเข้าเกมรอบถัดไป ถ้ายังเข้าไม่ได้ให้แจ้งผ่าน Discord"],en:{title:'Fixed getting stuck at "Checking character data" outside channel 1',lines:['Some players in channel 2 or higher on a map would log in and loop endlessly on "Checking character data." The cause was that the character lookup mistook the channel being asked as channel 1, so it never actually searched channel 1 — instead treating the asking channel itself as the last known location.',"Fixed — your character now gets routed to the channel holding its latest data automatically on your next login. If you're still stuck, please report it on Discord."]}},{id:"2026-09-27-guild-search",date:"2026-09-27",time:"00:01",title:"ค้นหาชื่อกิลเพื่อขอเข้าร่วม",lines:["หน้ากิลของคนที่ยังไม่มีกิลมีช่องค้นหาเหนือรายชื่อกิล พิมพ์ชื่อกิลบางส่วนแล้วรายชื่อจะกรองให้ทันที ไม่ต้องไล่เลื่อนหาเอง",'ชื่อที่ตรงทั้งหมดขึ้นก่อน ตามด้วยชื่อที่ขึ้นต้นด้วยคำค้น ตัวพิมพ์เล็กใหญ่ไม่มีผล แล้วกด "ขอเข้าร่วม" จากผลค้นหาได้เลย','ตัวหนังสือบนปุ่ม "ขอเข้าร่วม" กลับเป็นสีขาวอ่านชัดขึ้น และปุ่มรีเฟรชรายชื่อกิลไม่เบี้ยวแล้ว'],en:{title:"Search guild names to request joining",lines:["The guild page for players without a guild now has a search box above the guild list. Type part of a guild's name and the list filters instantly, no more scrolling to find it.",`Exact matches show first, then names starting with the search term; case doesn't matter, and you can press "Apply" straight from the search results.`,'The text on the "Apply" button is now readable white, and the guild-list refresh button no longer looks misaligned.']}},{id:"2026-09-26-guild-board",date:"2026-09-26",time:"23:28",title:"หน้ากิลโฉมใหม่",lines:["หน้ากิลกว้างขึ้นเป็นกระดานเดียว: ตราและเลเวลกิล จำนวนสมาชิก โบนัส EXP และความจุเลเวลถัดไปอยู่แถวบน","คลังกิลแยกช่องบริจาค Spirit Shard กับ Silver พร้อมแถบยอดสะสมและปุ่มบริจาคของแต่ละอย่าง","ตารางสมาชิกบอกตำแหน่ง เลเวล อาชีพ สถานะออนไลน์ และยอดบริจาครวมของแต่ละคน (นับตั้งแต่อัปเดตนี้) ส่วนหัวกิลเห็นตารางคำขอเข้าร่วมอยู่ข้างกัน"],en:{title:"A redesigned guild page",lines:["The guild page is now wider, in a single board: the guild crest and level, member count, EXP bonus, and next-level capacity sit in the top row.","The guild vault now has separate donation slots for Spirit Shard and Silver, each with its own progress bar and donate button.","The member table shows each member's rank, level, class, online status, and total donations (counted since this update); the guild leader also sees the join-request table right beside it."]}},{id:"2026-09-26-refund-mail-reminder",date:"2026-09-26",time:"22:51",title:"เตือนก่อนขอคืนเงินถ้า Gold รออยู่ในกล่องจดหมาย",lines:["กดขอคืนเงินรายการที่ Gold เข้ากล่องจดหมายแล้วแต่ยังไม่ได้กดรับ จะมีกล่องแจ้งพร้อมปุ่ม เปิด Mail ให้ไปกดรับได้ทันที","ถ้าตั้งใจขอคืนเงินจริงก็ส่งคำขอต่อได้ตามเดิม"],en:{title:"A warning before refunding if Gold is waiting in your mailbox",lines:["Requesting a refund for a purchase whose Gold already reached your mailbox, but hasn't been claimed yet, now shows a notice with an Open Mail button so you can claim it right away.","If you still want to go through with the refund, you can submit the request as before."]}},{id:"2026-09-26-arena-colosseum",date:"2026-09-26",time:"22:35",title:"สนาม PVP Aurelia Arena กลายเป็นโคลอสเซียม",lines:["สนาม PVP วาดใหม่เป็นโคลอสเซียม: ลานทรายรูปวงรีกว้างกว่าเดิมราว 1.5 เท่า ล้อมด้วยกำแพงและอัฒจันทร์ที่มีผู้ชมเต็มรอบ","กลางลานไม่มีวัตถุบังหรือขวางทางเลย สู้ได้เต็มพื้นที่ รูปปั้นนักสู้ เตาไฟ และธงย้ายไปอยู่ตามมุมนอกอาคาร","เข้าสนามแล้วเกิดหน้าประตูทิศใต้ ทางกลับเมืองอยู่ในอุโมงค์ประตูเดิม"],en:{title:"Aurelia Arena is now a colosseum",lines:["The PVP arena has been redrawn as a colosseum: an oval sand floor roughly 1.5x wider than before, ringed by walls and stands packed with spectators.","The center of the floor has no obstacles at all now, so you can fight across the full area — the fighter statue, braziers, and banners moved to the corners outside the building.","Entering the arena now spawns you at the south gate; the way back to town is through the same tunnel gate as before."]}},{id:"2026-09-26-stale-directory-login",date:"2026-09-26",time:"22:34",title:"เข้าเกมได้เร็วขึ้นหลังเซิร์ฟเวอร์กลางหลุด",lines:['ช่วงที่เซิร์ฟเวอร์กลางรีสตาร์ตบ่อย การย้ายแมพหรือย้ายห้องบางครั้งไม่ได้จดว่าตัวละครอยู่ห้องไหน ทำให้ตอนเข้าเกมรอบถัดไปต้องค้นหาตัวละครทุกห้องและติดหน้า "กำลังตรวจสอบข้อมูลตัวละคร" นาน',"ตอนนี้ห้องที่รับตัวละครมาจะจดซ้ำจนสำเร็จ และถ้าค้นหาไม่ทันในรอบแรก รอบถัดไปจะค้นต่อจากเดิมแทนการเริ่มใหม่ ตัวละครและของไม่ได้เปลี่ยน"],en:{title:"Faster logins after the hub drops",lines:['During frequent hub restarts, changing maps or channels sometimes failed to record which channel your character was on, so your next login had to search every channel and got stuck at "Checking character data" for a long time.',"The channel that receives a character now keeps retrying the record until it succeeds, and if a search doesn't finish in time, the next attempt continues from where it left off instead of starting over. Characters and items are unaffected."]}},{id:"2026-09-26-buff-two-columns",date:"2026-09-26",time:"22:29",title:"ไอคอนบัฟเรียงแนวตั้ง ไม่เกิน 2 คอลัมน์",lines:["ไอคอนบัฟและดีบัฟข้างการ์ดตัวละครเรียงลงเป็นแนวตั้งแล้ว ไม่ยาวเป็นแถวบังจอด้านบนเหมือนเดิม","มีบัฟหลายอันจะแบ่งเป็นสองคอลัมน์ คอลัมน์แรกเต็มก่อนแล้วค่อยต่อคอลัมน์ที่สอง"],en:{title:"Buff icons now stack vertically, up to 2 columns",lines:["Buff and debuff icons beside the character card now stack vertically instead of stretching into a row that covered the top of the screen.","With many buffs active, they split into two columns — the first column fills up before the second one starts."]}},{id:"2026-09-26-topup-confirm-on-return",date:"2026-09-26",time:"22:10",title:"เติม Gold เข้าเร็วขึ้นหลังจ่ายเงิน",lines:["กลับจากหน้าชำระเงินแล้ว เกมจะเช็กยอดกับ Stripe ให้ทันที ไม่ต้องรอระบบแจ้งกลับที่บางครั้งช้าเป็นชั่วโมง","จ่ายด้วย PromptPay แล้วธนาคารยังไม่ยืนยัน เกมจะถามซ้ำให้อีกราว 2 นาที ถ้ายังไม่ขึ้นของจะเข้ากล่องจดหมายเองเมื่อยืนยัน ไม่ต้องจ่ายซ้ำ"],en:{title:"Gold arrives faster after payment",lines:["Returning from the payment page now has the game check with Stripe right away, instead of waiting for a callback that could sometimes take an hour.","Paying with PromptPay while the bank hasn't confirmed yet triggers another check about 2 minutes later; if it still hasn't gone through, the Gold arrives in your mailbox automatically once confirmed — no need to pay again."]}},{id:"2026-09-26-emotes",date:"2026-09-26",time:"21:58",title:"อีโมตแบบ Ragnarok ขึ้นบนหัว",lines:["กดปุ่มหน้ายิ้มข้างปุ่มส่งแชท เลือกอีโมตได้ 30 แบบ บับเบิลจะเด้งขึ้นบนหัวตัวละครพร้อมแอนิเมชัน ผู้เล่นรอบข้างเห็นด้วย","พิมพ์คำย่อในแชทแทนได้ เช่น /! /? /lv /thx /sry /gg /help (ชี้ที่อีโมตในหน้าต่างเพื่อดูคำย่อ)","ส่งได้ทุก 1.2 วินาที ใช้ได้แม้นั่งอยู่หรือตายอยู่ แต่ไม่ขึ้นตอนซ่อนตัว"],en:{title:"Ragnarok-style emotes above your head",lines:["Press the smiley button next to the send button to pick from 30 emotes; a bubble pops up above your character's head with an animation, visible to nearby players too.","You can also type a shortcut in chat instead, e.g. /! /? /lv /thx /sry /gg /help (hover an emote in the window to see its shortcut).","Usable once every 1.2 seconds, works even while sitting or dead, but doesn't show while hidden."]}},{id:"2026-09-26-hub-locate-flood",date:"2026-09-26",time:"21:58",title:"แก้เซิร์ฟเวอร์กลางหลุดบ่อยช่วงคนเยอะ",lines:['ช่วงหัวค่ำเซิร์ฟเวอร์กลางรีสตาร์ตทุก ~3 นาที ทำให้ล็อกอินไม่ได้ แชทโลกหาย และเห็น "กำลังตรวจสอบข้อมูลตัวละคร" ซ้ำ ๆ สาเหตุคือการค้นหาตัวละครตอนเข้าเกมถามทุกห้องพร้อมกันจนคิวล้น ตอนนี้ถามทีละชุดและถามห้องที่ตัวละครอยู่ก่อนเสมอ',"ตัวละครและของไม่ได้หายหรือถูกเปลี่ยน ถ้ายังเข้าไม่ได้ให้รอสักครู่แล้วเกมจะต่อให้เอง"],en:{title:"Fixed frequent hub disconnects during busy hours",lines:[`During early evening the hub was restarting roughly every 3 minutes, breaking logins, dropping world chat, and repeatedly showing "Checking character data." The cause was that character lookups on login queried every channel at once, flooding the queue — it now queries in batches and always checks the character's actual channel first.`,"Characters and items were never lost or altered. If you still can't log in, wait a moment and the game will reconnect you automatically."]}},{id:"2026-09-26-lingering-buff-auras",date:"2026-09-26",time:"21:50",title:"ออร่าบัฟค้างอยู่ตลอดเวลาบัฟ",lines:["บัฟเหล่านี้มีออร่าติดตัวอยู่ตลอดจนกว่าบัฟจะหมด: Holy Guard โดมพลังจาง ๆ ครอบตัว · Power Surge เปลวไฟรอบตัว · Divine Boon ตราปีกทองลอยเหนือหัว · Spirit Instinct เหยี่ยววิญญาณบินวนรอบหัว · Remedy Light วงเวทย์สีเขียวใต้เท้า · Dokunuri คุไนชุบพิษข้างเอว · Vanish ควันสีม่วงลอยจากตัว","ออร่าขึ้นกับทุกคนที่ได้รับบัฟจริง รวมถึงเพื่อนในปาร์ตี้ที่ได้ Holy Guard หรือ Divine Boon และหายทันทีเมื่อบัฟหมด","ผู้เล่นคนอื่นเห็นด้วย ในที่คนเยอะจะแสดงเฉพาะคนที่อยู่ใกล้ และตั้งค่า ผู้เล่นคนอื่น เป็น ซ่อนชื่อและเอฟเฟกต์ เพื่อซ่อนออร่าของคนอื่นได้ ผลของบัฟไม่ได้เปลี่ยน"],en:{title:"Buff auras now stay on for the buff's whole duration",lines:["These buffs now keep a visible aura the entire time they're active: Holy Guard — a faint dome of light around you · Power Surge — flames circling you · Divine Boon — a golden wing emblem floating overhead · Spirit Instinct — a spirit hawk circling your head · Remedy Light — a green magic ring under your feet · Dokunuri — a poisoned kunai at your hip · Vanish — purple smoke drifting off you.","The aura shows for anyone who actually has the buff, including party members who receive Holy Guard or Divine Boon, and disappears the instant the buff ends.","Other players can see it too; in crowded areas only nearby players show theirs, and setting Other Players to Hide names and effects hides other people's auras. The buffs' actual effects are unchanged."]}},{id:"2026-09-26-bag-grid-tiles",date:"2026-09-26",time:"21:48",title:"ช่องกระเป๋าแบบเดียวกับคลังเก็บของ",lines:["ช่องไอเทมในกระเป๋า (มุมมองตาราง) ใช้ช่องสี่เหลี่ยมแบบเดียวกับคลังเก็บของ จำนวนเป็นตัวขาวที่มุมขวาล่าง ช่องว่างมีลายดาวจางๆ"],en:{title:"Bag slots now match storage's look",lines:["Item slots in your bag (grid view) now use the same square tiles as storage, with the quantity in white in the bottom-right corner and a faint starry pattern for empty slots."]}},{id:"2026-09-26-storage-grid",date:"2026-09-26",time:"21:42",title:"คลังเก็บของแสดงเป็นช่องตาราง",lines:["ของในคลังเก็บของแสดงเป็นช่องสี่เหลี่ยมแถวละ 6 ช่อง มีไอคอนและจำนวนที่มุมขวาล่าง ชี้ที่ช่องเพื่อดูชื่อไอเทม","ช่องที่ยังว่างแสดงเป็นช่องเปล่าให้เห็นว่ายังเก็บได้อีก"],en:{title:"Storage now shows a grid of slots",lines:["Items in storage now show as square tiles, 6 per row, with an icon and quantity in the bottom-right corner. Hover a slot to see the item's name.","Empty slots show as blank tiles, so you can see how much room is left."]}},{id:"2026-09-26-last-ten-skill-effects",date:"2026-09-26",time:"21:38",title:"เอฟเฟกต์ใหม่ให้สกิลที่เหลืออีก 10 สกิล",lines:["Piercing Shot ยิงหอกแสงสีฟ้าทะลุผ่านเป้าหมายออกไปอีกด้าน · Tierra Sharp Spear มีหนามหินพุ่งขึ้นจากพื้นใต้เป้าหมายทุกฮิต","Spirit Instinct มีวิญญาณเหยี่ยวสีเขียวกางปีกเหนือตัว · Vanish หายตัวไปในกลุ่มควันสีม่วง · Remedy Light มีดอกบัวแสงบานลอยขึ้นเหนือตัว · First Aid มีผ้าพันแผลตรากากบาทสีชมพูเด้งขึ้นเหนือหัว","Mamushi: Viper Fang มีงูพิษสีเขียวพุ่งฉกเป้าหมายตอนคุไนถึง · Venom Rupture พิษระเบิดเป็นสีม่วงเขียวบนตัวเป้าหมาย · Dokugiri มีหมอกพิษสีเขียวแผ่ไปรอบตัวจนถึงขอบระยะสกิล · Dokunuri มีคุไนชุบพิษหยดพิษอยู่ข้างตัว","Piercing Shot และ Spirit Instinct เลิกยิงลูกธนูเล็กแบบเดิมแล้ว ผู้เล่นคนอื่นเห็นเอฟเฟกต์ใหม่ด้วย ความแรงและผลของสกิลไม่ได้เปลี่ยน"],en:{title:"New effects for 10 more skills",lines:["Piercing Shot fires a blue light spear that pierces straight through the target and out the other side · Tierra Sharp Spear has stone spikes erupt from the ground under the target on every hit.","Spirit Instinct spreads a green spirit hawk's wings above you · Vanish disappears into a puff of purple smoke · Remedy Light has a glowing lotus bloom rise above you · First Aid pops a pink cross bandage above your head.","Mamushi: Viper Fang has a green venomous snake lunge at the target as the kunai lands · Venom Rupture bursts poison in purple-green on the target · Dokugiri spreads a green poison mist out to the skill's full range · Dokunuri drips poison beside you from a poisoned kunai.","Piercing Shot and Spirit Instinct no longer fire the old small arrow. Other players see the new effects too — the skills' power and effects are unchanged."]}},{id:"2026-09-26-gold-exchange-confirm",date:"2026-09-26",time:"21:34",title:"ตลาด Gold มีหน้าต่างยืนยันก่อนซื้อขาย",lines:["กดซื้อ ขาย ตั้งรับซื้อ หรือตั้งขาย Gold แล้วจะมีหน้าต่างยืนยันขึ้นมาก่อน บอกจำนวน Gold ราคา Silver ที่จ่ายหรือได้รับ และยอดคงเหลือหลังเทรด","ถ้าตลาดมี Gold ไม่ครบจำนวนที่ใส่ หน้าต่างยืนยันจะแจ้งว่าซื้อหรือขายได้เท่าที่มี","ถ้า Silver หรือ Gold ไม่พอ จะแจ้งทันทีโดยไม่เปิดหน้าต่างยืนยัน"],en:{title:"The Gold market now confirms before trading",lines:["Buying, selling, or placing a buy/sell order for Gold now shows a confirmation window first, stating the Gold amount, the Silver paid or received, and your balance after the trade.","If the market doesn't have enough Gold to fill your full amount, the confirmation window will say how much it can fill instead.","If you don't have enough Silver or Gold, you'll be told immediately without the confirmation window opening."]}},{id:"2026-09-26-locked-gear-card-replace",date:"2026-09-26",time:"21:33",title:"ใส่การ์ดทับบนไอเทมที่ล็อกได้แล้ว",lines:["ไอเทมที่ล็อกไว้ใส่การ์ดใหม่ทับการ์ดเดิมได้แล้ว ไม่ต้องปลดล็อกก่อน (รวมถึงไอเทมจาก Item Mall ที่ปลดล็อกไม่ได้) การ์ดเดิมยังหายถาวรเหมือนเดิม และเกมจะถามยืนยันก่อนทุกครั้ง","ล็อกยังกันการทิ้ง ขาย เทรด และตีบวกเสี่ยงแตกเหมือนเดิม"],en:{title:"You can now socket a card over a locked item",lines:["A locked item can now have a new card socketed over the old one without unlocking it first (this includes Item Mall items that can't be unlocked). The old card is still lost permanently, and the game asks you to confirm every time.","Locking still prevents dropping, selling, trading, and risking a break on refine, as before."]}},{id:"2026-09-26-power-surge-leap-shot-effects",date:"2026-09-26",time:"21:26",title:"เอฟเฟกต์ใหม่ให้สกิล Power Surge และ Leap Shot",lines:["Power Surge มีออร่าไฟสีส้มทองพุ่งขึ้นรอบตัวพ่อค้า และกำปั้นเกราะทองลอยขึ้นเหนือหัว","Leap Shot ยิงลูกธนูที่มีลมหมุนพันรอบพุ่งเข้าหาเป้าหมาย แล้วมีลมกระแทกระเบิดออกไปทางเดียวกับที่เป้าหมายถูกผลักกระเด็น แทนลูกธนูเล็กแบบเดิม","ผู้เล่นคนอื่นเห็นเอฟเฟกต์ใหม่ด้วย ความแรงและผลของสกิลไม่ได้เปลี่ยน"],en:{title:"New effects for Power Surge and Leap Shot",lines:["Power Surge surrounds the merchant with an orange-gold flame aura, with a golden armored fist rising above their head.","Leap Shot now fires an arrow wrapped in swirling wind that rushes at the target, followed by a burst of wind in the same direction the target gets knocked back, replacing the old small arrow.","Other players see the new effects too — the skills' power and effects are unchanged."]}},{id:"2026-09-26-gold-exchange-anywhere",date:"2026-09-26",time:"21:22",title:"ตลาด Gold ซื้อขายได้จากทุกที่",lines:["ทุกคนซื้อขาย Gold กับ Silver ในตลาด Gold ได้จากทุกที่แล้ว ไม่ต้องเดินไปหานายหน้าตลาด และไม่ต้องมี Premium"],en:{title:"The Gold market now works from anywhere",lines:["Everyone can now buy and sell Gold for Silver on the Gold market from anywhere — no need to walk to a market broker, and no Premium required."]}},{id:"2026-09-26-twin-fang-toxin-blink-effects",date:"2026-09-26",time:"21:18",title:"เอฟเฟกต์ใหม่ให้สกิล Twin Fang และ Toxin Blink",lines:["Twin Fang มีรอยฟันรูปเขี้ยวสีแดงสองอันงับเข้าหากันบนตัวเป้าหมายเหมือนถูกกัด พร้อมแสงวาบและประกายสีแดง","Toxin Blink มีรอยฟันมีดสีเขียวพิษพาดผ่านเป้าหมาย แล้วพิษสาดกระเซ็นขึ้นจากแผล หยดพิษร่วงลงพื้น","ผู้เล่นคนอื่นเห็นเอฟเฟกต์ใหม่ด้วย ความแรงและผลของสกิลไม่ได้เปลี่ยน"],en:{title:"New effects for Twin Fang and Toxin Blink",lines:["Twin Fang shows two red fang-shaped bite marks snapping together on the target as if bitten, with a flash and red sparks.","Toxin Blink leaves a green poisoned blade slash across the target, with poison splashing from the wound and dripping to the ground.","Other players see the new effects too — the skills' power and effects are unchanged."]}},{id:"2026-09-26-smaller-bag-storage-2",date:"2026-09-26",time:"21:04",title:"หน้าต่างกระเป๋าและคลังเก็บของเล็กลงอีก",lines:["หน้าต่างกระเป๋าและคลังเก็บของเล็กลงอีก 10% บนจอคอมพิวเตอร์"],en:{title:"The bag and storage windows are smaller again",lines:["The bag and storage windows are 10% smaller again on desktop."]}},{id:"2026-09-26-challenging-shadow-burst-effects",date:"2026-09-26",time:"20:56",title:"เอฟเฟกต์ใหม่ให้สกิล Challenging และ Shadow Burst",lines:["Challenging มีตราสิงโตคำรามพร้อมดาบไขว้เด้งขึ้นเหนือหัว และคลื่นเสียงสีแดงสองระลอกวิ่งออกไปถึงระยะยั่วยุ","Shadow Burst มีระเบิดเงามืดพร้อมใบมีดเงาหมุนออกรอบตัว และแอ่งเงาสีม่วงแผ่บนพื้นจนถึงขอบระยะสกิล","ผู้เล่นคนอื่นเห็นเอฟเฟกต์ใหม่ด้วย ความแรงและผลของสกิลไม่ได้เปลี่ยน"],en:{title:"New effects for Challenging and Shadow Burst",lines:["Challenging pops a roaring lion emblem with crossed swords above your head, sending two red sound-wave rings out to the taunt's range.","Shadow Burst detonates a burst of dark shadow with spinning shadow blades around you, spreading a pool of purple shadow across the ground out to the skill's full range.","Other players see the new effects too — the skills' power and effects are unchanged."]}},{id:"2026-09-26-smaller-bag-storage",date:"2026-09-26",time:"20:53",title:"หน้าต่างกระเป๋าและคลังเก็บของเล็กลง",lines:["หน้าต่างกระเป๋าและคลังเก็บของเล็กลง 20% บนจอคอมพิวเตอร์ เห็นฉากเกมรอบตัวมากขึ้น และวางสองหน้าต่างเคียงกันได้ง่ายขึ้น"],en:{title:"Inventory and Storage windows shrink",lines:["The Inventory and Storage windows are now 20% smaller on desktop, showing more of the game around you and making it easier to place the two windows side by side."]}},{id:"2026-09-26-storage-all-tab",date:"2026-09-26",time:"20:49",title:"คลังเก็บของมีแท็บ All",lines:["เพิ่มแท็บ All บนสุดของคลังเก็บของ แสดงของทุกหมวดรวมกัน และเปิดเป็นแท็บแรก","ตัวนับช่องในคลังไม่ล้นทับช่องค้นหาแล้ว ตัวหนังสือในหน้าต่างคลังเปลี่ยนเป็นฟอนต์เดียวกับหน้าต่างอื่น"],en:{title:"Storage gets an All tab",lines:["Added an All tab at the top of Storage that shows every category together, and it now opens first.","The slot counter in Storage no longer overlaps the search box, and its text now uses the same font as other windows."]}},{id:"2026-09-26-flame-burst-redrawn",date:"2026-09-26",time:"20:44",title:"เอฟเฟกต์ Flame Burst แบบใหม่",lines:["Flame Burst วาดใหม่ทั้งหมด: ระเบิดไฟลูกใหม่ปะทุรอบตัว พร้อมเศษไฟกระเด็นออกไป","มีวงไฟวิ่งออกไปบนพื้นจนถึงขอบระยะสกิลพอดี เห็นชัดว่าระเบิดโดนถึงไหน","ผู้เล่นคนอื่นเห็นเอฟเฟกต์ใหม่ด้วย ความแรงและผลของสกิลไม่ได้เปลี่ยน"],en:{title:"New Flame Burst effect",lines:["Flame Burst is fully redrawn: a new fireball erupts around the caster, with embers flying outward.","A ring of fire now spreads across the ground out to the exact skill range, so it's clear how far the blast reaches.","Other players see the new effect too. The skill's power and effect are unchanged."]}},{id:"2026-09-26-storage-window-redesign",date:"2026-09-26",time:"20:33",title:"หน้าต่างคลังเก็บของโฉมใหม่",lines:["คลังเก็บของวาดใหม่ทั้งหน้าต่าง แยกหมวดด้านซ้ายเป็น Etc. การ์ด ลูกธนู อาวุธ และชุดเกราะ พร้อมช่องค้นหาและปุ่มเรียงลำดับ","ฝากของโดยคลิกไอเทมในกระเป๋า ซึ่งจะเปิดขึ้นข้างคลังให้อัตโนมัติ","คลิกรายการในคลังเพื่อเลือกจำนวนที่จะนำออก Shift+คลิกนำออกทั้งกอง ส่วนอุปกรณ์คลิกครั้งเดียวนำออกเลย"],en:{title:"Storage window redesigned",lines:["Storage is fully redrawn, with categories on the left split into Etc., Cards, Ammo, Weapons and Armor, plus a search box and a sort button.","Deposit items by clicking them in your Inventory, which now opens automatically beside Storage.","Click an entry in Storage to choose how many to withdraw; Shift+click withdraws the whole stack, and equipment withdraws with a single click."]}},{id:"2026-09-26-iron-will-holy-guard-effects",date:"2026-09-26",time:"20:22",title:"เอฟเฟกต์ใหม่ให้สกิล Iron Will และ Holy Guard",lines:["Iron Will โล่เหล็กที่เด้งขึ้นหน้าตัวเป็นภาพวาดใหม่ มีหมุดย้ำและแสงสีเขียวรอบขอบ ออร่าสีเขียวที่อยู่ตลอดเวลาบัฟยังเหมือนเดิม","Holy Guard มีโดมพลังรูปหกเหลี่ยมสีทองฟ้าครอบตัวคนร่าย ตราโล่มีปีกเปล่งแสงเหนือหัว และวงแสงสีทองวิ่งออกไปถึงระยะที่สมาชิกปาร์ตี้ได้รับบัฟ","ผู้เล่นคนอื่นเห็นเอฟเฟกต์ใหม่ด้วย ความแรงและผลของสกิลไม่ได้เปลี่ยน"],en:{title:"New effects for Iron Will and Holy Guard",lines:["Iron Will's iron shield that pops up in front of the caster has a new design, with rivets and a green glow around the edge; the green aura that stays for the buff's whole duration is unchanged.","Holy Guard now surrounds the caster with a gold-and-blue hexagonal dome, a glowing winged shield emblem floats above their head, and a gold ring of light spreads out to the range where party members receive the buff.","Other players see the new effects too. The skills' power and effect are unchanged."]}},{id:"2026-09-26-card-slots-two-handed",date:"2026-09-26",time:"20:05",title:"การ์ดใส่ได้เฉพาะอุปกรณ์ชนิดเดียว และอาวุธสองมือ",lines:["การ์ดแต่ละใบใส่ได้อุปกรณ์ชนิดเดียว: การ์ดโจมตีใส่อาวุธ · การ์ด DEF ใส่โล่ · การ์ด HP/VIT ใส่ชุดเกราะ · การ์ด FLEE/MDEF ใส่ผ้าคลุม · การ์ด AGI/ความเร็ววิ่งใส่รองเท้า · การ์ด INT/SP ใส่หมวก · การ์ดสเตตัสใส่เครื่องประดับ ดูได้ในคำอธิบายการ์ด (ใส่ได้: ...)","หมวกทั้ง 3 ช่องใช้การ์ดหมวก แหวนทั้ง 2 วงใช้การ์ดเครื่องประดับ · หน้าฝังการ์ดแสดงเฉพาะอุปกรณ์ที่ใส่การ์ดใบนั้นได้","การ์ดที่ฝังไว้แล้วไม่ถูกถอด ยังอยู่และใช้ได้ตามเดิม กฎใหม่ใช้กับการฝังครั้งต่อไปเท่านั้น","Bow, Staff, Quarterstaff, Dagger Pair และ Hammer เป็นอาวุธสองมือ: ใส่โล่ไม่ได้ แต่ธนูยังใส่ quiver ได้ · สวมอาวุธสองมือแล้วโล่จะถูกถอดกลับเข้ากระเป๋าให้เอง ไม่หาย","อาวุธมือเดียว (Knife, Sword, Falchion, Blade, Rod, Viper Kunai) ใส่โล่ได้เหมือนเดิม"],en:{title:"Cards now match one equipment type, and two-handed weapons",lines:["Each card now sockets into only one equipment type: attack cards go in weapons · DEF cards go in shields · HP/VIT cards go in armor · FLEE/MDEF cards go in garments · AGI/run speed cards go in shoes · INT/SP cards go in hats · stat cards go in accessories. Check the card's description (Usable in: ...) to see which.","All 3 hat slots take hat cards, and both ring slots take accessory cards · the socketing window now shows only the equipment that card can go into.","Cards already socketed are not removed — they stay in place and keep working as before. The new rule only applies to the next socketing.","Bow, Staff, Quarterstaff, Dagger Pair and Hammer are now two-handed weapons: no shield can be equipped alongside them, though a bow can still take a quiver · equipping a two-handed weapon automatically unequips your shield back to your Inventory — it isn't lost.","One-handed weapons (Knife, Sword, Falchion, Blade, Rod, Viper Kunai) can still be equipped with a shield as before."]}},{id:"2026-09-26-stormbreak-radiant-light-effects",date:"2026-09-26",time:"20:00",title:"เอฟเฟกต์ใหม่ให้สกิล Stormbreak และ Radiant Light",lines:["Stormbreak มีวงเวทย์สายฟ้าสีม่วงขนาดเท่าระยะสกิลบนพื้น เมฆพายุก้อนใหม่ลอยอยู่ด้านบนและสว่างวาบทุกครั้งที่ฟ้าผ่า และจุดที่ฟ้าผ่าลงมีประกายไฟฟ้าแตกกระจาย","Radiant Light มีไม้กางเขนทองพร้อมรัศมีเปล่งแสงลอยขึ้นเหนือตัว และวงเวทย์ศักดิ์สิทธิ์สีทองบนพื้นเท่าระยะสกิล สายฟ้าสีทองยังฟาดลงเหมือนเดิม","ผู้เล่นคนอื่นเห็นเอฟเฟกต์ใหม่ด้วย ความแรงและผลของสกิลไม่ได้เปลี่ยน"],en:{title:"New effects for Stormbreak and Radiant Light",lines:["Stormbreak now draws a purple lightning circle on the ground sized to the skill range, a new storm cloud hovers above and flashes with every bolt, and each strike point sparks with scattering electricity.","Radiant Light now has a gold cross with a glowing halo rise above the caster, and a gold holy circle on the ground sized to the skill range; the gold lightning strike itself is unchanged.","Other players see the new effects too. The skills' power and effect are unchanged."]}},{id:"2026-09-26-bot-boss-portrait",date:"2026-09-26",time:"19:53",title:"รูปบอสในหน้าต่าง Auto Play ตรงกับตัวจริง",lines:["รายชื่อมอนสเตอร์ในหน้าต่าง Auto Play แสดงรูปบอสประจำแมพตามหน้าตาจริงของบอสแมพนั้น ไม่ใช่รูป Prism Hopper ทุกแมพอีกต่อไป"],en:{title:"Auto Play boss portraits now match the real boss",lines:["The monster list in the Auto Play window now shows each map's boss with its real appearance, instead of a Prism Hopper portrait for every map."]}},{id:"2026-09-26-ember-bolt-frost-area-effects",date:"2026-09-26",time:"19:50",title:"เอฟเฟกต์ใหม่ให้สกิล Ember Bolt และ Frost Area",lines:["Ember Bolt ลูกไฟแต่ละลูกที่ตกลงบนเป้าหมายจะระเบิดเป็นเปลวไฟลุกพรึ่บ แทนวงแสงเดิม","Frost Area มีวงเวทย์เกล็ดหิมะขนาดเท่าระยะสกิลกางออกบนพื้นแล้วหมุนช้า ๆ และแท่งน้ำแข็งที่ปักพื้นจะแตกเป็นผลึกน้ำแข็งกระจาย","ผู้เล่นคนอื่นเห็นเอฟเฟกต์ใหม่ด้วย ความแรงและผลของสกิลไม่ได้เปลี่ยน"],en:{title:"New effects for Ember Bolt and Frost Area",lines:["Each Ember Bolt fireball that lands on a target now bursts into a flare of flame, replacing the old ring of light.","Frost Area now unfolds a snowflake circle on the ground sized to the skill range that spins slowly, and the ice spike planted in the ground shatters into scattering ice crystals.","Other players see the new effects too. The skills' power and effect are unchanged."]}},{id:"2026-09-26-wiki-opens-in-browser",date:"2026-09-26",time:"19:46",title:"Wiki เปิดในเบราว์เซอร์ ไม่ทับหน้าเกม",lines:["กดลิงก์ Wiki จากหน้าตั้งค่าหรือหน้าล็อกอิน จะเปิด Wiki ในเบราว์เซอร์ปกติของเครื่อง เกมยังเปิดค้างอยู่ที่เดิม ไม่ถูกแทนที่ด้วยหน้า Wiki อีกต่อไป","แอปเดสก์ท็อปรุ่นถัดไปจะส่ง Wiki ไปเปิดในเบราว์เซอร์เสมอ"],en:{title:"Wiki opens in your browser, no longer over the game",lines:["Clicking the Wiki link from Settings or the login screen now opens the Wiki in your device's regular browser. The game stays open where it was, no longer replaced by the Wiki page.","The next desktop app update will always send the Wiki to open in a browser."]}},{id:"2026-09-26-gold-order-depth",date:"2026-09-26",time:"19:43",title:"ตลาด Gold แสดงความลึกตลาด",lines:["หน้าต่างตลาด Gold มีแผง ความลึกตลาด บอกว่ามี Gold รอซื้อขายสะสมอยู่เท่าไรใกล้ราคาดีสุด ฝั่งละ 3 ขั้น: ภายใน 5%, 10% และ 15%","ฝั่งซ้ายสีเขียวคือคำสั่งรับซื้อ นับลงจากราคารับซื้อสูงสุด ฝั่งขวาสีแดงคือคำสั่งขาย นับขึ้นจากราคาตั้งขายต่ำสุด แต่ละแถวบอกขอบราคาและจำนวน Gold รวม","แถบสีในแต่ละแถวยาวตามจำนวน Gold ใช้สเกลเดียวกันทั้งสองฝั่ง ดูได้ทันทีว่าฝั่งไหนหนากว่า ชี้ค้างที่แถวเพื่อดูมูลค่ารวมเป็น Silver"],en:{title:"Gold market shows market depth",lines:["The Gold market window has a Market Depth panel showing how much Gold is waiting to trade near the best price, in 3 steps per side: within 5%, 10% and 15%.","The green side on the left is buy orders, counting down from the highest bid; the red side on the right is sell orders, counting up from the lowest ask. Each row shows the price edge and the total Gold.","Each row's colored bar is scaled to its Gold amount, using the same scale on both sides, so you can see at a glance which side is thicker. Hover a row to see its total value in Silver."]}},{id:"2026-09-26-arrow-rain-twin-shot-effects",date:"2026-09-26",time:"19:40",title:"เอฟเฟกต์ใหม่ให้สกิล Arrow Rain และ Twin Shot",lines:["Arrow Rain ลูกธนูที่ตกลงมาเป็นลูกธนูขนนกสีเขียวเรืองแสงแบบใหม่ ปักพื้นแล้วมีแสงวาบตรงจุดที่ตก กรอบสี่เหลี่ยมบอกพื้นที่สกิลยังอยู่เหมือนเดิม","Twin Shot ยิงลูกธนูพลังงานสีทองสองดอกคู่กันพุ่งเข้าหาเป้าหมาย แต่ละดอกมีแสงระเบิดตอนโดน แทนลูกธนูเล็กดอกเดียวแบบเดิม","ผู้เล่นคนอื่นเห็นเอฟเฟกต์ใหม่ด้วย ความแรงและผลของสกิลไม่ได้เปลี่ยน"],en:{title:"New effects for Arrow Rain and Twin Shot",lines:["Arrow Rain's falling arrows are now new glowing green feathered arrows that flash where they land; the square outline marking the skill area is unchanged.","Twin Shot now fires a pair of gold energy arrows together at the target, each flashing on impact, replacing the old single small arrow.","Other players see the new effects too. The skills' power and effect are unchanged."]}},{id:"2026-09-26-weapon-properties-on-card",date:"2026-09-26",time:"19:34",title:"หน้าต่างไอเทมบอกคุณสมบัติอาวุธและโล่",lines:["อาวุธบอกระยะโจมตี (ประชิด หรือระยะไกลที่ ATK คิดจาก DEX) และ ASPD พื้นฐานของอาวุธนั้น เช่น Knife +2, Staff −10","โล่บอกว่าลด ASPD พื้นฐาน 8 ส่วนลูกธนูที่ใส่มือซ้ายไม่ลด","Knife และ Dagger Pair บอกว่าคริติคอล ×2 ขณะถือ","คำอธิบาย DEX บอกแล้วว่าเพิ่ม ATK ของคุไนด้วย และ FAQ บอกว่า Clip จากหีบให้ SP +15","ผลของอุปกรณ์ไม่ได้เปลี่ยน แก้เฉพาะคำอธิบายให้ตรงกับที่เป็นอยู่"],en:{title:"Item window lists weapon and shield properties",lines:["Weapons now show their attack range (melee, or ranged where ATK is based on DEX) and that weapon's base ASPD, e.g. Knife +2, Staff −10.","Shields now note that they reduce base ASPD by 8, while ammo equipped in the left hand does not.","Knife and Dagger Pair now note that critical damage is ×2 while wielded.","The DEX description now notes that it also increases kunai ATK, and the FAQ notes that a Clip from a chest gives SP +15.","Equipment effects are unchanged — only the descriptions were corrected to match how they already work."]}},{id:"2026-09-26-gold-exchange-window",date:"2026-09-26",time:"19:33",title:"ตลาด Gold มีปุ่มและหน้าต่างของตัวเอง",lines:["เพิ่มปุ่ม Gold ในแถบเมนู ถัดจากปุ่ม Shop กดแล้วเข้าหน้าต่างซื้อขาย Gold ได้ทันที ไม่ต้องเปิด Shop แล้วหาแท็บอีกต่อไป","หน้าต่างนี้มีครบ: กราฟราคาเฉลี่ย ซื้อ Gold ด้วย Silver ขาย Gold แลก Silver และรายการคำสั่งของฉัน พร้อมบอกยอด Gold และ Silver ที่มีอยู่","มุมซ้ายบนบอกว่าตอนนี้ซื้อขายได้ไหม: อยู่ใกล้นายหน้าตลาด, Premium ซื้อขายได้จากทุกที่ หรืออยู่นอกระยะ","ปุ่ม ตลาด Gold ใน Shop ยังกดได้ และจะพามาที่หน้าต่างใหม่นี้ ส่วนลิงก์ท้ายหน้าต่างพาไปเติม Gold ใน Shop","ปุ่ม PVP ย้ายเข้าไปอยู่ในเมนู ☰ เพื่อให้แถวเมนูไม่ยาวจนปุ่มสกิลไปซ่อนหลังการ์ดตัวละครบนมือถือจอแคบ","กติกาการซื้อขายเหมือนเดิม ไม่มีค่าธรรมเนียมและไม่หักภาษี"],en:{title:"Gold market gets its own button and window",lines:["Added a Gold button in the menu bar next to the Shop button; press it to go straight into the Gold trading window, no longer needing to open Shop and find a tab.","This window has everything: an average price chart, buying Gold with Silver, selling Gold for Silver, and a My Orders list, plus your current Gold and Silver totals.","The top-left corner shows whether you can trade right now: near a market broker, Premium can trade from anywhere, or out of range.","The Gold Market button in Shop still works and now opens this new window, while the link at the bottom of the window takes you to buy Gold in Shop.","The PVP button moved into the ☰ menu so the menu row doesn't grow long enough to hide skill buttons behind the character card on narrow mobile screens.","Trading rules are unchanged: no fees and no tax."]}},{id:"2026-09-26-loot-rabbit-faster",date:"2026-09-26",time:"19:32",title:"กระต่ายเก็บของเร็วขึ้น",lines:["กระต่ายวิ่งเร็วขึ้นเกือบเท่าตัว และก้มเก็บของแต่ละกองเร็วขึ้น เก็บเสร็จแล้ววิ่งไปกองถัดไปทันที","ระยะเก็บของรอบตัวเจ้าของกว้างขึ้นจาก 360 เป็น 480 พิกเซล ตีมอนตายไวแล้วเดินไปตัวต่อไป กระต่ายก็ยังตามเก็บของที่ตัวก่อนทัน"],en:{title:"Loot rabbit collects faster",lines:["The loot rabbit now runs almost twice as fast and picks up each pile of loot quicker, running straight to the next pile as soon as it's done.","Its pickup radius around its owner is now wider, from 360 to 480 pixels, so even if you kill a monster quickly and move on to the next, the rabbit can still catch up on the loot from the last one."]}},{id:"2026-09-26-cart-strike-twin-strike-effects",date:"2026-09-26",time:"19:30",title:"เอฟเฟกต์ใหม่ให้สกิล Cart Strike และ Twin Strike",lines:["Cart Strike พ่อค้าเหวี่ยงรถเข็นเรืองแสงวนรอบตัวหนึ่งรอบ แล้วกระแทกพื้นเป็นคลื่นกระแทกออกไปถึงขอบระยะสกิล พร้อมเหรียญทองกระเด็นออกมา","Twin Strike (พาสซีฟโจมตีสองครั้งของ Thief) ทุกครั้งที่ตีเข้าสองครั้ง จะมีรอยฟันมีดสีแดงสองเส้นไขว้กันเป็นรูปกากบาทบนตัวเป้าหมาย","ผู้เล่นคนอื่นเห็นเอฟเฟกต์ใหม่ด้วย ความแรงและผลของสกิลไม่ได้เปลี่ยน"],en:{title:"New effects for Cart Strike and Twin Strike",lines:["Cart Strike now has the merchant swing a glowing cart around themselves once, then slam it into the ground for a shockwave that spreads to the edge of the skill range, with gold coins flying out.","Twin Strike (the Thief's double-hit passive) now shows two crossed red slash marks on the target every time both hits land.","Other players see the new effects too. The skills' power and effect are unchanged."]}},{id:"2026-09-26-bag-gear-types",date:"2026-09-26",time:"19:27",title:"กรองอุปกรณ์ในกระเป๋าตามประเภท",lines:["แท็บ Equipment ในกระเป๋ามีปุ่มกรองประเภท: อาวุธ · โล่ · ลูกธนู · หมวก · เกราะ · ผ้าคลุม · รองเท้า · เครื่องประดับ","หมวกรวมของสวมศีรษะทั้งบน กลาง และล่าง ส่วนเครื่องประดับรวมแหวนและกิ๊บทั้งสองช่อง","กดช่องว่างบนตัวละครเพื่อเปิดกระเป๋า จะกรองเฉพาะของที่ใส่ช่องนั้นได้ให้ทันที"],en:{title:"Filter Inventory equipment by type",lines:["The Equipment tab in Inventory now has type filter buttons: Weapon · Shield · Ammo · Hat · Armor · Garment · Shoes · Accessory.","Hat covers all upper, middle and lower head slots, and Accessory covers both ring and clip slots.","Clicking an empty slot on your character to open Inventory now filters straight to items that fit that slot."]}},{id:"2026-09-26-aura-left-behind",date:"2026-09-26",time:"19:24",title:"แก้แสงออร่าค้างอยู่กลางแผนที่",lines:["แก้บัคแสงออร่าอาวุธตีบวกและออร่าเลเวลตันของผู้เล่นคนอื่นบางครั้งค้างเป็นเงาเรืองแสงอยู่จุดเดิม ทั้งที่ตัวละครเดินไปแล้วหรือถอดอุปกรณ์ไปแล้ว","ตอนนี้ออร่าจะแสดงเฉพาะตอนเห็นตัวละครจริงบนจอ"],en:{title:"Fixed aura light stuck on the map",lines:["Fixed a bug where other players' refined-weapon aura and max-level aura could sometimes stay behind as a glowing afterimage in the same spot, even after the character had moved away or unequipped the item.","Auras now only show while the actual character is visible on screen."]}},{id:"2026-09-26-protection-stone-bundles",date:"2026-09-26",time:"19:00",title:"โปรโมชั่น Protection Stone แบบแพ็ก",lines:["Item Mall ขาย Protection Stone เป็นแพ็กเหมือน EXP Scroll: 1 ก้อน 100 Gold · 5 ก้อน 450 Gold (-10%) · 10 ก้อน 800 Gold (-20%)","แก้คำอธิบายในร้านให้ตรงกับของจริง: หินกันแตกถูกหักเฉพาะเมื่อตีบวกล้มเหลว ตีบวกสำเร็จไม่เสียหิน"],en:{title:"Protection Stone bundle deals",lines:["The Item Mall now sells Protection Stone in bundles like EXP Scroll: 1 for 100 Gold · 5 for 450 Gold (-10%) · 10 for 800 Gold (-20%).","Fixed the shop description to match how it actually works: a Protection Stone is only consumed when a refine fails; a successful refine doesn't spend one."]}},{id:"2026-09-26-divine-boon-quake-hammer-effects",date:"2026-09-26",time:"18:55",title:"เอฟเฟกต์ใหม่ให้สกิล Divine Boon และ Quake Hammer",lines:["Divine Boon มีสัญลักษณ์ปีกสีทองเปล่งแสงเหนือหัวคนที่ได้รับพร พร้อมขนนกสีขาวร่วงลงมารอบตัว","Quake Hammer มีค้อนทองยักษ์ทุบลงพื้นจนแตกเป็นหลุม แล้วทุกฮิตจะมีคลื่นกระแทกวิ่งออกไปถึงขอบระยะสกิล","ผู้เล่นคนอื่นเห็นเอฟเฟกต์ใหม่ด้วย ความแรงและผลของสกิลไม่ได้เปลี่ยน"],en:{title:"New effects for Divine Boon and Quake Hammer",lines:["Divine Boon now shows a glowing gold wing emblem above the head of whoever receives the blessing, with white feathers drifting down around them.","Quake Hammer now has a giant gold hammer smash the ground into a crater, with a shockwave spreading to the edge of the skill range on every hit.","Other players see the new effects too. The skills' power and effect are unchanged."]}},{id:"2026-09-26-power-strike-heal-effects",date:"2026-09-26",time:"18:42",title:"เอฟเฟกต์ใหม่ให้สกิล Power Strike และ Heal",lines:["Power Strike มีรอยฟันดาบสีทองพาดผ่านตัวเป้าหมาย พร้อมแสงวาบและประกายไฟตรงจุดที่ฟันโดน แทนวงกลมสีเดิม","Heal มีวงเวทย์รักษาสีเขียวเปิดขึ้นที่เท้า แล้วมีเสาแสงสีเขียวพุ่งขึ้นผ่านตัวคนที่ถูกรักษา","ผู้เล่นคนอื่นเห็นเอฟเฟกต์ใหม่ด้วย ความแรงและผลของสกิลไม่ได้เปลี่ยน"],en:{title:"New effects for Power Strike and Heal",lines:["Power Strike now shows a gold slash mark across the target, with a flash and sparks at the point of impact, replacing the old colored circle.","Heal now opens a green healing circle at the target's feet, with a pillar of green light rising up through whoever is healed.","Other players see the new effects too. The skills' power and effect are unchanged."]}},{id:"2026-09-26-card-rules-on-card",date:"2026-09-26",time:"18:40",title:"คำอธิบายการ์ดบอกเงื่อนไขครบ",lines:["ค่าพิเศษบนการ์ดบอกเพดานรวมไว้ในวงเล็บ เช่น เจาะกาย +10% (รวมสูงสุด 60%) ดูดเลือด 8% โจมตีติดแข็ง 15% ATK% / MATK% 30% กันสตัน / กันแข็ง 80% ความเร็ววิ่ง 30% (นับรวม Fleet Foot)","การ์ด FLEE บอกว่า FLEE จากอุปกรณ์และการ์ดช่วยหลบมอนสเตอร์รวมได้ไม่เกิน 20%","การ์ด MDEF บอกว่า MDEF ลดเฉพาะดาเมจเวท เช่นสกิลธาตุของมอนสเตอร์ ไม่ลดการตีปกติ","การ์ดดูดเลือดบอกว่าฟื้นไม่เกิน 10% ของ MaxHP ต่อครั้ง และการ์ดติดแข็งบอกว่าติดเฉพาะการโจมตีปกติ บอสไม่ติด","ผลของการ์ดไม่ได้เปลี่ยน แก้เฉพาะคำอธิบายให้ตรงกับที่เป็นอยู่"],en:{title:"Card descriptions now list every condition",lines:["Special values on cards now show their combined cap in parentheses, e.g. Pierce +10% (60% combined max), Lifesteal 8%, Attack Freeze 15%, ATK% / MATK% 30%, Stun/Freeze Resist 80%, Run Speed 30% (counts Fleet Foot).","FLEE cards now note that FLEE from equipment and cards combined can reduce a monster's hit chance by at most 20%.","MDEF cards now note that MDEF only reduces magic damage, such as a monster's elemental skills, not basic attacks.","Lifesteal cards now note that they heal at most 10% of MaxHP per hit, and Freeze-on-hit cards note that they only trigger on basic attacks and never on bosses.","Card effects are unchanged — only the descriptions were corrected to match how they already work."]}},{id:"2026-09-26-gold-orders-clearer",date:"2026-09-26",time:"18:31",title:"รายการ คำสั่งของฉัน ในตลาด Gold อ่านง่ายขึ้น",lines:["แต่ละคำสั่งบอกตรง ๆ ว่าได้ Gold (หรือ Silver) ไปแล้วเท่าไร เหลืออีกเท่าไร แทนตัวเลข 4,000 / 4,000 ที่ดูเหมือนครบแล้ว ของที่ได้จากคำสั่งที่ตั้งไว้ส่งเข้าจดหมาย","บอกจำนวน Silver หรือ Gold ที่ถูกกันไว้กับคำสั่งนั้น ยกเลิกเมื่อไรก็ได้คืนเต็มจำนวนที่เหลือ","ถ้าราคาที่ตั้งยังห่างจากราคาตลาด จะบอกราคาคนขายถูกสุด (หรือคนรับซื้อสูงสุด) ตอนนี้ และว่าคำสั่งรอจับคู่อยู่","ปุ่ม ยกเลิก แยกออกมาชัดเจนและต้องกดยืนยันอีกครั้ง แตะแถวพลาดแล้วคำสั่งไม่หายไปเอง"],en:{title:"My Orders in the Gold market is easier to read",lines:["Each order now states plainly how much Gold (or Silver) it has filled and how much is left, instead of showing 4,000 / 4,000 that looks already complete. Gold or Silver received from a standing order is delivered by mail.","It shows the amount of Silver or Gold reserved for that order; canceling it at any time returns the full remaining amount.","If your set price is still far from the market price, it shows the current lowest ask (or highest bid) and notes that the order is waiting to be matched.","The Cancel button is now clearly separated and needs a second confirmation, so a stray tap on the row no longer cancels the order."]}},{id:"2026-09-26-aspd-potion-real-gain",date:"2026-09-26",time:"17:14",title:"คำอธิบายยา ASPD ตรงกับที่ได้จริง",lines:["ยา ASPD ให้ +3 / +4 / +5 เต็มเฉพาะตอน ASPD ยังไม่ถึง 180 ส่วนที่ทำให้เกิน 180 ได้ครึ่งเดียว และ ASPD สูงสุดที่ 193 คำอธิบายยาและบัฟบอกกติกานี้แล้ว","ตอนดื่มยา ข้อความจะบอก ASPD ที่ตัวละครได้เพิ่มจริง เช่น ASPD 178 ดื่ม Berserk Potion จะขึ้นว่า ASPD +3.3 ไม่ใช่ +5","ผลของยาไม่ได้เปลี่ยน แก้เฉพาะคำอธิบายให้ตรงกับที่เป็นอยู่"],en:{title:"ASPD potion descriptions match what you actually get",lines:["ASPD potions grant their full +3 / +4 / +5 only while ASPD is under 180; the portion that would push it past 180 is halved, and ASPD caps at 193. The potion and buff descriptions now state this rule.","When you drink a potion, the message now shows the ASPD you actually gained — e.g. at ASPD 178, drinking a Berserk Potion shows ASPD +3.3, not +5.","Potion effects are unchanged — only the descriptions were corrected to match how they already work."]}},{id:"2026-09-26-level-cap-120",date:"2026-09-26",time:"16:53",title:"ขยายเลเวลสูงสุดเป็น Lv.120 และปรับตาราง EXP",lines:["Base Level สูงสุดเพิ่มจาก 99 เป็น 120","Lv.1–89 ใช้ EXP เท่าเดิม ช่วง Lv.90–110 ใช้ EXP น้อยลงและเพิ่มขึ้นเลเวลละ 10% ส่วนช่วงที่ EXP พุ่งแรงตอนท้ายย้ายจาก Lv.90–99 ไปอยู่ที่ Lv.111–120 แทน ขั้นสุดท้าย Lv.119→120 ใช้ 1,850 ล้าน ดูตัวเลขครบทุกเลเวลได้ในตาราง EXP","ตัวละคร Lv.90 ขึ้นไปจะได้เลเวลคิดใหม่จาก EXP ที่เก็บมาทั้งหมดตอนเข้าเกมครั้งถัดไป ไม่มีใครเสีย EXP หรือเลเวล เช่น Lv.99 จะกลายเป็น Lv.107 และได้แต้มสถานะของเลเวลที่เพิ่มขึ้นครบ","ออร่าทองย้ายไปเป็นของผู้เล่นเลเวลสูงสุด Lv.120 แทน Lv.99","ค่าสถานะแต่ละตัวยังตันที่ 99 เหมือนเดิม"],en:{title:"Level cap raised to Lv.120, EXP table adjusted",lines:["Max Base Level is raised from 99 to 120.","Lv.1–89 use the same EXP as before. Lv.90–110 now needs less EXP, rising 10% per level, and the steep late-game EXP curve has moved from Lv.90–99 to Lv.111–120 instead. The final step, Lv.119→120, needs 1.85 billion. See the EXP table for every level's number.","Characters Lv.90 and above will have their level recalculated from all their stored EXP the next time they log in. Nobody loses EXP or a level — for example, Lv.99 becomes Lv.107, and gains the full status points for every level added.","The gold aura now belongs to players at the max level, Lv.120, instead of Lv.99.","Each individual stat still caps at 99, as before."]}},{id:"2026-09-26-named-gear-icons",date:"2026-09-26",time:"16:00",title:"ไอคอนใหม่ให้หมวก โล่ ผ้าคลุม และกิ๊บ",lines:["อุปกรณ์ 8 ชิ้นที่เคยใช้รูปเดียวกันมีไอคอนของตัวเองแล้ว: Guard, Buckler, Hood, Muffler, Hat, Cap, Helm และ Clip","Guard เป็นโล่ไม้ทรงเหลี่ยม Buckler เป็นโล่เหล็กกลม Hood เป็นผ้าคลุมมีฮู้ด Muffler เป็นผ้าพันคอลายทาง","Hat เป็นหมวกผ้า Cap เป็นหมวกแก๊ป Helm เป็นหมวกเกราะเหล็ก และ Clip เป็นกิ๊บติดผมประดับอัญมณี","เห็นรูปใหม่ในกระเป๋า หน้าต่างอุปกรณ์ ร้านค้า ตลาด และ Wiki ส่วนอุปกรณ์ดรอปที่ไม่มีชื่อเฉพาะยังใช้รูปเดิม"],en:{title:"New icons for hats, shields, garments and clips",lines:["8 items that used to share one icon now each have their own: Guard, Buckler, Hood, Muffler, Hat, Cap, Helm and Clip.","Guard is a square wooden shield, Buckler is a round steel shield, Hood is a hooded garment, and Muffler is a striped scarf.","Hat is a cloth hat, Cap is a baseball cap, Helm is a steel helmet, and Clip is a jeweled hairpin.","The new icons show up in Inventory, the equipment window, the shop, the market and the Wiki; dropped equipment without a specific name still uses the old icon."]}},{id:"2026-09-26-premium-carries-to-launch",date:"2026-09-26",time:"15:26",title:"วัน Premium ยกไปใช้ต่อได้ตอนเปิดเซิร์ฟเวอร์จริง",lines:["วันเปิดเซิร์ฟเวอร์จริง ตัวละคร ไอเทม Silver และ Gold ยังถูกล้างทั้งหมดเหมือนเดิม แต่วัน Premium ที่ยังเหลือจะไม่หาย","ระบบจะนับวัน Premium ที่เหลือตอนล้างข้อมูล ปัดขึ้นเป็นวันเต็ม แล้วส่งให้บัญชีเดิมทางกล่องจดหมาย","วันจะหยุดนับไว้จนกว่าจะกดรับจดหมาย และจดหมายนี้ไม่มีวันหมดอายุ ซื้อ Premium รายปีตอนนี้ได้โดยไม่ต้องกลัววันหาย","Gold ที่ยังไม่ได้ใช้ไม่ยกไป และข้อตกลงการใช้บริการกับนโยบายการคืนเงินปรับข้อความตามนี้แล้ว"],en:{title:"Premium days carry over into live launch",lines:["On launch day, characters, items, Silver and Gold will still all be wiped as planned, but any remaining Premium days will not be lost.","The system will count your remaining Premium days at wipe time, round up to a full day, and deliver them to your existing account by mail.","The days stop counting down until you claim the mail, and this mail never expires — you can buy a yearly Premium subscription now without worrying about losing days.","Unused Gold does not carry over, and the Terms of Service and Refund Policy have been updated to reflect this."]}},{id:"2026-09-26-three-new-realms",date:"2026-09-26",time:"15:19",title:"แมพใหม่ 3 แห่ง Lv.200–270",lines:["ทุ่งหมอกวิญญาณ Gloomveil Moor Lv.200–220 — เดินขึ้นทางแยกเหนือของหนองน้ำ มีบึงดำ หลุมศพ และหมอกวิญญาณ","โพรงคริสตัล Amethyst Hollows Lv.225–245 — เดินตามทางใต้สุดของป่าเริ่มต้น มีผลึกอเมทิสต์และบ่อพลังเวท","ยอดเขาพายุ Stormcrest Peaks Lv.250–270 — เดินขึ้นเหนือสุดของช่องเขาหิมะ มีหุบเหวและพายุฟ้าคะนอง","มอนสเตอร์ใหม่ 12 ชนิด แต่ละแมพแกร่งขึ้นจากแมพก่อนทีละนิด และไล่โจมตีทันทีที่เห็นผู้เล่น พร้อมบอสประจำแมพ Lv.230 / 255 / 280","บึง บ่อพลังเวท และหุบเหวเดินผ่านไม่ได้ มอนใหม่ทุกตัวมีการ์ดประจำตัว และแผนที่โลกมีเกาะใหม่ 3 เกาะ"],en:{title:"3 new maps, Lv.200–270",lines:["Gloomveil Moor, Lv.200–220 — take the north fork out of Mirewillow Marsh; a land of black bogs, graves and spirit mist.","Amethyst Hollows, Lv.225–245 — follow the path from the far south of Verdant Forest; home to amethyst crystals and pools of arcane energy.","Stormcrest Peaks, Lv.250–270 — head to the far north of Frostveil Pass; ravines and thunderstorms await.","12 new monsters, each map a little tougher than the last, and all aggro on sight, plus a map boss at Lv.230 / 255 / 280.","Bogs, arcane pools and ravines are impassable. Every new monster has its own card, and the World Map now shows 3 new islands."]}},{id:"2026-09-26-whisper-unread-badge",date:"2026-09-26",time:"15:14",title:"แจ้งเตือนเมื่อมีคนกระซิบหา",lines:["แท็บ กระซิบ ในแชทมีป้ายตัวเลขสีแดงบอกจำนวนข้อความกระซิบที่ยังไม่ได้อ่าน ตอนพับแชทไว้ ป้ายจะขึ้นที่ปุ่มแชทแทน","มีกล่องแจ้งเตือนเด้งขึ้นเหนือแชท บอกว่าใครกระซิบมาพร้อมข้อความ กด ตอบกลับ เพื่อตอบได้ทันที","มีเสียงเตือนเบา ๆ ตอนมีคนกระซิบมา ปิดได้ที่ ตั้งค่า > เสียง > กระซิบ","บน PC ชื่อแท็บเบราว์เซอร์จะมีตัวเลขนำหน้า เห็นได้แม้สลับไปหน้าอื่น","ตัวเลขหายเมื่อเปิดแท็บ กระซิบ หรือตอบกลับ"],en:{title:"Notifications for incoming whispers",lines:["The Whisper tab in chat now shows a red number badge for unread whisper messages; when chat is collapsed, the badge appears on the chat button instead.","A notification popup now appears above chat showing who whispered and their message; press Reply to answer right away.","A soft chime plays when someone whispers to you; turn it off under Settings > Sound > Whisper.","On PC, the browser tab title now shows a leading number, visible even after switching to another tab.","The number clears when you open the Whisper tab or reply."]}},{id:"2026-09-26-friend-request-hover-fix",date:"2026-09-26",time:"14:50",title:"แก้ปุ่มหน้าต่างคำขอเป็นเพื่อน",lines:["ชี้เมาส์ที่ปุ่ม รับเป็นเพื่อน ไว้ทีหลัง หรือ ปฏิเสธ แล้วรูปปุ่มไม่ขยายล้นกรอบอีก ปุ่มแค่สว่างขึ้นเล็กน้อย"],en:{title:"Fixed friend request window buttons",lines:["Hovering the Accept for later or Decline buttons no longer makes them grow past their frame — they just brighten slightly."]}},{id:"2026-09-26-emberfall-caldera",date:"2026-09-26",time:"14:34",title:"แมพใหม่: ปล่องภูเขาไฟ Emberfall Caldera Lv.175–195",lines:["เกาะภูเขาไฟแห่งใหม่ทางตะวันออกของทะเลทราย Sunscar เดินตามทางใหม่ไปขอบตะวันออกของทะเลทรายเพื่อข้ามไปได้เลย","มอนสเตอร์ใหม่ 4 ชนิด Lv.175–195 แกร่งกว่าธารน้ำแข็งขึ้นอีกขั้น: Magma Salamander, Ember Hound, Basalt Tortoise และ Obsidian Scorpion — ทุกตัวไล่โจมตีทันทีที่เห็นผู้เล่น","บอสประจำแมพ Crowned Obsidian Scorpion Lv.205","ทะเลสาบลาวากลางปล่องและบ่อลาวารอบแมพเดินผ่านไม่ได้ ใช้ทางเถ้าที่วนรอบปล่องแทน","มอนใหม่ทุกตัวมีการ์ดประจำตัว และแผนที่โลกมีเกาะภูเขาไฟเพิ่มขึ้นมา"],en:{title:"New map: Emberfall Caldera, Lv.175–195",lines:["A new volcanic island east of Sunscar Desert — follow the new path to the desert's eastern edge to cross over.","4 new monsters, Lv.175–195, a step tougher than Frostfang Glacier: Magma Salamander, Ember Hound, Basalt Tortoise and Obsidian Scorpion — all aggro on sight.","Map boss: Crowned Obsidian Scorpion, Lv.205.","The lava lake at the caldera's center and the lava pools around the map are impassable — use the ash path that circles the caldera instead.","Every new monster has its own card, and the World Map now shows the new volcanic island."]}},{id:"2026-09-26-login-finds-latest-copy",date:"2026-09-26",time:"14:34",title:"ล็อกอินหาตัวละครล่าสุดแม่นขึ้น",lines:["แก้กรณีที่ล็อกอินช่วงเซิร์ฟเวอร์หนักแล้วถูกพาไปเล่นข้อมูลตัวละครชุดเก่า (เลเวลหรือของย้อนกลับ) ตอนนี้ระบบจะไม่ยอมให้เข้าข้อมูลชุดเก่า แต่จะให้รอสักครู่แล้วต่อใหม่จนเจอชุดล่าสุด",'เซิร์ฟเวอร์หาตำแหน่งตัวละครได้เร็วขึ้นและเบาลง ช่วงหลังรีสตาร์ทควรติด "กำลังตรวจสอบข้อมูลตัวละคร" น้อยลง'],en:{title:"Login now finds your latest save more accurately",lines:["Fixed a case where logging in during heavy server load could load an old copy of your character (level or items reverted). The system now refuses to load stale data, instead waiting a moment and retrying until it finds the latest copy.",'The server now locates characters faster and with less load, so you should see "Checking your character data" less often right after a restart.']}},{id:"2026-09-26-starter-pack-destroy",date:"2026-09-26",time:"14:27",title:"ทำลายอุปกรณ์ Starter Pack ได้",lines:["อุปกรณ์จาก Starter Pack กดทำลายในกระเป๋าได้แล้ว เมื่อไม่ได้สวมใส่อยู่ ใช้เคลียร์ชิ้นที่ไม่ใช้ออกจากกระเป๋า","ยังทิ้งลงพื้น ขาย หรือเทรดให้คนอื่นไม่ได้เหมือนเดิม และทำลายแล้วเอาคืนไม่ได้"],en:{title:"Starter Pack gear can now be destroyed",lines:["Equipment from the Starter Pack can now be destroyed from Inventory while unequipped, letting you clear out pieces you don't use.","It still can't be dropped, sold or traded to others, and destroying it cannot be undone."]}},{id:"2026-09-26-haste-keeps-on-death",date:"2026-09-26",time:"07:11",title:"ยาเร่ง ASPD ไม่หายตอนตาย",lines:["บัฟเร่งความเร็วจากยา ASPD อยู่ต่อจนหมดเวลาแม้ตัวละครตาย เหมือนม้วน EXP และ Drop ไม่ต้องดื่มใหม่หลังฟื้น"],en:{title:"ASPD haste survives death",lines:["The speed buff from an ASPD potion now keeps counting down until it expires even if your character dies, just like EXP and Drop scrolls — no need to redrink after respawning."]}},{id:"2026-09-26-refined-weapon-aura",date:"2026-09-26",time:"06:53",title:"ออร่าอาวุธตีบวก",lines:["สวมอาวุธตีบวกตั้งแต่ +7 ขึ้นไป ตัวละครจะมีแสงเรืองรอบตัวและประกายลอยขึ้นฝั่งที่ถืออาวุธ ผู้เล่นคนอื่นเห็นด้วย","สีตามระดับ: +7–8 สีฟ้า · +9 สีม่วง · +10 สีทอง","ตั้งค่า ผู้เล่นคนอื่น เป็น ซ่อนชื่อและเอฟเฟกต์ เพื่อซ่อนออร่าของคนอื่นได้ และในที่คนเยอะจะแสดงเฉพาะคนที่อยู่ใกล้"],en:{title:"Refined weapon aura",lines:["Equipping a weapon refined to +7 or higher now gives your character a glow and rising sparkles on the side holding the weapon, visible to other players too.","Color depends on refine level: +7–8 blue · +9 purple · +10 gold.","Set Other Players to Hide names and effects to hide other players' auras, and in crowded areas only nearby players will show one."]}},{id:"2026-09-26-storage-withdraw-picker-visible",date:"2026-09-26",time:"06:54",title:"แก้ถอนของจากคลังบนมือถือแนวนอน",lines:["กดไอเทมในคลังแล้ว หน้าต่างเลือกจำนวนจะเลื่อนขึ้นมาให้เห็นทันที ไม่ไปซ่อนอยู่ใต้ปุ่มนำอุปกรณ์ออกทั้งหมดจนดูเหมือนกดไม่ติด"],en:{title:"Fixed Storage withdraw picker on landscape mobile",lines:["Tapping an item in Storage now slides the quantity picker into view immediately, instead of hiding it beneath the Withdraw All button where taps seemed to do nothing."]}},{id:"2026-09-26-relic-box-icon",date:"2026-09-26",time:"06:51",title:"ไอคอน Mystery Relic Box ใหม่",lines:["วาดไอคอน Mystery Relic Box ใหม่เป็นหีบไม้ขอบทองที่มีแม่กุญแจรูปเครื่องหมายคำถามเรืองแสงสีม่วง ใช้ลายเส้นแบบเดียวกับไอคอนยาแดง"],en:{title:"New Mystery Relic Box icon",lines:["Redrew the Mystery Relic Box icon as a gold-trimmed wooden chest with a padlock shaped like a glowing purple question mark, using the same line style as the Red Potion icon."]}},{id:"2026-09-26-explorer-gold-exchange",date:"2026-09-26",time:"06:25",title:"Explorer: หน้าตลาด Gold แบบกระดานเทรด",lines:["เพิ่มแท็บ ตลาด Gold ในหน้า Explorer ดูราคา Gold เทียบ Silver ได้แบบเดียวกับกระดานเทรดคริปโต","มีกราฟแท่งเทียนเลือกช่วงเวลา 15 นาที ถึง 1 วัน พร้อมเส้นค่าเฉลี่ยและปริมาณซื้อขาย และกราฟความลึกตลาด","แสดงสมุดคำสั่งซื้อขาย ส่วนต่างราคา สถิติ 24 ชั่วโมง และประวัติการซื้อขายล่าสุดพร้อมชื่อผู้ซื้อและผู้ขาย","ข้อมูลอัปเดตทันทีเมื่อมีคำสั่งใหม่หรือจับคู่สำเร็จ ไม่ต้องรีเฟรชหน้า"],en:{title:"Explorer: Gold market gets a trading-board page",lines:["Added a Gold Market tab to the Explorer page, showing the Gold-to-Silver price the same way a crypto trading board does.","It has a candlestick chart with time ranges from 15 minutes to 1 day, a moving average line, trading volume, and a market depth chart.","It shows the order book, the bid-ask spread, 24-hour stats, and recent trade history with buyer and seller names.","Data updates instantly on a new order or a successful match, with no need to refresh the page."]}},{id:"2026-09-26-login-stale-copy-lineage",date:"2026-09-26",time:"06:14",title:"กันข้อมูลตัวละครย้อนตอนล็อกอิน",lines:["ถ้าเซิร์ฟเวอร์มีสำเนาตัวละครเก่าค้างอยู่ (เลเวลและจำนวนฆ่าเท่ากัน แต่ยังไม่มีการเทรด ตีบวก หรือซื้อขายล่าสุด) ระบบจะพาไปเข้าสำเนาล่าสุดแทน ไอเทมและเงินไม่ย้อนกลับ"],en:{title:"Prevented stale character data on login",lines:["If the server has a lingering older copy of your character (same level and kill count, but no recent trades, refines or market activity), the system now loads the latest copy instead — items and currency are never reverted."]}},{id:"2026-09-26-profile-card-compact",date:"2026-09-26",time:"06:10",title:"ปรับการ์ดข้อมูลตัวละครใหม่",lines:["การ์ดมุมซ้ายบนเล็กลงและกะทัดรัดขึ้น แสดงรูปตัวละครในกรอบวงกลม ชื่อ เลเวล อาชีพ และแถบ HP / SP แบบใหม่ ยาวเท่ากัน มีตัวเลขอยู่กลางแถบ","EXP และ Job Lv รวมอยู่แถวล่างแถวเดียว แสดงเป็นเปอร์เซ็นต์ ชี้ค้างเพื่อดูตัวเลขเต็ม","Silver และน้ำหนักดูได้ในกระเป๋า"],en:{title:"Character info card redesigned",lines:["The top-left card is now smaller and more compact, showing your character portrait in a circular frame, name, level, class, and new HP / SP bars of equal length with the numbers centered in each bar.","EXP and Job Lv are combined into one row at the bottom, shown as a percentage — hover to see the exact numbers.","Silver and weight can now be checked in Inventory."]}},{id:"2026-09-26-enemy-status-icons",date:"2026-09-26",time:"05:57",title:"แสดงไอคอนบัฟและดีบัฟเหนือหัวศัตรู",lines:["มอนสเตอร์ที่ติดสถานะ เช่น เผาไหม้ สตัน แช่แข็ง พิษ หรือถูกยั่วยุ จะมีไอคอนเรียงอยู่เหนือหัวให้เห็นทันที","พิษงูแสดงจำนวนชั้นที่ซ้อนอยู่บนไอคอน","ในสนาม PVP และตอนดวล ผู้เล่นฝั่งตรงข้ามก็แสดงบัฟและดีบัฟที่ติดอยู่เหนือหัวเช่นกัน","กรอบสีเขียวคือบัฟ กรอบสีม่วงคือดีบัฟ"],en:{title:"Enemy buff and debuff icons above their heads",lines:["Monsters affected by a status — such as Burn, Stun, Freeze, Poison, or Taunted — now show a row of icons above their heads right away.","Snake venom shows its stack count on the icon.","In the PVP arena and during duels, the opposing player's active buffs and debuffs are shown above their head too.","A green border marks a buff; a purple border marks a debuff."]}},{id:"2026-09-26-skills-match-tooltips",date:"2026-09-26",time:"05:55",title:"สกิลทำงานตรงตามคำอธิบาย",lines:["สถานะผิดปกติที่ติดซ้ำใช้ค่าของสกิลที่ติดล่าสุดเท่านั้น เช่น ตาพร่าจาก Shadow Burst ลด Hit และ ASPD 25% ครบแม้เคยโดน Radiant Light มาก่อน และแช่แข็งจากอุปกรณ์ไม่ติดโบนัสดาเมจเวทของ Frost Area","สถานะที่สั้นกว่าจะไม่ทับให้สถานะเดิมที่ยังเหลือนานกว่าหมดเร็วขึ้น เช่น สตัน 1.7 วินาทีของ Stormbreak ไม่ตัดสตัน 2.5 วินาทีของ Power Strike","มอนสเตอร์ที่ติดตาพร่าร่ายสกิลธาตุพลาดได้และร่ายช้าลงตามคำอธิบาย","ใน PVP: Blade Mastery, Predator's Patience, Twin Strike, Dokunuri, คริติคอลของ Fatal Sense, ฮิตต่อเนื่องของ Radiant Light, การกระเด็นของ Cart Strike และ Leap Shot และ Perfect Dodge ของ Fleet Foot มีผลเหมือนตอนสู้มอนสเตอร์","คำอธิบายสกิลบอกชัดว่าบอสโลกไม่ติดสตัน แช่แข็ง กระเด็น และการยั่วยุ ส่วนไฟไหม้และพิษบอสโลกรับ 1/10","แก้คำอธิบาย Divine Boon ให้ระบุ AGI ด้วย"],en:{title:"Skills now work exactly as described",lines:["A stacked status ailment now only uses the value of whichever skill applied it most recently — e.g. Blind from Shadow Burst reduces Hit and ASPD by the full 25% even after being hit by Radiant Light first, and Freeze from equipment no longer gets Frost Area's magic damage bonus.","A shorter status no longer cuts short an existing one that has longer left — e.g. Stormbreak's 1.7-second stun no longer overwrites Power Strike's 2.5-second stun.","A monster affected by Blind can now miss elemental skill casts and casts more slowly, as its description says.","In PVP: Blade Mastery, Predator's Patience, Twin Strike, Dokunuri, Fatal Sense's critical chance, Radiant Light's chained hits, the knockback of Cart Strike and Leap Shot, and Fleet Foot's Perfect Dodge now all work the same as they do against monsters.","Skill descriptions now clearly state that World Bosses are immune to stun, freeze, knockback and taunt, and take only 1/10 damage from burn and poison.","Fixed the Divine Boon description to also mention AGI."]}},{id:"2026-09-26-wiki-guild-pvp",date:"2026-09-26",time:"05:53",title:"อัปเดต Wiki: กิล สนาม PVP และไอเทมล็อก",lines:["Wiki มีหัวข้อระบบกิล (ค่าสร้างกิล สมาชิกสูงสุด โบนัส EXP และค่าอัปแต่ละเลเวล) และสนาม PVP Aurelia Arena พร้อมกติกา","เพิ่มเรื่อง Protection Stone และอุปกรณ์ที่ล็อกไว้ในหัวข้อตีบวก Premium หลอมอุปกรณ์ได้ทุกที่ และการสร้างปาร์ตี้คนเดียว"],en:{title:"Wiki update: guilds, the PVP arena and item locking",lines:["The Wiki now has a Guild System section (founding cost, max members, EXP bonus, and upgrade cost per level) and a section on Aurelia Arena with its rules.","Added coverage of Protection Stone and locked equipment in the Refine section, Premium being able to use Fusion from anywhere, and creating a party solo."]}},{id:"2026-09-26-locked-card-replace-notice",date:"2026-09-26",time:"05:45",title:"แจ้งเตือนเมื่อใส่การ์ดทับบนไอเทมที่ล็อก",lines:["ไอเทมที่ตีบวกแล้วยังเปลี่ยนการ์ดได้ตามปกติ แต่ถ้าไอเทมล็อกอยู่และมีการ์ดแล้ว หน้าต่างฝังการ์ดจะแสดงว่าล็อกอยู่และให้ปลดล็อกในกระเป๋าก่อนใส่การ์ดทับ แทนที่จะกดยืนยันแล้วไม่มีอะไรเกิดขึ้น"],en:{title:"Notice when socketing a card over a locked item",lines:["Refined items can still have their cards changed as normal, but if an item is locked and already has a card, the socketing window now shows that it's locked and asks you to unlock it in Inventory before replacing the card — instead of confirming and doing nothing."]}},{id:"2026-09-26-ammo-compare-fix",date:"2026-09-26",time:"05:29",title:"แก้การเทียบค่าสถานะของลูกธนู",lines:["การ์ดไอเทมและข้อความเมื่อชี้ลูกธนูแสดงค่าที่เพิ่มหรือลดเทียบกับลูกธนูที่สวมอยู่ พร้อมสีเขียวแดงเหมือนอุปกรณ์อื่น ไม่ขึ้นว่าโบนัสเท่ากันผิด ๆ อีก"],en:{title:"Fixed ammo stat comparison",lines:["Item cards and the tooltip for hovering ammo now show its stat changes compared to the ammo you have equipped, with green/red coloring like other equipment, instead of wrongly showing the bonuses as equal."]}},{id:"2026-09-26-refused-gear-listing-mailed",date:"2026-09-26",time:"05:01",title:"คืนอุปกรณ์ที่ตั้งขายไม่สำเร็จทางจดหมาย",lines:["อุปกรณ์ที่กระดานตลาดรับไม่ได้ (เช่น ตั้งขายเกินจำนวนที่กำหนด) จะถูกส่งคืนเข้ากล่องจดหมายพร้อมค่าธรรมเนียมตั้งขายทันที ไม่ต้องกลับไปแผนที่เดิมเพื่อรับคืน"],en:{title:"Failed market listings are now returned by mail",lines:["Equipment the market board rejects (e.g. exceeding the listing limit) is now returned to your mailbox immediately along with the listing fee, with no need to go back to the original map to retrieve it."]}},{id:"2026-09-26-solo-party-create",date:"2026-09-26",time:"04:59",title:"สร้างปาร์ตี้คนเดียวได้",lines:["กดปุ่ม สร้างปาร์ตี้ ในหน้าต่างปาร์ตี้เพื่อเปิดปาร์ตี้ไว้รอคนมาเข้าได้ทันที ไม่ต้องมีสมาชิกคนที่สองก่อน","ติ๊ก ประกาศปาร์ตี้นี้ ตอนยังไม่มีปาร์ตี้ ระบบจะสร้างปาร์ตี้ให้และประกาศใน Party Finder ทันที"],en:{title:"Create a party solo",lines:["Press Create Party in the party window to open a party and wait for others to join right away, with no need for a second member first.","Ticking Announce this party while you have no party will now create one for you and list it in Party Finder immediately."]}},{id:"2026-09-26-economy-safety-pass",date:"2026-09-26",time:"04:33",title:"เพิ่มความปลอดภัยของตลาด กิล และไอเทมล็อก",lines:["คำสั่งตลาดทุกแบบถูกบันทึกก่อนส่ง ถ้าเซิร์ฟเวอร์รีสตาร์ทระหว่างทำรายการ ระบบจะทำต่อหรือคืนของให้อัตโนมัติ และผู้ขายได้เงินครบ","สร้างหรือร่วมจ่ายกิลตอนระบบกิลไม่ตอบ จะรอผลจริงก่อนหักหรือคืนเงิน ไม่คืนซ้ำ","อุปกรณ์ที่ล็อกไว้ไม่แตกจากการตีบวก (ต้องใช้ Protection Stone หรือปลดล็อกก่อน) เทรดให้คนอื่นไม่ได้ และการ์ดบนอุปกรณ์ที่ล็อกไม่ถูกแทนที่","Gold จากการชำระเงินที่ถูกคืนหรือถูกโต้แย้งจะถูกเรียกคืน","ย้ายแผนที่แล้วข้อมูลเก่าไม่ทับข้อมูลใหม่ และลบบัญชี Guest ได้สะอาดทุกแผนที่"],en:{title:"Added safety for the market, guilds and locked items",lines:["Every market order is now recorded before it's submitted; if the server restarts mid-transaction, the system automatically resumes it or refunds the items, and the seller always receives the full payment.","Founding or contributing to a guild while the guild system isn't responding now waits for the real result before charging or refunding, and never refunds twice.","Locked equipment can no longer be destroyed by refining (a Protection Stone or unlocking it first is required), can't be traded to others, and a card on locked equipment can no longer be replaced.","Gold from a refunded or disputed payment is now clawed back.","Changing maps no longer lets stale data overwrite newer data, and deleting a Guest account now cleans it up across every map."]}},{id:"2026-09-26-guild-leave-button-restyle",date:"2026-09-26",time:"03:44",title:"ปรับปุ่มออกจากกิล",lines:["ปุ่มออกจากกิลเป็นแบบกรอบทองเข้าชุดกับหน้ากิล","กดออกจากกิลแล้วแสดงหน้าต่างยืนยันพร้อมชื่อกิล ถ้าเป็นหัวกิลจะบอกว่าตำแหน่งหัวกิลโอนให้สมาชิกคนถัดไป"],en:{title:"Restyled the Leave Guild button",lines:["The Leave Guild button now has a gold frame matching the guild window.","Pressing Leave Guild now shows a confirmation window naming the guild; if you're the guild leader, it notes that leadership will pass to the next member."]}},{id:"2026-09-26-guild-roster-buttons-restyle",date:"2026-09-26",time:"03:24",title:"ปรับปุ่มและหน้ายืนยันในหน้ากิล",lines:["ปุ่มรับเข้ากิล ปฏิเสธ รีเฟรช และนำสมาชิกออกกลับมาเป็นแบบกรอบทองเข้าชุดกับหน้ากิล","การนำสมาชิกออกแสดงหน้าต่างยืนยันพร้อมชื่อสมาชิกและชื่อกิล มีปุ่มยืนยันสีแดงและปุ่มยกเลิก"],en:{title:"Restyled buttons and confirmations in the guild window",lines:["The Accept, Decline, Refresh and Remove Member buttons now have a gold frame matching the guild window.","Removing a member now shows a confirmation window with the member's name and the guild's name, with a red Confirm button and a Cancel button."]}},{id:"2026-09-26-arena-population-entry-fix",date:"2026-09-26",time:"02:40",title:"แก้จำนวนคนและปุ่มเข้าสนาม PVP",lines:["ห้องที่รายงานว่าไม่มีคนยังแสดง 0 เมื่อห้องพักการทำงาน","ยืนยันเข้าสนามได้แม้โหลดจำนวนคนไม่สำเร็จ โดยระบบยังตรวจความจุและเลือกช่องให้ตามปกติ"],en:{title:"Fix PVP population preview and entry",lines:["Empty rooms retain their reported zero count while asleep.","Entry confirmation remains available when population counts cannot load; server capacity checks and channel selection still apply."]}},{id:"2026-09-26-gold-exchange-durable-settlement",date:"2026-09-26",time:"02:21",title:"เพิ่มความปลอดภัยของการแลก Gold",lines:["บันทึกยอดและคำสั่ง Gold ก่อนส่งไปตลาด พร้อมบันทึกการรับเงินและยกเลิกคำสั่งให้กู้คืนได้เมื่อเซิร์ฟเวอร์หยุดระหว่างทำรายการ","เพิ่มการกู้คืนการรับจดหมาย และเก็บผลธุรกรรมเพื่อป้องกันคำขอค้างถูกทำซ้ำแม้ผ่านไปเกิน 7 วัน"],en:{title:"More reliable Gold exchange settlement",lines:["Gold balances and pending orders are saved before dispatch, with recoverable payouts and cancellations if a server stops during a transaction.","Mail claims now checkpoint their recovery state, and financial results are retained to prevent replaying requests delayed more than seven days."]}},{id:"2026-09-26-guild-contribution-reserve",date:"2026-09-26",time:"02:19",title:"แก้ยอดติดลบจากการร่วมจ่ายกิล",lines:["กันยอด Silver และ Spirit Shard ก่อนส่งคำขอร่วมจ่ายกิล และป้องกันการกดจ่ายซ้ำระหว่างรอผล เพื่อไม่ให้หักทรัพยากรเกินยอดที่มี","คืนส่วนที่กิลไม่ได้ใช้ และส่งคืนทางจดหมายหากผู้เล่นออกจากแผนที่ระหว่างรอผล"],en:{title:"Fixed negative balances from guild contributions",lines:["Silver and Spirit Shard are now reserved before a guild contribution request is sent, and duplicate contribute clicks are blocked while waiting for a result, so resources are never deducted past what you have.","Any portion the guild doesn't use is refunded, and delivered by mail if the player left the map while waiting for the result."]}},{id:"2026-09-26-gold-trail-recovery",date:"2026-09-26",time:"01:24",title:"แก้การตรวจสอบประวัติตลาด Gold",lines:["แก้ข้อผิดพลาดเมื่อตรวจประวัติตลาด Gold และการรับจดหมายที่มีข้อมูลจำนวนมาก เพื่อให้ทีมงานตรวจสอบรายการซื้อขายย้อนหลังได้ต่อเนื่อง"],en:{title:"Fixed Gold market history auditing",lines:["Fixed an error when auditing Gold market history and mail claims with a large amount of data, so the team can keep reviewing past trades without interruption."]}},{id:"2026-09-26-arena-show-all",date:"2026-09-26",time:"01:02",title:"เข้า PVP แล้วแสดงผู้เล่นทั้งหมดอัตโนมัติ",lines:["เมื่อเข้าสนาม PVP หรือเปิดเกมใหม่ขณะอยู่ในสนาม ระบบเปลี่ยนการแสดงผลผู้เล่นคนอื่นเป็น Show All อัตโนมัติ เพื่อให้เห็นคู่ต่อสู้และยอดฆ่าเหนือหัว"],en:{title:"Show All players automatically on PVP entry",lines:["Entering the arena or reopening the game there automatically selects Show All players, revealing opponents and their overhead kill totals."]}},{id:"2026-09-26-arena-kill-count",date:"2026-09-26",time:"00:58",title:"แสดงยอดฆ่า PVP พร้อมหัวกะโหลก",lines:["แสดงหัวกะโหลกและยอดฆ่า PVP สะสมเหนือหัวผู้เล่นในสนาม พร้อมแจ้งเมื่อฆ่าได้ นับเมื่อคู่ต่อสู้ล้มจากการโจมตี สกิล หรือพิษเพียงครั้งเดียว","ยอดฆ่าเก็บต่อเนื่องเมื่อออกเข้าเกมหรือเปลี่ยนห้อง แยกจากการฆ่ามอนสเตอร์ และไม่นับสมาชิกปาร์ตี้เดียวกัน"],en:{title:"PVP skull badges and kill totals",lines:["Arena players now show a skull and lifetime PVP kill count overhead, with a notification on each kill. Attacks, skills and damage-over-time award one kill per knockout.","Totals persist across reconnects and room changes, remain separate from monster kills, and exclude party members."]}},{id:"2026-09-26-pvp-menu-only",date:"2026-09-26",time:"00:50",title:"เข้าสนาม PVP ผ่านเมนูเท่านั้น",lines:["นำประตูเข้า PVP ในเมืองและทางเข้าจากแผนที่ World ออก ให้เข้าผ่านปุ่ม PVP พร้อมหน้ากติกาและยืนยันเท่านั้น ประตูกลับเมืองในสนามยังใช้งานได้"],en:{title:"PVP entry through the menu only",lines:["Removed the town PVP entrance and World map entry. Use the PVP menu to review the rules and confirm entry. The arena exit to town remains available."]}},{id:"2026-09-26-premium-fusion-translations",date:"2026-09-26",time:"00:44",title:"เติมคำแปลหลอมรวม Premium",lines:["เติมคำอธิบายการหลอมรวมจากเมนูระหว่างเปิดบอทให้ครบทุกภาษาที่รองรับ"],en:{title:"Premium fusion translations",lines:["Completed translations for menu-based fusion while Auto Play continues."]}},{id:"2026-09-26-arena-room-capacity",date:"2026-09-26",time:"00:31",title:"สนาม PVP ห้องละ 20 คน",lines:["จำกัดสนาม PVP สูงสุดห้องละ 20 คน เมื่อเต็มจะจัดผู้เล่นเข้าห้องว่างหรือเปิดช่องใหม่ตามระบบ channel สมาชิกปาร์ตี้และการเลือกช่องไม่สามารถเข้าห้องเกินกำหนดได้","หน้าก่อนเข้าแสดงจำนวนผู้เล่นแต่ละห้องเทียบกับความจุ 20 คน"],en:{title:"20-player PVP rooms",lines:["PVP rooms hold at most 20 players. Full rooms send arrivals to available rooms or open another channel. Party members and manual channel choices cannot exceed the limit.","The entry preview shows each room’s player count out of 20."]}},{id:"2026-09-26-more-menu-five-columns",date:"2026-09-26",time:"00:30",title:"เมนูเพิ่มเติม 5 คอลัมน์",lines:["จัดไอคอนในเมนูเพิ่มเติมเป็น 5 คอลัมน์ เพื่อแสดงปุ่มได้มากขึ้นในแต่ละแถว"],en:{title:"Five-column More menu",lines:["The More menu now arranges icons in five columns to show more buttons per row."]}},{id:"2026-09-26-arena-lobby-confirm",date:"2026-09-26",time:"00:27",title:"ดูกติกาและจำนวนคนก่อนเข้าสนาม PVP",lines:["กด PVP เพื่ออ่านกติกา ดูจำนวนผู้เล่นรวมและแยกช่องในภูมิภาคเดียวกัน พร้อมปุ่มอัปเดตจำนวนคน","ต้องกดยืนยันก่อนเข้าสนาม ทั้งจากเมนู World และประตูเข้า หากโหลดจำนวนคนไม่สำเร็จจะแสดงให้ลองใหม่"],en:{title:"PVP rules, player count and entry confirmation",lines:["The PVP menu now shows combat rules and reported player counts by channel in your region, with a refresh button.","Confirm before entering from the menu, World map or portal. Unavailable counts show a retry message."]}},{id:"2026-09-26-pvp-menu-entry",date:"2026-09-26",time:"00:21",title:"เข้าสนาม PVP จากเมนูได้ทันที",lines:["เพิ่มไอคอนดาบไขว้พร้อมชื่อ PVP ในเมนูหลัก กดเพื่อเข้าสนาม Aurelia Arena ได้ทันที ไม่ต้องเดินไปประตูหรือเปิดแผนที่โลก","กดซ้ำขณะอยู่ในสนามจะไม่ย้ายตำแหน่ง และยังป้องกันสมาชิกปาร์ตี้เดียวกันโจมตีกันตามเดิม"],en:{title:"Enter PVP directly from the menu",lines:["Added a crossed-swords icon labelled PVP to the main menu. Click it to enter Aurelia Arena immediately, without walking to a portal or opening the World map.","Clicking again inside the arena leaves your position unchanged. Party friendly-fire protection remains active."]}},{id:"2026-09-26-shops-more-menu",date:"2026-09-26",time:"00:25",title:"ย้ายร้าน Silver และ Market เข้าเมนูเพิ่มเติม",lines:["เปิดร้าน Silver และตลาด Market ได้จากเมนูเพิ่มเติม เพื่อลดจำนวนไอคอนบนแถบหลัก"],en:{title:"Silver Shop and Market in the More menu",lines:["Moved Silver Shop and Market into the More menu to free up the main toolbar."]}},{id:"2026-09-26-fusion-menu-icon",date:"2026-09-26",time:"00:20",title:"เพิ่มไอคอนและชื่อเมนูหลอมรวม",lines:["เมนูเพิ่มเติมแสดงไอคอนเตาหลอมพร้อมชื่อ หลอมรวม สำหรับผู้เล่น Premium ให้ค้นหาและกดได้ชัดเจนขึ้น"],en:{title:"Fusion menu icon and label",lines:["The Premium Fusion button now shows a furnace icon and a visible label in the More menu."]}},{id:"2026-09-26-party-panel-compact-width",date:"2026-09-26",time:"00:02",title:"ปรับแผงปาร์ตี้ให้กระชับ",lines:["ลดความกว้างแผงปาร์ตี้และระยะห่างบนหัวแผงให้พอดีกับเนื้อหา โดยยังขึ้นบรรทัดใหม่ได้เมื่อพื้นที่ไม่พอ"],en:{title:"More compact party panel",lines:["Reduced party panel width and header spacing while keeping wrapping for narrow screens."]}},{id:"2026-09-25-guild-exp-benefits-restored",date:"2026-09-25",time:"23:55",title:"แสดงโบนัส EXP และปรับโฉมหน้าประโยชน์กิล",lines:["รวมระบบกิล Lv.1–20 กลับมา พร้อมความจุเพิ่ม 2 คนต่อเลเวล และโบนัส Base/Job EXP จากมอนสเตอร์ เริ่ม +0.1% ถึงประมาณ +16.6588%","โบนัสทำงานโดยไม่ต้องเปิดหน้ากิล และปรับตามการเข้ากิล ออกกิล และอัปเลเวล","ตกแต่งหน้าคำอธิบายโทนน้ำเงินทอง พร้อมการ์ดสรุปและตารางโบนัสทุกเลเวล"],en:{title:"Restored guild EXP bonuses and refreshed the benefits guide",lines:["Restored levels 1–20 with 2 additional member slots per level and monster Base/Job EXP bonuses from +0.1% to about +16.6588%.","Bonuses apply without opening the guild window and follow membership and level changes.","Added a blue-and-gold guide with summary cards and per-level EXP bonuses."]}},{id:"2026-09-25-premium-remote-fusion",date:"2026-09-25",time:"23:55",title:"Premium หลอมรวมได้ทุกที่",lines:["ผู้เล่น Premium เปิดช่างหลอมรวมจากเมนูได้ทุกแผนที่ โดยบอทยังเดิน ต่อสู้ และเก็บของต่อระหว่างเปิดหน้าต่างและหลอมรวม","ผู้เล่นทั่วไปยังใช้ช่างหลอมรวมที่ NPC ได้ตามเดิม"],en:{title:"Premium fusion from anywhere",lines:["Premium players can open the Fusion Master from the menu on any map while Auto Play keeps moving, fighting, and looting during fusion.","Players without Premium can still fuse at the NPC."]}},{id:"2026-09-25-guild-benefits-guide",date:"2026-09-25",time:"23:46",title:"เพิ่มหน้าอธิบายประโยชน์และเลเวลกิล",lines:["เปิดอ่านจากหน้ากิลได้ทั้งก่อนและหลังเข้ากิล พร้อมตารางความจุสมาชิกตามเลเวล ระบุเลเวลปัจจุบัน และอธิบายแชทกิลกับการร่วมบริจาค","อธิบายประโยชน์ที่สมาชิกได้รับจากกิล"],en:{title:"Guild benefits and level guide",lines:["Added a guide accessible before and after joining a guild, with member capacity by level, the current level, guild chat, and contribution details.","Explained the benefits available to guild members."]}},{id:"2026-09-25-open-pvp-arena",date:"2026-09-25",time:"23:45",title:"เปิดสนาม Aurelia Arena สำหรับ PVP",lines:["เข้าสนาม PVP จากเมือง Aurelia หรือเลือกใน World แล้วคลิกผู้เล่นเพื่อโจมตีได้ทันที ไม่ต้องรับคำท้า","ปาร์ตี้เดียวกันโจมตีกันไม่ได้ รวมถึงสกิลหมู่และดาเมจต่อเนื่อง ล้มแล้วลุกใน 10 วินาทีโดยไม่เสีย EXP หรือไอเท็ม"],en:{title:"Aurelia Arena opens for PVP",lines:["Enter the PVP arena from Aurelia or select it on the World Map, then click a player to attack instantly — no challenge to accept.","Party members can't attack each other, including with AoE skills and damage over time. Falling in the arena, you're back up in 10 seconds with no EXP or item loss."]}},{id:"2026-09-25-guild-contribution-zero-default",date:"2026-09-25",time:"23:39",title:"ช่องบริจาคกิลเริ่มต้นที่ 0",lines:["ช่องร่วมจ่ายอัปเลเวลกิลทั้ง Spirit Shard และ Silver เริ่มต้นเป็น 0 เพื่อให้เลือกจำนวนที่ต้องการบริจาคเอง"],en:{title:"Guild contributions start at zero",lines:["Spirit Shard and Silver contribution fields now default to 0 so members can enter the amount they want to donate."]}},{id:"2026-09-25-card-socket-design",date:"2026-09-25",time:"23:35",title:"ปรับโฉมหน้าฝังการ์ด",lines:["ตกแต่งหน้าฝังการ์ดด้วยกรอบน้ำเงินทอง พื้นกระดาษสีครีม รูปการ์ดขนาดใหญ่ และรายการอุปกรณ์แยกชื่อกับค่าสถานะ พร้อมแสดงชิ้นที่เลือกและคำเตือนชัดเจน"],en:{title:"Redesigned card socketing window",lines:["Added a blue-and-gold parchment window with larger card artwork, separate equipment names and stats, clear selection markers, and a permanent-card warning."]}},{id:"2026-09-25-stable-window-scale",date:"2026-09-25",time:"23:20",title:"ปรับขนาดหน้าต่างโดยสเกลเกมไม่กระโดด",lines:["แก้ภาพเกมขยายหรือย่อทันทีเมื่อลากขอบหน้าต่าง Client ผ่านขนาด 700px บนคอม · การปรับหน้าต่างจะเพิ่มหรือลดพื้นที่ที่มองเห็น โดยคงขนาดตัวละครและขนาด HUD ที่ตั้งไว้"],en:{title:"Stable game scale while resizing",lines:["Resizing a desktop client window across 700px no longer abruptly doubles or halves the game world. Resizing changes the visible area while preserving character size and the chosen HUD size."]}},{id:"2026-09-25-save-rollback-guards",date:"2026-09-25",time:"23:05",title:"เพิ่มการป้องกันเซฟความคืบหน้าถอยหลัง",lines:["ปฏิเสธเซฟย้ายแมพที่มีเลเวลหรือจำนวนฆ่าล้าหลังกว่าเซฟปลายทาง และไม่รับทับตัวละครที่กำลังออนไลน์","หยุดการเข้าเซฟเมื่อตรวจพบว่าล้าหลังกว่าข้อมูลสำรอง เพื่อให้ทีมงานตรวจสอบกู้คืน โดยไม่คืนของหรือเงินจากสำรองอัตโนมัติ"],en:{title:"Guard against character progress rollback",lines:["Reject incoming map transfers behind destination progress and transfers into an active character.","Refuse login when available backup evidence shows the selected save has regressed so support can verify recovery without automatically restoring currency or items."]}},{id:"2026-09-25-party-panel-width",date:"2026-09-25",time:"23:02",title:"ขยายแผงปาร์ตี้ให้อ่านครบ",lines:["ขยายความกว้างแผงปาร์ตี้เพื่อให้จำนวนสมาชิก โบนัส EXP/Drop และปุ่ม Refresh ไม่ทับกัน พร้อมขึ้นบรรทัดใหม่เมื่อพื้นที่จอแคบ"],en:{title:"Widened the party panel to fit everything",lines:["Widened the party panel so member count, EXP/Drop bonus and the Refresh button no longer overlap, and it now wraps to a new line when screen space is narrow."]}},{id:"2026-09-25-party-manual-location-only",date:"2026-09-25",time:"22:59",title:"ลดการดึงข้อมูลปาร์ตี้อัตโนมัติ",lines:["ตำแหน่งสมาชิกปาร์ตี้ดึงใหม่เมื่อกด Refresh โดยไม่ขอข้อมูลซ้ำเมื่อเปิดหน้าต่างหรือซิงก์สมาชิก","สถานะสมาชิกยังอัปเดตจากเซิร์ฟเวอร์ โดยแนบข้อมูลซ่อมสถานะมากับรายงานออนไลน์เดิมเพื่อลด request ไปยัง HUB"],en:{title:"Reduced automatic party data polling",lines:["Party member locations now only refresh when you press Refresh, without re-requesting the data every time you open the window or sync members.","Member status still updates from the server, now piggybacking status-repair data onto the existing online report to cut down requests to the Hub."]}},{id:"2026-09-25-gold-trade-mail-receipts",date:"2026-09-25",time:"22:47",title:"เพิ่มจดหมายสรุปการซื้อขาย Gold",lines:["ตลาด Gold ส่งหลักฐานให้ผู้ซื้อและผู้ขายเมื่อจับคู่สำเร็จ ระบุคู่ค้า จำนวน ราคา และยอด Silver · ฝั่งที่ได้รับเงินเข้ากระเป๋าทันทีจะได้รับจดหมายสรุปโดยไม่มีเงินแนบซ้ำ"],en:{title:"Added mail receipts for Gold trades",lines:["The Gold market now sends both sides a receipt when a trade matches, listing the counterparty, amount, price and Silver total. The side who receives Silver directly still gets the receipt mail, just without the money attached again."]}},{id:"2026-09-25-remove-directory-repair",date:"2026-09-25",time:"19:25",title:"ยกเลิก Directory Repair",lines:["นำระบบกวาดซ่อม Directory และล้างเซฟเก่าเบื้องหลังออก รวมถึงช่องเรียกด้วยมือ โดยคงการค้นหาเซฟและตรวจเซฟเก่าตอนเข้าเกมไว้"],en:{title:"Removed Directory Repair",lines:["Removed the background sweep-and-repair system for the Directory and old-save cleanup, including its manual trigger, while keeping the save lookup and stale-save check that runs at login."]}},{id:"2026-09-25-support-slot-tier-gear",date:"2026-09-25",time:"23:01",title:"ส่งคืนอุปกรณ์ได้ครบทุกช่อง",lines:["ทีมงานส่งอุปกรณ์ทุกช่องรวม Feather Arrow พร้อม Tier I–V ออฟที่กำหนด และการ์ดหนึ่งใบผ่านจดหมายได้ โดยมีรหัสป้องกันส่งซ้ำ"],en:{title:"Support can now mail gear for every slot",lines:["The team can now mail equipment for any slot, including Feather Arrow, with a specified Tier I–V and stat roll, plus one card, with a duplicate-send safeguard."]}},{id:"2026-09-25-login-reconnect-hotfix",date:"2026-09-25",time:"22:35",title:"แก้ค้างตรวจข้อมูลตอนเข้าเกม",lines:["คืนขั้นตอนเข้าเกมก่อนอัปเดตล่าสุด เพื่อลดคิวตรวจข้อมูลเมื่อผู้เล่นเชื่อมต่อพร้อมกัน โดยยังป้องกันการสร้างตัวละครทับเซฟเดิม","ยกเลิกการตรวจทุกแชนเนลและล้างสำเนาเซฟทุกครั้งที่เข้าเกมจากอัปเดตก่อนหน้า"],en:{title:"Fixed login verification congestion",lines:["Restored the previous login flow to reduce congestion during simultaneous reconnects while retaining safeguards against replacing existing saves.","Reverted the previous update’s exhaustive channel checks and login-triggered save-copy pruning."]}},{id:"2026-09-25-device-hud-defaults",date:"2026-09-25",time:"22:16",title:"แยกขนาด HUD เริ่มต้นของคอมและมือถือ",lines:["ผู้เล่นใหม่บนคอมจะเริ่มด้วย HUD ขนาด 100% ส่วนมือถือและอุปกรณ์จอสัมผัสยังเริ่มที่ 70% · ค่าที่ผู้เล่นเคยปรับเองไว้จะไม่เปลี่ยน"],en:{title:"Separate desktop and mobile HUD defaults",lines:["New desktop players now start with the HUD at 100%, while phones and touch-first devices continue to start at 70%. Previously saved HUD preferences are unchanged."]}},{id:"2026-09-25-party-hud-refresh",date:"2026-09-25",time:"22:15",title:"รีเฟรชตำแหน่งสมาชิกปาร์ตี้ได้เอง",lines:["เพิ่มปุ่ม ↻ บนแผงปาร์ตี้สำหรับดึงแมพและ Channel ล่าสุดของสมาชิกทันที พร้อมจำกัดการกดรัวเพื่อลดภาระเซิร์ฟเวอร์"],en:{title:"Manually refresh party member locations",lines:["Added a ↻ button on the party panel to pull members' latest map and Channel immediately, with a rate limit on rapid clicks to ease server load."]}},{id:"2026-09-25-party-friend-map-channel",date:"2026-09-25",time:"22:00",title:"ปาร์ตี้และเพื่อนบอกแมพกับ Channel",lines:["สมาชิกปาร์ตี้ที่ออนไลน์ต่างแมพหรือต่าง Channel จะแสดงตำแหน่งจริงแทนคำว่าออฟไลน์ทันทีหลังเข้าปาร์ตี้","รายชื่อเพื่อนแสดงทั้งชื่อแมพและหมายเลข Channel ของเพื่อนที่ออนไลน์"],en:{title:"Party and friends now show map and Channel",lines:['Party members online on a different map or Channel now show their real location instead of "Offline," right after joining the party.',"The friends list now shows both the map name and Channel number for friends who are online."]}},{id:"2026-09-25-guild-silver-rounded-costs",date:"2026-09-25",time:"21:58",title:"ปรับค่า Silver อัปกิลเป็นเลขกลม",lines:["ค่า Silver อัปเลเวลกิลยังเพิ่มประมาณ 50% ต่อขั้น แต่ปัดขึ้นหลักแสนทุกเลเวลให้อ่านและวางแผนสะสมง่ายขึ้น ตั้งแต่ 1,000,000 จนถึง 27,000,000 Silver"],en:{title:"Rounded guild Silver upgrade costs",lines:["Guild level-up Silver costs still rise about 50% per step, but are now rounded up to the nearest 100,000 at every level, making them easier to read and save toward — from 1,000,000 up to 27,000,000 Silver."]}},{id:"2026-09-25-guild-upgrade-silver-and-costs",date:"2026-09-25",time:"21:48",title:"เพิ่มเป้าหมาย Silver สำหรับอัปเลเวลกิล",lines:["ค่า Spirit Shard สำหรับอัปเลเวลกิลเพิ่มอีก 10 เท่า เป็น 10,000 ชิ้นคูณเลเวลปัจจุบัน","เพิ่มเป้าหมาย Silver เริ่ม 1,000,000 ตอนขึ้น Lv.2 และเพิ่ม 50% ทุกขั้น โดยสมาชิกช่วยกันสะสมได้ทั้งสองทรัพยากร"],en:{title:"Added a Silver target for guild level-ups",lines:["The Spirit Shard cost for guild level-ups is increased 10x, to 10,000 pieces times the current level.","Added a Silver target, starting at 1,000,000 for Lv.2 and rising 50% every level, which members can contribute toward alongside Spirit Shard."]}},{id:"2026-09-25-party-benefits-toggle",date:"2026-09-25",time:"21:35",title:"เปิดดูประโยชน์ของปาร์ตี้ได้อีกครั้ง",lines:["เพิ่มปุ่มคำอธิบายใน Party Finder สำหรับสลับเปิดข้อมูล EXP โบนัส การแบ่งของ รับสมาชิกอัตโนมัติ และตำแหน่งสมาชิก โดยไม่ลดพื้นที่รายการปาร์ตี้"],en:{title:"Party benefits are available again",lines:["Added a Description button in Party Finder to show EXP, bonus, loot sharing, auto-accept, and member-location details without shrinking the party list."]}},{id:"2026-09-25-party-finder-controls",date:"2026-09-25",time:"21:28",title:"ขยายรายการและปรับช่องประกาศปาร์ตี้",lines:["ขยายกล่องปาร์ตี้ที่เปิดรับให้เห็นรายการได้มากขึ้น และปรับช่องประกาศปาร์ตี้ให้แสดงตรงตำแหน่ง อ่านง่าย และกดได้ชัดเจนขึ้น"],en:{title:"Expanded the Party Finder list",lines:["Expanded the open-party list to show more entries and fixed the party-listing control so it stays aligned, readable, and easy to toggle."]}},{id:"2026-09-25-home-player-links",date:"2026-09-25",time:"21:06",title:"เพิ่มลิงก์สำคัญในหน้าแรก",lines:["หน้าเข้าสู่ระบบมีหมวด “ลิงก์ที่ผู้เล่นควรรู้” สำหรับเปิด Wiki, FAQ, บันทึกการอัปเดต และ Explorer ได้ทันที"],en:{title:"Added useful player links to the home page",lines:["The login page now groups quick links to the Wiki, FAQ, patch notes, and Explorer in one easy-to-find section."]}},{id:"2026-09-25-desktop-window-resize-zoom",date:"2026-09-25",time:"20:35",title:"Client ปรับขนาดและซูมได้เหมือนเว็บ",lines:["หน้าต่าง Client บน Windows ย่อ ขยาย และปรับขนาดได้อิสระมากขึ้น พร้อมใช้ Ctrl +, Ctrl - และ Ctrl 0 เพื่อซูมหน้าเกมหรือคืนขนาดเดิม"],en:{title:"Desktop client window and zoom controls",lines:["The Windows client can now be minimized, maximized, and resized more freely, with Ctrl +, Ctrl -, and Ctrl 0 controls to zoom the game or restore its original size."]}},{id:"2026-09-25-gym-pass-surplus-refund",date:"2026-09-25",time:"20:20",title:"คืน Gold สำหรับ Gym Pass ที่เกินเพดาน",lines:["แก้กรณีร้านค้าเปิดให้ซื้อ Gym Pass ซ้ำหลังใช้ครบ 10 ใบ โดยนำบัตรส่วนเกินที่ใช้ไม่ได้ออกและคืน Gold เต็มราคาให้อัตโนมัติเมื่อเข้าเกม","ร้านค้ายังคงนับทั้งจำนวนที่ใช้แล้วและบัตรที่ถืออยู่ เพื่อไม่ให้ซื้อเกินเพดาน 10 ใบอีก"],en:{title:"Refunded surplus Gym Passes",lines:["Fixed a brief issue that allowed more Gym Passes to be purchased after reaching the 10-pass lifetime limit. Unusable surplus passes are removed and refunded at full Gold price automatically on login.","The mall continues to count both consumed and held passes so purchases cannot exceed the 10-pass cap."]}},{id:"2026-09-25-bilingual-changelog",date:"2026-09-25",time:"20:05",title:"บันทึกการอัปเดตรองรับไทยและอังกฤษ",lines:["เพิ่มปุ่ม ไทย / EN ในหน้าบันทึกการอัปเดต พร้อมจดจำภาษาที่เลือกและเลือกภาษาเริ่มต้นตามภาษาของเกมหรือเบราว์เซอร์","รายการใหม่รองรับข้อความไทยและอังกฤษในข้อมูลชุดเดียว โดยรายการเก่าที่ยังไม่มีคำแปลจะแสดงต้นฉบับภาษาไทยแทน"],en:{title:"Patch notes now support Thai and English",lines:["Added a ไทย / EN switch to the patch notes page. The page remembers your choice and initially follows the game or browser language.","New entries can include Thai and English in the same source. Older entries without a translation continue to show their original Thai text."]}},{id:"2026-09-25-login-prune-stale",date:"2026-09-25",time:"19:42",title:"ล้างเซฟเก่าหลังตรวจตอนเข้าเกม",lines:["เมื่อเข้าแชนเนลของเซฟหลักและตรวจครบแล้ว จะลบสำเนาที่เก่ากว่าและออฟไลน์ โดยเก็บสำเนาที่มีความคืบหน้าขัดแย้งกันและข้อมูลสำรองรายวันไว้"],en:{title:"Old saves pruned after the login check",lines:["Once a login on your main save's channel has been fully verified, older, offline copies are now deleted, while copies with conflicting progress and the daily backups are kept."]}},{id:"2026-09-25-login-best-save",date:"2026-09-25",time:"19:32",title:"ตรวจเซฟทุกครั้งก่อนเข้าเกม",lines:["ตรวจเซฟตัวละครข้ามแชนเนลทุกครั้งที่เข้าเกม เลือกเลเวลสูงสุดแล้วเทียบ EXP และจำนวนมอนสเตอร์ที่กำจัดเมื่อเท่ากัน","หากตรวจข้อมูลไม่ครบจะรอเชื่อมต่อใหม่ก่อน ไม่เข้าเซฟจากผลตรวจที่ยังไม่ครบ"],en:{title:"Every login now checks all your saves",lines:["Every login now checks your character's saves across all Channels, picking the highest level, and if there's a tie, comparing EXP and then kill count.","If the check can't reach every save, it now waits and reconnects instead of loading a save from an incomplete check."]}},{id:"2026-09-25-keep-protection-on-refine-success",date:"2026-09-25",time:"19:25",title:"ตีบวกสำเร็จไม่เสียหินกันแตก",lines:["Protection Stone จะถูกหัก 1 ก้อนเฉพาะเมื่อตีบวกล้มเหลวและป้องกันอุปกรณ์กับการ์ดไว้ได้ · ตีบวกสำเร็จเก็บหินกันแตกไว้ตามเดิม ส่วน Refine Stone และ Silver ยังใช้ทุกครั้ง"],en:{title:"A successful refine no longer spends Protection Stone",lines:["A Protection Stone is now only consumed on a failed refine that saves the item and its cards; a successful refine keeps your stone as before, while Refine Stone and Silver are still spent every time."]}},{id:"2026-09-25-storage-size",date:"2026-09-25",time:"18:42",title:"ขยายหน้าคลัง Storage",lines:["ขยายหน้าคลัง Storage พร้อมช่องไอเทม ข้อความ และปุ่มขึ้น 30% โดยปรับให้พอดีกับหน้าจอขนาดเล็ก"],en:{title:"Enlarged the Storage window",lines:["Enlarged the Storage window, including its item slots, text and buttons, by 30%, while still fitting small screens."]}},{id:"2026-09-25-silver-shop-size",date:"2026-09-25",time:"18:41",title:"ขยายหน้าพ่อค้า Silver",lines:["ขยายหน้าร้าน Silver พร้อมข้อความ ไอคอน และปุ่มขึ้น 30% โดยปรับให้พอดีกับหน้าจอขนาดเล็ก"],en:{title:"Enlarged the Silver Shop window",lines:["Enlarged the Silver Shop window, including its text, icons and buttons, by 30%, while still fitting small screens."]}},{id:"2026-09-25-player-silver-history",date:"2026-09-25",time:"18:40",title:"ดูประวัติ Silver ในหน้าตัวละคร",lines:["เพิ่มประวัติธุรกรรม Silver ในหน้า Explorer ของแต่ละตัวละคร แสดงเงินเข้าและเงินออก อัปเดตสด และเปิดรายการย้อนหลังได้","เงินเข้าแสดงยอดสุทธิหลังภาษี เงินออกแสดงยอดที่จ่าย พร้อมเปิดรายละเอียดธุรกรรมได้"],en:{title:"View Silver history on a character's page",lines:["Added Silver transaction history to each character's Explorer page, showing money in and out, updating live, with older entries available to open.","Money in shows the net amount after tax, money out shows the amount paid, and each transaction's details can be opened."]}},{id:"2026-09-25-silver-explorer-live",date:"2026-09-25",time:"18:33",title:"ดูธุรกรรม Silver แบบสดใน Explorer",lines:["เพิ่มแท็บธุรกรรม Silver สาธารณะ ครอบคลุมเทรดตรง ตลาดไอเทม ตลาดอุปกรณ์ และตลาด Gold พร้อมชื่อผู้ส่ง ผู้รับ ภาษี ยอดสุทธิ และรหัสรายการ","อัปเดตเมื่อมีธุรกรรม ค้นหาตามชื่อตัวละครหรือรหัสรายการ และเปิดประวัติย้อนหลังได้ เริ่มเก็บข้อมูลตั้งแต่เปิดระบบ"],en:{title:"Live Silver transactions in Explorer",lines:["Added a public Silver Transactions tab covering direct trades, the item market, the equipment market and the Gold market, with sender and recipient names, tax, net amount and a transaction ID.","It updates live with each transaction, can be searched by character name or transaction ID, and older history can be opened; data collection started when the system launched."]}},{id:"2026-09-25-release-preserve-production",date:"2026-09-25",time:"18:30",title:"รวมอัปเดตโดยรักษาระบบที่แก้ไขแล้ว",lines:["รวมอัปเดตใหม่กับแพตช์ production เดิม โดยคงระบบป้องกัน HUB โหลดเกิน การเดินทางข้ามแมป Gym Pass และจดหมายชดเชยป้องกันส่งซ้ำ","รักษาระบบ HIT/FLEE เดิมร่วมกับดาเมจ PvP ใหม่ และรวมจดหมายอุปกรณ์จากทีมงาน"],en:{title:"Merged the update while keeping fixed systems intact",lines:["Merged the new update with the existing production patch, keeping the Hub overload protection, cross-map travel, Gym Pass, and the duplicate-send safeguard on compensation mail.","Kept the existing HIT/FLEE system working alongside the new PvP damage rules, and merged in support's equipment mail feature."]}},{id:"2026-09-25-consumable-drop-half",date:"2026-09-25",time:"18:24",title:"ลดอัตราดรอปไอเทมสิ้นเปลือง 50%",lines:["ลดโอกาสสุ่มดรอปยาฟื้น HP/SP และปีกวาร์ปจากมอนสเตอร์จาก 30% เหลือ 15% โดยคงสัดส่วนไอเทมแต่ละชนิด และปรับข้อมูลอัตราดรอปให้ตรงกัน"],en:{title:"Halved consumable item drop rate",lines:["Reduced the random drop chance for HP/SP potions and Warp Wings from monsters, from 30% to 15%, keeping the same ratio between item types and updating the drop-rate data to match."]}},{id:"2026-09-25-pvp-damage-fifth",date:"2026-09-25",time:"18:11",title:"ลดดาเมจ PvP ลงอีก 5 เท่า",lines:["ลดดาเมจการดวลเหลือ 1/5 ของเดิม จาก 10% เป็น 2% ของดาเมจปกติ ครอบคลุมการโจมตี สกิล และสถานะดาเมจต่อเนื่อง เพื่อให้ดวลได้นานขึ้น"],en:{title:"PvP damage cut by another 5x",lines:["Reduced duel damage to 1/5 of before, from 10% down to 2% of normal damage, covering attacks, skills, and damage-over-time effects, so duels last longer."]}},{id:"2026-09-25-mamushi-idle-sit",date:"2026-09-25",time:"18:08",title:"อัปเดตท่ายืนและท่านั่ง Mamushi",lines:["เปลี่ยนแอนิเมชัน idle เป็นชุดใหม่ครบ 8 ทิศ และเพิ่มท่านั่งพร้อมแอนิเมชันลุกยืนของ Mamushi"],en:{title:"Updated Mamushi's idle and sitting poses",lines:["Changed Mamushi's idle animation to a complete new set across all 8 directions, and added a sitting pose with a stand-up animation."]}},{id:"2026-09-25-one-time-google-link",date:"2026-09-25",time:"17:55",title:"ผูกบัญชี Google ได้ครั้งเดียว",lines:["ผู้เล่นไม่สามารถผูก Guest หรือ Google ที่เคยผูกแล้วซ้ำหรือย้ายไปตัวละครอื่นได้ · ล็อกอิน Google เดิมเข้าเล่นต่อได้ตามปกติ","ปิดการเลือกตัวละครเพื่อแทนที่บัญชีและคำขอเก่า ส่วนทีมงานยังย้ายลิงก์ผ่านเครื่องมือหลังบ้านเพื่อกู้บัญชีได้"],en:{title:"Google accounts can only be linked once",lines:["Players can no longer link a Guest or Google account that has already been linked before, or move a link to a different character · logging in with the same Google account continues to work normally.","Disabled selecting a character to replace an account link, and removed old requests; support can still move a link with backend tools to recover an account."]}},{id:"2026-09-25-support-custom-gear",date:"2026-09-25",time:"17:53",title:"รองรับจดหมายอุปกรณ์จากทีมงาน",lines:["ทีมงานส่งอุปกรณ์พร้อมออฟและระดับตีบวกที่กำหนดผ่านจดหมายได้ พร้อมรหัสรายการป้องกันส่งซ้ำ"],en:{title:"Support can mail custom equipment",lines:["The team can now mail equipment with a specified stat roll and refine level, with a duplicate-send safeguard on the transaction."]}},{id:"2026-09-25-market-return-gear-mail",date:"2026-09-25",time:"17:46",title:"แก้การคืนอุปกรณ์จากตลาด",lines:["เมื่อกระเป๋าเต็ม น้ำหนักเกิน หรือออกจากเกมระหว่างรับอุปกรณ์ ตลาดจะส่งจดหมายแนบอุปกรณ์จริงแทนนำกลับไปตั้งขาย","เก็บคืนได้แม้กระเป๋าอุปกรณ์เต็ม และข้อความแจ้งผลระบุชัดว่าของเข้ากระเป๋าหรือกล่องจดหมาย"],en:{title:"Fixed returning equipment from the market",lines:["When your Inventory is full, you're overweight, or you disconnect while claiming equipment, the market now mails the actual item to you instead of putting the listing back up for sale.","It can be claimed even with a full Inventory, and the result message clearly states whether the item went to your Inventory or your mailbox."]}},{id:"2026-09-25-death-button-countdown",date:"2026-09-25",time:"17:45",title:"แสดงเวลารอกลับเมืองบนปุ่ม",lines:["ปุ่มกลับเมืองจางลงและแสดงนับถอยหลัง 2 วินาทีหลังหมดสติ เมื่อครบเวลาจะกลับเป็นสีปกติและกดได้"],en:{title:"Countdown to return to town on the button",lines:["The Return to Town button now dims and shows a 2-second countdown after you're knocked out; once it finishes, the button returns to normal color and can be pressed."]}},{id:"2026-09-25-death-game-theme-instant-revive",date:"2026-09-25",time:"17:43",title:"หน้าต่างหมดสติธีมเกมและกลับเมืองทันที",lines:["ใช้กรอบกระดาษและปุ่มชุดเดียวกับเกม พร้อมไอคอนกลับเมือง","ยกเลิกเวลารอ 2 วินาทีหลังหมดสติ กดกลับเมืองได้ทันทีทั้งออนไลน์และออฟไลน์"],en:{title:"Unconscious window matches the game theme, instant return to town",lines:["Uses the same paper frame and buttons as the rest of the game, with a return-to-town icon.","Removed the 2-second wait after going unconscious — you can return to town immediately, online or offline."]}},{id:"2026-09-25-keelen-silver-reimbursement",date:"2026-09-25",time:"17:40",title:"คืนเงินตามรายการแจ้งสูญหาย",lines:["ส่งคืน 100,000 Silver ให้ keelen ผ่านกล่องจดหมายตามคำขอ"],en:{title:"Refund for a reported loss",lines:["Sent 100,000 Silver back to keelen by mail as requested."]}},{id:"2026-09-25-forge-size-30-percent",date:"2026-09-25",time:"17:37",title:"ขยายหน้าตีบวก 30%",lines:["เพิ่มขนาดหน้าต่างช่างตีบวกและองค์ประกอบภายใน 30% เพื่อให้อ่านและกดได้ง่ายขึ้น"],en:{title:"Blacksmith window enlarged 30%",lines:["Enlarged the Blacksmith window and everything inside it by 30% for easier reading and tapping."]}},{id:"2026-09-25-remove-gear-salvage",date:"2026-09-25",time:"17:35",title:"นำระบบย่อยอุปกรณ์ออก",lines:["นำปุ่มย่อยอุปกรณ์และคำอธิบายออกจากช่างตีบวกและ Wiki พร้อมปิดคำสั่งย่อยฝั่งเซิร์ฟเวอร์"],en:{title:"Removed gear salvage",lines:["Removed the salvage button and its description from the Blacksmith and the Wiki, and disabled the salvage command on the server."]}},{id:"2026-09-25-mail-refresh-on-claim",date:"2026-09-25",time:"17:35",title:"แก้กล่องจดหมายค้างข้อมูลเก่า",lines:["เปิดกล่องจดหมายใหม่จะโหลดข้อมูลล่าสุดได้แม้ครั้งก่อนเชื่อมต่อไม่สำเร็จ และตรวจข้อมูลจดหมายล่าสุดก่อนรับของ เพื่อไม่ให้จดหมายเก่าขวางการรับโดยต้องรีเกม"],en:{title:"Fixed mailbox showing stale mail",lines:["Opening the mailbox now loads the latest mail even if the previous connection failed, and checks for the newest mail before claiming, so stale mail no longer blocks a claim and forces a restart."]}},{id:"2026-09-25-unconscious-window-style",date:"2026-09-25",time:"17:32",title:"ตกแต่งหน้าต่างหมดสติ",lines:["ปรับกรอบน้ำเงินขลิบทองพร้อมตราดาว เพิ่มความชัดเจนของข้อความและปุ่มกลับเมือง พร้อมรูปแบบปุ่มระหว่างรอนับถอยหลัง"],en:{title:"Restyled the unconscious window",lines:["Gave it a blue frame with gold trim and a star badge, made the text and the return-to-town button clearer, and added a button style for the countdown wait."]}},{id:"2026-09-25-refine-shared-painted-theme",date:"2026-09-25",time:"17:32",title:"ใช้ธีมเกมกับกล่องลูกแก้วหมด",lines:["กล่องยืนยันใช้ภาพกรอบ กระดาษ แถบหัว และปุ่มชุดเดียวกับหน้าต่างช่างตีบวก พร้อมปุ่มปิดเพื่อยกเลิก"],en:{title:"Applied the game theme to the out-of-Protection-Stones dialog",lines:["The confirmation dialog now uses the same frame art, paper background, header bar and buttons as the Blacksmith window, with a close button to cancel."]}},{id:"2026-09-25-refine-dialog-style",date:"2026-09-25",time:"17:29",title:"ปรับหน้าต่างแจ้งลูกแก้วหมด",lines:["จัดกล่องยืนยันให้เข้าธีมเกมด้วยหัวสีน้ำเงิน กรอบทอง และไอคอนลูกแก้ว พร้อมแยกคำเตือนและปุ่มให้ชัดเจนบนมือถือ"],en:{title:"Restyled the out-of-Protection-Stones dialog",lines:["Styled the confirmation dialog to match the game with a blue header, gold frame and a Protection Stone icon, and separated the warning text from the buttons for clarity on mobile."]}},{id:"2026-09-25-silver-sale-keep-auto",date:"2026-09-25",time:"17:28",title:"ขายของแล้วบอทตีต่อได้",lines:["แก้การขายของกับพ่อค้า Silver ที่ปิด Auto Play และยกเลิกเป้าหมายโจมตี · ขายแล้วต่อสู้ต่อได้ตามเดิม"],en:{title:"Selling no longer stops the bot",lines:["Fixed selling to the Silver merchant turning off Auto Play and clearing the attack target · Selling now lets the fight continue as before."]}},{id:"2026-09-25-refine-ingame-confirm",date:"2026-09-25",time:"17:25",title:"แก้กดตีต่อเมื่อลูกแก้วหมด",lines:["เปลี่ยนกล่องยืนยันเป็นหน้าต่างในเกม มีปุ่มยกเลิกและตีต่อโดยไม่กันแตก รองรับเบราว์เซอร์ฝังในแอป"],en:{title:"Fixed continuing to refine when out of Protection Stones",lines:["Changed the confirmation to an in-game window with Cancel and Refine-without-protection buttons, and made it work in in-app embedded browsers."]}},{id:"2026-09-25-hub-all-time-peak",date:"2026-09-25",time:"17:25",title:"เก็บสถิติโหลด HUB สูงสุดถาวร",lines:["แสดง requests/s สูงสุดตลอดกาลและบันทึกไว้ข้ามการรีสตาร์ตหรือ deploy โดยเริ่มสะสมตั้งแต่ใช้ระบบนี้"],en:{title:"Keep the Hub's all-time peak load",lines:["Shows the all-time peak requests/s and keeps it across restarts and deploys, counting from when this system went live."]}},{id:"2026-09-25-hub-peak-rps",date:"2026-09-25",time:"17:22",title:"แสดงโหลด HUB สูงสุด",lines:["เก็บและแสดง requests/s สูงสุดตั้งแต่ HUB เริ่มทำงาน แม้ไม่ได้เปิดหน้ามอนิเตอร์ โดยรีเซ็ตเมื่อ HUB เริ่มทำงานใหม่"],en:{title:"Show the Hub's peak load",lines:["Tracks and shows the peak requests/s since the Hub started, even without the Monitor page open, resetting whenever the Hub restarts."]}},{id:"2026-09-25-skill-drag-cleanup",date:"2026-09-25",time:"17:14",title:"แก้ไอคอนสกิลลากค้างบนจอ",lines:["ล้างไอคอนลากเมื่อการลากถูกขัดจังหวะ สลับหน้าต่าง ปิดหน้าสกิล หรือเริ่มลากใหม่ และล้างก่อนวางลงช่องลัด"],en:{title:"Fixed a dragged skill icon sticking on screen",lines:["Clears the dragged icon when the drag is interrupted, when switching windows, closing the skill page, or starting a new drag, and clears it right before dropping onto a hotbar slot."]}},{id:"2026-09-25-unified-skill-rank-controls",date:"2026-09-25",time:"17:12",title:"เลือกเลเวลใช้งานจากการ์ดสกิล",lines:["รวมปุ่มอัปสกิลและเลือกระดับใช้งานไว้ใต้รูปบนการ์ด · กดลบหลังเรียนเพื่อลดระดับใช้งานแล้วลากลงช่องลัดได้ โดยไม่เสียระดับที่เรียน","กดบวกเพื่อกลับถึงระดับที่เรียนก่อนอัปเพิ่มด้วยแต้ม และนำตัวเลือกระดับซ้ำในช่องรายละเอียดออก"],en:{title:"Choose the active skill rank from its card",lines:["Combined the skill-up button and the active-rank selector under the icon on the skill card · Pressing minus after learning it lowers the active rank so it can be dragged to a hotbar slot, without losing the rank you've learned.","Pressing plus returns it to the learned rank before spending points to raise it further, and removed the duplicate rank selector from the detail panel."]}},{id:"2026-09-25-empty-protection-confirm",date:"2026-09-25",time:"17:05",title:"ถามยืนยันเมื่อลูกแก้วกันแตกหมด",lines:["เมื่อลูกแก้วกันแตกหมดและกำลังตีบวกระดับที่มีโอกาสแตก จะแสดงกล่องถามว่าจะตีต่อโดยไม่กันแตกหรือไม่ พร้อมเตือนว่าอุปกรณ์และการ์ดอาจหายถาวร","ยกเลิกจะไม่เสียของหรือเงิน · ยืนยันมีผลเฉพาะครั้งนั้น และถามใหม่หากครั้งต่อไปลูกแก้วยังหมด"],en:{title:"Confirmation prompt when out of Protection Stones",lines:["When you're out of Protection Stones and refining a level that can fail, a prompt now asks whether to continue without protection, warning that the item and its cards could be lost for good.","Cancel loses nothing · Confirming applies to that attempt only, and you'll be asked again next time if you're still out of stones."]}},{id:"2026-09-25-protection-cost-per-attempt",date:"2026-09-25",time:"17:03",title:"ปรับการใช้ลูกแก้วกันแตกต่อครั้ง",lines:["เมื่อเลือกใช้ Protection Stone จะหัก 1 ก้อนทุกครั้งที่ตีบวก ไม่ว่าสำเร็จหรือล้มเหลว · ตีพลาดยังรักษาอุปกรณ์ การ์ด และระดับเดิม","หากเลือกกันแตกแต่ลูกแก้วหมด จะหยุดรายการก่อนหัก Silver และ Refine Stone"],en:{title:"Changed Protection Stone use per attempt",lines:["Choosing to use a Protection Stone now spends 1 stone on every refine attempt, success or failure · A failed attempt still keeps the item, its cards and its current level.","If protection is selected but you have no stones left, the attempt stops before any Silver or Refine Stone is spent."]}},{id:"2026-09-25-premium-silver-shop-menu",date:"2026-09-25",time:"17:02",title:"ซ่อนเมนู Silver Shop เมื่อไม่มี Premium",lines:["ไอคอน Silver Shop บนเมนูแสดงเฉพาะขณะที่ Premium ยังไม่หมดอายุ"],en:{title:"Hid the Silver Shop menu without Premium",lines:["The Silver Shop icon on the menu now shows only while Premium is still active."]}},{id:"2026-09-25-skill-cast-selector-under-icon",date:"2026-09-25",time:"17:01",title:"จัดตัวเลือกเลเวลสกิลใต้รูป",lines:["นำปุ่ม Use skill ออกจากหน้าสกิล และย้ายปุ่มเลือกระดับที่ใช้ไปใต้รูปสกิลในช่องรายละเอียด"],en:{title:"Moved the skill rank selector under the icon",lines:["Removed the Use skill button from the skill page and moved the active-rank selector under the skill icon in the detail panel."]}},{id:"2026-09-25-restore-refine-protection",date:"2026-09-25",time:"16:59",title:"แก้ลูกแก้วกันแตกไม่ทำงาน",lines:["คืนระบบ Protection Stone ให้รักษาอุปกรณ์ การ์ด และระดับตีบวกเดิมเมื่อตีบวกล้มเหลว รวมถึงธนู +7 ไป +8","เปิดใช้กันแตกเป็นค่าเริ่มต้น · หัก 1 ก้อนเฉพาะครั้งที่กันแตกสำเร็จ และหยุดตีหากเลือกกันแตกแต่ของไม่พอ"],en:{title:"Fixed Protection Stones not working",lines:["Restored Protection Stone so it keeps the item, its cards and its current refine level on a failed refine, including a bow going from +7 to +8.","Protection is now on by default · It spends 1 stone only when it actually saves the item, and refining stops if protection is selected but you don't have enough stones."]}},{id:"2026-09-25-hub-monitor-rps-only",date:"2026-09-25",time:"16:49",title:"ย่อสถานะ HUB ให้อ่านง่าย",lines:["หน้ามอนิเตอร์แสดงสถานะ HUB เฉพาะ requests/s พร้อมช่วงเวลาที่วัด"],en:{title:"Simplified Hub status for readability",lines:["The Monitor page now shows Hub status as just requests/s, along with the measured time window."]}},{id:"2026-09-25-gamezxz-level-one",date:"2026-09-25",time:"16:46",title:"ปรับเลเวลตัวละครตามคำขอ",lines:["ปรับ Base Level ของ gamezxz เป็น 1 และ EXP เป็น 0 ตามคำขอ โดยคงอาชีพ ไอเท็ม และเงินเดิม"],en:{title:"Adjusted a character's level on request",lines:["Set gamezxz's Base Level to 1 and EXP to 0 as requested, keeping their class, items and money unchanged."]}},{id:"2026-09-25-guild-applications",date:"2026-09-25",time:"16:44",title:"เลือกกิลและส่งคำขอเข้าร่วม",lines:["หน้ากิลแสดงรายชื่อกิล เลเวล จำนวนสมาชิก และสถานะคำขอ · หัวกิลรับหรือปฏิเสธผู้สมัครได้ โดยเห็นชื่อ เลเวล อาชีพ และไอคอนอาชีพ","การเข้ากิลต้องได้รับอนุมัติจากหัวกิล และตรวจจำนวนสมาชิกก่อนรับเข้าทุกครั้ง"],en:{title:"Browse guilds and send join requests",lines:["The Guild page lists guilds with their level, member count and your request status · Guild leaders can accept or reject applicants, seeing each one's name, level, class and class icon.","Joining a guild now requires the leader's approval, and member capacity is checked every time before someone is let in."]}},{id:"2026-09-25-guild-shared-upgrade-fund",date:"2026-09-25",time:"16:30",title:"สมาชิกช่วยกันสะสมค่าอัปเลเวลกิลได้แล้ว",lines:["เพิ่มค่าอัปเลเวลกิลเป็น 10 เท่า และเปิดให้สมาชิกทุกคนเลือกจำนวน Spirit Shard เพื่อร่วมจ่ายเข้ากองกลาง","ยอดบริจาคสะสมข้ามครั้งจนเต็มเป้าหมายแล้วกิลจึงอัปเลเวล พร้อมแสดงยอดสะสมและแถบความคืบหน้า"],en:{title:"Members can now pitch in toward the guild's level-up cost",lines:["Raised the guild level-up cost 10x, and let every member choose how many Spirit Shards to contribute to the shared fund.","Contributions carry over between sessions until the target is met, at which point the guild levels up, with a running total and progress bar shown."]}},{id:"2026-09-25-gold-exchange-compact-layout",date:"2026-09-25",time:"16:16",title:"ปรับขนาดข้อความและแนวปุ่มตลาด Gold",lines:["ลดขนาดหัวข้อ ราคา และตัวเลขสรุปให้พอดี พร้อมจัดแผงซื้อขายและปุ่มยืนยันทั้งสองฝั่งให้สูงเท่ากัน"],en:{title:"Resized text and aligned buttons on the Gold Market",lines:["Shrunk the headers, prices and summary numbers to fit, and aligned the buy and sell panels and their confirm buttons to the same height on both sides."]}},{id:"2026-09-25-gym-pass-compensation",date:"2026-09-25",time:"16:09",title:"คืน Gym Pass ที่ยอดสูญหาย",lines:["ตรวจยอดซื้อเทียบจำนวนใช้ กระเป๋า คลัง จดหมาย และ Gold ที่เคยคืน เพื่อชดเชย Gym Pass เฉพาะยอดที่ยังขาดผ่านจดหมาย","เพิ่มรหัสชดเชยถาวรเพื่อป้องกันส่งของซ้ำ แม้จดหมายเดิมถูกรับหรือลบแล้ว"],en:{title:"Refunded missing Gym Passes",lines:["Checked purchase totals against usage, inventory, storage, mail and any Gold already refunded, then compensated only the still-missing Gym Passes by mail.","Added a permanent compensation record to prevent duplicate mail, even if the original letter was already claimed or deleted."]}},{id:"2026-09-25-restore-shipped-features",date:"2026-09-25",time:"15:58",title:"กู้ระบบที่ตกหล่นจากการอัปเดต",lines:["รวมแพตช์ที่เคยขึ้นเกมกลับมา: ร้าน Silver สำหรับ Premium, Gym Pass, Protection Stone, ตลาดหมดอายุและคืนของ, เดินทางข้ามหลายแมพ และ Hit/Flee ใน PvP โดยรักษาแพตช์ใหม่ไว้","เพิ่มการตรวจสายโค้ดก่อนปล่อยอัปเดตและป้องกัน deploy ซ้อนจากหลายงานในเครื่องเดียวกัน"],en:{title:"Restored features dropped by an update",lines:["Merged back patches that had previously shipped: the Silver Shop for Premium, Gym Pass, Protection Stone, market listing expiry and returns, multi-map travel, and Hit/Flee in PvP, while keeping the newer patches intact.","Added a code-history check before shipping updates, and guarded against overlapping deploys from multiple sessions on the same machine."]}},{id:"2026-09-25-google-link-overwrite-guards",date:"2026-09-25",time:"15:58",title:"ป้องกัน Google เชื่อมไปตัวละครอื่นโดยไม่ตั้งใจ",lines:["ล็อกอิน Google ปกติเข้าตัวละครเดิม แม้มี Guest อื่นค้างในเบราว์เซอร์ · การเลือกตัวละครเปิดเฉพาะเมื่อกดผูก Guest","ปฏิเสธคำขอเลือกตัวละครเก่าหลังลิงก์เปลี่ยนหรือกู้คืน และแยกการ sync ชื่อออกจากการแก้เจ้าของบัญชี"],en:{title:"Prevented Google accidentally linking to another character",lines:["A normal Google login now goes to your original character even with a leftover Guest session in the browser · The character picker only opens when you choose to link a Guest account.","Rejects requests to pick an old character after a link change or recovery, and separated name syncing from account-ownership changes."]}},{id:"2026-09-25-gym-pass-main-restoration",date:"2026-09-25",time:"15:51",title:"คืนระบบ Gym Pass และแก้การบันทึกโบนัสน้ำหนัก",lines:["Gym Pass กลับมาซื้อและใช้ได้ เพิ่มน้ำหนักถาวรใบละ 1,000 สูงสุด 10 ใบ และแสดงจำนวนที่ใช้ในร้านค้า","บันทึกจำนวนที่ใช้ผ่านจุดบันทึกหลัก รวมถึงออกเกม เข้าใหม่ และย้าย Channel พร้อมป้องกันการทิ้ง ทำลาย หรือฝากคลังของไอเทมผูกตัวละคร"],en:{title:"Restored Gym Pass and fixed weight-bonus saving",lines:["Gym Pass can be bought and used again — each one permanently adds 1,000 weight, up to 10 passes, and the shop shows how many you've used.","The used count is now saved through the main save points, including logging out, logging back in and switching channel, and character-bound items are again protected from being dropped, destroyed or stored."]}},{id:"2026-09-25-premium-silver-merchant",date:"2026-09-25",time:"15:51",title:"แก้สิทธิ์ร้าน Silver สำหรับ Premium",lines:["Premium ซื้อและขายกับพ่อค้า Silver ผ่านเมนูได้ทุกที่ โดยตรวจสิทธิ์ตรงกันทั้งหน้าร้านและ Server · ผู้เล่นทั่วไปยังต้องอยู่ใกล้พ่อค้า"],en:{title:"Fixed Premium access to the Silver Shop",lines:["Premium players can buy and sell with the Silver merchant from the menu anywhere, with the shop window and server now checking the same permission · Regular players still need to be near the merchant."]}},{id:"2026-09-25-original-google-recovery",date:"2026-09-25",time:"15:55",title:"ปรับปรุงการกู้สิทธิ์เข้าถึงตัวละคร",lines:["ทีมงานตรวจและคืนการเชื่อมต่อ Google เดิมของตัวละครที่เริ่มจาก Guest ได้ พร้อมล้างสถานะถูกลบที่ค้างหลังการกู้คืน"],en:{title:"Improved character access recovery",lines:["The team can now review and restore a character's original Google link when it started as a Guest, and clears any leftover deleted status after the recovery."]}},{id:"2026-09-25-unknown-inventory-boot-fix",date:"2026-09-25",time:"15:52",title:"แก้หน้าโหลดเกมไม่สำเร็จหลังอัปเดต",lines:["แก้เกมค้างหน้าโหลดเมื่อบัญชีมีไอเท็มจากระบบรุ่นใหม่กว่าตัว Client · ตอนนี้เข้าเกมได้ตามปกติและไอเท็มเดิมไม่สูญหาย"],en:{title:"Fixed the game getting stuck loading after an update",lines:["Fixed the game getting stuck on the loading screen when an account had items from a newer system than the client · You can now log in normally and no items are lost."]}},{id:"2026-09-25-guild-chat-translation-coverage",date:"2026-09-25",time:"15:46",title:"เติมคำแปลส่วนแชทกิลและการ์ดตัวละคร",lines:["ภาษาอังกฤษและภาษาเสริมแสดงชื่อแท็บกิล ช่องพิมพ์ ข้อความแจ้งเตือน และปุ่มย่อการ์ดตัวละครโดยไม่เหลือข้อความไทยปะปน"],en:{title:"Filled in translations for guild chat and the character card",lines:["English and the other supported languages now show the Guild tab name, the message box, notification text and the character card's collapse button without any leftover Thai."]}},{id:"2026-09-25-party-presence-events",date:"2026-09-25",time:"15:24",title:"ปาร์ตี้อัปเดตแมพและ Channel เมื่อสมาชิกย้าย",lines:["ตำแหน่งแมพและ Channel ของสมาชิกปาร์ตี้อัปเดตจาก event ตอนเข้า ออก ย้าย Channel หรือหลุดจากเกม โดยไม่ polling ระหว่างที่ทุกคนยังอยู่ที่เดิม"],en:{title:"Party map and channel update on member movement",lines:["A party member's map and channel now update from events when they join, leave, switch channel or disconnect, instead of polling while everyone stays put."]}},{id:"2026-09-25-party-live-client-overlay",date:"2026-09-25",time:"15:10",title:"ลดโหลดสถานะปาร์ตี้โดยยังเห็นสมาชิกแบบสด",lines:["โบนัสนับเฉพาะสมาชิกในแมพและ Channel เดียวกันเหมือนเดิม","Client ใช้ snapshot ผู้เล่นที่ได้รับอยู่แล้วอัปเดต HP และตำแหน่งสมาชิกใกล้ตัวทุก 50 ms ส่วนข้อมูลปาร์ตี้จาก Server ลดเหลือสูงสุด 2 ครั้งต่อวินาที"],en:{title:"Cut party status load while keeping live member updates",lines:["The bonus still counts only members on the same map and channel, as before.","The client now uses the player snapshots it already receives to update the HP and position of nearby members every 50 ms, while party data from the server is cut to at most twice per second."]}},{id:"2026-09-25-party-exp-drop-label",date:"2026-09-25",time:"14:59",title:"แสดงโบนัส EXP และ Drop ของปาร์ตี้ตามค่าจริง",lines:["แถบปาร์ตี้แยกตัวเลข EXP กับ Drop เมื่อโบนัสไม่เท่ากัน เช่น ผู้เล่นเลเวลสูงสุดจะเห็น EXP +0% · Drop +12% แทนข้อความรวมที่ทำให้เข้าใจว่า Drop เป็น 0%"],en:{title:"Show the party's real EXP and Drop bonus",lines:["The party bar now splits the EXP and Drop numbers when the bonuses differ — the highest-level player, for example, now sees EXP +0% · Drop +12% instead of a combined figure that made Drop look like 0%."]}},{id:"2026-09-25-explorer-show-storage-gear",date:"2026-09-25",time:"14:45",title:"Explorer แสดงอุปกรณ์ในคลังแล้ว",lines:["หน้าตัวละครใน Explorer แสดงชื่อ รูป ขั้น ตีบวก ค่าสถานะ และการ์ดของอุปกรณ์ที่เก็บไว้ในคลังตามปกติ ส่วนอุปกรณ์บนตัวละครยังคงซ่อนอยู่"],en:{title:"Explorer now shows storage gear",lines:["A character's Explorer page now shows the name, image, tier, refine level, stats and cards of gear kept in storage as normal, while equipped gear stays hidden."]}},{id:"2026-09-25-profile-card-click-toggle",date:"2026-09-25",time:"14:44",title:"กดการ์ดตัวละครเพื่อย่อหรือขยาย",lines:["นำปุ่มกากบาทออกจากการ์ดตัวละคร และเปลี่ยนให้กดที่ตัวการ์ดเพื่อย่อหรือเปิดกลับได้โดยตรง"],en:{title:"Tap the character card to collapse or expand",lines:["Removed the X button from the character card, and tapping the card itself now collapses or reopens it directly."]}},{id:"2026-09-25-chat-tabs-single-row",date:"2026-09-25",time:"14:36",title:"แก้แท็บ EXP ในกล่องแชท",lines:["จัดแท็บแชททั้ง 7 หมวดให้อยู่ในแถวเดียวกัน ไม่ให้ EXP ตกลงมาซ้อนใต้แท็บทั้งหมด"],en:{title:"Fixed the EXP tab in the chat box",lines:["Lined up all 7 chat tabs in a single row, so EXP no longer drops down and overlaps beneath the rest."]}},{id:"2026-09-25-guild-chat",date:"2026-09-25",time:"14:25",title:"เพิ่มแชทกิล",lines:["เพิ่มแท็บ “กิล” ในกล่องแชท ส่งข้อความหาสมาชิกกิลได้ข้ามแมพ Channel และภูมิภาค"],en:{title:"Added guild chat",lines:['Added a "Guild" tab to the chat box, so you can message guild members across maps, channels and regions.']}},{id:"2026-09-25-whisper-continuation",date:"2026-09-25",time:"14:19",title:"กระซิบต่อเนื่องได้โดยไม่ต้องเลือกชื่อใหม่",lines:["หลังส่งข้อความกระซิบ ช่องแชทยังคงชื่อผู้รับคนเดิมไว้ พิมพ์ข้อความถัดไปแล้วกด Enter ส่งต่อได้ทันที"],en:{title:"Keep whispering without reselecting the name",lines:["After sending a whisper, the chat box keeps the same recipient's name, so typing the next message and pressing Enter sends it right away."]}},{id:"2026-09-25-on-demand-social-sync",date:"2026-09-25",time:"14:12",title:"ลดการโหลดข้อมูลสังคมเบื้องหลัง",lines:["ข้อมูลสมาชิกปาร์ตี้ต่าง Channel และรายชื่อเพื่อนโหลดใหม่เมื่อเปิดหน้าต่างแทนการตรวจซ้ำตลอดเวลา","กล่องจดหมายใช้การแจ้งเตือนเมื่อมีจดหมายเข้าและหยุดส่ง heartbeat ระหว่างเปิดหน้าต่าง"],en:{title:"Cut background social data loading",lines:["Party members on other channels and the friends list now reload when you open their window instead of being checked constantly.","The mailbox now relies on a notification for incoming mail and stops sending a heartbeat while its window is open."]}},{id:"2026-09-25-auto-loot-items-always-visible",date:"2026-09-25",time:"14:10",title:"แสดงตัวเลือกเก็บไอเท็มทันที",lines:["รายการเลือกเก็บไอเท็มทีละชิ้นใน Auto Play แสดงอยู่เสมอ ไม่ต้องกดเปิด dropdown ก่อนตั้งค่า"],en:{title:"Show item-pickup choices right away",lines:["The per-item loot list in Auto Play now stays visible, instead of needing the dropdown opened before you can configure it."]}},{id:"2026-09-25-guild-load-on-open",date:"2026-09-25",time:"14:02",title:"ลดโหลดระบบกิลเมื่อไม่ได้เปิดหน้าต่าง",lines:["หยุดตรวจข้อมูลกิลทุก 5 วินาทีในทุก Channel และเปลี่ยนเป็นโหลดข้อมูลครั้งเดียวเมื่อผู้เล่นเปิดหน้าต่าง Guild"],en:{title:"Cut guild system load when its window is closed",lines:["Stopped checking guild data every 5 seconds on every channel, and switched to loading it once when a player opens the Guild window."]}},{id:"2026-09-25-changelog-times",date:"2026-09-25",time:"13:58",title:"แสดงเวลาในรายการอัปเดตครบทุกหัวข้อ",lines:["เติมเวลาของรายการอัปเดตที่เคยแสดงเฉพาะวันที่ และป้องกันไม่ให้รายการใหม่ถูกเพิ่มโดยไม่มีเวลาอีก"],en:{title:"Show times on every patch note",lines:["Filled in times for patch notes that previously showed only a date, and stopped new entries from being added without a time again."]}},{id:"2026-09-25-guild-creation-cost-icons",date:"2026-09-25",time:"13:57",title:"เพิ่มไอคอนค่าสร้างกิลด์",lines:["บรรทัดค่าสร้างกิลด์แสดงไอคอน Gold, Silver และ Spirit Shard กำกับแต่ละจำนวนให้อ่านได้ง่ายขึ้น"],en:{title:"Added icons to the guild creation cost",lines:["The guild creation cost line now shows Gold, Silver and Spirit Shard icons next to each amount for easier reading."]}},{id:"2026-09-25-guild-menu-label",date:"2026-09-25",time:"13:56",title:"เพิ่มชื่อกำกับเมนูกิลด์",lines:["ไอคอนตรากิลด์บนแถบเมนูแสดงชื่อ “กิลด์” แล้ว และเปลี่ยนตามภาษาที่เลือกเหมือนเมนูระบบอื่น"],en:{title:"Added a label to the guild menu",lines:['The guild crest icon on the menu bar now shows the label "Guild" and changes with your language setting like every other menu.']}},{id:"2026-09-25-double-attack-all-melee-weapons",date:"2026-09-25",time:"13:53",title:"แก้พาสซีฟ Twin Strike ข้ามอาชีพ",lines:["Twin Strike ที่เรียนจาก Thief กลับมาติดเมื่อเปลี่ยนอาชีพแล้วถืออาวุธประชิดประจำสาย เช่น Hammer, Rod, Staff และ Quarterstaff · Bow และ Kunai ยังเป็นอาวุธระยะไกลจึงไม่ติดตามเงื่อนไขเดิม"],en:{title:"Fixed the Twin Strike passive across classes",lines:["Twin Strike learned as Thief now works again after switching class while wielding a melee weapon for that class, such as Hammer, Rod, Staff or Quarterstaff · Bow and Kunai are still ranged weapons, so they don't trigger it, as before."]}},{id:"2026-09-25-combined-production-release",date:"2026-09-25",time:"13:52",title:"อัปเดตรวมระบบกิล ตลาด และหน้าตัวละคร",lines:["เปิดระบบกิลพร้อมเลเวลและความจุสมาชิก สร้างกิลใช้ 800 Gold, 200,000 Silver และ Spirit Shard 1,000 ชิ้น พร้อมหน้าต่างและไอคอนกิลชุดใหม่","Explorer ซ่อนรายละเอียดอุปกรณ์ของตัวละครในกระเป๋าและคลัง พร้อมข้อความและไอคอนแม่กุญแจ","แก้การแสดงไอเทมที่เก็บและอุปกรณ์จากกล่องให้ตรงกับกระเป๋า พร้อมแสดงราคาจริงก่อนซื้อ Gold ทันที","รวมภาพ Bramble Hare รุ่นใหม่ โดยคงระบบ Gym Pass การป้องกันไอเทมผูกมัด การคืนสินค้าตลาดหมดอายุ และการเดินทาง World Map ต่อเนื่องข้ามแมพ"],en:{title:"Combined update: Guild, Market and character page",lines:["Launched the Guild system with levels and member capacity — creating a guild costs 800 Gold, 200,000 Silver and 1,000 Spirit Shards — along with a new Guild window and icons.","Explorer now hides a character's inventory and storage gear details, showing a message and a padlock icon instead.","Fixed picked-up items and gear from boxes matching what's shown in your inventory, and now shows the real price before an instant Gold purchase.","Merged in the new Bramble Hare artwork, while keeping Gym Pass, bound-item protection, expired market listing returns, and continuous World Map travel across maps."]}},{id:"2026-09-25-guild-menu-icon",date:"2026-09-25",time:"13:34",title:"เพิ่มไอคอนเมนูกิล",lines:["เมนู Guild ใช้ไอคอนโล่ตรากิลสีน้ำเงินขอบทอง เข้าชุดกับเมนูเพื่อนและปาร์ตี้"],en:{title:"Added a guild menu icon",lines:["The Guild menu now uses a blue, gold-trimmed shield crest icon, matching the Friends and Party menus."]}},{id:"2026-09-25-guild-creation-cost",date:"2026-09-25",time:"13:31",title:"เพิ่มค่าใช้จ่ายในการสร้างกิล",lines:["สร้างกิลใช้ 800 Gold, 200,000 Silver และ Spirit Shard 1,000 ชิ้น โดยการเข้าร่วมและค่าอัปเลเวลกิลยังคงเดิม"],en:{title:"Added a cost to create a guild",lines:["Creating a guild now costs 800 Gold, 200,000 Silver and 1,000 Spirit Shards, while joining a guild and the level-up cost stay unchanged."]}},{id:"2026-09-25-explorer-hidden-gear-ui",date:"2026-09-25",time:"13:30",title:"ปรับหน้าซ่อนอุปกรณ์ใน Explorer",lines:["จัดข้อความซ่อนอุปกรณ์ไว้กึ่งกลางกล่อง และเพิ่มไอคอนแม่กุญแจให้มองเห็นสถานะได้ชัดเจนขึ้น"],en:{title:"Adjusted the hidden-gear view in Explorer",lines:["Centered the hidden-gear message in its box and added a padlock icon so the status is clearer at a glance."]}},{id:"2026-09-25-guild-form-alignment",date:"2026-09-25",time:"13:20",title:"แก้ตำแหน่งปุ่มในหน้าต่าง Guild",lines:["จัดปุ่มสร้างกิลและเข้าร่วมกิลให้ตรงกับช่องกรอกชื่อ และใช้ความกว้างเท่ากันทั้งสองแถว"],en:{title:"Fixed button placement in the Guild window",lines:["Aligned the Create Guild and Join Guild buttons with their name fields, and made both rows the same width."]}},{id:"2026-09-25-guild-painted-window",date:"2026-09-25",time:"13:17",title:"ปรับหน้าต่าง Guild ให้เข้าชุดกับ UI เกม",lines:["หน้าต่างกิลใช้กรอบกระดาษ แถบหัวน้ำเงินขอบทอง และปุ่มชุดเดียวกับหน้าต่างเพื่อน พร้อมปรับส่วนเลเวลและรายชื่อให้อ่านง่ายบนมือถือ"],en:{title:"Restyled the Guild window to match the game UI",lines:["The Guild window now uses the same paper frame, blue and gold header bar and buttons as the Friends window, with the level section and member list reworked for easier reading on mobile."]}},{id:"2026-09-25-bramble-hare-v2",date:"2026-09-25",time:"13:13",title:"ปรับภาพ Bramble Hare ให้เข้ากับมอนสเตอร์ตัวอื่น",lines:["Bramble Hare ใช้ภาพใหม่แบบ 3 เฟรม พร้อมขนาด ตำแหน่ง และเอฟเฟกต์การเคลื่อนไหวมาตรฐานเดียวกับมอนสเตอร์ชนิดอื่น"],en:{title:"Updated Bramble Hare's art to match other monsters",lines:["Bramble Hare now uses new 3-frame art, with the same standard size, positioning and movement effects as other monsters."]}},{id:"2026-09-25-guild-levels",date:"2026-09-25",time:"13:05",title:"เปิดระบบกิลและเลเวลกิล",lines:["สร้างหรือเข้าร่วมกิลได้จากเมนู Guild โดยกิล Lv.1 รับสมาชิกได้ 10 คน","หัวหน้ากิลใช้ Spirit Shard อัปเลเวลได้ถึง Lv.10 ทุกเลเวลเพิ่มความจุสมาชิก 5 คน พร้อมจัดการรายชื่อและโอนหัวหน้าเมื่อออกจากกิล"],en:{title:"Launched guilds and guild levels",lines:["You can now create or join a guild from the Guild menu — a Lv.1 guild holds 10 members.","The guild leader can spend Spirit Shards to level up to Lv.10, with each level adding 5 member slots, and can manage the member list and hand off leadership when leaving the guild."]}},{id:"2026-09-25-explorer-hide-equipped-gear",date:"2026-09-25",time:"12:53",title:"Explorer ซ่อนข้อมูลอุปกรณ์ของตัวละคร",lines:["หน้าตัวละครใน Explorer ไม่แสดงรายละเอียดอุปกรณ์ทั้งในกระเป๋าและคลังต่อสาธารณะ และแสดงข้อความกำกับว่าข้อมูลส่วนนี้ถูกซ่อนไว้แทน"],en:{title:"Explorer hides a character's gear details",lines:["A character's Explorer page no longer shows inventory or storage gear details to the public, showing a note that this information is hidden instead."]}},{id:"2026-09-25-loot-inventory-sync",date:"2026-09-25",time:"12:43",title:"แก้ไอเทมที่เก็บและของจากกล่องให้ตรงกับกระเป๋า",lines:["ไอเทมที่เก็บสำเร็จจะแสดงในกระเป๋าพร้อมข้อความเก็บทันที และอุปกรณ์จาก Mystery Relic Box จะแสดงชื่อกับค่าสุ่มของชิ้นเดียวกับที่เข้ากระเป๋า"],en:{title:"Fixed picked-up and box items matching your inventory",lines:["An item you pick up now shows in your inventory along with the pickup message right away, and gear from a Mystery Relic Box shows the same name and rolled stats as the piece that lands in your inventory."]}},{id:"2026-09-25-wiki-independent-deploy",date:"2026-09-25",time:"12:29",title:"Wiki อัปเดตแยกจากเซิร์ฟเวอร์เกมได้แล้ว",lines:["URL /wiki/ ยังเหมือนเดิม แต่การอัปเดต Wiki ครั้งต่อไปไม่ต้องรีสตาร์ตแมพหรือทำให้ผู้เล่นเชื่อมต่อใหม่"],en:{title:"Wiki updates deploy separately from the game server",lines:["The /wiki/ URL stays the same, but the next Wiki update no longer restarts any map or disconnects players."]}},{id:"2026-09-25-gold-buy-now-quote",date:"2026-09-25",time:"12:15",title:"Buy Now แสดงราคาจริงก่อนซื้อ Gold",lines:["ซื้อ Gold ทันทีไม่ต้องกรอกราคา และแสดงจำนวนที่จะได้รับ ราคาเฉลี่ยต่อ Gold และ Silver ที่ต้องจ่ายรวมจากคำสั่งขายที่มีอยู่"],en:{title:"Buy Now shows the real price before buying Gold",lines:["Buying Gold instantly no longer needs a price entered, and shows how much you'll receive, the average price per Gold, and the total Silver cost drawn from the existing sell orders."]}},{id:"2026-09-25-wiki-source-sync",date:"2026-09-25",time:"12:13",title:"Wiki อัปเดตข้อมูลจากระบบเกมล่าสุด",lines:["เพิ่มข้อมูลย่อยอุปกรณ์ Auto Play กระต่ายเก็บของ Party Finder และผลของน้ำหนักเกิน โดยตัวเลขสำคัญอ่านจาก source code เดียวกับเกม"],en:{title:"Wiki data now follows the latest game systems",lines:["Added coverage of gear salvage, Auto Play, the loot-collecting pet, Party Finder and the effects of being overweight, with key numbers read from the same source code as the game."]}},{id:"2026-09-25-gold-trade-mode",date:"2026-09-25",time:"12:10",title:"เลือกซื้อขาย Gold ทันทีหรือตั้ง Order ได้ชัดเจนขึ้น",lines:["ตลาด Gold มีตัวเลือกโหมดซื้อขายทันทีและตั้ง Order ก่อนกรอกข้อมูล พร้อมซ่อนช่องราคาที่ไม่จำเป็นในโหมดทันที"],en:{title:"Clearer choice between instant Gold trades and placing an Order",lines:["The Gold Market now asks you to pick Instant or Order mode before entering details, and hides the price field that instant mode doesn't need."]}},{id:"2026-09-25-regional-chat-sockets",date:"2026-09-25",time:"11:33",title:"เตรียมระบบส่งแชทผ่าน Socket ระดับภูมิภาค",lines:["เพิ่มสวิตช์แยกสำหรับ Socket ระหว่างตัวส่งแชทประจำภูมิภาคและแมพ พร้อมยืนยันการรับและทางสำรองเมื่อเชื่อมต่อไม่ได้","ป้องกันแชทซ้ำเมื่อส่งซ้ำและแสดงสถานะการเชื่อมต่อใน Monitor โดยยังไม่เปิดใช้กับผู้เล่นจริง","เพิ่มคำแปลปุ่มดาวน์โหลดโปรแกรมครบทุกภาษา"],en:{title:"Prepared regional chat over Sockets",lines:["Added a separate switch for the Socket connection between the regional and map chat relays, with delivery confirmation and a fallback if the connection fails.","Prevents duplicate messages on a resend and shows the connection status in the Monitor, though it is not yet enabled for real players.","Added translations for the download button in every language."]}},{id:"2026-09-25-hub-staged-rollout",date:"2026-09-25",time:"11:18",title:"แยกเปิดระบบลดโหลดทีละขั้นและตรวจสถานะใน Monitor",lines:["เริ่มจากเก็บสถิติด้วยรอบตรวจสอบเดิม ก่อนเปิดระบบลดโหลดแต่ละส่วนและย้อนกลับได้แยกกัน","Monitor แสดงสวิตช์ระบบและรุ่นค่าที่แมพรับแล้ว เพื่อช่วยตรวจสอบระหว่างทยอยเปิดใช้งาน"],en:{title:"Staged rollout of load-reduction systems, tracked in Monitor",lines:["Starts by collecting stats on the existing check cycle, before turning on each load-reduction piece separately, with each one revertible on its own.","The Monitor shows each system's switch and the config version each map has picked up, to help track the gradual rollout."]}},{id:"2026-09-25-hub-background-monitor",date:"2026-09-25",time:"11:07",title:"ลดงานเบื้องหลังเซิร์ฟเวอร์และเพิ่มสถานะตรวจสอบระบบ",lines:["ลดการโหลดประวัติแชทและตรวจกล่องจดหมายซ้ำ โดยยังรับการแจ้งเตือนทันทีและตรวจข้อมูลตกหล่นเป็นระยะ","งานส่งข้อมูลที่ยังไม่สำเร็จเว้นช่วงลองใหม่ เพื่อลดโหลดสะสมตอนเซิร์ฟเวอร์ตอบช้า","หน้า Monitor แสดงโหลด HUB คิวงานและอายุข้อมูลรายแมพจากรายงานที่ส่งมา โดยไม่เรียกทุกแมพเมื่อเปิดดู"],en:{title:"Cut server background work and added system status checks",lines:["Reduced repeated loading of chat history and mailbox checks, while still getting instant notifications and periodically checking for anything missed.","Failed data-send jobs now back off before retrying, to keep load from piling up when the server responds slowly.","The Monitor page shows Hub load, job queue size and how stale each map's data is, drawn from reports already sent in, without querying every map when opened."]}},{id:"2026-09-25-joystick-touch-zone",date:"2026-09-25",time:"10:21",title:"จอยสติ๊กไม่รบกวนการแตะกลางจอแล้ว",lines:["จำกัดพื้นที่เรียกจอยสติ๊กลอยไว้เฉพาะโซนมุมซ้ายล่าง แตะพื้นที่ด้านบนหรือกลางจอจะไม่กลายเป็นคำสั่งเดิน","แตะตรงไหนภายในโซนมุมซ้ายล่าง ตรงนั้นจะเป็นจุดกึ่งกลางของจอยสติ๊กเหมือนเดิม"],en:{title:"The joystick no longer interferes with center-screen taps",lines:["Limited the floating joystick's trigger area to the bottom-left corner only — tapping the top or center of the screen no longer turns into a move command.","Tapping anywhere inside the bottom-left zone still centers the joystick there, as before."]}},{id:"2026-09-25-desktop-packaging",date:"2026-09-25",time:"11:40",title:"เตรียมแอป Desktop และตัวติดตั้ง macOS/Windows",lines:["เพิ่มแอป Desktop ที่เปิดเกมออนไลน์โดยไม่หยุด Auto Play เมื่อหน้าต่างถูกบังหรือย่อ พร้อมคำสั่งสร้าง DMG/ZIP สำหรับ macOS และ Installer/Portable สำหรับ Windows","แอปแยกลิงก์ภายนอกไปเปิดในเบราว์เซอร์หลัก ปิด Node integration และไม่อนุญาตสิทธิ์เว็บไซต์ที่ไม่จำเป็น"],en:{title:"Prepared the Desktop app and macOS/Windows installers",lines:["Added a Desktop app that keeps you online with Auto Play running even when the window is covered or minimized, along with build commands for a macOS DMG/ZIP and a Windows Installer/Portable build.","The app opens external links in your default browser, disables Node integration, and denies website permissions it doesn't need."]}},{id:"2026-09-25-world-map-multihop-travel",date:"2026-09-25",time:"11:25",title:"เลือกปลายทางบนแผนที่โลกแล้วเดินทางต่อเนื่องได้",lines:["เมื่อเลือกพื้นที่ที่อยู่ไกล ตัวละครจะเดินผ่านประตูของแต่ละแผนที่ต่อเนื่องจนถึงปลายทาง ไม่ต้องเปิดแผนที่โลกสั่งใหม่ทุกช่วง","การแตะเดินเอง จับจอย หรือเปิด Auto Play จะยกเลิกเส้นทางข้ามแผนที่ทันที"],en:{title:"Pick a destination on the World Map and travel there in one go",lines:["Selecting a distant area now walks your character through each map's portal in sequence all the way to the destination, without reopening the World Map at every step.","Tapping to walk yourself, using the joystick, or starting Auto Play cancels the cross-map route immediately."]}},{id:"2026-09-25-restore-gym-pass-protection",date:"2026-09-25",time:"11:08",title:"แก้การแสดงน้ำหนัก Gym Pass และป้องกันไอเทมผูกตัวละคร",lines:["น้ำหนักสูงสุดในหน้าจอกลับมาแสดงโบนัส Gym Pass ครบตามจำนวนที่ใช้ โดยโบนัสฝั่งเซิร์ฟเวอร์และข้อมูลตัวละครออนไลน์ยังคงอยู่ตามเดิม","Gym Pass, EXP Scroll, Drop Scroll และ Protection Stone กลับมาทิ้ง ทำลาย หรือฝากคลังไม่ได้ตามเงื่อนไขไอเทมผูกตัวละคร","โหมดออฟไลน์กลับมาบันทึกจำนวน Gym Pass ที่ใช้แล้วอย่างถูกต้อง"],en:{title:"Fixed the Gym Pass weight display and character-bound item protection",lines:["The max-weight display now shows the full Gym Pass bonus for however many you've used again, while the server-side bonus and online character data stayed correct all along.","Gym Pass, EXP Scroll, Drop Scroll and Protection Stone can no longer be dropped, destroyed or stored, matching the rules for character-bound items again.","Offline mode now correctly saves the number of Gym Passes used again."]}},{id:"2026-09-25-market-listing-expiry",date:"2026-09-25",time:"10:35",title:"ตลาดกำหนดอายุประกาศขายและส่งของคืนทางจดหมาย",lines:["รายการขายเดิมทั้งหมดจะถูกยกเลิกและส่งสินค้าและอุปกรณ์คืนเจ้าของทางจดหมาย โดยคำสั่งรับซื้อและตลาด Gold ไม่ถูกยกเลิก","ประกาศขายใหม่ของผู้เล่นทั่วไปอยู่ได้ 24 ชั่วโมง ส่วนผู้เล่น Premium อยู่ได้ 48 ชั่วโมง จากนั้นตลาดส่งของที่เหลือคืนทางจดหมายอัตโนมัติ","ผู้เล่นแต่ละคนตั้งขายอุปกรณ์พร้อมกันได้ไม่เกิน 20 ชิ้น","แท็บรายการของฉันแสดงเวลาที่เหลือของประกาศขายแต่ละรายการ และนับถอยหลังจนระบบส่งคืนทางจดหมาย"],en:{title:"Market listings now expire and return items by mail",lines:["All existing sell listings will be cancelled, with the goods and gear returned to their owner by mail; buy orders and the Gold Market are not affected.","A new listing lasts 24 hours for regular players and 48 hours for Premium players, after which the market automatically mails back whatever's left.","Each player can have at most 20 listings active at once.","The My Listings tab shows the remaining time on each listing, counting down until the system mails it back."]}},{id:"2026-09-25-market-restart-sync",date:"2026-09-25",time:"10:24",title:"ตลาดกลับมาแสดงสินค้าได้เร็วหลังเซิร์ฟเวอร์รีสตาร์ต",lines:["แก้หน้าตลาดว่างหรือโหลดค้างหลังเซิร์ฟเวอร์ตลาดรีสตาร์ต โดยไม่บังคับให้ทุกแมพดาวน์โหลดรายการสินค้าทั้งตลาดใหม่พร้อมกัน"],en:{title:"The market loads listings faster after a server restart",lines:["Fixed the market appearing empty or stuck loading after the market server restarts, without forcing every map to redownload the entire market's listings at once."]}},{id:"2026-09-25-completed-session-release",date:"2026-09-25",time:"02:35",title:"รวมอัปเดตจากงานที่เสร็จแล้วทุกชุด",lines:["เพิ่ม Party Finder ข้ามแผนที่และข้ามชาแนล พร้อมปรับหน้าต่างปาร์ตี้ให้อ่านง่ายขึ้น หัวหน้าปาร์ตี้เลือกเปิดรับสมาชิกและรับอัตโนมัติได้","เพิ่ม Break Protection Stone และ Gym Pass พร้อมปรับระบบซื้อและใช้ไอเทมพัฒนาตัวละครให้ปลอดภัยขึ้น","มือถือวางจอยตามจุดแรกที่แตะได้แม่นขึ้น · หน้า Login มีลิงก์ดาวน์โหลดเกม Desktop · หน้าต่างที่เปิดล่าสุดจะแสดงอยู่ด้านหน้าสุด","Auto Play ทำงานต่อได้ขณะเปิด Silver Shop และบอทเว้นช่วงการใช้ Blue Potion เพื่อลดการกดซ้ำ","ปิด Directory Repair อัตโนมัติเพื่อลดความเสี่ยง Hub รีสตาร์ต แต่ทีมงานยังสั่งซ่อมเป็นรายครั้งจากระบบ Support ได้"],en:{title:"Merged updates from every finished session",lines:["Added Party Finder across maps and channels, reworked the Party window for easier reading, and let party leaders choose to open recruitment and auto-accept members.","Added Protection Stone and Gym Pass, and made buying and using character-growth items safer.","The joystick now places itself more accurately at the first touch point on mobile · The Login page has a link to download the Desktop game · The most recently opened window now shows in front.","Auto Play keeps running while the Silver Shop is open, and the bot now spaces out Blue Potion use to cut down on repeat presses.","Turned off automatic Directory Repair to cut the risk of a Hub restart, though the team can still trigger a one-off repair from the Support system."]}},{id:"2026-09-25-directory-repair-paced",date:"2026-09-25",time:"01:34",title:"ระบบซ่อมตำแหน่งตัวละครทำงานเบาลง",lines:["ระบบตรวจหาข้อมูลตัวละครที่อยู่ผิดแผนที่หรือผิดชาแนลกลับมาทำงานอัตโนมัติแบบค่อยเป็นค่อยไป โดยตรวจครั้งละหนึ่งเซิร์ฟเวอร์และเว้นช่วงระหว่างการตรวจ","ช่วยนำผู้เล่นกลับไปยังข้อมูลตัวละครฉบับล่าสุดและเก็บสำเนาเก่า โดยลดภาระที่ Hub ต้องรับในช่วงหลังอัปเดตเซิร์ฟเวอร์"],en:{title:"Character-location repair now runs lighter",lines:["The system that finds character data stuck on the wrong map or channel is automatic again, but now runs gradually — checking one server at a time with a pause between checks.","It moves players back to their latest character data and keeps the old copy, while cutting the load on the Hub right after a server update."]}},{id:"2026-09-25-hub-startup-load-guard",date:"2026-09-25",time:"01:07",title:"เพิ่มการป้องกัน Hub รีสตาร์ตช่วงผู้เล่นเข้าเกมพร้อมกัน",lines:["ลดงานหนักที่ Hub เริ่มเองหลังเปิดเซิร์ฟเวอร์ และจำกัดคิวค้นหาตัวละครเมื่อมีผู้เล่นกลับเข้าเกมพร้อมกัน เพื่อให้เซิร์ฟเวอร์รับการเชื่อมต่อได้เสถียรขึ้น","หากคิวเต็ม ระบบจะให้ลองเชื่อมต่อใหม่ภายหลัง โดยไม่สร้างตัวละครใหม่แทนข้อมูลเดิม"],en:{title:"Added protection against a Hub restart when many players log in at once",lines:["Reduced the heavy work the Hub starts on its own after the server opens, and capped the character-lookup queue when players return all at once, so the server accepts connections more reliably.","If the queue is full, the system asks you to retry later, instead of creating a new character in place of your existing data."]}},{id:"2026-09-25-market-purchase-recovery-hub-reconnect",date:"2026-09-25",time:"00:40",title:"ซื้ออุปกรณ์ในตลาดปลอดภัยขึ้น และเข้าเกมหลังอัปเดตเสถียรขึ้น",lines:["หากซื้ออุปกรณ์แล้วตลาดขาดการเชื่อมต่อ ระบบจะเก็บรายการที่หัก Silver ไว้เพื่อลองทำต่อด้วยรายการเดิม เมื่อได้รับคำตอบจะส่งอุปกรณ์ให้หรือคืน Silver ตามผลจริง","ช่วงเซิร์ฟเวอร์อัปเดตที่ผู้เล่นกลับเข้าเกมพร้อมกัน ระบบจำกัดงานค้นหาตัวละครและกระจายเวลาลองเชื่อมต่อใหม่ เพื่อลดปัญหาเข้าเกมไม่ได้จาก Hub ทำงานหนัก"],en:{title:"Safer market gear purchases, and steadier logins after an update",lines:["If the market disconnects right after Silver is charged for a purchase, the system now holds onto that order to retry it, then delivers the gear or refunds the Silver once it learns the real result.","When players return all at once after a server update, the system now caps character-lookup work and spreads out reconnect attempts, to cut down on failed logins caused by a heavily loaded Hub."]}},{id:"2026-09-24-premium-silver-shop-anywhere",date:"2026-09-24",time:"23:40",title:"Premium เปิดร้าน Silver ได้จากทุกที่",lines:["ผู้เล่น Premium จะเห็นปุ่ม Silver Shop ในเมนู กดซื้อยา อุปกรณ์ หรือขายของในกระเป๋าได้จากทุกแผนที่เหมือนเปิดตลาดกลางจากระยะไกล","เมื่อ Premium หมดอายุ ปุ่มจะหายและหน้าร้านระยะไกลจะปิดเอง ผู้เล่นทั่วไปยังซื้อ–ขายได้ตามเดิมเมื่อเข้าใกล้พ่อค้า Silver"],en:{title:"Premium can open the Silver Shop from anywhere",lines:["Premium players now see a Silver Shop button in the menu, letting them buy potions and gear or sell inventory items from any map, as if opening the merchant remotely.","When Premium expires, the button disappears and the remote shop closes itself; regular players still buy and sell as before by getting close to the Silver merchant."]}},{id:"2026-09-24-pet-pickup-toggle-owner-first",date:"2026-09-24",time:"22:11",title:"กระต่ายเปิด/ปิดการเก็บของได้ และเลือกให้ของเข้าตัวเราก่อนได้",lines:["หน้าต่างสัตว์เลี้ยงมีสวิตช์ “ให้กระต่ายเก็บของ” ปิดแล้วกระต่ายเดินตามเฉยๆ บอทจะเดินไปเก็บของเองเหมือนตอนไม่มีกระต่าย","เลือกได้ว่าของที่เก็บได้เข้า “ตัวเราก่อน” หรือ “กระต่ายก่อน” · ตัวเราก่อน: ของเข้ากระเป๋าเราจนน้ำหนักใกล้ 50% แล้วค่อยเข้ากระต่าย ยาที่ดรอประหว่างเปิดบอทยาวๆ จึงเข้าตัวให้บอทกินต่อได้ และไม่ทำให้ HP/SP หยุดฟื้น","ค่าเริ่มต้นยังเป็นกระต่ายก่อนเหมือนเดิม"],en:{title:"Toggle the pet's pickup and choose to receive loot first",lines:['The Pet window now has a "Let the pet collect loot" switch — turn it off and the pet just follows you, while the bot walks over to collect loot itself, as if you had no pet.','Choose whether loot goes to "you first" or "the pet first" · You first: items go into your own inventory until it nears 50% weight, then overflow to the pet — so potions that drop during a long bot session reach you for the bot to keep using, and HP/SP regen never stalls.',"The default is still pet first, as before."]}},{id:"2026-09-24-market-buy-tab-no-lag",date:"2026-09-24",time:"21:47",title:"หน้าซื้อสินค้าในตลาดไม่หน่วงตอนฟาร์มแล้ว",lines:["เปิดตลาดค้างไว้ระหว่างฟาร์ม หน้าซื้อสินค้าไม่วาดรายการใหม่ทุกครั้งที่ได้ Silver แล้ว เกมไม่หน่วงไม่ค้าง","รายการในตลาดโหลดตอนเปิดหน้าต่าง ตอนเลือกไอเทม และหลังซื้อ ขาย หรือเก็บคืน ถ้าอยากเห็นรายการล่าสุด ปิดแล้วเปิดตลาดใหม่ได้เลย"],en:{title:"The market's Buy tab no longer lags while farming",lines:["Leaving the market open while farming no longer redraws the Buy list every time you gain Silver, so the game no longer lags or freezes.","Market listings now load when you open the window, when you select an item, and after a buy, sell or reclaim · To see the very latest listings, just close and reopen the market."]}},{id:"2026-09-24-overweight-auto-stop-popup",date:"2026-09-24",time:"21:41",title:"Auto หยุดเพราะน้ำหนักเกิน มีหน้าต่างแจ้งก่อนวาร์ป",lines:["ของในกระเป๋าหนักเกิน 90% ตอนเปิด Auto จะมีหน้าต่างบอกว่า Auto หยุดเพราะน้ำหนักเกิน ไม่เด้งเข้าเมืองเฉยๆ อีกแล้ว","นับถอยหลัง 5 วินาทีก่อนใช้ Butterfly Wing กลับเมือง กด “กลับเมืองตอนนี้” หรือ “อยู่ต่อ” ได้ ถ้าไม่ได้กดอะไรจะกลับเมืองเองเหมือนเดิม"],en:{title:"Auto stops on overweight, with a warning before the warp",lines:["When your inventory is over 90% weight, turning on Auto now shows a window saying Auto stopped because of overweight — it no longer just teleports you into town.","A 5-second countdown starts before using Butterfly Wing to return to town; press “Fly to town now” or “Stay here” — if you don't press anything, it still returns you to town on its own as before."]}},{id:"2026-09-24-overweight-debuff-chip",date:"2026-09-24",time:"21:15",title:"น้ำหนักเกินขึ้นเป็นไอคอนดีบัฟแล้ว",lines:["ถือของหนักตั้งแต่ 50% ของน้ำหนักบรรทุก จะมีไอคอน “น้ำหนักเกิน” ขึ้นในแถบบัฟ/ดีบัฟข้างโปรไฟล์ แตะดูได้ว่าโดนอะไรบ้าง","ช่วงนี้ HP/SP ไม่ฟื้นเองแม้นั่งพัก · ถึง 90% โจมตีและใช้สกิลไม่ได้ · เกินลิมิตเดินช้าลงครึ่งหนึ่ง ขายหรือฝากของให้ต่ำกว่า 50% แล้วไอคอนจะหายไป"],en:{title:"Overweight now shows as a debuff icon",lines:["Carrying 50% of your carry weight or more now shows an “Overweight” icon in the buff/debuff bar beside your profile — tap it to see what it's doing to you.","During this: HP/SP don't regenerate even while resting · at 90% you can't attack or use skills · over the limit you walk at half speed. Sell or store items to drop below 50% and the icon disappears."]}},{id:"2026-09-24-login-queue",date:"2026-09-24",time:"20:30",title:"หน้าโหลดบอกจำนวนคนที่รอเข้าเกม",lines:["ช่วงอัปเดตเซิร์ฟเวอร์ที่ทุกคนเข้าเกมพร้อมกัน หน้าโหลดจะบอกว่ามีผู้เล่นกำลังรอเข้าเกมอยู่กี่คน และคุณรอมาแล้วนานเท่าไร",'ระหว่างที่คนรอเยอะ ระบบจะรอให้นานขึ้นก่อนขึ้นว่า "เชื่อมต่อไม่สำเร็จ" ไม่ต้องรีเฟรช ระบบจะพาเข้าเกมเอง'],en:{title:"The loading screen now shows the queue",lines:["During a server update when everyone logs in at once, the loading screen now shows how many players are waiting to get in, and how long you've been waiting.",'While the queue is long, the system waits longer before showing "Connection failed" — no need to refresh, it will bring you into the game on its own.']}},{id:"2026-09-24-destroy-item",date:"2026-09-24",time:"20:08",title:"ทำลายไอเทมทิ้งได้แล้ว",lines:['เปิดรายละเอียดไอเทมในกระเป๋าแล้วกด "ทำลาย" ของจะหายไปเลย ไม่ตกบนพื้น บอทและกระต่ายจะไม่เก็บกลับมาอีก',"ต้องกดยืนยันทุกครั้ง ไอเทมที่ซ้อนกันเลือกจำนวนที่จะทำลายได้ (ค่าเริ่มต้นคือทั้งหมด)","ไอเทมที่ล็อกไว้ ของที่สวมอยู่ และตอนล็อกกระเป๋า ทำลายไม่ได้"],en:{title:"You can now destroy items",lines:[`Open an item's details in your bag and press "Destroy" — it's gone for good, nothing drops on the ground, and the bot and pet rabbit won't pick it back up.`,"You have to confirm every time; for stacked items, choose how many to destroy (default is all).","Locked items, worn gear, and anything while your bag is locked can't be destroyed."]}},{id:"2026-09-24-market-hover-stats",date:"2026-09-24",time:"20:03",title:"ตลาดกลาง: ชี้เมาส์ดูค่าสถานะได้ทุกหน้า",lines:["ชี้เมาส์ที่อุปกรณ์ในหน้าซื้อสินค้า ขายสินค้า และรายการของฉัน จะเห็นค่าสถานะและเทียบกับชิ้นที่สวมอยู่ทันที ไม่ต้องกดดูทีละชิ้น","ไอเทมทั่วไปชี้แล้วเห็นชื่อและคำอธิบาย"],en:{title:"Market: hover to see stats on every page",lines:["Hover over gear on the Buy, Sell and My Listings pages to see its stats compared with what you have equipped instantly — no need to open each piece one by one.","Hovering an ordinary item shows its name and description."]}},{id:"2026-09-24-overweight-penalty",date:"2026-09-24",time:"20:02",title:"แบกของหนักเกินไปมีผลแล้ว",lines:["น้ำหนัก 50% ขึ้นไป: HP/SP ไม่ฟื้นเอง (นั่งพักก็ไม่ฟื้น) ยังกินยาได้ตามปกติ","น้ำหนัก 90% ขึ้นไป: โจมตีและใช้สกิลไม่ได้ Auto Play จะหยุด และใช้ Return Scroll กลับเมืองให้ถ้ามีติดตัว","น้ำหนักเกินลิมิต: เดินช้าลงครึ่งหนึ่ง ต้องกลับไปขายของหรือฝากคลังก่อน","เปลี่ยนอาชีพหรือรีเซ็ตสเตตัสแล้ว STR ลดลง ลิมิตน้ำหนักจะลดตาม ของที่แบกอยู่เลยอาจเกินลิมิตได้"],en:{title:"Carrying too much weight now has real effects",lines:["50% weight and up: HP/SP don't regenerate on their own (resting doesn't help either); you can still drink potions normally.","90% weight and up: you can't attack or use skills, Auto Play stops, and a Return Scroll is used automatically to send you to town if you're carrying one.","Over the weight limit: you walk at half speed; you'll need to go sell items or store them first.","Changing class or resetting your stats lowers STR, so your weight limit drops too — what you're carrying can end up over the new limit."]}},{id:"2026-09-24-world-map-keeps-fighting",date:"2026-09-24",time:"18:47",title:"เปิดแผนที่โลกแล้วยังตีมอนต่อได้",lines:["เปิดแผนที่โลก (M) ตัวละครไม่หยุดแล้ว ยังตีมอนต่อ บอทยังทำงาน กินยา และใช้สกิลได้ตามปกติระหว่างดูแผนที่"],en:{title:"Keep fighting with the World Map open",lines:["Opening the World Map (M) no longer stops your character — you keep attacking, and the bot keeps working, drinking potions and using skills normally while you view the map."]}},{id:"2026-09-24-pet-bag-after-respawn",date:"2026-09-24",time:"18:46",title:"กระเป๋าสัตว์เลี้ยงไม่ว่างหลังตาย/ย้ายแมพ · บอทเดินกลับเข้าวง",lines:["แก้กระเป๋าสัตว์เลี้ยงและคลังขึ้นว่างหลังตายกลับเมืองหรือย้ายแมพ ของไม่ได้หาย แค่หน้าต่างไม่อัปเดตจนกว่ากระต่ายจะเก็บของชิ้นใหม่","บอทที่จำกัดพื้นที่: หลุดออกนอกวง (เช่นมีคนลากมอนผ่าน) จะเดินกลับเข้าวงเอง ไม่ยืนนิ่งอยู่ข้างนอก","มอนนอกวงหรือมอนที่ไม่ได้ติ๊กตีมาโจมตี บอทจะไม่หยุดนิ่งอีกแล้ว"],en:{title:"Pet bag no longer looks empty after death or a map change; leashed bots walk back into range",lines:["Fixed the pet bag and storage showing empty after dying back to town or changing maps — nothing was lost, the window just hadn't refreshed until the rabbit picked up a new item.","Leashed bots: if pulled outside the leash radius (say, someone dragged a monster through), the bot now walks back into range on its own instead of standing still outside it.","The bot no longer freezes up when hit by a monster outside the leash, or one you haven't ticked to attack."]}},{id:"2026-09-24-premium-tooltip-pet",date:"2026-09-24",time:"18:37",title:"คำอธิบาย Premium ครบขึ้น",lines:["ชี้หรือกดไอคอน Premium ตอนนี้บอกสิทธิ์ครบแล้ว: เทรดกับผู้เล่นอื่นได้โดยตรง และสัตว์เลี้ยงกระต่ายเดินตามเก็บของให้ พร้อมกระเป๋าสัตว์เลี้ยง 300 ช่อง น้ำหนัก 5,000"],en:{title:"Premium's full perks now shown",lines:["Hovering or tapping the Premium icon now lists every perk in full: direct trading with other players, plus a pet rabbit that follows and picks up loot for you, with a 300-slot, 5,000-weight pet bag."]}},{id:"2026-09-24-stale-copy-same-level",date:"2026-09-24",time:"18:25",title:"กันตัวละครย้อนกลับตอนย้ายแมพ",lines:["ระบบตรวจข้อมูลตัวละครตอนเข้าแมพละเอียดขึ้น: ดูทั้งเลเวล EXP และจำนวนมอนที่ล่า ไม่ใช่แค่เลเวล","แก้กรณีเลเวลไม่ขึ้นแต่ของที่เก็บมา (รวมกระเป๋าสัตว์เลี้ยง) หายกลับไปเป็นข้อมูลเก่า"],en:{title:"Guards against reverting to an old character copy on a map change",lines:["The character-data check on entering a map is now more thorough: it checks level, EXP and monsters killed, not just level.","Fixed a case where level hadn't changed but collected items (including the pet bag) vanished, reverted to an old data copy."]}},{id:"2026-09-24-explorer-level-board",date:"2026-09-24",time:"18:04",title:"หน้า Explorer มีอันดับ Level แล้ว",lines:['เพิ่มแท็บ "Level สูงสุด" ข้าง Silver และ Gold ในหน้า Explorer เรียงตาม Base Level ถ้าเท่ากันดู EXP',"แสดง 50 อันดับแรก อัปเดตทุก ~5 นาทีเหมือนอันดับเงิน"],en:{title:"Explorer now has a Level ranking",lines:['Added a "Top Level" tab next to Silver and Gold on the Explorer page, ranked by Base Level and, on a tie, by EXP.',"Shows the top 50, updating roughly every 5 minutes like the Silver ranking."]}},{id:"2026-09-24-market-buy-confirm",date:"2026-09-24",time:"14:45",title:"ตลาดกลางถามยืนยันก่อนซื้อทุกครั้ง",lines:['กดซื้อในตลาดกลางแล้วจะมีหน้าต่างบอกชื่อไอเทม ผู้ขาย ราคา และ Silver ที่เหลือหลังซื้อ ต้องกด "ยืนยันซื้อ" อีกครั้งถึงจะซื้อ',"กันกดโดนรายการข้าง ๆ ตอนกระดานขยับ เช่นตั้งใจซื้อชิ้นละ 4,500 แต่ไปโดนชิ้นละ 40,000"],en:{title:"The Market now confirms every purchase",lines:[`Pressing buy in the Market now shows a window with the item's name, seller, price and how much Silver you'll have left — you have to press "Confirm purchase" again to actually buy it.`,"This stops you from hitting the wrong row when the list shifts — like meaning to buy at 4,500 per piece and hitting 40,000 per piece instead."]}},{id:"2026-09-24-card-overwrite",date:"2026-09-24",time:"14:36",title:"ใส่การ์ดทับอุปกรณ์ที่มีการ์ดแล้วได้",lines:["หน้าฝังการ์ดแสดงอุปกรณ์ที่มีการ์ดแล้วด้วย เลือกแล้วใส่การ์ดใหม่ทับได้เลย","การ์ดเดิมจะหายถาวร ไม่ได้คืน · ระบบถามยืนยันอีกครั้งพร้อมบอกชื่อการ์ดที่จะหาย","ใส่การ์ดใบเดียวกับที่ฝังอยู่ทับไม่ได้"],en:{title:"You can now overwrite a card on gear that already has one",lines:["The card-socketing page now also shows gear that already has a card — select it and socket a new card right over it.","The old card is lost for good, it isn't returned · the system asks you to confirm again, naming the card that will be lost.","You can't overwrite a card with another copy of the same card."]}},{id:"2026-09-24-pet-loot-skip",date:"2026-09-24",time:"14:35",title:"แก้กระต่ายเก็บของที่ติ๊กออกไว้",lines:['กระต่ายทำตาม "เลือกทีละชิ้น" ในหน้าต่าง Auto Play แล้ว ของที่ติ๊กออกไว้ เช่น Red Potion กระต่ายจะไม่เก็บ เหมือนที่บอทไม่เก็บ',"เดิมกระต่ายดูแค่ทั้งหมวด (Consumption / ETC / การ์ด / อุปกรณ์) เลยยังเก็บชิ้นที่ติ๊กออกไปด้วย"],en:{title:"Fixed the pet rabbit picking up items you'd unticked",lines:[`The rabbit now follows "Pick item by item" in the Auto Play window — items you've unticked, like Red Potion, are skipped, matching the bot's own behavior.`,"It used to only look at the whole category (Consumption / ETC / Cards / Equipment), so it still picked up pieces you had unticked individually."]}},{id:"2026-09-24-combat-rebalance",date:"2026-09-24",time:"13:57",title:"ปรับสมดุลการต่อสู้: ASPD ดันยากขึ้น ดาเมจมีหลายชั้น สกิลหลากหลายขึ้น ย่อยอุปกรณ์ได้",lines:["ASPD: AGI ทุกแต้มให้ความเร็วเท่ากัน (เดิมช่วงต้นให้เยอะเกิน) · เกิน 180 ได้ครึ่งเดียว · ยา ASPD เปลี่ยนเป็น +3 / +4 / +5 · ASPD จากการ์ด Vine Lynx ไม่ซ้อนกัน · สาย AGI เต็มยังตีเร็วเท่าเดิม","มอนสเตอร์ Lv.20 ขึ้นไปมี DEF/MDEF ตามเลเวล (สูงสุด 30% ที่ Lv.140+) · แมพต้นไม่เปลี่ยน","ออปชันพิเศษใหม่บนอุปกรณ์ดรอป: เจาะกาย เจาะเวท ATK% MATK% ดูดเลือด โจมตีติดแข็ง กันสตัน กันแข็ง ความเร็ววิ่ง (ยิ่งขั้นสูงยิ่งเจอบ่อย)","การ์ดได้เอฟเฟกต์เพิ่ม: Pebble Golem กันสตัน 25% · Frost Puff กันแข็ง 25% · Icicle Hare ติดแข็ง 3% · Forest Wolf / Sand Drake เจาะกาย · Lantern Wisp เจาะเวท · Wild Boar ดูดเลือด · Vine Lynx วิ่งเร็ว · Reed Mantis / Aurora Fox / การ์ดบอส ATK%/MATK%","ธนู: Twin Shot ยิง 4 ฮิต 20% (จาก 43%) · Piercing Shot 600% · Arrow Rain 155% × 10 คูลดาวน์ 5 วิ","พ่อค้า: Gold Strike 450% · Cart Strike 800% คูลดาวน์ 3 วิ · Quake Hammer 280% × 5","เมจ: Stormbreak ร่ายลงที่มอนที่เลือกได้ไกล 240 · Tierra ร่ายนานขึ้นตามจำนวนหอก · Ember Bolt ติดไฟ 15%","โจร: Fleet Foot วิ่งเร็วขึ้น 1.5% ต่อระดับ (สูงสุด 15%)","ช่างตีบวกย่อยอุปกรณ์ที่ไม่ใช้ได้: ได้ Spirit Shard และมีโอกาสได้ Refine Stone ตามขั้นของไอเทม"],en:{title:"Combat rebalance: ASPD harder to stack, layered damage, more varied skills, gear salvage",lines:["ASPD: every point of AGI now grants the same amount of speed (early points used to give too much) · past 180 you only get half as much · ASPD potions changed to +3 / +4 / +5 · ASPD from the Vine Lynx card no longer stacks · full-AGI builds still attack at the same speed as before.","Monsters Lv.20 and up now have DEF/MDEF scaling with level (capped at 30% at Lv.140+) · early maps are unchanged.","New special options on dropped gear: Armor Pierce, Magic Pierce, ATK%, MATK%, Lifesteal, Freeze on Hit, Stun Resist, Freeze Resist, Move Speed (higher tiers roll them more often).","Cards gained extra effects: Pebble Golem Stun Resist 25% · Frost Puff Freeze Resist 25% · Icicle Hare Freeze 3% · Forest Wolf / Sand Drake Armor Pierce · Lantern Wisp Magic Pierce · Wild Boar Lifesteal · Vine Lynx Move Speed · Reed Mantis / Aurora Fox / boss cards ATK%/MATK%.","Archer: Twin Shot now hits 4 times at 20% each (down from 43%) · Piercing Shot 600% · Arrow Rain 155% × 10 hits, 5s cooldown.","Merchant: Gold Strike 450% · Cart Strike 800%, 3s cooldown · Quake Hammer 280% × 5.","Mage: Stormbreak can now be cast on a chosen monster up to 240 range away · Tierra's cast time scales with the number of spears · Ember Bolt has a 15% chance to set the target on fire.","Thief: Fleet Foot now grants 1.5% move speed per rank (up to 15%).","The Blacksmith can now salvage unused gear: get Spirit Shards, plus a chance at a Refine Stone, based on the item's tier."]}},{id:"2026-09-24-party-bonus-display",date:"2026-09-24",time:"13:49",title:"ปาร์ตี้: ตัวเลขโบนัสตรงกับ EXP ที่ได้จริง",lines:["ตัวเลข EXP/Drop +% บนแถบปาร์ตี้ไม่นับสมาชิกที่ตายอยู่แล้ว เลยตรงกับที่ได้จริงเวลาคุณตีแรงสุด","สมาชิกเลเวลสูงสุดไม่รับส่วนแบ่ง Base EXP ของปาร์ตี้อีก (เดิมได้ส่วนแบ่งไปแต่ใช้ไม่ได้ EXP ส่วนนั้นเลยหายไปเฉย ๆ) EXP ไปอยู่กับเพื่อนที่ยังเก็บเลเวลแทน","สมาชิกเลเวลสูงสุดยังได้ Job EXP จากดาเมจที่ตัวเองตี และยังนับโบนัส Drop เหมือนเดิม"],en:{title:"Party: bonus numbers now match the EXP you actually get",lines:["The EXP/Drop +% shown on the party bar no longer counts members who are dead, so it now matches what you actually get when you're hitting hardest.","The highest-level member no longer takes a share of the party's Base EXP (it used to take a share it couldn't use, so that EXP just vanished) — that EXP now goes to friends who are still leveling instead.","The highest-level member still gets Job EXP from the damage they deal, and still counts toward the Drop bonus as before."]}},{id:"2026-09-24-bot-loot-per-item",date:"2026-09-24",time:"13:44",title:"บอทเลือกเก็บของทีละชิ้นได้",lines:['หน้าต่าง Auto Play › ไอเท็มที่เก็บ มีหัวข้อ "เลือกทีละชิ้น" ติ๊กออกเฉพาะของที่ไม่อยากเก็บ เช่น Red Potion ส่วนยาอื่นยังเก็บตามปกติ',"แยกได้ทุกชิ้นในหมวด Consumption และ ETC ถ้าปิดทั้งหมวดไว้ บอทก็ไม่เก็บทั้งหมวดเหมือนเดิม","ตั้งค่าเดิมไม่เปลี่ยน ทุกชิ้นยังติ๊กเก็บอยู่จนกว่าจะเอาออกเอง"],en:{title:"The bot can now pick loot item by item",lines:[`Auto Play > Items to collect now has a "Pick item by item" section — untick just the items you don't want, like Red Potion, and other potions are still collected as usual.`,"Every item in the Consumption and ETC categories can be split out individually; turning off a whole category still stops the bot from collecting it, as before.","Existing settings are unchanged — every item stays ticked to collect until you untick it yourself."]}},{id:"2026-09-24-max-level-exp-log",date:"2026-09-24",time:"13:42",title:"เลเวล 99 ไม่ขึ้น Base EXP ในบันทึกแล้ว",lines:["ตัวละครเลเวล 99 ตีมอนแล้วบันทึก EXP จะแสดงเฉพาะ Job EXP ที่ได้จริง ไม่ขึ้น Base EXP ที่ไม่ได้นับแล้ว"],en:{title:"Level 99 no longer shows Base EXP in the log",lines:["At level 99, the EXP log after hitting a monster now shows only the Job EXP you actually got, not the Base EXP that no longer counts."]}},{id:"2026-09-24-party-even-share",date:"2026-09-24",time:"13:22",title:"ปาร์ตี้หาร EXP เท่ากัน และขยายช่วงเลเวลเป็น 20",lines:["EXP จากมอนที่ปาร์ตี้ตีตาย หารเท่ากันให้สมาชิกทุกคนที่อยู่แมพเดียวกันและยังไม่ตาย ไม่ต้องตีเองก็ได้ส่วนแบ่ง (เดิมใครตีเท่าไหร่ได้เท่านั้น)","ช่วงเลเวลขยายจาก 10 เป็น 20: สมาชิกที่เลเวลห่างเกิน 20 จากคนที่ตีมอนตัวนั้นหนักสุด จะไม่ได้ส่วนแบ่งและไม่นับโบนัส ได้แค่ EXP จากดาเมจที่ตัวเองตี","โบนัส EXP/Drop ยังเป็น +2% ต่อคนที่ได้ส่วนแบ่ง สูงสุด 12 คน","หน้าต่างปาร์ตี้ขึ้นเลเวลสีแดงพร้อม ⚠ ที่สมาชิกซึ่งห่างเกิน 20 และแจ้งในแชทตอนเข้าปาร์ตี้"],en:{title:"Party EXP now splits evenly, and the level range is now 20",lines:["EXP from a monster the party kills now splits evenly among every member on the same map who is still alive — you don't have to land a hit yourself to get a share (it used to be based purely on your own damage).","The level range widened from 10 to 20: a member more than 20 levels away from whoever dealt the most damage to that monster gets no share and no bonus, only EXP from their own damage.","The EXP/Drop bonus is still +2% per member who gets a share, up to 12 people.","The party window shows a member's level in red with a ⚠ when they're more than 20 levels away, and announces it in chat when they join the party."]}},{id:"2026-09-24-aspd-skill-hold",date:"2026-09-24",time:"12:23",title:"สกิล ASPD ออกทันใจขึ้น กดค้างเพื่อใช้ต่อเนื่องได้",lines:["Power Strike, Twin Shot, Gold Strike, Twin Fang: กดค้างปุ่มลัดหรือปุ่มบนจอ สกิลจะออกต่อเนื่องเร็วเท่าการโจมตีปกติ","กดสกิลก่อนคูลดาวน์หมดไม่เกิน 0.4 วินาที เกมจะจำไว้แล้วใช้ให้ทันทีที่พร้อม ไม่ต้องกดซ้ำ (ทุกสกิล)","มีเป้าหมายอยู่แล้ว กดปุ่มลัดสกิลโจมตีจะใช้ใส่เป้าหมายนั้นทันที ไม่ต้องคลิกมอนสเตอร์อีกรอบ","ใช้สกิลกลางจังหวะฟัน ดาเมจของการฟันครั้งนั้นยังเข้าครบ ไม่หายไปแล้ว","บอท Auto Play ใช้สกิล ASPD ได้ถี่เท่าความเร็วโจมตีจริง ไม่ข้ามรอบแล้ว"],en:{title:"ASPD skills fire faster and can be held down",lines:["Power Strike, Twin Shot, Gold Strike, Twin Fang: hold the hotkey or the on-screen button and the skill fires repeatedly as fast as a normal attack.","Press a skill up to 0.4 seconds before its cooldown ends and the game remembers it, firing it the instant it's ready — no need to press again (every skill).","With a target already selected, pressing an attack skill's hotkey uses it on that target immediately — no need to click the monster again.","Using a skill mid-swing no longer loses that swing's damage — it still lands in full.","Auto Play's bot can now use ASPD skills as often as your real attack speed allows, no longer skipping cycles."]}},{id:"2026-09-24-bag-toolbar-weight",date:"2026-09-24",time:"12:07",title:"ปุ่มกระเป๋าบอก % น้ำหนักด้วย",lines:["มุมปุ่มกระเป๋าบนแถบเมนูบอกว่าใช้น้ำหนักไปกี่ % แล้ว เหมือนปุ่มสัตว์เลี้ยง สีเขียวปกติ สีส้มตั้งแต่ 70% สีแดงตั้งแต่ 90%","ชี้เมาส์ค้างที่ปุ่มจะเห็นน้ำหนักเป็นตัวเลขเต็ม ๆ"],en:{title:"The bag button now shows weight %",lines:["The corner of the bag button on the menu bar now shows how much weight you've used, just like the pet button — green as normal, orange from 70%, red from 90%.","Hold your mouse over the button to see the exact weight number."]}},{id:"2026-09-24-referral-link",date:"2026-09-24",time:"11:04",title:"ชวนเพื่อนมาเล่น รับ 300 Gold + EXP Scroll และ Drop Scroll อย่างละ 3",lines:['เปิด Shop → แท็บ "ชวนเพื่อน" แล้วคัดลอกลิงก์ของคุณส่งให้เพื่อน',"เพื่อนที่เข้าเกมผ่านลิงก์และเติมเงินรวมครบ 600 บาท คุณได้รับ 300 Gold, EXP Scroll 3 ม้วน และ Drop Scroll 3 ม้วน ทางกล่องจดหมาย","ได้รางวัลจากเพื่อนทุกคนที่ชวนมา คนละ 1 ครั้ง · ลิงก์ใช้ได้กับบัญชีใหม่ที่เริ่มเล่นไม่เกิน 7 วัน","ยอดจะนับเมื่อเพื่อนกดรับ Gold จากจดหมายแล้ว รายการที่ขอคืนเงินไม่นับ"],en:{title:"Invite a friend for 300 Gold + 3 EXP Scrolls and 3 Drop Scrolls",lines:['Open Shop → the "Invite Friends" tab and copy your link to send to a friend.',"When a friend joins through your link and tops up 600 Baht total, you get 300 Gold, 3 EXP Scrolls and 3 Drop Scrolls by mail.","You get a reward from every friend you invite, once per friend · the link only works for new accounts that started within the last 7 days.","The count only updates once a friend claims the Gold from the mail; refunded top-ups don't count."]}},{id:"2026-09-24-pet-wander-offline",date:"2026-09-24",time:"10:59",title:"กระต่ายเดินเล่นเองได้แล้ว และมีในโหมดออฟไลน์",lines:["ตอนไม่มีของให้เก็บ กระต่ายจะเดินเล่นดมนั่นดมนี่รอบตัวเจ้าของ ไม่เดินติดหลังตลอดเวลาแล้ว","ถ้าเจ้าของเดินไปไกล กระต่ายจะรีบวิ่งตามมาทันที","แก้กระต่ายเดินสั่น/หันไปมาบางจังหวะ ตอนนี้เดินนิ่งและหันตามทิศที่เดินจริง","โหมดออฟไลน์: มี Gold 10,000 เติมกลับให้ทุกครั้งที่เข้าเกม ซื้อ Premium ได้ และมีกระต่ายเก็บของเหมือนออนไลน์ (เป็นโหมดทดลองเล่น ไม่มีผลกับตัวละครออนไลน์)"],en:{title:"The pet rabbit now wanders on its own, and it's in offline mode too",lines:["With nothing to pick up, the rabbit now wanders around sniffing at things near its owner instead of always walking right behind them.","If its owner walks far away, the rabbit rushes to catch up right away.","Fixed the rabbit jittering or turning oddly at times — it now walks smoothly and faces the direction it's actually moving.","Offline mode: you get 10,000 Gold refilled every time you log in, can buy Premium, and have a loot-collecting pet rabbit just like online (it's a practice mode with no effect on your online character)."]}},{id:"2026-09-24-starter-pack-kunai",date:"2026-09-24",time:"10:46",title:"Starter Pack มี Lumina Kunai แล้ว · คนที่ซื้อไปก่อนได้รับทางจดหมาย",lines:["Starter Pack มีอาวุธครบทุกสาย รวม Lumina Kunai สำหรับ Mamushi ด้วย","ใครซื้อ Starter Pack ไปก่อนที่จะมีคุไน จะได้รับ Lumina Kunai 1 ชิ้นทางจดหมายเมื่อเข้าเกมครั้งถัดไป เปิดกล่องจดหมายแล้วกดรับได้เลย","คุไนนี้ผูกกับตัวละครเหมือนชิ้นอื่นในแพ็ก ซื้อขายและเทรดไม่ได้"],en:{title:"Starter Pack now includes Lumina Kunai; earlier buyers get it by mail",lines:["The Starter Pack now covers every class's weapons, including Lumina Kunai for Mamushi.","Anyone who bought the Starter Pack before the kunai was added will get 1 Lumina Kunai by mail the next time they log in — open your mailbox and claim it.","This kunai is bound to your character like the rest of the pack's items — it can't be sold or traded."]}},{id:"2026-09-24-pet-toolbar-weight",date:"2026-09-24",time:"10:38",title:"ปุ่มสัตว์เลี้ยงขึ้นแถบเมนูหลัก พร้อมบอก % น้ำหนัก",lines:['ปุ่ม "สัตว์เลี้ยง" ย้ายออกจากเมนู ☰ มาอยู่บนแถบเมนูหลักแล้ว',"มุมปุ่มบอกว่ากระเป๋ากระต่ายใช้น้ำหนักไปกี่ % แล้ว สีเขียวปกติ สีส้มตั้งแต่ 70% สีแดงตั้งแต่ 90% ใกล้เต็มจะได้รู้ก่อน","กด P เปิด/ปิดกระเป๋าสัตว์เลี้ยงได้เลย"],en:{title:"The pet button moved to the main menu bar, with weight %",lines:['The "Pet" button has moved out of the ☰ menu and onto the main menu bar.',"The corner of the button now shows how much weight the rabbit's bag has used — green as normal, orange from 70%, red from 90%, so you'll know before it fills up.","Press P to open or close the pet bag directly."]}},{id:"2026-09-24-premium-loot-pet",date:"2026-09-24",time:"10:10",title:"Premium ได้สัตว์เลี้ยงเก็บของ: กระต่ายเดินตามและเก็บของให้",lines:["ผู้เล่นที่มี Premium จะมีกระต่ายเดินตาม คอยวิ่งไปเก็บของที่ดรอปรอบตัวให้เองโดยไม่ต้องเดินไปเก็บเอง",'กระต่ายเก็บตามหมวดที่ติ๊กไว้ใน ตั้งค่าบอท → เก็บของ (ยา / อื่นๆ / การ์ด / อุปกรณ์) และจะเก็บของคนอื่นเฉพาะเมื่อเปิด "เก็บของผู้เล่นอื่น" ไว้',"กระต่ายมีกระเป๋าของตัวเอง 300 ช่อง น้ำหนัก 5,000 เมื่อเต็มแล้วของที่เก็บได้จะเข้ากระเป๋าคุณแทน",'เปิดดูและหยิบของจากกระต่ายได้ที่ปุ่ม "สัตว์เลี้ยง" ในเมนู หยิบได้ทุกที่ และยังหยิบได้แม้ Premium หมดแล้ว',"ขณะกระต่ายอยู่ด้วย Auto Play จะล่ามอนต่อไปเลย ไม่เดินไปเก็บของเอง"],en:{title:"Premium now gets a loot-collecting pet: a rabbit that follows and picks up items for you",lines:["Players with Premium now have a pet rabbit that follows them and automatically runs to collect nearby drops, so you don't have to walk over and pick them up yourself.",`The rabbit only picks up categories ticked in Bot Settings → Loot (Potions / Other / Cards / Equipment), and only picks up other players' drops when "Pick up other players' items" is turned on.`,"The rabbit has its own 300-slot, 5,000-weight bag; once it's full, anything it picks up goes straight into your bag instead.",`Open the rabbit's bag and take items from it via the "Pet" button in the menu — you can grab items anywhere, and even after Premium has expired.`,"While the rabbit is with you, Auto Play keeps hunting monsters instead of walking off to collect loot itself."]}},{id:"2026-09-24-ip-account-limit-back",date:"2026-09-24",time:"10:06",title:"กลับมาจำกัด 1 เครื่อง (1 IP) เข้าเกมพร้อมกันได้ไม่เกิน 3 ไอดี",lines:["เครื่องเดียวกัน — นับจากหมายเลข IP ที่ต่อเข้าเซิร์ฟเวอร์ — เข้าเกมพร้อมกันได้สูงสุด 3 ไอดีเหมือนเดิม ไอดีที่ 4 จะเข้าไม่ได้ และมีข้อความบอกเหตุผล","บ้านที่เล่นหลายคนด้วยเน็ตเส้นเดียวกัน หรือใช้เน็ตมือถือที่ IP ซ้ำกัน อาจถูกนับเป็นเครื่องเดียว ถ้าเข้าไม่ได้ทั้งที่ไม่ได้เปิดหลายไอดี แจ้งแอดมินได้เลย"],en:{title:"Back to a 3-account limit per machine (IP)",lines:["The same machine — counted by the IP address connecting to the server — can log in with up to 3 accounts at once as before; a 4th account is blocked, with a message explaining why.","Households where several people share one internet connection, or mobile data with a shared IP, may get counted as one machine. If you can't log in even though you're not running multiple accounts, please contact an admin."]}},{id:"2026-09-24-ground-gear-icon",date:"2026-09-24",time:"10:00",title:"อุปกรณ์ที่ตกบนพื้นโชว์รูปตรงกับของจริง",lines:["แก้บัคที่อุปกรณ์ตกบนพื้นเป็นรูปดาบ (หรือรูปทั่วไปของช่องนั้น) แต่เก็บเข้ากระเป๋าแล้วกลายเป็นค้อน มีด ไม้เท้า ฯลฯ ตอนนี้รูปบนพื้นตรงกับของที่จะได้เลย"],en:{title:"Gear on the ground now shows the right icon",lines:["Fixed a bug where gear dropped on the ground showed as a sword (or that slot's generic icon), but turned into a hammer, dagger, staff, etc. once picked up — the ground icon now matches the item you'll actually get."]}},{id:"2026-09-24-share-item-party",date:"2026-09-24",time:"09:52",title:"แชร์ไอเทมลงแชทปาร์ตี้ได้แล้ว",lines:['ปุ่ม "แชร์ลงแชท" ในรายละเอียดไอเทมเคยส่งไปแชทโลกเสมอ ตอนนี้ถ้าเปิดแท็บปาร์ตี้ค้างไว้ ไอเทมจะไปที่แชทปาร์ตี้แทน แท็บอื่นยังส่งลงแชทโลกเหมือนเดิม'],en:{title:"You can now share items to party chat",lines:[`The "Share to chat" button in an item's details used to always send it to world chat; now, if you have the party tab open, the item goes to party chat instead — other tabs still send it to world chat as before.`]}},{id:"2026-09-24-market-price-keyboard",date:"2026-09-24",time:"09:51",title:"ตั้งราคาขายในตลาดบนมือถือได้แล้ว",lines:["แก้บัคที่แตะช่องราคาหรือจำนวนในตลาดแล้วแป้นพิมพ์เด้งขึ้นแล้วปิดทันที ทำให้พิมพ์ราคาขายไม่ได้ ตอนนี้แป้นพิมพ์ค้างอยู่จนพิมพ์เสร็จ"],en:{title:"Setting a sale price on mobile Market now works",lines:["Fixed a bug where tapping the price or quantity field in the Market popped up the keyboard and then closed it immediately, making it impossible to type a sale price — the keyboard now stays open until you finish typing."]}},{id:"2026-09-24-far-sight-opening-range",date:"2026-09-24",time:"09:36",title:"Far Sight ของนักธนู: ท่ายิงไม่หน่วงแล้ว",lines:["Far Sight เพิ่มระยะยิงธนู 6 ต่อระดับ ทุกนัด (Lv.10 ยิงได้จาก 260 แทน 200) ใช้ได้จริงมาตลอด ที่ดูเหมือนไม่ไกลขึ้นเพราะมอนที่โดนยิงจะวิ่งเข้ามาหา ลองยิงมอนตัวใหม่หรือถอยออกมาก่อนยิงจะเห็นระยะที่เพิ่มชัด","ยิงจากระยะที่ได้จาก Far Sight แล้วท่ายิงออกทันที ไม่ต้องรอเซิร์ฟเวอร์ก่อนเหมือนเดิม"],en:{title:"Archer's Far Sight: the shot no longer feels delayed",lines:["Far Sight adds 6 range per rank to every shot with a bow (Lv.10 shoots from 260 instead of 200) and has always worked — it looked like it wasn't reaching further because a monster you shoot runs toward you. Try shooting a fresh monster, or back away before shooting, to see the extra range clearly.","Shooting from the range Far Sight grants now fires the shot immediately, instead of waiting on the server first like before."]}},{id:"2026-09-24-explorer-dressed",date:"2026-09-24",time:"09:34",title:"หน้า Explorer แต่งใหม่ มีหน้าตัวละครตามอาชีพ",lines:["หน้า Explorer (lumivaraonline.com/explorer) มีฉากปราสาทเป็นพื้นหลัง กล่องและตารางแบบกรอบทองน้ำเงิน","ตารางอันดับมีไอคอนหน้าตัวละครตามอาชีพหน้าชื่อ และมงกุฎทอง เงิน ทองแดงให้อันดับ 1-3","หน้าโปรไฟล์ตัวละครก็โชว์หน้าอาชีพของตัวละครนั้นด้วย"],en:{title:"Explorer page redressed, with class portraits",lines:["The Explorer page (lumivaraonline.com/explorer) now has a castle scene as its background, with gold-and-blue framed boxes and tables.","The ranking table shows a class portrait icon next to each name, plus gold, silver and bronze crowns for ranks 1–3.","The character profile page also shows that character's class portrait."]}},{id:"2026-09-24-no-ip-account-limit",date:"2026-09-24",time:"09:19",title:"ยกเลิกการจำกัด 3 ไอดีต่อเครื่อง (IP)",lines:['เครื่องเดียวกันหรือเน็ตเส้นเดียวกันเข้าเกมพร้อมกันได้กี่ไอดีก็ได้แล้ว ไม่มีข้อความ "เข้าเกมพร้อมกันได้สูงสุด 3 ไอดี" อีก',"บ้านที่เล่นหลายคน หรือใช้เน็ตมือถือที่ IP ซ้ำกัน ไม่ถูกกันออกแล้ว"],en:{title:"The 3-account-per-machine (IP) limit is removed",lines:['Any number of accounts can now log in at once from the same machine or the same internet connection — the "up to 3 accounts at once" message is gone.',"Households with several players, or mobile data with a shared IP, are no longer blocked."]}},{id:"2026-09-24-sixty-four-channels",date:"2026-09-24",time:"09:19",title:"แมปเปิดช่องได้ถึง 64 ช่อง",lines:["ขยายเพดานจาก 32 เป็น 64 ช่องต่อหนึ่งแมป เตรียมไว้ก่อนคนเล่นจะเพิ่มขึ้นอีก แมปยอดนิยมจะได้ไม่แน่นจนกระตุก","ช่องใหม่ยังเปิดเองเมื่อคนแน่นและปิดเองเมื่อคนออกหมดเหมือนเดิม"],en:{title:"Maps can now open up to 64 channels",lines:["Raised the cap from 32 to 64 channels per map, ahead of the player count growing further, so popular maps won't get crowded enough to lag.","New channels still open on their own when a map gets crowded and close on their own once everyone leaves, as before."]}},{id:"2026-09-24-more-menu-site-pages",date:"2026-09-24",time:"08:42",title:"FAQ, บันทึกการอัปเดต และ Explorer อยู่ในเมนูเพิ่มเติมแล้ว",lines:["กดปุ่ม ☰ เพิ่มเติม บนแถบเมนู จะเห็นไอคอนใหม่ 3 อัน ต่อจาก Discord และ Wiki: FAQ (คำถามที่พบบ่อย), อัปเดต (บันทึกการอัปเดตย้อนหลัง) และ Explorer","กดแล้วเปิดหน้านั้นในแท็บใหม่ ไม่ต้องออกจากเกม"],en:{title:"FAQ, the patch notes and Explorer are now in the More menu",lines:["Press the ☰ More button on the menu bar and you'll see 3 new icons after Discord and Wiki: FAQ (frequently asked questions), Updates (past patch notes) and Explorer.","Pressing one opens that page in a new tab, without leaving the game."]}},{id:"2026-09-24-faq-links",date:"2026-09-24",time:"08:22",title:"ลิงก์ไปหน้า FAQ จากทุกหน้า",lines:["หน้าล็อกอินและหน้าโหลดเกมมีลิงก์ FAQ แล้ว (หน้ารวมคำถามที่ถามบ่อยพร้อมคำตอบ)","บนมือถือ เปิดหน้าต่าง Settings จะเห็นปุ่ม FAQ ต่อจาก Discord และ Wiki · หน้า Explorer ก็มีลิงก์ FAQ แล้ว","บอทตอบคำถามในแชทรู้จักหน้า /faq/ แล้ว จะแนะนำให้ผู้เล่นที่ถามเรื่องพื้นฐานไปอ่านได้"],en:{title:"FAQ links added on every page",lines:["The login and loading screens now have an FAQ link (a page of the most frequently asked questions, with answers).","On mobile, opening the Settings window shows an FAQ button after Discord and Wiki · the Explorer page also has an FAQ link now.","The chat-support bot now recognizes /faq/ pages and will point players asking basic questions there."]}},{id:"2026-09-24-miss-readable",date:"2026-09-24",time:"08:10",title:"ตีวืดเห็นคำว่า MISS ชัดขึ้น",lines:["คำว่า MISS ตอนตีไม่โดนหรือหลบได้ ใหญ่เท่าตัวเลขดาเมจแล้ว มีขอบเข้มและเด้งขึ้นให้เห็น ไม่เล็กจนกลืนไปกับฉากเหมือนก่อน · โอกาสตีโดนขึ้นกับ HIT (DEX, LUK, ของสวมใส่) เทียบกับ FLEE ของมอนสเตอร์ มอนเลเวลสูงหลบเก่งขึ้น"],en:{title:"MISS is now easier to read on a whiff",lines:["The word MISS on a whiffed or dodged attack is now as large as the damage numbers, with a bold outline and a pop-up animation — no longer small enough to blend into the background as before · your hit chance depends on HIT (DEX, LUK, gear) against the monster's FLEE, and higher-level monsters dodge better."]}},{id:"2026-09-24-faq-fil-id",date:"2026-09-24",time:"08:06",title:"หน้า FAQ อ่านเป็นภาษาฟิลิปปินส์และอินโดนีเซียได้แล้ว",lines:["หน้า /faq/ เพิ่มปุ่มภาษา FIL (Filipino) และ ID (Bahasa Indonesia) นอกจากไทยและอังกฤษ เปิดหน้าครั้งแรกจะเลือกภาษาตามเครื่องให้อัตโนมัติ","แก้คำตอบเรื่อง Mamushi ให้ตรงกับเกมตอนนี้: เป็นสายตีไกล ขว้าง Viper Kunai และเน้นอัป DEX เหมือนธนู"],en:{title:"The FAQ page now reads in Filipino and Indonesian",lines:["The /faq/ page adds FIL (Filipino) and ID (Bahasa Indonesia) buttons alongside Thai and English; opening the page for the first time picks a language based on your device automatically.","Fixed the Mamushi answer to match the current game: it's a ranged attacker who throws Viper Kunai and focuses on DEX like an Archer."]}},{id:"2026-09-24-hold-to-add-stats",date:"2026-09-24",time:"08:06",title:"กดค้างปุ่ม + เพื่ออัปสถานะรัวๆ ได้แล้ว",lines:["ในหน้าต่าง Status กดค้างที่ปุ่ม + แล้วแต้มจะขึ้นต่อเนื่องจนกว่าจะปล่อยหรือแต้มหมด · มีหน่วงสั้นๆ ก่อนเริ่มรัว แตะครั้งเดียวยังได้ 1 แต้มเหมือนเดิม"],en:{title:"You can now hold the + button to add stat points repeatedly",lines:["In the Status window, hold the + button and points keep rising until you release it or run out of points · there's a short delay before it starts repeating; a single tap still adds 1 point as before."]}},{id:"2026-09-24-faq-page",date:"2026-09-24",time:"07:57",title:"หน้าคำถามที่พบบ่อย (FAQ) มาแล้ว",lines:["เปิดหน้า /faq/ รวม 30 คำถามที่ผู้เล่นถามในแชทบ่อยที่สุด เรียงจากที่ถามกันมากสุด เช่น อัปสเตตัสอะไรดี เปลี่ยนอาชีพ ย้ายแนล ตั้งบอท การ์ด และตีบวก","อ่านได้ทั้งภาษาไทยและภาษาอังกฤษ ค้นหาคำถามได้ และส่งลิงก์ไปที่คำถามข้อไหนก็ได้ให้เพื่อน","มีลิงก์ FAQ เพิ่มใน Wiki หน้าบันทึกการอัปเดต และหน้าข้อตกลงด้วย"],en:{title:"The FAQ page has arrived",lines:["Open the /faq/ page for 30 of the questions players ask most often in chat, sorted by how often they're asked — things like which stats to raise, changing class, moving to a new map, bot setup, cards and refining.","Readable in both Thai and English, searchable, and you can send a friend a link straight to any question.","FAQ links were also added to the Wiki, the patch-notes page and the terms page."]}},{id:"2026-09-24-mamushi-class",date:"2026-09-24",time:"07:37",title:"อาชีพใหม่: Mamushi นักฆ่างูพิษ",lines:["อาชีพที่ 7 มาแล้ว! Mamushi (มามุชิ) นักฆ่างูพิษสายโจมตีระยะไกล เปลี่ยนได้ที่หน้าต่างเปลี่ยนอาชีพหลัง Novice Job Lv.10","ฝังพิษงูซ้อนได้ 5 ชั้น ทำดาเมจทุกวินาทีตาม ATK และบอสโลกก็โดนเต็ม ๆ ไม่ลดเหลือ 1/10","7 สกิล: Viper Fang, Dokugiri (หมอกพิษรอบตัว), Venom Rupture (ระเบิดพิษทุกชั้น ครบ 5 ชั้นติดสตัน), Dokunuri (ชุบพิษอาวุธ) และพาสซีฟ Venom Mastery, Numbing Toxin, Predator's Patience","อาวุธประจำอาชีพ Viper Kunai ขว้างโจมตีจากระยะไกล (สั้นกว่าธนูเล็กน้อย) ดาเมจคิดจาก DEX เหมือนธนู ซื้อได้ที่ร้านค้า 100 Silver และดรอปจากมอนสเตอร์ทุกตัวแบบมีระดับ (tier) เหมือนอาวุธอาชีพอื่น","Starter Pack มี Lumina Kunai เพิ่มสำหรับ Mamushi (คนที่ซื้อไปแล้วซื้อ Viper Kunai ที่ร้านค้าได้เลย)"],en:{title:"New class: Mamushi, the venomous-snake assassin",lines:["The 7th class has arrived! Mamushi, a ranged pit-viper assassin, can be unlocked from the class-change window after Novice Job Lv.10.","Venom stacks up to 5 layers, dealing damage every second based on ATK — and world bosses take it in full, not reduced to 1/10.","7 skills: Viper Fang, Dokugiri (poison mist around you), Venom Rupture (bursts every stack; 5 stacks stun), Dokunuri (coats your weapon in venom), plus the passives Venom Mastery, Numbing Toxin and Predator's Patience.","The class weapon, Viper Kunai, is a ranged throwing weapon (slightly shorter range than a bow) with damage based on DEX like a bow; it's sold at the shop for 100 Silver and drops from every monster with a tier, like other classes' weapons.","The Starter Pack now adds a Lumina Kunai for Mamushi (anyone who already bought it can buy Viper Kunai at the shop directly)."]}},{id:"2026-09-24-pvp-damage-tenth",date:"2026-09-24",time:"07:31",title:"ดวล PvP ไม่ตายในทีเดียวแล้ว",lines:["ดาเมจที่ผู้เล่นทำใส่กันระหว่างดวลลดเหลือ 1 ใน 10 ทั้งตีธรรมดา สกิล และพิษ/ไฟเผาจากสกิล — ดาเมจที่ทำกับมอนสเตอร์เหมือนเดิม"],en:{title:"PvP duels no longer end in one hit",lines:["Damage players deal to each other in a duel is cut to 1/10 — for basic attacks, skills, and poison/burn from skills alike — damage against monsters is unchanged."]}},{id:"2026-09-24-hold-to-walk",date:"2026-09-24",time:"07:29",title:"กดค้างเพื่อเดินต่อเนื่อง",lines:["คลิกพื้นแล้วกดเมาส์ (หรือนิ้ว) ค้างไว้ ตัวละครจะเดินตามเคอร์เซอร์ไปเรื่อย ๆ จนกว่าจะปล่อย ไม่หยุดแค่จุดแรกที่คลิกแล้ว"],en:{title:"Hold to keep walking",lines:["Click the ground and hold the mouse (or your finger) down, and your character keeps walking toward the cursor until you release — it no longer stops at just the first point you clicked."]}},{id:"2026-09-24-nine-slice-seams",date:"2026-09-24",time:"07:00",title:"ลบเส้นขีดบาง ๆ บนปุ่มและกรอบ",lines:["ปุ่ม ช่องค้นหา และกรอบหน้าต่างที่เป็นภาพวาด (จดหมาย ปาร์ตี้ เปลี่ยนอาชีพ ตลาด ตั้งค่า Auto Play) ไม่มีเส้นขีดจาง ๆ ตัดผ่านอีกแล้ว"],en:{title:"Removed thin seam lines on buttons and frames",lines:["Buttons, search boxes and painted window frames (mail, party, class change, market, Auto Play settings) no longer have faint seam lines cutting across them."]}},{id:"2026-09-24-guide-painted-buttons",date:"2026-09-24",time:"06:59",title:"ปุ่มในหน้าแนะนำสวยขึ้น",lines:["หน้าแนะนำตอนเริ่มเกมและหน้าแนะนำเปลี่ยนอาชีพ ใช้ปุ่มลายเดียวกับหน้าต่าง Auto Play ทั้งปุ่มน้ำเงิน ปุ่มสีทอง และปุ่มปิด ×"],en:{title:"Nicer buttons on the guide pages",lines:["The starting guide and the class-change guide now use the same painted buttons as the Auto Play window — the blue button, the gold button, and the × close button."]}},{id:"2026-09-24-bag-view-toggle-even",date:"2026-09-24",time:"06:56",title:"ปุ่มมุมมองกระเป๋าเท่ากันแล้ว",lines:["ปุ่มสลับมุมมองตาราง/รายการท้ายหน้าต่างกระเป๋า ขนาดและระดับเท่ากันทั้งคู่ ไม่ว่าจะกดปุ่มไหนอยู่"],en:{title:"Bag view-toggle buttons are now the same size",lines:["The grid/list view toggle buttons at the bottom of the bag window are now the same size and sit at the same level, whichever one is active."]}},{id:"2026-09-24-minimap-buttons",date:"2026-09-24",time:"06:53",title:"ปุ่มแผนที่ย่อแบบใหม่",lines:["ปุ่มขยาย/ย่อ และปุ่มปิดแผนที่ย่อเป็นกรอบสีน้ำเงินขอบเงินแบบเดียวกับเมนู ไม่เพี้ยนเป็นกล่องหรืออีโมจิอีกแล้ว","ตอนซ่อนแผนที่ย่อ จะเหลือปุ่มรูปแผนที่ขอบทองปุ่มเดียว กดเพื่อเปิดกลับมาได้"],en:{title:"New-style minimap buttons",lines:["The minimap's expand/collapse and close buttons are now a blue-and-silver frame matching the menu, instead of turning into a plain box or emoji.","When the minimap is hidden, only a single gold-framed map icon remains — press it to bring the minimap back."]}},{id:"2026-09-24-space-button-painted-icons",date:"2026-09-24",time:"06:53",title:"ไอคอนปุ่ม Space วาดใหม่",lines:["ไอคอนคุยกับ NPC และเก็บของบนปุ่ม Space เปลี่ยนเป็นภาพวาดแบบเดียวกับไอคอนดาบไขว้ (บับเบิลคำพูดกรอบทอง และถุงเงินกับเหรียญทอง)"],en:{title:"Repainted icons for the Space button",lines:["The talk-to-NPC and pick-up icons on the Space button are now painted art matching the crossed-swords icon (a gold-framed speech bubble, and a money bag with a gold coin)."]}},{id:"2026-09-24-mali-thai-chat-menu",date:"2026-09-24",time:"06:46",title:"ฟอนต์มะลิกลับมาในแชทและเมนูมุมขวาบน",lines:["ถ้าตั้งภาษาไทย กล่องแชทและชื่อปุ่มเมนูมุมขวาบนจะกลับมาใช้ฟอนต์มะลิเหมือนเดิม","ภาษาอื่นยังใช้ฟอนต์ Google Sans ตามเดิม"],en:{title:"The Mali font is back in chat and the top-right menu",lines:["With Thai selected, chat boxes and the top-right menu button labels go back to using the Mali font as before.","Other languages still use Google Sans as before."]}},{id:"2026-09-24-bot-window-buttons",date:"2026-09-24",time:"06:33",title:"ปุ่ม Auto Play สวยขึ้น",lines:["ปุ่มเริ่ม/หยุด Auto Play และป้ายสถานะเป็นภาพวาดกรอบทองแบบเดียวกับหน้าต่าง","ป้ายสถานะเป็นสีเขียวตอนบอทกำลังทำงานแล้ว (ก่อนหน้านี้ค้างเป็นสีน้ำตาล)"],en:{title:"Nicer Auto Play buttons",lines:["The Auto Play start/stop button and the status badge are now painted, gold-framed art matching the window.","The status badge shows green while the bot is running (it used to stay stuck on brown before)."]}},{id:"2026-09-24-friend-request-dialog",date:"2026-09-24",time:"06:24",title:"หน้าต่างคำขอเป็นเพื่อนแบบใหม่",lines:["คำขอเป็นเพื่อนเด้งเป็นหน้าต่างใหม่ เห็นรูปอาชีพ เลเวล และแมพของคนที่ส่งมา",'ถ้าอยู่แมพเดียวกันจะขึ้นว่า "บริเวณใกล้เคียง"',"มีปุ่ม ไว้ทีหลัง · ปฏิเสธ · รับเป็นเพื่อน ครบ คำขอที่ปิดไปยังรอตอบในหน้าต่างเพื่อนเหมือนเดิม"],en:{title:"New-style friend request window",lines:["A friend request now pops up as a new window showing the sender's class portrait, level and map.",`If you're on the same map, it shows "Nearby".`,"It has Later, Decline and Accept Friend buttons; requests you dismiss still wait for a reply in the friends window as before."]}},{id:"2026-09-24-menu-icons-wiki-friends-market",date:"2026-09-24",time:"06:28",title:"ไอคอนใหม่ของปุ่ม Wiki เพื่อน และ Market · ไอคอนเมนูไม่มีวงกลมแล้ว",lines:["ปุ่ม Wiki เป็นรูปหนังสือเวทพร้อมแว่นขยาย ปุ่มเพื่อนเป็นรูปนักผจญภัยสองคนกับหัวใจ และปุ่ม Market เป็นรูปแผงร้านค้า วาดแบบพิกเซลเข้าชุดกับไอคอนปุ่มอื่นในเมนู","ปุ่มในแถบเมนูทุกปุ่มไม่มีวงกลมหรือกรอบสี่เหลี่ยมสีเข้มรองหลังแล้ว เห็นรูปไอคอนเต็มๆ บนฉาก"],en:{title:"New icons for Wiki, Friends and Market; menu icons lost their circles",lines:["The Wiki button is now a spellbook with a magnifying glass, the Friends button is two adventurers with a heart, and the Market button is a market stall — all drawn as pixel art matching the menu's other icons.","Every button on the menu bar has lost the dark circle or square backing it — you now see the full icon art directly on the scene."]}},{id:"2026-09-24-class-target-no-seams",date:"2026-09-24",time:"06:26",title:"กรอบเลือกอาชีพไม่มีเส้นแปลกๆ แล้ว",lines:["เอาเส้นบางๆ เป็นกรอบสี่เหลี่ยมที่ขึ้นในกล่อง TARGET ของหน้าต่างเปลี่ยนอาชีพออก"],en:{title:"No more stray lines on the class-selection frame",lines:["Removed the faint square lines that appeared in the TARGET box of the class-change window."]}},{id:"2026-09-24-painted-buttons-no-seams",date:"2026-09-24",time:"06:26",title:"ปุ่มทองและปุ่มน้ำเงินไม่มีเส้นแปลกๆ แล้ว",lines:["เอาเส้นบางๆ ที่ขึ้นด้านซ้ายและขวาในปุ่ม เช่น ปุ่ม “เปิด Auto Bot” ในคำแนะนำผู้เล่นใหม่ ออก ปุ่มทองและน้ำเงินในหน้าต่างแบบใหม่วาดใหม่ให้ขอบเรียบทุกขนาดจอ"],en:{title:"No more stray lines on gold and blue buttons",lines:['Removed the thin lines that appeared on the left and right edges of buttons, such as the "Turn on Auto Bot" button in the new-player guide — gold and blue buttons in the new-style windows are now redrawn with clean edges at every screen size.']}},{id:"2026-09-24-equipment-window-bigger",date:"2026-09-24",time:"06:24",title:"หน้าต่างไอเทมที่สวมใส่ใหญ่ขึ้น",lines:["ขยายหน้าต่างไอเทมที่สวมใส่ใหญ่ขึ้น 20% ชื่อไอเทม ไอคอน และตัวละครอ่านง่ายขึ้น · จอเล็กยังย่อให้พอดีจอเหมือนเดิม"],en:{title:"The equipped-items window is now bigger",lines:["Enlarged the equipped-items window by 20% — item names, icons and the character are easier to read · it still shrinks to fit small screens as before."]}},{id:"2026-09-24-bot-window-painted",date:"2026-09-24",time:"06:24",title:"หน้าต่าง Auto Play โฉมใหม่",lines:["หน้าต่างตั้งค่าบอทวาดใหม่ทั้งกรอบ แบบเดียวกับหน้าต่างสถานะ: กรอบทอง แถบหัวสีน้ำเงิน ธงห้อย และอัญมณีบนกรอบ","หัวข้อแต่ละหมวดเป็นริบบิ้นพร้อมไอคอนใหม่ และมีลายจางๆ ประจำหมวดที่มุมการ์ด","การตั้งค่าทุกอย่างยังเหมือนเดิม ไม่ต้องตั้งใหม่"],en:{title:"Auto Play window's new look",lines:["The bot settings window is fully repainted, matching the Status window: a gold frame, a blue header bar, a hanging banner and gems on the frame.","Each section's heading is now a ribbon with a new icon, with a faint category pattern in the card's corner.","Every setting is unchanged — nothing needs to be set up again."]}},{id:"2026-09-24-menu-drawer-no-scrollbar",date:"2026-09-24",time:"06:24",title:"เมนูเพิ่มเติมไม่มีแถบเลื่อนแล้ว",lines:["เอาแถบเลื่อนแนวนอนใต้ปุ่มอันดับ ปาร์ตี้ และเพื่อน ในเมนู ☰ ออก เมนูยังเลื่อนขึ้นลงได้เหมือนเดิมถ้ายาวเกินจอ"],en:{title:"The More menu no longer has a scrollbar",lines:["Removed the horizontal scrollbar under the Rankings, Party and Friends buttons in the ☰ menu — the menu can still scroll up and down as before if it runs longer than the screen."]}},{id:"2026-09-24-inventory-clean-widgets",date:"2026-09-24",time:"06:08",title:"กระเป๋าเก็บงานให้เรียบร้อย",lines:["ปุ่ม ช่องค้นหา ตัวกรอง และปุ่มจัดเรียง/ทิ้งไอเทม ไม่มีเส้นซ้อนด้านในแล้ว","ช่องไอเทมมีขอบครบทั้ง 4 ด้าน และตัวเลขจำนวนอยู่มุมขวาล่างในช่อง","กรอบหมวดที่เลือกเต็มแถวพอดีเส้นแบ่ง ปุ่มสวมใส่และปุ่ม X ปิดหน้าต่างอยู่ตรงกลางกล่อง","ช่องเงินกว้างขึ้น ตัวเลขหลักแสนไม่ล้นกรอบ · ปุ่มสลับมุมมองตาราง/รายการขนาดเท่ากันแล้ว"],en:{title:"Tidied up the bag's layout",lines:["The buttons, search box, filters, and the sort/discard buttons no longer have overlapping inner lines.","Item slots now have a full border on all 4 sides, and the quantity number sits in the slot's bottom-right corner.","The selected category's frame fills the row exactly at the divider line, and the equip button and the X close button sit centered in their box.","The Silver field is wider so six-figure numbers don't overflow it · the grid/list view toggle buttons are now the same size."]}},{id:"2026-09-24-chat-moderation",date:"2026-09-24",time:"06:05",title:"แชทสะอาดขึ้น: กรองคำหยาบ บล็อก และรีพอร์ต",lines:["คำหยาบในแชทจะถูกเซ็นเซอร์เป็น *** อัตโนมัติ ทั้งแชทโลก ปาร์ตี้ และกระซิบ","พิมพ์คำหยาบ 3 ครั้งใน 10 นาที จะถูกพักแชท 1 นาที · ถ้ายังพิมพ์ต่อจะนานขึ้นเป็น 3 และ 10 นาที",'คลิกขวา (หรือกดค้าง) ที่ชื่อในแชท เลือก "บล็อกแชท" เพื่อซ่อนข้อความของคนนั้น · พิมพ์ /blocklist ดูรายชื่อ, /unblock ชื่อ เพื่อเลิกบล็อก','เลือก "รีพอร์ต" ที่เมนูเดียวกันเพื่อแจ้งทีมงาน · ถ้าผู้เล่น 3 คนรีพอร์ตคนเดียวกันใน 30 นาที ระบบจะพักแชทคนนั้น 10 นาทีทันที'],en:{title:"Cleaner chat: word filter, block, and reports",lines:["Rude words in chat are now automatically censored to *** in world chat, party chat and whispers.","Typing rude words 3 times in 10 minutes pauses your chat for 1 minute · keep typing them and it grows to 3, then 10 minutes.",`Right-click (or press and hold) a name in chat and choose "Block chat" to hide that person's messages · type /blocklist to see your list, /unblock name to unblock.`,`Choose "Report" from the same menu to notify staff · if 3 players report the same person within 30 minutes, that person's chat is paused for 10 minutes immediately.`]}},{id:"2026-09-24-inventory-v3-art",date:"2026-09-24",time:"05:56",title:"กระเป๋าหน้าตาใหม่ วาดใหม่ทั้งบาน",lines:["กรอบกระเป๋า ปุ่ม ช่องไอเทม และแถบหมวดวาดใหม่เป็นภาพพิกเซล คมชัดขึ้น","ไอคอนหมวด (ทั้งหมด ใช้ของ อุปกรณ์ อื่นๆ วัตถุดิบ เควส ไอเทมพิเศษ) ช่องค้นหา น้ำหนัก จัดเรียง และทิ้งไอเทม เปลี่ยนเป็นไอคอนพิกเซลชุดใหม่"],en:{title:"Bag redesigned, repainted from top to bottom",lines:["The bag's frame, buttons, item slots and category bar are all repainted as pixel art, sharper than before.","The category icons (All, Usables, Equipment, Other, Materials, Quests, Special Items), the search box, weight, sort and discard icons all changed to a new pixel-art set."]}},{id:"2026-09-24-market-clean-frames",date:"2026-09-24",time:"05:48",title:"ปุ่มและกรอบในตลาดคมชัดขึ้น",lines:["แท็บ ช่อง Silver ปุ่มประวัติซื้อขาย หมวดที่เลือก และหัวตาราง ไม่มีเส้นซ้อนด้านในกับขอบแหว่งแล้ว","ชื่อไอเทมยาวๆ อยู่บรรทัดเดียว ไม่ตัดคำกลางคำ และสเตตัสไม่ล้นแถว","เอาแถบเลื่อนสีน้ำเงินใต้ปุ่มรายการโปรดออก"],en:{title:"Sharper buttons and frames in the Market",lines:["Tabs, the Silver field, the trade-history button, the selected category and the table header no longer have overlapping inner lines or chipped edges.","Long item names now stay on one line without breaking mid-word, and stats no longer overflow the row.","Removed the blue scrollbar under the favorites button."]}},{id:"2026-09-24-mail-partial-claim",date:"2026-09-24",time:"05:45",title:"แก้รับของจากจดหมายไม่ได้ เมื่อของในจดหมายหนักเกินกระเป๋า",lines:["จดหมายที่มีของหนักกว่าน้ำหนักกระเป๋าทั้งใบ (เช่น ยาจำนวนมากที่ถูกส่งคืนตอนกระเป๋าเต็ม) กดรับไม่ได้เลยแม้กระเป๋าจะว่าง","ตอนนี้กดรับแล้วจะได้ของเท่าที่กระเป๋ารับไหว ส่วนที่เหลือส่งกลับเข้ากล่องจดหมายเป็นฉบับใหม่ ไม่มีของหาย เคลียร์กระเป๋าแล้วกดรับต่อได้เรื่อยๆ"],en:{title:"Fixed being unable to claim mail when its contents were too heavy for your bag",lines:["Mail carrying more weight than your entire bag capacity (for example, a large stack of potions returned when your bag was full) couldn't be claimed at all, even with an empty bag.","Now claiming it gives you as much as your bag can hold, and the rest is sent back to your mailbox as a new letter — nothing is lost, and you can keep clearing your bag and claiming more."]}},{id:"2026-09-24-market-armor-parts",date:"2026-09-24",time:"05:41",title:"ตลาดแยกชุดเกราะเป็นส่วนๆ และตารางอ่านง่ายขึ้น",lines:["กดหมวดชุดเกราะในตลาดแล้วจะมีปุ่มแยกส่วนให้เลือก: หมวก ศีรษะกลาง ศีรษะล่าง เสื้อ ผ้าคลุม รองเท้า โล่","ช่องคุณสมบัติกว้างขึ้นและแสดงสเตตัสครบทุกตัว ไม่ตัดเหลือแค่ 2 บรรทัดแล้ว","หัวตาราง ไอเทม / คุณสมบัติ / ราคา ชิดซ้ายตรงกับข้อมูลด้านล่าง"],en:{title:"The Market splits armor sets into pieces, and tables read better",lines:["Pressing the armor-set category in the Market now shows separate buttons to pick from: helmet, mid-head, low-head, top, cloak, shoes, shield.","The stats column is wider and shows every stat in full, no longer cut down to just 2 lines.","The Item / Stats / Price headers are now left-aligned to match the data below."]}},{id:"2026-09-24-stale-copy-rollback",date:"2026-09-24",time:"05:28",title:"แก้ตัวละครย้อนกลับไปเลเวลเก่าชั่วคราวหลังเซิร์ฟเวอร์รีสตาร์ท",lines:["บางคนเข้าเกมช่วงเซิร์ฟเวอร์รีสตาร์ทแล้วได้ตัวละครฉบับเก่าที่เลเวลต่ำกว่า จนกว่าจะรีสตาร์ทรอบถัดไปจึงกลับมาเป็นตัวจริง","ตอนนี้ถ้าระบบยังหาข้อมูลตัวละครล่าสุดไม่เจอ จะขึ้น “กำลังตรวจสอบข้อมูลตัวละคร” แล้วเชื่อมต่อใหม่อัตโนมัติ แทนการให้เข้าเล่นด้วยตัวฉบับเก่า","ข้อมูลตัวละครฉบับเก่าที่ค้างอยู่ในเซิร์ฟเวอร์จะถูกเก็บกวาดออก ไม่ต้องทำอะไรเพิ่ม ความคืบหน้าของตัวจริงไม่หาย"],en:{title:"Fixed characters temporarily reverting to an old level after a server restart",lines:["Some players who logged in during a server restart got an old copy of their character at a lower level, only returning to their real one after the next restart.",`Now, if the system can't find the latest character data yet, it shows "Checking your character data" and reconnects automatically, instead of letting you play on the old copy.`,"Stale character data left behind on the server gets cleaned up on its own — nothing else to do, and your real progress is not lost."]}},{id:"2026-09-24-bag-stack-count-corner",date:"2026-09-24",time:"05:28",title:"ตัวเลขจำนวนไอเทมในกระเป๋ากลับไปอยู่มุมขวาล่าง",lines:["จำนวนไอเทมที่ซ้อนกัน (เช่น ยา 104 ขวด) กลับมาเป็นตัวเลขเล็กที่มุมขวาล่างของช่องเหมือนเดิม ไม่ทับกลางรูปไอเทมอีกแล้ว"],en:{title:"Bag item counts moved back to the bottom-right corner",lines:["Stacked item counts (like 104 bottles of potion) are back to a small number in the slot's bottom-right corner, no longer overlapping the item's picture."]}},{id:"2026-09-24-item-card-no-quote-footer",date:"2026-09-24",time:"05:18",title:"หน้าต่างรายละเอียดไอเทมโล่งขึ้น",lines:["เอาคำคมท้ายหน้าต่างรายละเอียดไอเทม (เช่น “อุปกรณ์ที่ดี คือเพื่อนร่วมทางที่ไว้ใจได้”) ออก ทั้งในกระเป๋าและในตลาด","เอาแถบล่างสุดที่บอกสถานะยา (เช่น “HP เต็ม”) และประเภทไอเทมซ้ำออก ประเภทยังดูได้ใต้ชื่อไอเทมเหมือนเดิม"],en:{title:"The item-details window is less cluttered",lines:["Removed the quote at the bottom of the item-details window (like “Good gear is a companion you can trust”) in both the bag and the Market.","Removed the bottom bar showing potion status (like “HP full”) and the duplicate item type — the type is still shown under the item's name as before."]}},{id:"2026-09-24-ruby-ring-str-vit",date:"2026-09-24",time:"05:14",title:"แหวนสายกายภาพติด STR/VIT ได้ แหวนสายเวทไม่ติด AGI",lines:["Ruby Ring (แหวนซ้าย สายกายภาพ) สุ่มสเตตัสได้จาก STR, AGI, VIT, DEX, LUK จากเดิมที่ได้แค่ AGI, DEX, LUK สายแทงก์และสายตีแรงจึงมีแหวนของตัวเองแล้ว","Sapphire Ring (แหวนขวา สายเวท) สุ่มสเตตัสได้จาก INT, DEX, VIT ไม่ติด AGI ที่สายเวทไม่ได้ใช้อีกต่อไป","แหวนยังใส่ได้ข้างเดิมของตัวเอง มีผลกับแหวนที่ดรอปใหม่ แหวนที่มีอยู่แล้วไม่เปลี่ยน"],en:{title:"Ruby Ring can now roll STR/VIT; Sapphire Ring no longer rolls AGI",lines:["Ruby Ring (left ring, physical) can now roll stats from STR, AGI, VIT, DEX, LUK, instead of just AGI, DEX, LUK before — tanks and heavy hitters finally have a ring of their own.","Sapphire Ring (right ring, caster) rolls stats from INT, DEX, VIT — no longer rolling AGI, which casters don't use anyway.","Rings still go on their usual side · this affects newly dropped rings only, existing rings are unchanged."]}},{id:"2026-09-24-shared-item-card-layout",date:"2026-09-24",time:"05:06",title:"ไอเทมที่แชร์ในแชทแสดงรายละเอียดแบบเดียวกับในกระเป๋า",lines:["กดชื่อไอเทมในแชทแล้ว หน้าต่างรายละเอียดแบ่งเป็นสองฝั่งเหมือนตอนดูของตัวเอง ค่าสถานะอยู่ซ้าย ช่องการ์ด น้ำหนัก ราคาขาย และตำแหน่งอยู่ขวา","ค่าสถานะของอุปกรณ์ขึ้นในแถบสีน้ำเงินใต้ชื่อด้วย"],en:{title:"Items shared in chat now show the same layout as your own bag",lines:["Clicking an item's name in chat now splits its details window in two, like viewing your own items — stats on the left, card slots, weight, sell price and slot on the right.","Equipment stats also show in the blue bar under the name."]}},{id:"2026-09-24-red-potion-sell-price",date:"2026-09-24",time:"04:56",title:"Red Potion ขายคืนร้านได้ 5 Silver",lines:["ราคาขาย Red Potion ลดจาก 10 เหลือ 5 Silver ให้เท่าครึ่งหนึ่งของราคาซื้อ เหมือนของอื่นทุกชิ้นในร้าน","ก่อนหน้านี้พ่อค้าที่มี Markup ขายยาแดงได้แพงกว่าราคาซื้อ ตอนนี้ไม่มีของในร้านชิ้นไหนขายคืนได้เกินราคาซื้อแล้ว"],en:{title:"Red Potion now sells back for 5 Silver",lines:["Red Potion's sell price dropped from 10 to 5 Silver, half its buy price like every other item in the shop.","Merchants with Markup used to sell Red Potion back for more than its buy price — now nothing in the shop sells back above its buy price."]}},{id:"2026-09-24-inventory-filter-labels",date:"2026-09-24",time:"04:53",title:"ตัวกรองในกระเป๋าอ่านได้ครบคำ",lines:["ช่องเลเวล คุณภาพ สเตตัส และการเรียง กว้างพอให้เห็นข้อความเต็ม ไม่ถูกตัดท้ายเป็นจุดไข่ปลาอีกแล้ว","เลือกคุณภาพหรือวิธีเรียงแล้ว ช่องจะแสดงชื่อที่เลือกล้วนๆ ไม่ซ้ำคำนำหน้า"],en:{title:"Bag filters now show full text",lines:["The level, quality, stat and sort fields are now wide enough to show the full text, no longer cut off with an ellipsis.","Once you pick a quality or sort option, the field shows just the chosen name, without repeating its prefix."]}},{id:"2026-09-24-site-page-links",date:"2026-09-24",time:"04:46",title:"Wiki อัปเดต Explorer และข้อตกลง ลิงก์ถึงกันครบทุกหน้า",lines:['หน้า Wiki มีลิงก์ไป Explorer แล้ว และมีกลุ่ม "หน้าอื่น" ในแถบข้าง กดไปหน้าแรก บันทึกการอัปเดต Explorer และข้อตกลงได้ทั้งบนมือถือและจอเล็ก',"หน้า Explorer มีลิงก์ไปหน้าข้อตกลงและติดต่อเรา · หน้าข้อตกลงมีลิงก์ไป Explorer"],en:{title:"Wiki, Updates, Explorer and the terms page now link to each other everywhere",lines:['The Wiki page now links to Explorer, and has an "Other pages" group in its sidebar linking to the home page, Updates, Explorer and the terms page, on both mobile and small screens.',"The Explorer page links to the terms page and Contact Us · the terms page links to Explorer."]}},{id:"2026-09-24-inventory-painted-v2",date:"2026-09-24",time:"04:43",title:"กระเป๋าโฉมใหม่ ตามภาพต้นแบบ",lines:["กรอบหน้าต่าง แถบหัวเป้สะพายหลัง แผงหมวดหมู่ ช่องค้นหาและตัวกรอง ตารางช่องไอเทม และแถบล่าง วาดใหม่ทั้งหมดให้ตรงกับภาพต้นแบบ","ทุกขนาดในหน้านี้วัดจากภาพต้นแบบโดยตรง ตำแหน่งทุกชิ้นจึงตรงกับที่วาดไว้"],en:{title:"Bag redesigned to match the reference art",lines:["The window frame, the backpack header bar, the category panel, the search box and filters, the item-slot grid, and the bottom bar are all redrawn to match the reference art.","Every size on this page is measured directly from the reference art, so every piece lines up exactly where it was drawn."]}},{id:"2026-09-24-monster-sprite-bleed",date:"2026-09-24",time:"04:43",title:"แก้ภาพมอนสเตอร์มีเศษชิ้นส่วนลอยอยู่ข้างตัว",lines:["มอนสเตอร์ 14 ชนิดไม่มีเศษภาพลอยอยู่ข้างตัวตอนโดนตีแล้ว เช่น Pebble Golem, Moon Owl, Bog Toad, Tide Crab","ท่าโจมตีของมอนเหล่านี้ได้ปลายหมัด หาง ก้าม หรือหนวดที่เคยขาดกลับคืนมา"],en:{title:"Fixed stray sprite fragments beside monsters",lines:["14 monster types no longer show stray fragments beside their body when hit — including Pebble Golem, Moon Owl, Bog Toad, Tide Crab.","These monsters' attack poses got back the fist tips, tails, claws or feelers that used to be cut off."]}},{id:"2026-09-24-close-button-ring",date:"2026-09-24",time:"04:25",title:"ลบวงขาวจางๆ รอบปุ่มปิดหน้าต่าง",lines:["ปุ่มปิด (X) ของหน้าต่างเควส เปลี่ยนอาชีพ สถานะ สวมใส่ สกิล ปาร์ตี้ จดหมาย จัดอันดับ ตั้งค่า รางวัลรายวัน และตลาด ไม่มีวงขาวจางๆ ขึ้นรอบปุ่มเวลาชี้เมาส์หรือแตะแล้วอีกต่อไป"],en:{title:"Removed the faint white ring around window close buttons",lines:["The (X) close button on the quest, class-change, status, equipped-items, skills, party, mail, rankings, settings, daily rewards and Market windows no longer shows a faint white ring around it on hover or tap."]}},{id:"2026-09-24-starter-pack-wording",date:"2026-09-24",time:"04:21",title:"ปรับคำอธิบาย Starter Pack",lines:['หัวข้อ Lv.1–70 ในการ์ด Starter Pack ร้าน Gold เปลี่ยนเป็น "อุปกรณ์ช่วยเหลือเริ่มต้น" แทนคำเทียบค่าพลังกับของดรอป'],en:{title:"Reworded the Starter Pack description",lines:['The "Lv.1–70" heading on the Gold-shop Starter Pack card now reads "Early gear to help you get started" instead of comparing its power to drops.']}},{id:"2026-09-24-class-window-frame-hairline",date:"2026-09-24",time:"04:15",title:"ลบเส้นบางๆ ในหน้าต่างเปลี่ยนอาชีพ",lines:["ขอบทองของการ์ดอาชีพปัจจุบัน การ์ดอาชีพเป้าหมาย และแถบคำแนะนำ วาดหนาเท่าภาพจริงแล้ว","เส้นจางๆ ที่ลอยอยู่ด้านในกรอบหายไป เพราะขอบไม่ถูกบีบจนเหลือเส้นเดียวอีกต่อไป"],en:{title:"Removed a thin line in the class-change window",lines:["The gold border on the current-class card, the target-class card and the tip banner is now drawn at full thickness matching the source art.","The faint line that used to float inside the frame is gone, since the border is no longer squeezed down to a single line."]}},{id:"2026-09-24-offline-sandbox",date:"2026-09-24",time:"04:15",title:"โหมดออฟไลน์: เลเวล 99 ทุกอาชีพ พร้อมอุปกรณ์ขั้น V ทุกชิ้น",lines:["เข้าเล่นแบบออฟไลน์แล้วตัวละครจะเป็น Base Lv.99 และ Job Lv.70 ทุกอาชีพทันที (Novice Job Lv.10) เปลี่ยนอาชีพไปลองได้ทุกสาย","ได้อุปกรณ์ขั้น V ทุกชิ้นในเกม (อาวุธทุกอาชีพ หมวก เกราะ โล่ ผ้าคลุม รองเท้า เครื่องประดับ ซองธนู) และสวมครบทั้งตัวให้อัตโนมัติ · เปลี่ยนอาชีพแล้วจะถืออาวุธของอาชีพนั้นให้เอง","การเล่นออฟไลน์บันทึกลงเครื่อง (localStorage) อัตโนมัติ ชุดที่ใส่ ของที่เก็บ และความคืบหน้าอยู่ครบหลังรีเฟรช","มีผลเฉพาะโหมดออฟไลน์ ตัวละครออนไลน์ไม่เปลี่ยนแปลง"],en:{title:"Offline mode: every class at Lv.99 with full Tier V gear",lines:["Playing offline now makes your character Base Lv.99 and Job Lv.70 in every class immediately (Novice Job Lv.10) — switch classes freely to try any of them.","You get every Tier V item in the game (every class's weapon, hats, armor, shields, cloaks, shoes, accessories, quivers), equipped automatically head to toe · switching class equips that class's weapon for you.","Offline play saves to your device (localStorage) automatically — your gear, items and progress are all still there after a refresh.","This only affects offline mode; your online character is unchanged."]}},{id:"2026-09-24-channel-grid",date:"2026-09-24",time:"03:59",title:"หน้าเลือกช่องเป็นตาราง 3 ช่องต่อแถว",lines:["รายการช่องในหน้าเลือกเซิร์ฟเวอร์เรียงเป็นตาราง แถวละ 3 ช่อง เห็นจำนวนคนทุกช่องในหน้าเดียวไม่ต้องเลื่อนยาว","ช่องที่อยู่ตอนนี้ยังเป็นสีทองเหมือนเดิม · ขอบคุณ SaintGap ที่เสนอมาใน Discord"],en:{title:"Channel select screen is now a 3-per-row grid",lines:["The channel list on the server select screen is now a grid, 3 channels per row, so you can see every channel's headcount on one page without scrolling far.","Your current channel is still highlighted in gold · thanks to SaintGap for suggesting this on Discord."]}},{id:"2026-09-24-archer-thief-cleric-skills",date:"2026-09-24",time:"03:57",title:"ปรับสกิล Archer / Thief / Cleric",lines:["Keen Eye (Archer): ATK จาก DEX ปรับเป็น 4.5% ต่อระดับ (สูงสุด 45%) · DEX +2 / Hit +1% และ ATK 2% ของ Hit ต่อระดับเท่าเดิม · Twin Shot ยังมีโอกาส 43% ยิงเป็น 4 ฮิต ใช้ SP 1.8 ต่อระดับ","Fatal Sense (Thief): ATK จาก AGI ปรับเป็น 5.5% ต่อระดับ (สูงสุด 55%) · คริติคอล +2% และ ASPD +1% ต่อระดับเท่าเดิม","Heal (Cleric): ฟื้น HP 30 + 70% MATK ที่ระดับ 1 ถึง 30 + 250% MATK ที่ระดับ 10 · ใช้ SP 3 ต่อระดับ (3→30) · ฮีลตัวเองและตัวละครทุกคนรอบตัวในระยะ 150 พร้อมกัน · คูลดาวน์ 1 วินาที","Divine Boon (Cleric): STR/AGI/INT/DEX +2 ที่ระดับ 1 ถึง +11 ที่ระดับ 10 · ใช้ SP 5 ต่อระดับ (5→50) · อยู่ได้ 75 วินาที · บัฟตัวเองและตัวละครทุกคนรอบตัวในระยะ 150 ไม่ต้องอยู่ปาร์ตี้ · คูลดาวน์ 15 วินาที"],en:{title:"Archer / Thief / Cleric skill adjustments",lines:["Keen Eye (Archer): ATK from DEX changes to 4.5% per level (max 45%) · DEX +2 / Hit +1% and ATK 2% of Hit per level stay the same · Twin Shot still has a 43% chance to fire 4 hits, using 1.8 SP per level.","Fatal Sense (Thief): ATK from AGI changes to 5.5% per level (max 55%) · Critical +2% and ASPD +1% per level stay the same.","Heal (Cleric): Restores HP 30 + 70% MATK at level 1, up to 30 + 250% MATK at level 10 · Uses 3 SP per level (3→30) · Heals yourself and every character within range 150 at once · 1-second cooldown.","Divine Boon (Cleric): STR/AGI/INT/DEX +2 at level 1, up to +11 at level 10 · Uses 5 SP per level (5→50) · Lasts 75 seconds · Buffs yourself and every character within range 150, no party needed · 15-second cooldown."]}},{id:"2026-09-24-region-codes",date:"2026-09-24",time:"03:58",title:"ตัวย่อภูมิภาคตรงตามที่ใช้กันทั่วไป",lines:["เปลี่ยนตัวย่อในหน้าเลือกภูมิภาค แชท และตลาด: เอเชียตะวันออก EA · ยุโรป EU · อเมริกา NA · ออสเตรเลีย AU (เอเชียตะวันออกเฉียงใต้ยังเป็น SEA)","เปลี่ยนแค่ตัวอักษรที่แสดง เซิร์ฟเวอร์ ตัวละคร และของในตลาดของแต่ละภูมิภาคอยู่ที่เดิมทั้งหมด"],en:{title:"Region abbreviations now match common usage",lines:["The abbreviations on the region select screen, chat and market change to: East Asia EA · Europe EU · Americas NA · Australia AU (Southeast Asia stays SEA).","Only the displayed letters change — each region's servers, characters and market listings all stay exactly where they were."]}},{id:"2026-09-24-market-matches-mockup",date:"2026-09-24",time:"03:57",title:"ตลาดกลางตรงกับภาพต้นแบบแล้ว",lines:["หน้าต่างคงสัดส่วนตามภาพต้นแบบ จึงเห็นสินค้าครบ 9 แถวอย่างที่ออกแบบไว้","แถวสินค้ายาวเต็มความกว้างตาราง ปุ่มซื้ออยู่ชิดขอบขวาเหมือนต้นแบบ","การ์ดรายละเอียดด้านขวาจัดระยะใหม่ทั้งใบ ตั้งแต่หัวไอเทมจนถึงปุ่มซื้อสินค้า"],en:{title:"The Market now matches the mockup",lines:["The window keeps the mockup's proportions, so all 9 item rows show as designed.","Item rows now stretch to the full table width, with the buy button flush against the right edge like the mockup.","The detail card on the right has been re-spaced from top to bottom, from the item header down to the buy button."]}},{id:"2026-09-24-frost-area-cooldown",date:"2026-09-24",time:"03:55",title:"Mage: ปรับ Frost Area",lines:["Frost Area คูลดาวน์ 1.7 วินาที (เดิม 6 วินาที) · โอกาสแช่แข็ง 30% (เดิม 50%) · แช่แข็งนาน 1 วินาที (เดิม 3 วินาที)","ดาเมจและค่า SP เท่าเดิม"],en:{title:"Mage: Frost Area adjustment",lines:["Frost Area cooldown is now 1.7 seconds (was 6) · Freeze chance 30% (was 50%) · Freeze duration 1 second (was 3).","Damage and SP cost are unchanged."]}},{id:"2026-09-24-exp-event-x2",date:"2026-09-24",time:"03:36",title:"กิจกรรม EXP x2 ทุกคน 8 ชั่วโมง",lines:["ตั้งแต่ 03:40 น. ถึง 11:40 น. วันนี้ (เวลาไทย) ทุกคนได้ EXP x2 ทั้ง Base EXP และ Job EXP ไม่ต้องกดรับอะไร ไม่ต้องเป็น Premium","ตัวคูณนี้คูณทับโบนัสปาร์ตี้และโบนัส Premium ตามปกติ — ล่ารวมปาร์ตี้ในแผนที่เดียวกันยิ่งคุ้ม","ดูเวลาที่เหลือได้จากป้ายบัฟ EXP x2 บนหน้าจอ"],en:{title:"EXP x2 event for everyone, 8 hours",lines:["From 03:40 to 11:40 today (Thai time), everyone gets EXP x2 on both Base EXP and Job EXP. No claiming needed, and Premium is not required.","This multiplier stacks on top of the party bonus and Premium bonus as usual — hunting together with a party on the same map pays off even more.","Check the remaining time from the EXP x2 buff icon on screen."]}},{id:"2026-09-24-no-level-gap-exp-cut",date:"2026-09-24",time:"03:29",title:"ยกเลิกการลด EXP ตามเลเวลที่ห่าง",lines:["เดิมมอนที่เลเวลสูงกว่าเราเกิน 10 เลเวลจะให้ EXP ลดลง 5% ต่อเลเวล จนเหลือต่ำสุด 10%","ตอนนี้ยกเลิกแล้ว มอนทุกตัวให้ EXP เต็มไม่ว่าเลเวลจะห่างแค่ไหน — ตีค้างคาว โกเลม หรือมอนแมพไหนก็ได้ EXP เต็มตามดาเมจที่ทำ"],en:{title:"Removed the EXP cut for level gaps",lines:["Previously, a monster more than 10 levels above you gave 5% less EXP per level over, down to a floor of 10%.","That cut is now removed — every monster gives full EXP no matter how far apart your levels are. Bats, golems, or monsters on any map all give full EXP for the damage you deal."]}},{id:"2026-09-24-market-painted-v2",date:"2026-09-24",time:"03:28",title:"หน้าตลาดโฉมใหม่ ตามภาพต้นแบบ",lines:["กรอบหน้าต่าง แถบหัวเมืองยามเย็น ร้านค้า แท็บ แผงหมวดหมู่ ตารางสินค้า และการ์ดรายละเอียด วาดใหม่ทั้งหมดให้ตรงกับภาพต้นแบบ","ช่องค้นหามีปุ่มล้างคำค้นให้กดได้ตลอด · หัวคอลัมน์ราคาบอกทิศการเรียงด้วยลูกศรเดียว","ใช้ได้เหมือนเดิมทุกอย่าง ทั้งซื้อ ตั้งขาย และรายการของฉัน"],en:{title:"Market page redesigned to match the mockup",lines:["The window frame, evening-town header bar, shop tabs, category panel, item table and detail card were all redrawn to match the mockup.","The search box now has a clear button you can press any time · the price column header shows sort direction with a single arrow.","Everything still works the same — buying, listing, and My Listings."]}},{id:"2026-09-24-classic-exp-table",date:"2026-09-24",time:"03:29",title:"ตาราง EXP กลับเป็นแบบเดิม",lines:["ยกเลิกตาราง EXP แบบ 3 เดือน กลับไปใช้ตาราง EXP เดิม · เลเวลที่ได้แล้วยังอยู่ครบ","ใครมี EXP สะสมเกินค่าของเลเวลปัจจุบัน จะเลเวลอัปทันทีเมื่อฆ่ามอนตัวถัดไป","การปรับสมดุลอาชีพ (Frost Area, Merchant, Power Strike, Auto Play ใช้สกิลโจมตี) ยังใช้ตามเดิม"],en:{title:"EXP table reverts to the classic version",lines:["The 3-month EXP table is reverted — back to the original EXP table · Levels already earned stay exactly as they are.","If your stored EXP already exceeds your current level's requirement, you'll level up immediately on your next kill.","The class balance changes (Frost Area, Merchant, Power Strike, Auto Play using attack skills) still stand."]}},{id:"2026-09-24-exp-bar-stuck-full",date:"2026-09-24",time:"03:12",title:"แก้แถบ EXP ค้าง 100% แต่ไม่เลเวลอัป",lines:["ใครเปิดเกมค้างไว้ตั้งแต่ก่อนอัปเดตตาราง EXP ใหม่ แถบ EXP จะแสดง 100% ทั้งที่ยังเก็บ EXP ไม่ครบตามตารางใหม่ — ไม่ได้เสีย EXP และตัวละครยังเก็บ EXP ต่อตามปกติ","ตอนนี้แถบ EXP ใช้ค่าจากเซิร์ฟเวอร์เสมอ รีโหลดหน้าเกมหนึ่งครั้งแล้วเปอร์เซ็นต์จะถูกต้อง"],en:{title:"Fixed the EXP bar stuck at 100% without leveling up",lines:["If you left the game running from before the new EXP table update, the EXP bar showed 100% even though you hadn't yet earned enough EXP for the new table — no EXP was lost, and your character kept earning EXP as normal.","The EXP bar now always reads from the server — reload the game page once and the percentage will be correct."]}},{id:"2026-09-24-skill-window-real-sp",date:"2026-09-24",time:"03:12",title:"หน้าต่างสกิลแสดง SP ที่ใช้จริง",lines:["เดิมหน้าต่างสกิลแสดงราคา SP ก่อนหักส่วนลดจาก Meditation และ Mage Mastery จึงไม่ตรงกับตัวเลขบนปุ่มสกิล (เช่น Frost Area Lv.10 หน้าต่างบอก SP 50 แต่ใช้จริง 25)","ตอนนี้หน้าต่างสกิลแสดง SP หลังหักส่วนลดแล้ว ตรงกับปุ่มสกิลและ SP ที่ถูกหักจริง"],en:{title:"Skill window now shows the actual SP cost",lines:["The skill window used to show the SP cost before Meditation and Mage Mastery discounts, so it didn't match the number on the skill button (e.g. Frost Area Lv.10 showed SP 50 in the window, but actually cost 25).","The skill window now shows SP after discounts, matching the skill button and the SP actually spent."]}},{id:"2026-09-24-boost-scroll-no-waste",date:"2026-09-24",time:"03:04",title:"ม้วน EXP/Drop ไม่เสียฟรีเมื่อกดใช้รัว",lines:["เดิมเมื่อบัฟเต็ม 5 ชั่วโมงแล้ว ถ้ากดใช้ม้วนต่อช้าไปเพียงวินาทีเดียว ระบบจะกินม้วนไปทั้งอันแต่ต่อเวลาให้แค่วินาทีนั้น","ตอนนี้จะใช้ม้วนได้ก็ต่อเมื่อเวลาบัฟเหลือไม่เกิน 4 ชั่วโมง ให้ได้เต็ม 1 ชั่วโมงทุกม้วน ถ้าเกินจะไม่ให้ใช้และเก็บม้วนไว้ในกระเป๋า"],en:{title:"EXP/Drop scrolls no longer wasted when used back-to-back",lines:["Previously, once the buff was capped at 5 hours, using another scroll even one second late consumed the whole scroll but only extended the buff by that one second.","Now a scroll can only be used when the buff has 4 hours or less remaining, so every scroll grants the full 1 hour. If the buff is above that, the scroll can't be used and stays in your bag."]}},{id:"2026-09-24-market-night-sky",date:"2026-09-24",time:"02:57",title:"ตลาดกลางแต่งใหม่ทั้งหน้าต่าง",lines:["หัวหน้าต่างตลาดเป็นท้องฟ้ายามค่ำกับเมืองโดมและต้นปาล์ม แท็บซื้อ/ขาย/รายการของฉันวางอยู่บนแถบนั้น · ชื่อไอเทมและหัวข้อใช้ตัวอักษรแบบใหม่ อ่านง่ายขึ้น","แผงขวาขึ้นคำอธิบายไอเทมก่อน ตามด้วยน้ำหนักและจำนวนในกระเป๋า · กล่องราคาต่อชิ้นและปุ่มซื้อพอดีกับหน้าต่างไม่ต้องเลื่อน"],en:{title:"The Market redecorated, window and all",lines:["The Market window header now shows a night sky over a domed town with palm trees, with the Buy/Sell/My Listings tabs sitting on that bar · Item names and headings use a new typeface that's easier to read.","The right panel now shows the item description first, followed by weight and how many you're carrying · the per-item price box and buy button fit the window without scrolling."]}},{id:"2026-09-24-remote-bow-arrows",date:"2026-09-24",time:"02:54",title:"เห็นลูกธนูของนักธนูคนอื่นแล้ว",lines:["การโจมตีปกติของนักธนูคนอื่นจะมีลูกธนูพุ่งไปหาเป้าหมาย ไม่ดูเหมือนฟันอากาศจากระยะไกลอีกต่อไป","ระยะโจมตีไม่ได้เปลี่ยน: อาวุธประชิดยังตีได้แค่ระยะใกล้ ส่วนธนูยิงไกลได้ตามปกติ"],en:{title:"You can now see other archers' arrows",lines:["Other archers' basic attacks now fire an arrow toward their target, instead of looking like they're swinging at thin air from a distance.","Attack range is unchanged: melee weapons still only hit up close, and bows still fire from range as usual."]}},{id:"2026-09-24-explorer",date:"2026-09-24",time:"02:40",title:"เปิด Explorer: ตรวจสอบเงินและไอเทมของทุกตัวละคร",lines:["หน้าใหม่ lumivaraonline.com/explorer — ใครก็เข้าดูได้ คล้าย Explorer ของบล็อกเชน เพื่อความโปร่งใส","ค้นหาชื่อตัวละครเพื่อดู Silver, Gold, ไอเทมในกระเป๋า อุปกรณ์ (พร้อมตีบวก การ์ด และผู้พบคนแรก) และของในคลัง","หน้าแรกแสดงอันดับผู้ถือ Silver และ Gold สูงสุด พร้อมปริมาณเงินหมุนเวียนรวมทั้งเซิร์ฟเวอร์ (อัปเดตทุก ~5 นาที)"],en:{title:"Explorer is live: check any character's currency and items",lines:["A new page at lumivaraonline.com/explorer — anyone can open it, like a blockchain explorer, for transparency.","Search a character's name to see their Silver, Gold, inventory items, gear (with refine level, cards, and who first found it), and storage contents.","The front page lists the top Silver and Gold holders, plus total currency in circulation server-wide (updated roughly every 5 minutes)."]}},{id:"2026-09-24-market-ledger-trim",date:"2026-09-24",time:"02:38",title:"ตารางตลาดกลางอ่านง่ายขึ้น",lines:["ตารางซื้อสินค้าเหลือแค่ ไอเทม · คุณสมบัติ · ราคา ช่องคุณสมบัติกว้างขึ้นจนอ่านได้ครบ · ชื่อผู้ขายและสถานะออนไลน์ดูได้ที่แผงขวาเมื่อเลือกรายการ","อุปกรณ์บอกเลเวลที่ใช้ไว้ใต้ชื่อ (ขึ้นสีแดงถ้าเลเวลยังไม่ถึง) · ป้าย Premium มีหีบสมบัติใหม่ประดับ"],en:{title:"The Market table is easier to read",lines:["The buy table now shows only Item · Stats · Price, with the stats column widened enough to read in full · seller name and online status now show in the right panel when you select a listing.","Gear now shows its required level under the name (in red if you're not there yet) · the Premium badge now has a new treasure chest icon."]}},{id:"2026-09-24-refine-stone-lv70",date:"2026-09-24",time:"02:18",title:"Refine Stone ดรอปเฉพาะมอน Lv.70 ขึ้นไป",lines:["หินตีบวก (Refine Stone) จะดรอปจากมอนสเตอร์ Lv.70 ขึ้นไปเท่านั้น (โอกาส 1% เท่าเดิม) มอนที่ต่ำกว่า Lv.70 จะไม่ดรอปหินแล้ว","เควสล่ารายวันและการถวายเศษวิญญาณยังให้หินตีบวกเหมือนเดิม"],en:{title:"Refine Stone now drops only from Lv.70+ monsters",lines:["Refine Stones now drop only from Lv.70+ monsters (still a 1% chance). Monsters below Lv.70 no longer drop them.","The daily hunt quest and Spirit Shard offerings still give Refine Stones as before."]}},{id:"2026-09-24-three-month-climb",date:"2026-09-24",time:"02:05",title:"ปรับการเติบโต: ถึง Lv.99 ใช้เวลาราว 3 เดือน · ปรับสมดุลอาชีพ",lines:["ตาราง EXP ใหม่: เลเวลต้น ๆ ยังขึ้นเร็ว แต่กว่าจะถึง Lv.99 ใช้เวลาราว 3 เดือนถ้าเปิดบอททั้งวัน · Lv.98 ใช้ EXP น้อยลงจาก 250 ล้านเหลือ 106 ล้าน จึงไม่มีเลเวลไหนติดนานเป็นสัปดาห์อีก","มอนที่เลเวลสูงกว่าเราเกิน 10 ให้ EXP ลดลง 5% ต่อเลเวลที่เกิน (ต่ำสุด 10%) ยกเว้นบอสแมพ · มอนที่เลเวลต่ำกว่าเรายังให้ EXP เต็ม","Mage: Frost Area แช่แข็ง 50% นาน 3 วินาที คูลดาวน์ 6 วินาที (เดิม 77% · 5 วินาที · 1.7 วินาที)","Swordsman: Power Strike Lv.10 เหลือ 420% ATK (เดิม 530%)","Merchant: Gold Strike ใช้ SP น้อยลง (Lv.10 ใช้ 3 จากเดิม 8) · Weight Training เพิ่ม ATK +5% ต่อระดับ (สูงสุด +50%) · Hammer ลด ASPD แค่ 2 (เดิม 6)","Auto Play: สกิลโจมตีที่เรียนแล้วถูกติ๊กให้ใช้เองตั้งแต่แรก · ถ้าเคยเอาติ๊กออกเองระบบคงไว้ตามเดิม ส่วน Power Strike และ Flame Burst ที่ไม่ได้ติ๊กเพราะค่าเริ่มต้นเก่าจะกลับมาติ๊กให้"],en:{title:"Progression rework: about 3 months to Lv.99 · class balance changes",lines:["New EXP table: early levels still come fast, but reaching Lv.99 now takes about 3 months of botting all day · Lv.98 now needs 106 million EXP instead of 250 million, so no single level takes weeks to clear anymore.","Monsters more than 10 levels above you give 5% less EXP per level over (floor 10%), except map bosses · monsters below your level still give full EXP.","Mage: Frost Area freeze chance 50%, duration 3 seconds, cooldown 6 seconds (was 77% · 5 seconds · 1.7 seconds).","Swordsman: Power Strike Lv.10 drops to 420% ATK (was 530%).","Merchant: Gold Strike costs less SP (Lv.10 now 3, was 8) · Weight Training gives ATK +5% per level (max +50%) · the Hammer now only reduces ASPD by 2 (was 6).","Auto Play: learned attack skills are now ticked on by default · if you'd unticked one yourself, that choice is kept · Power Strike and Flame Burst, left unticked by the old default, get re-ticked for you."]}},{id:"2026-09-24-market-one-click-buy",date:"2026-09-24",time:"02:04",title:"ตลาดกลางโฉมใหม่ กดซื้อได้ทันที",lines:['กดปุ่ม "ซื้อ" ในรายการหรือ "ซื้อสินค้า" ทางขวา จะซื้อทันที ไม่มีหน้ายืนยันเด้งขึ้นมาแล้ว · เช็กจำนวนและราคาในแผงขวาก่อนกดนะ',"แผงรายละเอียดทางขวาจัดใหม่: คำอธิบายไอเทม ข้อมูลผู้ขาย และช่องเลือกจำนวนที่ต้องการซื้อแยกเป็นหัวข้อชัดเจน · ดูกราฟราคาเฉลี่ยได้จากปุ่มกราฟมุมขวาของกล่องคำอธิบาย",'ผู้เล่น Premium จะเห็นป้าย "Premium - ซื้อขายได้จากทุกที่" มุมขวาบนของหน้าต่างตลาด'],en:{title:"Market redesign: buy instantly with one click",lines:['Pressing "Buy" in the list or "Buy item" on the right now purchases instantly — no confirmation window pops up anymore · check the quantity and price in the right panel before you press it.',"The detail panel on the right is reorganized: item description, seller info, and the quantity selector are now clearly separated · view the average price chart from the chart button in the corner of the description box.",'Premium players see a "Premium - trade from anywhere" badge in the top-right corner of the Market window.']}},{id:"2026-09-24-archer-thief-passive-buff",date:"2026-09-24",time:"01:36",title:"บัฟสกิล Archer และ Thief",lines:["Archer: Keen Eye เพิ่ม DEX +2 และ Hit +1% ต่อระดับ (สูงสุด +20 / +10%) · ATK เพิ่มเท่ากับ 2% ของ Hit + 6.5% ของ DEX ต่อระดับ (สูงสุด 20% / 65%)","Archer: Twin Shot โอกาสยิง 4 ฮิตเพิ่มเป็น 43% · ใช้ SP 1.8 ต่อระดับเหมือนเดิม (Lv.10 = 18)","Thief: Fatal Sense เพิ่ม ATK เท่ากับ 6.5% ของ AGI ต่อระดับ (สูงสุด 65%) · ดาเมจคริ +2% และ ASPD +1% ต่อระดับเหมือนเดิม (สูงสุด +20% / +10%)"],en:{title:"Archer and Thief skill buffs",lines:["Archer: Keen Eye gives DEX +2 and Hit +1% per level (max +20 / +10%) · ATK increases by 2% of Hit + 6.5% of DEX per level (max 20% / 65%).","Archer: Twin Shot's chance to fire 4 hits rises to 43% · still costs 1.8 SP per level (Lv.10 = 18).","Thief: Fatal Sense increases ATK by 6.5% of AGI per level (max 65%) · crit damage +2% and ASPD +1% per level stay the same (max +20% / +10%)."]}},{id:"2026-09-24-trade-premium-with-anyone",date:"2026-09-24",time:"01:17",title:"ผู้เล่น Premium เทรดกับผู้เล่นทั่วไปได้แล้ว",lines:["ผู้เล่น Premium เริ่มเทรดไอเทมและ Silver กับผู้เล่นคนไหนก็ได้ อีกฝ่ายไม่ต้องมี Premium","ผู้เล่นที่ไม่มี Premium รับคำขอเทรดจากผู้เล่น Premium ได้ แต่เริ่มเทรดเองไม่ได้ · ซื้อขายผ่านตลาดกลางได้ตามปกติ"],en:{title:"Premium players can now trade with anyone",lines:["Premium players can now start a trade for items and Silver with any player, whether or not the other player has Premium.","A player without Premium can accept a trade request from a Premium player, but can't start one themselves · buying and selling through the Market still works as usual."]}},{id:"2026-09-24-no-tap-highlight",date:"2026-09-24",time:"01:09",title:"กดปุ่มบนมือถือไม่มีกรอบสีฟ้าแล้ว",lines:["แตะปุ่มเมนู (สถานะ สกิล อุปกรณ์ ฯลฯ) บนมือถือเคยมีกรอบสีฟ้าเทาขึ้นมาครอบชั่วครู่ ตอนนี้เอาออกแล้ว"],en:{title:"No more blue highlight when tapping buttons on mobile",lines:["Tapping menu buttons (Status, Skills, Equipment, etc.) on mobile used to briefly flash a blue-grey outline around them. That's now removed."]}},{id:"2026-09-24-bag-limits-on-mail-and-market",date:"2026-09-24",time:"01:07",title:"ของจากจดหมายและตลาดไม่ทะลุกระเป๋าอีกแล้ว",lines:["กดรับของจากจดหมายตอนกระเป๋าเต็มหรือน้ำหนักเกิน ระบบจะบอกให้เคลียร์กระเป๋าก่อน แทนที่จะยัดของเข้าไปจนเก็บของอื่นไม่ได้ · กดรับทั้งหมดจะได้เท่าที่กระเป๋ารับไหว ที่เหลือยังอยู่ในกล่องจดหมาย","ไอเทมจากตลาดที่กระเป๋ารับไม่ไหวจะถูกส่งเข้ากล่องจดหมายแทน ส่วนอุปกรณ์จากกระดานต้องมีช่องและน้ำหนักพอก่อนซื้อ","ชื่อตัวละครบนการ์ดโปรไฟล์ไม่ถูกแปลอีกแล้วเมื่อเปลี่ยนภาษาเกม และปุ่ม Esc ปิดแผนที่ขยายไม่ซ้อนตัวเองทุกครั้งที่เปลี่ยนแมพ"],en:{title:"Mail and market items no longer overflow your bag",lines:["Claiming mail while your bag is full or overweight now tells you to clear space first, instead of stuffing the item in and locking out anything else · Claim All now grabs as much as your bag can hold, and leaves the rest in your mailbox.","Market items your bag can't fit are now delivered to your mailbox instead · gear bought from the board still needs a free slot and enough weight room before purchase.","Character names on the profile card no longer get translated when you switch the game's language, and Esc no longer stacks extra closes on the expanded map every time you change maps."]}},{id:"2026-09-24-stuck-checking-character",date:"2026-09-24",time:"00:42",title:'แก้ค้างหน้า "กำลังตรวจสอบข้อมูลตัวละคร"',lines:['ตัวละครบางตัวเข้าเกมไม่ได้ ค้างที่หน้าโหลด "กำลังตรวจสอบข้อมูลตัวละคร" ทั้งที่ข้อมูลยังอยู่ครบ · ระบบจะชี้กลับไปยังช่องที่เก็บตัวละครจริงให้เองหลังอัปเดต'],en:{title:'Fixed getting stuck on "Checking your character data"',lines:[`Some characters couldn't log in, stuck on the "Checking your character data" loading screen even though their data was intact · the game now points itself back to the channel actually holding the character after this update.`]}},{id:"2026-09-24-hotbar-potion-count",date:"2026-09-24",time:"00:41",title:"ช่องยา HP บนคีย์ลัดแสดงตรงกับกระเป๋า",lines:["ช่องยาฟื้น HP บนคีย์ลัดเคยโชว์รูปยาแดงแต่ตัวเลขเป็นยอดรวมยา HP ทุกสี ดูแล้วเหมือนจำนวนไม่ตรงกับกระเป๋า","ตอนนี้ช่องจะโชว์รูปและจำนวนของขวดที่จะใช้ก่อน (ใช้จากขวดเล็กสุด: แดง → ส้ม → เหลือง → ขาว) พอขวดนั้นหมดก็เปลี่ยนเป็นสีถัดไปเอง · ชี้ที่ช่องเพื่อดูยอดรวมทุกขวด"],en:{title:"The HP potion hotkey slot now matches your bag",lines:["The HP potion hotkey slot used to show a Red Potion icon but the count was the total of every color of HP potion combined, making it look like the number didn't match your bag.","The slot now shows the icon and count of whichever potion will be used next (smallest first: Red → Orange → Yellow → White), switching to the next color automatically once one runs out · hover the slot to see the total across all colors."]}},{id:"2026-09-24-hud-default-70",date:"2026-09-24",time:"00:33",title:"ขนาด HUD เริ่มต้นเล็กลงเป็น 70%",lines:["ขนาด HUD / UI มาตรฐานเปลี่ยนจาก 100% เป็น 70% ปุ่ม เมนู แผนที่ย่อ แชต และหน้าต่างต่าง ๆ จะเล็กลง เห็นฉากเกมได้กว้างขึ้น",'ใครเคยปรับขนาดเองไว้แล้ว ขนาดจะยังเท่าเดิม · อยากปรับอีกก็ทำได้ที่ "ขนาด HUD / UI" ในตั้งค่า ปุ่ม "มาตรฐาน" จะพากลับไปที่ 70%'],en:{title:"Default HUD size reduced to 70%",lines:["The default HUD / UI size changes from 100% to 70%. Buttons, menus, the minimap, chat and windows all shrink, so you can see more of the game world.",`If you'd already set a custom size, it stays exactly as you left it · you can still adjust it in "HUD / UI Size" under Settings, and the "Default" button now returns you to 70%.`]}},{id:"2026-09-24-mail-after-payment",date:"2026-09-24",time:"00:25",title:"เติมเงินแล้วเห็นจดหมาย Gold ทันที",lines:["จ่ายเงินเสร็จแล้วกลับเข้าเกม กล่องจดหมายจะเปิดให้เอง และจดหมาย Gold จะขึ้นภายในไม่กี่วินาทีหลังระบบรับยอด ไม่ต้องรอป้ายแจ้งเตือนอีกครึ่งนาทีเหมือนก่อน"],en:{title:"Gold mail arrives right after payment",lines:["After paying and returning to the game, your mailbox now opens automatically, and the Gold mail appears within a few seconds of the payment being received — no more waiting up to half a minute for the notification like before."]}},{id:"2026-09-24-starter-pack",date:"2026-09-24",time:"00:21",title:"Starter Pack ใน Item Mall และแพ็กเติม ฿30",lines:["Starter Pack ราคา 160 Gold: ชุด Lumina ครบ 9 ช่อง + อาวุธทุกสาย 6 ชิ้น สวมได้ทุกอาชีพตั้งแต่ Lv.1 ซื้อแล้วใส่ได้เลย ค่าพลังพอพาเก็บเลเวลถึงราว Lv.70","ของในแพ็กผูกกับตัวละคร ขาย ทิ้ง เทรด และตั้งขายไม่ได้ · ซื้อได้ 1 ครั้งต่อตัวละคร","แพ็ก Gold ใหม่: เติม ฿30 ได้ 160 Gold พอดีกับ Starter Pack","Item Mall แบ่งเป็นหน้า: หน้า 1 Starter Pack · หน้า 2 Scroll"],en:{title:"Starter Pack in the Item Mall, plus a THB 30 top-up pack",lines:["Starter Pack costs 160 Gold: the full 9-slot Lumina set plus all 6 weapon types, wearable by every class from Lv.1. Equip it right after buying, and it's strong enough to carry you to around Lv.70.","Pack items are bound to the character — they can't be sold, dropped, traded or listed · limited to one purchase per character.","New Gold pack: THB 30 for 160 Gold, exactly enough for the Starter Pack.","The Item Mall is now split into pages: page 1 Starter Pack · page 2 Scrolls."]}},{id:"2026-09-24-no-afk-kick",date:"2026-09-24",time:"00:19",title:"ยืน AFK ได้ ไม่โดนเตะออกแล้ว",lines:["เลิกเตะผู้เล่นที่ยืนเฉยไม่กดอะไรเกิน 5 นาทีออกจากเกม ยืนรอเพื่อน นั่งพัก หรือเปิดทิ้งไว้ได้ตามสบาย","ยังหลุดได้ถ้าเน็ตขาดจริง ๆ หรือเซสชันหมดอายุเหมือนเดิม"],en:{title:"Stand AFK without getting kicked",lines:["Players are no longer kicked for standing idle with no input for over 5 minutes. Wait for friends, rest, or leave the game open freely.","You can still be disconnected if your connection actually drops or your session expires, as before."]}},{id:"2026-09-24-item-mall-shop",date:"2026-09-24",time:"00:13",title:"เปิด Item Mall และเปลี่ยนชื่อปุ่ม Premium เป็น Shop",lines:["ปุ่ม Premium บนแถบเมนูเปลี่ยนชื่อเป็น Shop พร้อมไอคอนใหม่ ข้างในยังมี Premium, ซื้อ Gold และตลาด Gold ครบเหมือนเดิม","แท็บใหม่ Item Mall: ซื้อ EXP Scroll (EXP x2) และ Drop Scroll (ดรอป x2) ด้วย Gold ม้วนละ 30 Gold · 5 ม้วน 135 (-10%) · 10 ม้วน 240 (-20%)","ของเข้ากระเป๋าทันที ซื้อได้จากทุกที่ ม้วนผูกกับตัวละคร ขายและเทรดไม่ได้ · ไม่มี Gold ก็แลกด้วย Silver ที่ตลาด Gold ได้"],en:{title:"Item Mall launches, and the Premium button is renamed Shop",lines:["The Premium button on the menu bar is renamed Shop, with a new icon. Inside, Premium, buying Gold and the Gold Exchange are all still there as before.","New Item Mall tab: buy EXP Scrolls (EXP x2) and Drop Scrolls (drop x2) with Gold — 30 Gold each · 5 scrolls for 135 (-10%) · 10 scrolls for 240 (-20%).","Scrolls land in your bag instantly and can be bought from anywhere. They're bound to the character and can't be sold or traded · no Gold? Trade Silver for it on the Gold Exchange."]}},{id:"2026-09-24-five-bosses-per-map",date:"2026-09-24",time:"00:04",title:"บอสประจำแมพเพิ่มเป็น 5 ตัว สุ่มช่อง",lines:["ทุกแมพล่ามีบอส Crowned ได้สูงสุด 5 ตัวพร้อมกัน กระจายอยู่ในช่องที่มีผู้เล่นแบบสุ่ม ช่องละไม่เกิน 1 ตัว (เดิมมีแค่ช่อง 1 ตัวเดียว)","ช่องที่คนเยอะมีโอกาสได้บอสมากกว่า · บอสที่ถูกล้มจะเกิดใหม่ 1 ชั่วโมงต่อมาในช่องสุ่ม","ไม่มีประกาศว่าบอสเกิดที่ช่องไหน ต้องเปลี่ยนช่องออกล่าหาเอง"],en:{title:"Map bosses now spawn up to 5 at once, in random channels",lines:["Every hunting map can now have up to 5 Crowned bosses alive at once, spread randomly across channels with players, at most 1 per channel (previously there was only ever a single boss in one channel).","Busier channels have a better chance of getting a boss · a fallen boss respawns an hour later in a random channel.","There's no announcement of which channel a boss spawns in — you'll need to switch channels and hunt it down yourself."]}},{id:"2026-09-23-one-layout-every-device",date:"2026-09-23",time:"23:53",title:"หน้าจอเดียวกันทุกเครื่อง",lines:['เลิกย่อหน้าต่างอัตโนมัติตามขนาดจอ: มือถือได้หน้าต่างขนาดเท่ากับคอมแล้ว ถ้าอยากให้เล็กลงหรือใหญ่ขึ้น ปรับเองได้ที่ "ขนาด HUD" ในตั้งค่า',"HUD ใช้หน่วยขนาดเดียวกันทุกเครื่อง ไม่ย่อตามความกว้างจออีกต่อไป","หน้าต่างเควสต์เปิดค้างไว้ตั้งแต่เข้าเกมเหมือนกันทุกเครื่อง ไม่ถูกซ่อนบนมือถือแล้ว","ช่องแชทค้างเคอร์เซอร์ไว้ให้พิมพ์ต่อได้ทันทีทุกเครื่อง กด Enter ตอนช่องว่างเพื่อออกจากช่อง"],en:{title:"The same layout on every device",lines:['Windows no longer auto-shrink to fit your screen size: mobile now gets the same window size as PC. If you want it smaller or bigger, adjust it yourself in "HUD Size" under Settings.',"The HUD now uses the same size unit on every device, no longer scaling down with screen width.","The quest window now stays open from login the same way on every device, no longer hidden on mobile.","The chat box now keeps its cursor ready to type on every device — press Enter while it's empty to leave the box."]}},{id:"2026-09-23-profile-card-redesign",date:"2026-09-23",time:"23:48",title:"การ์ดข้อมูลตัวละครโฉมใหม่",lines:["จัดการ์ดข้อมูลตัวละครมุมซ้ายบนใหม่: ชื่อ เลเวล และอาชีพอยู่แถวเดียวกัน, Silver กับน้ำหนักแยกเป็นสองช่อง, HP / SP / EXP รวมอยู่ในกรอบเดียว แถบ Job อยู่ด้านล่าง และแถบสถานะยังอยู่ล่างสุดเหมือนเดิม","EXP และ Job EXP แสดงเป็นเปอร์เซ็นต์ ชี้เมาส์ค้างไว้เพื่อดูตัวเลขเต็ม"],en:{title:"Character info card redesigned",lines:["The character info card in the top-left corner has been reorganized: name, level and class share one row; Silver and weight get their own two boxes; HP / SP / EXP sit together in one frame; the Job bar sits below that; and the status bar stays at the very bottom as before.","EXP and Job EXP now show as percentages — hover to see the full numbers."]}},{id:"2026-09-23-hit-matters-monster-balance",date:"2026-09-23",time:"23:23",title:"ค่า HIT มีผลจริงแล้ว และปรับสมดุลมอนสเตอร์",lines:["มอนทุกตัวมี FLEE ตามเลเวล (100 + 2 × เลเวล) โอกาสตีโดน = 90% บวก 0.5% ต่อ HIT ที่เกิน FLEE ของมอน ต่ำสุด 50% สูงสุด 100%","ใช้กับการโจมตีปกติและสกิลกายภาพ ส่วนคริติคอลและสกิลเวทโดนเสมอ · สายที่ไม่อัป DEX ตีมอนเลเวลเท่ากันโดนราว 85% ตีมอน Lv.150+ โดนราวครึ่งเดียว","ดู FLEE ของมอนและ HIT ที่ต้องมีเพื่อตีโดนทุกครั้งได้ในสมุดมอนสเตอร์","อุปกรณ์ที่ดรอปใหม่: HIT เต็ม (1–4) × ขั้นเฉพาะอาวุธ ลูกธนู และแหวนซ้าย ชิ้นอื่นได้ 0 หรือ 1 × ขั้น","Tide Crab, Forest Wolf, Lantern Wisp, Wild Boar และ Cave Bat มี HP ต่ำกว่ามอนเลเวลเดียวกันถึง 2–4 เท่าแต่ให้ EXP เท่ากัน ตอนนี้ปรับให้อยู่ระดับเดียวกับมอนตัวอื่นแล้ว","ปรับ HP มอนให้เรียงตามเลเวลในแต่ละแมพ: Cave Bat 10k → 49k, Pebble Golem 46k → 56k, Honey Moth, Mud Newt, Reed Mantis และ Moon Owl เพิ่มขึ้นเล็กน้อย ส่วน Scarab Sentinel ลดลงจาก 4.4k เหลือ 3.2k ให้ตีง่ายพอ ๆ กับมอนตัวอื่นในทะเลทราย","ดาเมจมอนโตช้าลงตามเลเวล: มอนช่วงต้นแทบไม่เปลี่ยน มอน Lv.90–100 ตีเบาลงราว 15% และ Lv.100 ขึ้นไปเบาลงราว 20% แต่ยังหนักอยู่"],en:{title:"HIT now actually matters, and monster balance changes",lines:["Every monster now has FLEE scaling with its level (100 + 2 × level). Hit chance = 90% plus 0.5% per point of HIT above the monster's FLEE, with a floor of 50% and a cap of 100%.","This applies to basic attacks and physical skills; criticals and magic skills still always land · a build that never invests in DEX hits a same-level monster around 85% of the time, and a Lv.150+ monster only about half the time.","Check a monster's FLEE and the HIT you need to always land a hit in the Monster Book.","Newly dropped gear: full HIT (1–4) × tier now rolls only on weapons, arrows and the left ring slot — other pieces get 0 or 1 × tier.","Tide Crab, Forest Wolf, Lantern Wisp, Wild Boar and Cave Bat had 2–4 times less HP than other same-level monsters while giving the same EXP. They're now brought in line with the rest.","Monster HP within each map now scales properly by level: Cave Bat 10k → 49k, Pebble Golem 46k → 56k, with small increases for Honey Moth, Mud Newt, Reed Mantis and Moon Owl. Scarab Sentinel drops from 4.4k to 3.2k, to be about as easy to kill as the other desert monsters.","Monster damage now scales up more slowly with level: early monsters barely change, Lv.90–100 monsters hit about 15% lighter, and Lv.100+ monsters hit about 20% lighter — though still hard-hitting."]}},{id:"2026-09-23-gear-flee-rebalance",date:"2026-09-23",time:"22:58",title:"ปรับสมดุล FLEE บนอุปกรณ์",lines:["อุปกรณ์ที่ดรอปใหม่: มีแค่ผ้าคลุมและรองเท้าที่ได้ FLEE (1–4) × ขั้น ชิ้นอื่นได้แค่ 0 หรือ 1 × ขั้น","FLEE จากอุปกรณ์และการ์ดรวมกันช่วยหลบได้สูงสุด 20% ส่วน FLEE จาก AGI, LUK และ Fleet Foot คิดเต็มเหมือนเดิม","อุปกรณ์เดิมยังเก็บค่า FLEE ไว้ตามเดิม แต่ส่วนที่ช่วยหลบจะถูกจำกัดที่ 20% เช่นกัน","สาเหตุ: เดิมใส่ชุดดรอปครบแล้วทุกอาชีพหลบได้ 95% จนค่า AGI และสกิล Fleet Foot ของ Thief แทบไม่มีผล"],en:{title:"FLEE on gear rebalanced",lines:["Newly dropped gear: only garments and shoes can roll FLEE (1–4) × tier — other pieces get only 0 or 1 × tier.","FLEE from gear and cards combined now caps at 20% dodge chance, while FLEE from AGI, LUK and Fleet Foot still counts in full.","Existing gear keeps its FLEE stat unchanged, but the dodge chance it contributes is capped at 20% as well.","Reason: a full set of dropped gear used to give every class 95% dodge, making AGI and the Thief's Fleet Foot skill almost pointless."]}},{id:"2026-09-23-touch-controls-opacity",date:"2026-09-23",time:"22:30",title:"จอยและปุ่มบนจอจางลง ปรับความทึบเองได้",lines:["จอยสติ๊กและปุ่มโจมตี / สกิลบนจอจางลงตอนไม่ได้แตะ มองเห็นฉากและมอนสเตอร์ด้านหลังได้ชัดขึ้น",'ปรับความทึบได้ที่ ตั้งค่า > การเล่นเกม > "ความทึบจอย / ปุ่ม" ตั้งแต่ 20% ถึง 100%',"ปุ่มที่กำลังกด และปุ่ม AUTO ตอนบอททำงาน ยังแสดงชัดเต็มเหมือนเดิม"],en:{title:"Joystick and on-screen buttons now dimmer, with adjustable opacity",lines:["The joystick and attack/skill buttons now dim when you're not touching them, so you can see the scene and monsters behind them more clearly.",'Adjust the opacity in Settings > Gameplay > "Joystick / Button Opacity", from 20% to 100%.',"A button you're actively pressing, and the AUTO button while the bot is running, still show at full opacity as before."]}},{id:"2026-09-23-daily-exp-ranking",date:"2026-09-23",time:"22:14",title:"อันดับประจำวันนับจาก EXP ที่ได้",lines:['หน้าต่าง Ranking เปลี่ยนเป็น "อันดับ EXP" เรียงตาม Base EXP ที่ได้ทั้งวันของเมื่อวาน แทนการเรียงตามเลเวล',"เริ่มนับ EXP ตั้งแต่วันนี้ กระดานแรกขึ้นหลังเที่ยงคืน และอัปเดตทุกวันเวลา 00:00 น. (เวลาไทย)","เลเวลของแต่ละคนยังแสดงอยู่ข้างชื่อ"],en:{title:"Daily ranking now counts EXP earned",lines:[`The Ranking window becomes "EXP Ranking", sorted by yesterday's total Base EXP earned instead of by level.`,"EXP counting starts today; the first board appears after midnight, and it updates daily at 00:00 (Thai time).","Each player's level still shows next to their name."]}},{id:"2026-09-23-boot-injected-script",date:"2026-09-23",time:"22:19",title:'แก้อาการค้างที่หน้า "โหลดเกมไม่สำเร็จ"',lines:['บางเบราว์เซอร์ (เช่นที่มีแถบผู้ช่วย AI ตัวแปลภาษา หรือส่วนเสริม) ทำให้เกมขึ้น "โหลดเกมไม่สำเร็จ" ทุกครั้ง แม้กดโหลดใหม่ก็เข้าไม่ได้ ตอนนี้แก้แล้ว เข้าเกมได้ตามปกติ'],en:{title:'Fixed getting stuck on "Failed to load the game"',lines:['Some browsers (for example, ones with an AI assistant bar, a translator, or other extensions) caused the game to show "Failed to load the game" every time, even after reloading. This is now fixed, and the game loads normally.']}},{id:"2026-09-23-english-item-names",date:"2026-09-23",time:"21:00",title:"ชื่อไอเท็มเป็นภาษาอังกฤษทั้งหมด",lines:["ยา ม้วนคัมภีร์ กล่อง วัตถุดิบ และอุปกรณ์ดรอป ใช้ชื่อภาษาอังกฤษล้วน เช่น Red Potion, Warp Scroll, Spirit Shard, Refine Stone, Ruby Ring","อุปกรณ์ที่มีอยู่แล้วในกระเป๋า คลัง และกระดานตลาด จะเปลี่ยนชื่อให้อัตโนมัติ ค่าสถานะไม่เปลี่ยน","ป้ายช่องการ์ดท้ายชื่ออุปกรณ์เปลี่ยนเป็น [Card] และ [Empty]","ข้อความในเกม เควส Wiki และทุกภาษาที่เลือกได้ เรียกไอเท็มด้วยชื่อภาษาอังกฤษชื่อเดียวกัน ผู้เล่นทุกประเทศคุยเรื่องไอเท็มชิ้นเดียวกันได้ตรงกัน"],en:{title:"Item names are now all in English",lines:["Potions, scrolls, boxes, materials and dropped gear now use English names only, such as Red Potion, Warp Scroll, Spirit Shard, Refine Stone, Ruby Ring.","Gear already sitting in your bag, storage or on the market board will have its name changed automatically. Stats are unaffected.","The card-slot tag after an item's name changes to [Card] and [Empty].","In-game text, quests, the Wiki and every selectable language now refer to an item by the same English name, so players from any country can talk about the same item without confusion."]}},{id:"2026-09-23-refund-requests",date:"2026-09-23",time:"20:59",title:"ขอคืนเงินค่า Gold ได้ในเกม",lines:['ร้านค้า Premium มีแท็บใหม่ "ประวัติการเติม" ดูยอดที่เติมทั้งหมด และกด "ขอคืนเงิน" ได้ภายใน 3 วัน ถ้ายังไม่ได้กดรับ Gold จากจดหมาย',"ยอดที่เติมก่อนประกาศเปลี่ยนเป็นการสนับสนุนเกม (23 ก.ย. 2569) ขอคืนได้ถึง 23 ต.ค. 2569 แม้กดรับแล้ว ถ้า Gold ยังอยู่ครบในกระเป๋า","วันเปิดเซิร์ฟเวอร์จริงทุกอย่างเริ่มใหม่หมด ไม่มีการคืน Gold ให้ใคร","เมื่อส่งคำขอ Gold จำนวนนั้นจะถูกพักไว้ ทีมงานจะแจ้งผลทางกล่องจดหมาย ถ้าไม่อนุมัติ Gold จะส่งคืนให้ครบ"],en:{title:"Gold refund requests, now in-game",lines:[`The Premium shop has a new "Top-up history" tab, showing every top-up, with a "Request refund" button available for 3 days as long as you haven't yet claimed the Gold from mail.`,"Top-ups made before the announcement that this counts as supporting the game (Sep 23, 2026) can be refunded through Oct 23, 2026, even after being claimed, as long as the Gold is still fully in your inventory.","On the real launch day, everything resets — no Gold will be given back to anyone.","Once a request is sent, that amount of Gold is held in escrow. The team will reply through your mailbox, and if it's not approved, the Gold is returned to you in full."]}},{id:"2026-09-23-trade-premium-only",date:"2026-09-23",time:"20:45",title:"ระบบเทรดเป็นสิทธิประโยชน์ของ Premium",lines:["เทรดไอเทมและ Silver กับผู้เล่นคนอื่นโดยตรงได้เฉพาะผู้เล่น Premium และอีกฝ่ายต้องมี Premium ด้วย","ผู้เล่นที่ไม่มี Premium ยังซื้อขายผ่านตลาดกลางได้ตามปกติทุกอย่าง"],en:{title:"Trading is now a Premium benefit",lines:["Trading items and Silver directly with another player is now limited to Premium players, and the other side must have Premium too.","Players without Premium can still buy and sell through the Market as normal."]}},{id:"2026-09-23-skill-rebalance",date:"2026-09-23",time:"12:58",title:"ปรับสมดุลสกิล: Swordsman · Mage · Archer · Thief · Merchant",lines:["Swordsman: Vigor ลดเหลือ ATK +1% ของ HP สูงสุดต่อระดับ (สูงสุด 10%) · Iron Body เพิ่ม HP สูงสุด +0.5% ต่อระดับ (สูงสุด +5%) · Power Strike ทำดาเมจเพิ่ม 0.1% ของ MaxHP ศัตรูต่อระดับ (Lv.10 = 1%, บอสโลกรับ 1/10)","Mage: Mentality เพิ่ม SP สูงสุด +0.5% ต่อระดับ และ MATK เพิ่มเท่ากับ 1.5% ของ SP สูงสุด + 3.5% ของ DEX ต่อระดับ (สูงสุด 15% / 35%)","Archer: Keen Eye เพิ่ม Hit +0.5% ต่อระดับ และ ATK เพิ่มเท่ากับ 0.5% ของ Hit + 1.5% ของ DEX ต่อระดับ · Twin Shot โอกาสยิง 4 ฮิตเป็น 38% และใช้ SP 1.8 ต่อระดับ (Lv.10 = 18)","Thief: Fatal Sense เพิ่ม ATK เท่ากับ 1.5% ของ AGI ต่อระดับ (สูงสุด 15%) · ดาเมจคริ +2% และ ASPD +1% ต่อระดับเหมือนเดิม","Merchant: Cart Strike คูลดาวน์ 3.5 วิ ใช้ SP 3.5 ต่อระดับ (Lv.10 = 35) · Quake Hammer คูลดาวน์ 4.5 วิ ใช้ SP 4 ต่อระดับ (Lv.10 = 40)"],en:{title:"Skill rebalance: Swordsman · Mage · Archer · Thief · Merchant",lines:["Swordsman: Vigor drops to ATK +1% of max HP per level (max 10%) · Iron Body gives max HP +0.5% per level (max +5%) · Power Strike now deals bonus damage equal to 0.1% of the enemy's max HP per level (Lv.10 = 1%, world bosses take 1/10 of that).","Mage: Mentality gives max SP +0.5% per level, and MATK increases by 1.5% of max SP + 3.5% of DEX per level (max 15% / 35%).","Archer: Keen Eye gives Hit +0.5% per level, and ATK increases by 0.5% of Hit + 1.5% of DEX per level · Twin Shot's chance to fire 4 hits is 38%, costing 1.8 SP per level (Lv.10 = 18).","Thief: Fatal Sense increases ATK by 1.5% of AGI per level (max 15%) · crit damage +2% and ASPD +1% per level stay the same.","Merchant: Cart Strike cooldown 3.5 seconds, costing 3.5 SP per level (Lv.10 = 35) · Quake Hammer cooldown 4.5 seconds, costing 4 SP per level (Lv.10 = 40)."]}},{id:"2026-09-23-thirty-two-channels",date:"2026-09-23",time:"20:24",title:"แมปเปิดช่องได้ถึง 32 ช่อง",lines:["ขยายเพดานจาก 16 เป็น 32 ช่องต่อหนึ่งแมป ช่วงคนเยอะ Desert เปิดครบ 16 ช่องและแน่นทุกช่อง ตอนนี้คนที่เข้ามาใหม่จะได้ช่องใหม่ที่โล่งกว่าแทน","ช่องใหม่ยังเปิดเองเมื่อคนแน่นและปิดเองเมื่อคนออกหมดเหมือนเดิม"],en:{title:"Maps can now open up to 32 channels",lines:["The channel cap rises from 16 to 32 per map. During busy times, Desert used to fill all 16 channels to capacity — now newcomers get a fresh, less crowded channel instead.","New channels still open automatically when crowded and close automatically once empty, as before."]}},{id:"2026-09-23-wiki-refresh-premium-tile",date:"2026-09-23",time:"16:47",title:"Wiki อัปเดตใหม่ อ่านง่ายขึ้น · ปุ่ม Premium อยู่แถวเมนูหลัก",lines:["หน้า Wiki ข้อมูลตรงกับเกมตอนนี้แล้ว: Job Lv. สูงสุด 70, ขั้นอุปกรณ์ I–V ตามเลเวลมอนที่ถูกต้อง, บอสประจำแมพครบ 7 ตัว, การ์ดครบ 33 ใบ, NPC ครบ 6 คน",'หน้า "ระบบเกม" มีสารบัญ และทุกหัวข้อมีสรุปสั้น ๆ ก่อน ส่วนสูตรยาว ๆ กดเปิดดูเองได้ · เพิ่มหัวข้อใหม่: เรื่องที่ควรรู้ก่อนเล่น, หลอมอุปกรณ์, บอส, ม้วน EXP/Drop x2, เทรดและล็อกไอเทม','โอกาสดรอปบอกเป็น "1 ใน กี่ตัว" ด้วย และเวลาเกิดใหม่บอกเป็นนาที/ชั่วโมง',"ปุ่ม Premium อยู่แถวไอคอนด้านบนแล้ว ไม่ต้องเปิดเมนูเพิ่มเติม (☰) ก่อน","แถบใต้แผนที่ย่อ (ช่อง · จำนวนคน · พิกัด) อยู่บรรทัดเดียวเสมอบนจอเล็ก"],en:{title:"Wiki refreshed and easier to read · Premium button moved to the main menu row",lines:["The Wiki now matches the current game: Job Lv. cap of 70, gear tiers I–V matched to the correct monster levels, all 7 map bosses, all 33 cards, and all 6 NPCs.",'The "Game Systems" page now has a table of contents, and every topic gets a short summary up front, with long formulas tucked away to expand · new sections added: what to know before you start, gear fusion, bosses, EXP/Drop x2 scrolls, and trading and item locking.','Drop chances now also show as "1 in how many", and respawn times show in minutes/hours.',"The Premium button now sits on the top icon row — no need to open the More menu (☰) first.","The bar under the minimap (channel · headcount · coordinates) now always fits on one line, even on small screens."]}},{id:"2026-09-23-chat-room-chip",date:"2026-09-23",time:"16:10",title:"เปลี่ยนห้องแชทได้จากช่องแชทเลย",lines:["มีปุ่มห้องแชท (เช่น 🌐 TH) อยู่หน้าช่องพิมพ์ กดแล้วเลือกห้องภาษาที่อยากคุยได้ทันที ไม่ต้องเข้าตั้งค่า","ปุ่มบอกตัวย่อห้องที่คุยอยู่ตอนนี้ และเปลี่ยนตามเมื่อย้ายห้อง ใช้ได้ทั้งคอมและมือถือ"],en:{title:"Switch chat rooms right from the chat box",lines:["A chat room button (e.g. 🌐 TH) now sits in front of the text box — press it to pick your language room instantly, without going into Settings.","The button shows the abbreviation of the room you're currently in, and updates when you switch. Works on both PC and mobile."]}},{id:"2026-09-23-keep-screen-on",date:"2026-09-23",time:"16:00",title:"จอไม่ดับเองระหว่างเล่น",lines:["เปิดเกมค้างไว้แล้วจอมือถือจะไม่หรี่และล็อกเองอีก เปิดบอททิ้งไว้ได้โดยไม่ต้องคอยแตะจอ","iPhone ต้องเป็น iOS 16.4 ขึ้นไป ถ้าเล่นจากไอคอนบนหน้าจอโฮมต้องเป็น iOS 18.4 ขึ้นไป · ถ้าเปิดโหมดประหยัดพลังงาน เครื่องอาจยังดับจอเองอยู่","ถ้าสลับไปแอปอื่นแล้วกลับมา ระบบจะกันจอดับให้ใหม่เอง ถ้าจอยังดับอยู่ให้แตะจอหนึ่งครั้ง"],en:{title:"The screen no longer sleeps while you play",lines:["Leaving the game open no longer dims and locks your phone screen — you can leave the bot running without having to keep tapping.","On iPhone, this needs iOS 16.4 or later; if playing from a home screen icon, iOS 18.4 or later is needed · with Low Power Mode on, your screen may still sleep on its own.","Switching to another app and back re-enables the screen lock, so if the screen still sleeps, just tap it once."]}},{id:"2026-09-23-chat-room-fix",date:"2026-09-23",time:"15:46",title:"แก้ห้องแชทจัดผิดห้อง",lines:["ผู้เล่นไทยบางคนถูกจัดเข้าห้องแชท English ตอนอัปเดตห้องแชทตามภาษา แก้แล้ว กลับมาอยู่ห้องไทยตามปกติ","ถ้ายังไม่ใช่ห้องที่ต้องการ เปลี่ยนได้ที่ ตั้งค่า → ห้องแชท"],en:{title:"Fixed players landing in the wrong chat room",lines:["Some Thai players were placed into the English chat room when language-based rooms rolled out. This is fixed, and they're back in the Thai room as normal.","If you're still in the wrong room, change it under Settings → Chat room."]}},{id:"2026-09-23-chat-language-rooms",date:"2026-09-23",time:"15:39",title:"แชทโลกแยกห้องตามภาษาแล้ว",lines:["แชทโลกไม่แยกตามภูมิภาคแล้ว แต่แยกเป็นห้องตามภาษา 24 ภาษา เช่น ไทย English 中文 日本語 한국어 Tiếng Việt Bahasa Indonesia Filipino Español Português และอีกมาก","เล่นเซิร์ฟเวอร์ภูมิภาคไหนก็คุยห้องเดียวกันได้ ย้ายเซิร์ฟเวอร์เพื่อ ping แล้วไม่เสียเพื่อนคุย","เกมเลือกห้องให้อัตโนมัติจากภาษาของเกม ภาษาเครื่อง หรือประเทศ · เปลี่ยนห้องได้ที่ ตั้งค่า → ห้องแชท"],en:{title:"World chat now split into rooms by language",lines:["World chat is no longer split by region — instead it's split into 24 language rooms, including Thai, English, 中文, 日本語, 한국어, Tiếng Việt, Bahasa Indonesia, Filipino, Español, Português, and more.","You can chat in the same room no matter which regional server you play on, so moving servers for a better ping no longer costs you your chat friends.","The game picks your room automatically from your game language, device language, or country · change it under Settings → Chat room."]}},{id:"2026-09-23-premium-market-bot",date:"2026-09-23",time:"15:38",title:"Premium: เปิด Market แล้วบอทยังตีมอนต่อ",lines:["ผู้เล่น Premium เปิดหน้าต่าง Market ระหว่างเปิดบอทได้แล้ว บอทจะตีมอน เก็บของ และกินยาต่อตามปกติ","ตั้งซื้อ ตั้งขาย หรือยกเลิกคำสั่งในตลาด ก็ไม่ปิดบอทแล้วเช่นกัน"],en:{title:"Premium: the bot keeps fighting with the Market open",lines:["Premium players can now open the Market window while the bot is running — it keeps attacking monsters, picking up loot and drinking potions as normal.","Placing a buy or sell order, or cancelling one, no longer stops the bot either."]}},{id:"2026-09-23-premium-market-tile",date:"2026-09-23",time:"15:19",title:"Premium: ปุ่ม Market อยู่แถวเมนูหลักแล้ว",lines:['ผู้เล่น Premium จะเห็นปุ่ม "Market" ที่แถวไอคอนด้านบนเลย ไม่ต้องเปิดเมนูเพิ่มเติม (☰) ก่อน กดแล้วเปิดตลาดกลางได้ทุกที่'],en:{title:"Premium: the Market button moved to the main menu row",lines:['Premium players now see a "Market" button right on the top icon row, no need to open the More menu (☰) first — press it to open the Market from anywhere.']}},{id:"2026-09-23-shop-confirm",date:"2026-09-23",time:"14:53",title:"ร้าน Premium: ยืนยันก่อนซื้อทุกครั้ง",lines:["กดซื้อ Gold จะมีหน้าต่างยืนยันขึ้นมา ต้องติ๊กรับทราบว่าเป็นการสนับสนุนเกม และจะไม่ได้รับ Gold คืนหลังรีเซ็ตเปิดเซิร์ฟเวอร์จริง ก่อนไปหน้าชำระเงิน","ซื้อ Premium ด้วย Gold เปลี่ยนจากกดซ้ำสองครั้ง เป็นหน้าต่างยืนยันที่บอกแพ็กเกจ ราคา และ Gold คงเหลือหลังซื้อ","ปรับข้อตกลงการใช้บริการให้ตรงกัน: Gold ที่เติมช่วงทดสอบเป็นการสนับสนุนเกม ต้องติ๊กยอมรับข้อตกลงฉบับใหม่อีกครั้ง"],en:{title:"Premium shop: confirm before every purchase",lines:["Buying Gold now shows a confirmation window — you must tick to acknowledge this is a donation to support the game, and that Gold won't be returned after the real-server reset, before going to the payment page.","Buying Premium with Gold changes from a double-tap into a confirmation window that shows the package, price, and remaining Gold after purchase.","The Terms of Service have been updated to match: Gold topped up during testing is a donation to support the game — you'll need to tick and accept the new terms again."]}},{id:"2026-09-23-starter-guide",date:"2026-09-23",time:"14:40",title:"ตัวละครใหม่มีคำแนะนำเริ่มเกมแล้ว",lines:["ตัวละคร Lv.1 จะเห็นการ์ดแนะนำ 3 ขั้น: เดินลงทางใต้ไปป่าเริ่มต้น → เปิด Auto Bot → ออกผจญภัย",'กด "พาเดินไปเลย" ให้ตัวละครเดินไปประตูเมืองเอง หรือกด × เพื่อข้ามได้'],en:{title:"New characters now get a starter guide",lines:["Lv.1 characters now see a 3-step guide card: walk south to Verdant Forest → turn on Auto Bot → head out and adventure.",'Press "Walk me there" to have your character walk to the town gate on its own, or press × to skip it.']}},{id:"2026-09-23-gold-donate-open",date:"2026-09-23",time:"14:06",title:"เปิดเติม Gold แล้ว — ช่วงทดสอบถือเป็นการสนับสนุนเกม",lines:["เปิดรับเติม Gold ด้วยบัตรหรือ PromptPay แล้ว ของส่งเข้ากล่องจดหมาย","เกมยังอยู่ระหว่างทดสอบระบบและพัฒนา ซึ่งน่าจะใช้เวลาอีกนาน การเติม Gold ช่วงนี้ถือเป็นการสนับสนุนและ Donate ให้ทีมพัฒนา จะไม่ได้รับ Gold คืนเมื่อเปิดเซิร์ฟเวอร์จริง","ใครยินดีสนับสนุนเกม เติมเพื่อใช้ Premium ได้เลย ขอบคุณที่ช่วยให้เกมได้ไปต่อครับ"],en:{title:"Gold top-ups are open — during testing, this counts as supporting the game",lines:["Topping up Gold by card or PromptPay is now open. Gold is delivered to your mailbox.","The game is still in system testing and development, which is likely to take a while longer. Topping up Gold during this period counts as a donation to the dev team, and it won't be given back when the real server launches.","If you'd like to support the game, feel free to top up for Premium. Thanks for helping keep the game going!"]}},{id:"2026-09-23-stale-copy-rollback",date:"2026-09-23",time:"14:00",title:"แก้ตัวละครเลเวลย้อนหลังเดินข้ามแผนที่",lines:["แก้กรณีเดินผ่านประตูหรือย้ายแชนแนลตอนเซิร์ฟเวอร์ติดขัด แล้วตัวละครไปโผล่เป็นสำเนาเก่า ทำให้เลเวลและของย้อนกลับ ตอนนี้จะเก็บตัวละครล่าสุดไว้เสมอ","ใครเจอเลเวลย้อนหลัง แจ้งทีมงานได้เลย กู้คืนให้จากข้อมูลล่าสุด"],en:{title:"Fixed characters reverting to old levels when crossing maps",lines:["Fixed a case where walking through a gate or switching channels during a server hiccup could load an old copy of your character, reverting your level and items. The game now always keeps your latest character data.","If you ran into a level rollback, let the team know and they'll restore you from the latest data."]}},{id:"2026-09-23-market-town-lag",date:"2026-09-23",time:"13:44",title:"แก้เดินในเมืองหน่วงตอนมีคนเปิดตลาด",lines:["แก้อาการเดินในเมืองหน่วง: หน้าต่างตลาดส่งเฉพาะรายการที่เปลี่ยน แทนการส่งกระดานอุปกรณ์ทั้งหมดใหม่ทุกครั้ง","กดรีโหลดหน้าเว็บเพื่อรับการแก้นี้"],en:{title:"Fixed lag walking in town while others had the Market open",lines:["Fixed lag while walking in town: the Market window now sends only what changed, instead of resending the entire gear board every time.","Reload the game page to get this fix."]}},{id:"2026-09-23-market-busy-fix",date:"2026-09-23",time:"13:27",title:"แก้ตลาดกลางตอบช้าหลังอัปเดต",lines:['แก้ตลาดกลางที่ตอบช้าและขึ้น "ตลาดกลางตอบช้า" บ่อยหลังอัปเดตแยกตลาดตามภูมิภาค คำสั่งที่รอยืนยันอยู่จะเสร็จเองโดยไม่ต้องสั่งซ้ำ'],en:{title:"Fixed the Market responding slowly after the update",lines:['Fixed the Market responding slowly and often showing "The Market is slow to respond" after the regional split. Orders still waiting on confirmation will complete on their own without needing to be resent.']}},{id:"2026-09-23-fusion-master",date:"2026-09-23",time:"13:23",title:"NPC ใหม่: ช่างหลอมรวม",lines:["ช่างหลอมรวมยืนอยู่ถนนฝั่งตะวันออกของ Aurelia Forum ข้างเจ้าหน้าที่คลัง","หลอมอาวุธ: ใช้อาวุธที่ดรอปจากมอนสเตอร์ Tier เดียวกัน 5 ชิ้น แลกอาวุธที่เลือกได้เอง 1 ชิ้น Tier เดียวกัน","หลอมชุดเกราะ: ใช้ชุดเกราะ หมวก รองเท้า ผ้าคลุม โล่ หรือเครื่องประดับ Tier เดียวกัน 5 ชิ้น (คละช่องได้) แลกชิ้นที่เลือก 1 ชิ้น","ของที่ได้สุ่มออปชั่นใหม่เหมือนดรอปจากมอนสเตอร์ · ของที่สวมอยู่ ล็อกไว้ หรือซื้อจากร้านใช้หลอมไม่ได้ · การ์ดและระดับตีบวกของชิ้นที่นำมาหลอมจะหายไป"],en:{title:"New NPC: the Fusion Master",lines:["The Fusion Master stands on the east side of the road in Aurelia Forum, next to the Storage Keeper.","Fuse weapons: hand over 5 monster-dropped weapons of the same tier to receive 1 weapon of your choice, same tier.","Fuse armor: hand over 5 pieces of the same tier — armor, helmets, shoes, garments, shields or accessories in any mix of slots — to receive 1 chosen piece.","The result rolls new random stats just like a monster drop · equipped, locked, or shop-bought items can't be used in fusion · cards and refine levels on the pieces consumed are lost."]}},{id:"2026-09-23-market-window-stuck",date:"2026-09-23",time:"13:13",title:"แก้หน้าต่างตลาดไม่อัปเดตในบางแมพ",lines:["แก้หน้าต่างตลาดในบางแมพที่ค้างไม่อัปเดตหลังอัปเดตล่าสุด"],en:{title:"Fixed the Market window not updating on some maps",lines:["Fixed the Market window getting stuck without updating on some maps after the last update."]}},{id:"2026-09-23-storage-withdraw-all",date:"2026-09-23",time:"13:10",title:"นำอุปกรณ์ออกจากคลังทีเดียว และเลื่อนกระเป๋าบนมือถือได้",lines:['คลังเก็บของมีปุ่ม "นำอุปกรณ์ออกทั้งหมด" ดึงอุปกรณ์ทุกชิ้นเข้ากระเป๋าในคลิกเดียว (หยุดเมื่อกระเป๋าเต็มหรือน้ำหนักเกิน)',"มือถือ: ปัดขึ้น–ลงบนช่องไอเท็มเพื่อเลื่อนดูของในกระเป๋าได้แล้ว (ลากไอเท็มให้ลากไปด้านข้าง)"],en:{title:"Withdraw all storage gear at once, and scroll your bag on mobile",lines:['Storage now has a "Withdraw all gear" button that pulls every piece into your bag in one click (it stops once your bag is full or overweight).',"Mobile: swipe up and down over the item slots to scroll through your bag (drag items sideways to move them instead)."]}},{id:"2026-09-23-regional-markets",date:"2026-09-23",time:"13:04",title:"ตลาดกลางแยกตามภูมิภาค",lines:["แต่ละภูมิภาค (SEA · NE · EUR · NAM · OC) มีตลาดกลางและกระดานอุปกรณ์ของตัวเอง ราคาแต่ละที่ต่างกันได้ ซื้อถูกที่หนึ่งไปขายแพงอีกที่ได้","ตลาด Gold ยังเป็นตลาดเดียวทั้งโลก ราคาเดียวกันทุกภูมิภาค","คำสั่งที่ตั้งไว้ก่อนหน้านี้ทั้งหมดอยู่ในตลาด SEA เหมือนเดิม",'"รายการของฉัน" แสดงคำสั่งที่ค้างในภูมิภาคอื่นพร้อมชื่อภูมิภาค กดเก็บคืนหรือยกเลิกได้จากทุกที่ ของกลับเข้ากระเป๋าทันที',"ตลาดตอบเร็วขึ้น: แต่ละภูมิภาคมีเซิร์ฟเวอร์ตลาดของตัวเอง และหน้าต่างตลาดโหลดเฉพาะส่วนที่เปลี่ยน"],en:{title:"The Market is now split by region",lines:["Each region (SEA · NE · EUR · NAM · OC) now has its own Market and gear board. Prices can differ between regions, so you can buy cheap in one and sell high in another.","The Gold Exchange remains a single, global market, with the same price in every region.","All orders placed before this change stay in the SEA market as before.",`"My Listings" now shows pending orders in other regions along with the region's name — you can retrieve or cancel them from anywhere, and items return straight to your bag.`,"The Market also responds faster: each region has its own market server, and the window loads only the parts that changed."]}},{id:"2026-09-23-skill-rebalance",date:"2026-09-23",time:"12:58",title:"ปรับสมดุลสกิล และกรองอุปกรณ์ตามสเตตัส",lines:["Thief: Toxin Knife เปลี่ยนเป็น Toxin Blink พุ่งเข้าหาเป้าหมายในระยะ 220 · 5%→50% ATK · SP 1→10 · คูลดาวน์ 7 วิ · 57% ติดพิษ 5 วิ (HP −4%/วิ) · ติดคริตามค่าคริตัวละคร","Thief: Fleet Foot เปลี่ยนเป็น FLEE +2% และ Perfect Dodge +1 ต่อระดับ (สูงสุด FLEE +20% / Perfect Dodge +10)","Merchant: Cart Strike 65%→650% ATK · ระยะ 100 · คูลดาวน์ 5.5 วิ · 75% กระเด็น 3 ช่องแล้วสตัน 2.5 วิ · อ่อนแรง 5 วิ (ดาเมจศัตรู −20% · รับดาเมจ +20%)","Archer: Arrow Rain SP 4→40 · คูลดาวน์ 7 วิ · Twin Shot 33%→330% × 2 ฮิต · SP 2→20 · โอกาส 33% ยิงเป็น 4 ฮิต","Cleric: Radiant Light SP 4→40 · คูลดาวน์ 1.5 วิ · Holy Guard ป้องกันทั้งตัวเองและปาร์ตี้ในระยะ 170 · 4%→40% · SP 3→30","Swordsman: Challenging ทำดาเมจ 0.15%→1.5% ของ MaxHP ศัตรู (บอสโลกโดน 1/10)","Mage: Frost Area รับดาเมจเวท +55% · Stormbreak 115% MATK ระยะ 120 · Ember Bolt เผาไหม้ HP −5%/วิ · Tierra ร่าย 0.5 วิ SP 4→40 · 7% อ่อนแรง (−25%)",'กระเป๋าและตลาดกลางมีตัวเลือก "สเตตัส" กรองอุปกรณ์ตาม STR AGI VIT INT DEX LUK เรียงสูง→ต่ำ หรือต่ำ→สูง'],en:{title:"Skill rebalance, and filter gear by stat",lines:["Thief: Toxin Knife becomes Toxin Blink, dashing to a target within range 220 · 5%→50% ATK · SP 1→10 · 7-second cooldown · 57% chance to poison for 5 seconds (HP −4%/sec) · crits at your character's crit rate.","Thief: Fleet Foot becomes FLEE +2% and Perfect Dodge +1 per level (max FLEE +20% / Perfect Dodge +10).","Merchant: Cart Strike 65%→650% ATK · range 100 · 5.5-second cooldown · 75% chance to knock back 3 tiles then stun for 2.5 seconds · weakens for 5 seconds (enemy damage −20% · damage taken +20%).","Archer: Arrow Rain SP 4→40 · 7-second cooldown · Twin Shot 33%→330% × 2 hits · SP 2→20 · 33% chance to fire 4 hits.","Cleric: Radiant Light SP 4→40 · 1.5-second cooldown · Holy Guard now shields yourself and your party within range 170 · 4%→40% · SP 3→30.","Swordsman: Challenging now deals 0.15%→1.5% of the enemy's max HP (world bosses take 1/10 of that).","Mage: Frost Area increases magic damage taken +55% · Stormbreak 115% MATK, range 120 · Ember Bolt burns for HP −5%/sec · Tierra now has a 0.5-second cast time, SP 4→40 · 7% chance to weaken (−25%).",'Your bag and the Market now have a "Stats" filter for gear by STR, AGI, VIT, INT, DEX or LUK, sortable high→low or low→high.']}},{id:"2026-09-23-market-sell-instant",date:"2026-09-23",time:"12:36",title:"ตั้งขายในตลาดไม่หน่วงแล้ว",lines:['กด "ตั้งขาย" แล้วอุปกรณ์หายจากช่องกระเป๋าทันที ขึ้นว่ากำลังส่งรายการ และกดซ้ำไม่ได้ ตั้งขายชิ้นถัดไปต่อได้เลย','อุปกรณ์ที่ตั้งขายขึ้นกระดานและ "รายการของฉัน" ทันทีที่ตลาดรับ ไม่ต้องรอรอบอัปเดตถัดไป',"แก้ให้ผู้เล่นที่เข้าแมพไม่ทำให้หน้าต่างตลาดของคนอื่นต้องโหลดข้อมูลซ้ำ"],en:{title:"Listing an item on the Market is no longer delayed",lines:[`Pressing "List" now removes the item from your bag immediately, shows the listing as being sent, and can't be pressed twice — you can move straight on to listing the next item.`,'A listed item appears on the board and in "My Listings" the instant the Market accepts it, without waiting for the next update cycle.',"Fixed players entering a map no longer forcing other players' Market windows to reload their data."]}},{id:"2026-09-23-market-take-back-instant",date:"2026-09-23",time:"12:21",title:"เก็บของคืนจากตลาดไม่หน่วงแล้ว",lines:['กด "เก็บคืน" หรือ "ยกเลิก" แล้วรายการหายจากหน้าต่างทันที ไม่ต้องรอตลาดตอบก่อน และกดซ้ำไม่ได้แล้ว',"หลังเก็บคืน ซื้อ หรือตั้งขาย กระดานในตลาดอัปเดตทันที ไม่มีรายการเก่าเด้งกลับมาให้เห็นอีก","ตลาดกลางบันทึกข้อมูลเฉพาะรายการที่เปลี่ยน แทนการเขียนข้อมูลทั้งตลาดใหม่ทุกครั้ง จึงตอบเร็วขึ้นเมื่อคนเล่นเยอะ"],en:{title:"Retrieving items from the Market is no longer delayed",lines:[`Pressing "Retrieve" or "Cancel" now removes the listing from the window immediately, without waiting for the Market's reply, and can no longer be pressed twice.`,"After retrieving, buying or listing, the Market board updates instantly, so an old listing never pops back into view.","The Market now saves only the listings that changed instead of rewriting the whole market each time, so it responds faster when many people are playing."]}},{id:"2026-09-23-market-buy-lag",date:"2026-09-23",time:"11:57",title:"แก้ตลาดกลางกดซื้อไม่ได้",lines:['ตลาดกลางตอบช้าจนกดซื้อ/ตั้งขายแล้วค้าง หรือขึ้นว่า "ตลาดกลางตอบช้า" ตอนนี้แก้แล้ว',"หน้าต่างตลาดที่เปิดค้างไว้ส่งข้อมูลน้อยลงมาก คำสั่งซื้อขายจึงไม่ต้องรอคิวนานอีก","ใครที่กดซื้อไปตอนตลาดช้า รายการที่ค้างอยู่จะยืนยันและเข้ากระเป๋าให้อัตโนมัติ"],en:{title:"Fixed being unable to buy on the Market",lines:['The Market was slow enough that buying or listing could hang, or show "The Market is slow to respond." This is now fixed.',"A Market window left open now sends far less data, so buy and sell orders no longer wait long in a queue.","If you bought something while the Market was slow, any pending order will now confirm and land in your bag automatically."]}},{id:"2026-09-23-stuck-warp-and-lost-items",date:"2026-09-23",time:"08:27",title:"แก้บั๊กวาร์ปติดหลุม ของหาย และหน้าต่างค้าง",lines:["Warp Scroll จะไม่พาไปตกในช่องที่ล้อมด้วยต้นไม้แล้ว ใครที่ติดอยู่ในหลุมเดิม เข้าเกมใหม่จะถูกย้ายออกมาที่พื้นที่เดินได้ใกล้ที่สุด","กดรับของจากจดหมายตอนเน็ตหลุด ของจะไม่หายแล้ว ระบบจะส่งเข้ากระเป๋าให้เองเมื่อเชื่อมต่อได้","แก้บั๊กอุปกรณ์ที่ตั้งขายถูกลงกระดานซ้ำ และคำสั่งตลาดที่ค้างถูกทำซ้ำ","ช่องแชทไม่แสดงข้อความซ้ำ และข้อความระบบ/ปาร์ตี้/กระซิบไม่ถูกดันหายเมื่อมีคนพิมพ์","หน้าต่างเทรด ตีบวก และร้านค้าไม่ค้างแล้วเมื่อคำขอถูกปฏิเสธหรือเน็ตหลุดกลางทาง","เกมไม่ค้างทั้งจออีกเมื่อมีสถานะใหม่หลังอัปเดต โดยที่ยังไม่ได้รีโหลด"],en:{title:"Fixed warping into pits, lost items, and stuck windows",lines:["Warp Scroll no longer drops you into a tile surrounded by trees. If you're already stuck in one, logging back in will move you to the nearest walkable spot.","Claiming mail during a disconnect no longer loses the item — it's now delivered to your bag automatically once you reconnect.","Fixed a bug where a listed item could appear on the board twice, and pending market orders could be duplicated.","The chat box no longer shows duplicate messages, and system/party/whisper messages no longer get pushed out when someone else is typing.","The trade, refine and shop windows no longer freeze when a request is rejected or the connection drops midway.","The game no longer freezes entirely when a new status appears after an update, even before you reload."]}},{id:"2026-09-23-bot-defaults-ready-to-run",date:"2026-09-23",time:"07:10",title:"เปิดบอทแล้วใช้ได้เลย ไม่ต้องตั้งค่าก่อน",lines:["ตัวละครใหม่กดเปิด Auto Play ได้ทันที ค่าเริ่มต้นคือเก็บไอเท็มทั้งหมด (ของใช้ ของทั่วไป การ์ด อุปกรณ์)","ค่าเริ่มต้นจะโจมตีมอนสเตอร์ธรรมดาทุกตัวในแมพที่ยืนอยู่ ไม่ต้องไปติ๊กชื่อมอนทีละตัวก่อน · บอสประจำแมพยังต้องติ๊กเอง",'ตีธรรมดาอย่างเดียว ไม่มีสกิลติ๊กไว้ให้ และปิด "ขอบเขตบอท" ไว้แล้ว บอทจึงหาของทั้งแมพโดยไม่ต้องตั้งรัศมี',"ใครที่เคยตั้งค่าบอทไว้แล้ว ค่าเดิมของตัวเองยังอยู่เหมือนเดิม"],en:{title:"Auto Play now works right away, no setup needed",lines:["New characters can turn on Auto Play right away — the default is to loot everything (consumables, general items, cards, gear).","By default it attacks every regular monster on the map you're standing in, with no need to tick each monster's name first · map bosses still need to be ticked manually.",'It uses basic attacks only, with no skills ticked, and "Bot range" is turned off by default, so it hunts across the whole map without needing a radius set.',"If you'd already configured your bot, your own settings stay exactly as you left them."]}},{id:"2026-09-23-short-login-announcement",date:"2026-09-23",time:"07:05",title:"ประกาศตอนเข้าเกมสั้นลง",lines:["เมื่อก่อนพอเข้าเกมจะมีประกาศเก่ายาวเป็นสิบบรรทัดไหลในช่องแชทจนหาข้อความคนอื่นไม่เจอ ตอนนี้เหลือเฉพาะเท่าที่ควรมี","ช่องแชทจะบอกแค่หัวข้ออัปเดตล่าสุดที่ยังไม่ได้อ่าน (ไม่เกิน 3 รายการ) แล้วชี้ไปที่หน้า /changelog/ ซึ่งอ่านย้อนหลังได้ทั้งหมด","ประกาศช่วงโบนัส EXP และคำเตือน Test Server ยังแสดงเหมือนเดิม"],en:{title:"The login announcement is now shorter",lines:["Logging in used to flood chat with dozens of lines of old announcements, burying everyone else's messages. Now it shows only what's actually needed.","Chat now shows only the latest unread update titles (up to 3), then points you to the /changelog/ page, where you can read the full history.","EXP bonus announcements and the Test Server warning still show as before."]}},{id:"2026-09-23-refine-armor-clarity",date:"2026-09-23",time:"06:06",title:"บอกให้ชัดว่าตีบวกเกราะแล้วได้อะไร",lines:["หลายคนถามว่าตีบวกหมวก ผ้าคลุม เกราะ รองเท้า โล่ แล้วทำไมเลขบนไอเทมไม่ขึ้น — ระบบตั้งใจให้เป็นแบบนั้นมาตั้งแต่แรก: ตีบวกชุดเกราะไม่ได้เพิ่ม DEF เป็นตัวเลขบนไอเทม แต่ลดดาเมจที่ได้รับ 1% ต่อ 1 ระดับ นับรวมทุกชิ้นที่สวมอยู่ สูงสุด 60%",'ตอนนี้การ์ดไอเทมเขียนบรรทัดนี้ให้เห็นแล้ว เช่น "ตีบวก +7 ลดดาเมจที่ได้รับ 7%" พร้อมบอกว่ายอดรวมไปดูได้ที่ +% ท้ายค่า DEF ในหน้าสถานะ',"หน้าต่างช่างตีบวกเพิ่มคำอธิบายว่า อาวุธตีบวกแล้วได้ ATK เพิ่มบนไอเทม ส่วนเกราะ หมวก ผ้าคลุม รองเท้า โล่ ได้เป็นเปอร์เซ็นต์ลดดาเมจแทน","เป็นการแก้คำอธิบายอย่างเดียว ตัวเลขและสูตรไม่เปลี่ยน ของที่ตีบวกไว้แล้วยังได้ผลเท่าเดิมทุกชิ้น"],en:{title:"Made it clear what refining armor actually gives you",lines:["Many players asked why refining a helmet, garment, armor, shoes or shield doesn't raise the number on the item — this has been intentional from the start: refining armor doesn't add DEF as a number on the item, it reduces damage taken by 1% per refine level, totaled across every piece you're wearing, up to 60%.",'The item card now spells this out, e.g. "Refine +7 — reduces damage taken by 7%", and notes that the total is shown as the +% after your DEF value on the status page.',"The refine window now explains that refining a weapon adds ATK directly on the item, while armor, helmets, garments, shoes and shields instead give a percentage of damage reduction.","This is a wording fix only — the numbers and formulas are unchanged, and every piece you've already refined still gives the same effect."]}},{id:"2026-09-23-market-server-gate",date:"2026-09-23",time:"05:59",title:"ปิดช่องอ่านกระดานตลาดจากนอกเมือง",lines:["การซื้อ ขาย ตั้งราคา ยกเลิก และซื้อขาย Gold ถูกตรวจที่เซิร์ฟเวอร์อยู่แล้วเสมอ ไม่ว่าจะแก้หน้าเว็บอย่างไรก็ทำไม่ได้ถ้าไม่มี Premium และไม่ได้ยืนอยู่หน้านายหน้า","รอบนี้ปิดเพิ่มอีกจุด: การขอข้อมูลกระดานราคาก็ต้องอยู่หน้านายหน้าหรือมี Premium เช่นกัน จากเดิมที่ส่งคำขอดูราคาจากที่ไหนก็ได้"],en:{title:"Closed off reading the Market board from outside town",lines:["Buying, selling, listing, cancelling, and trading Gold have always been checked server-side — no amount of tampering with the web page lets you do any of it without Premium and standing in front of the Market Broker.","This update closes off one more gap: requesting the price board's data now also requires standing at the Market Broker or having Premium, whereas before that request could be sent from anywhere."]}},{id:"2026-09-23-linked-guest-payment-fix",date:"2026-09-23",time:"05:54",title:"แก้บั๊กใหญ่: คนที่ผูก Google ทีหลัง เติมเงินแล้วไม่ได้ Gold",lines:["ใครที่เริ่มเล่นเป็น Guest แล้วมาผูกบัญชี Google ทีหลัง บัญชีจะยังใช้รหัสเดิมของ Guest อยู่ ทำให้หน้าร้านยอมให้จ่ายเงินได้ แต่ระบบส่งของกลับปฏิเสธเพราะดูแค่รูปแบบรหัส ผลคือเงินถูกตัดจริงแต่ไม่มี Gold และไม่มีบันทึกรายการเลย",'ตอนนี้ระบบดูที่ "บัญชีนี้ผูก Google ไว้หรือไม่" แทนการดูรูปแบบรหัส คนที่ผูกทีหลังจึงเติมเงินและได้ Gold ปกติแล้ว รวมถึงสิทธิ์รับ Gold คืนอีกครั้งในวันเปิดเซิร์ฟเวอร์จริงด้วย',"ใครที่เคยจ่ายเงินแล้วไม่ได้ Gold จากสาเหตุนี้ ทีมงานตามส่งให้ครบทุกคน ทักแอดมินในดิสคอร์ดพร้อมเวลาที่จ่ายได้เลย","เพิ่มการบันทึกทุกครั้งที่มีการเปิดหน้าชำระเงิน ถ้าเงินถูกตัดแต่ของไม่ถึงมือ ทีมงานจะเห็นและตามคืนได้เองโดยไม่ต้องรอผู้เล่นแจ้ง"],en:{title:"Fixed a major bug: linking Google later meant top-ups gave no Gold",lines:["If you started as a Guest and linked a Google account later, your account still kept its original Guest ID. The shop page allowed payment, but item delivery rejected it because it only checked the ID's format. The result: real money was charged, but no Gold arrived and no record was ever logged.",`The system now checks "is this account linked to Google" instead of the ID's format, so anyone who linked later now tops up and receives Gold normally, including the right to have Gold returned again on real launch day.`,"If you paid before and never got Gold because of this, the team has been sending it to everyone affected — message an admin on Discord with your payment time.","Every time the payment page opens, it's now logged, so if money is charged but the item never arrives, the team can spot it and follow up without waiting for a player report."]}},{id:"2026-09-23-google-sans-everywhere",date:"2026-09-23",time:"05:48",title:"ทั้งเกมใช้ฟอนต์ Google Sans แล้ว ยกเว้นตัวเลขดาเมจ",lines:["รอบก่อนเปลี่ยนเฉพาะเมนูบนกับกล่องแชท รอบนี้ยกไปทั้งเกม: หน้าล็อกอิน หน้าต่างทุกบาน ตลาดกลาง กระเป๋า ตีบวก ตั้งค่า ปาร์ตี้ เพื่อน จดหมาย บอท ป้ายชื่อ NPC และชื่อสกิลที่ลอยขึ้นกลางจอ","หน้าเว็บนอกเกมก็เปลี่ยนตาม ทั้ง Wiki ข้อตกลงการใช้บริการ และหน้าประวัติการอัปเดต","ตัวเลขดาเมจยังเป็นฟอนต์พิกเซลเหมือนเดิม และยังสลับแบบได้ในตั้งค่าเหมือนเดิม","ฟอนต์ที่โหลดน้อยลงจากเดิม 4 ชุดเหลือ 2 ชุด เปิดเกมครั้งแรกจึงเบาลงนิดหน่อย"],en:{title:"The whole game now uses Google Sans, except damage numbers",lines:["The last update only changed the top menu and the chat box. This one covers the whole game: the login screen, every window, the Market, bag, refining, settings, party, friends, mail, bot, NPC name tags, and the skill names that float up on screen.","Pages outside the game changed too — the Wiki, the Terms of Service, and the patch notes page.","Damage numbers still use the pixel font as before, and can still be switched in Settings.","Fewer fonts are loaded now, down from 4 sets to 2, so the first load is a little lighter."]}},{id:"2026-09-23-topup-closed",date:"2026-09-23",time:"05:51",title:"ปิดการเติมเงินซื้อ Gold ชั่วคราว",lines:['ตอนนี้ปุ่มราคาบาทในร้านค้าจะขึ้นว่า "เร็ว ๆ นี้" และยังเปิดชำระเงินไม่ได้ ระบบเติมเงินจริงถูกปิดไว้ก่อน',"ส่วนอื่นยังใช้ได้ตามปกติ: ซื้อ Premium ด้วย Gold ในเกม และซื้อขาย Gold กับ Silver ที่กระดานแลกเปลี่ยน","Gold ที่เติมไว้ก่อนหน้านี้ยังอยู่ครบ จดหมาย Gold ที่ยังไม่ได้กดรับก็ไม่หายไปไหน"],en:{title:"Gold top-ups temporarily closed",lines:[`The Baht-priced buttons in the shop now show "Soon" and can't open payment yet — real-money top-ups have been closed for now.`,"Everything else still works as usual: buying Premium with in-game Gold, and trading Gold for Silver on the exchange board.","Gold topped up earlier is still fully intact, and any unclaimed Gold mail hasn't gone anywhere."]}},{id:"2026-09-23-revenue-names",date:"2026-09-23",time:"05:50",title:"หลังบ้าน: หน้าสถิติการเติมเงินโชว์ชื่อผู้เล่นแล้ว",lines:["หน้าสถิติการเติมเงินของทีมงานเคยแสดงเป็นรหัสบัญชียาว ๆ ตอนนี้แสดงชื่อตัวละครและเลเวลของผู้เติมเงินแทน (รหัสบัญชียังอยู่ตัวเล็ก ๆ ไว้ให้ทีมงานตรวจสอบเวลามีเรื่องคืนเงิน)","เป็นการแก้เฉพาะหน้าจอของทีมงาน ไม่มีผลกับตัวเกม"],en:{title:"Backend: the top-up dashboard now shows player names",lines:["The team's top-up dashboard used to show only long account IDs. It now shows the character name and level of whoever topped up instead (the account ID is still shown, in small text, for the team to check when handling refunds).","This only changes the team's own screen and has no effect on the game itself."]}},{id:"2026-09-23-block-browser-translate",date:"2026-09-23",time:"05:26",title:"ปิดการแปลหน้าเว็บอัตโนมัติของเบราว์เซอร์",lines:["เกมมีระบบแปลภาษาของตัวเองอยู่แล้ว (เลือกภาษาได้ในหน้าตั้งค่า) แต่ถ้าเบราว์เซอร์เอา Google แปลภาษามาแปลทับ ข้อความจะถูกแปลซ้ำสองชั้นจนเพี้ยน และบางหน้าต่างจะค้างหรือแสดงผลผิดเพราะตัวแปลไปแก้โครงสร้างข้อความในหน้าเกม","ตอนนี้หน้าเกมบอกเบราว์เซอร์ไม่ให้แปลแล้ว จะไม่มีป๊อปอัพชวนแปลขึ้นมาอีก ถ้าอยากเล่นภาษาอื่นให้เลือกจากเมนูภาษาในหน้าตั้งค่าแทน"],en:{title:"Blocked the browser's automatic page translation",lines:["The game already has its own translation system (pick a language in Settings), but if the browser layered Google Translate on top, text got double-translated into nonsense, and some windows froze or displayed incorrectly because the translator altered the game page's structure.","The game page now tells the browser not to translate it, so the translate prompt will no longer appear. If you want to play in another language, pick it from the language menu in Settings instead."]}},{id:"2026-09-23-tooltip-drift",date:"2026-09-23",time:"05:23",title:"แก้คำอธิบายสกิลที่ไหลไปทางซ้ายเรื่อย ๆ",lines:["ตอนเอาเมาส์ชี้ปุ่มสกิล กล่องคำอธิบายจะค่อย ๆ เลื่อนไปทางซ้ายไม่หยุด เพราะความกว้างของกล่องถูกคำนวณใหม่ทุกเฟรมตามตำแหน่งของตัวมันเอง","ตอนนี้กล่องกว้างคงที่ตามข้อความแล้ว ชี้ค้างไว้นานแค่ไหนก็อยู่กับที่"],en:{title:"Fixed skill tooltips drifting left",lines:["Hovering a skill button used to make its tooltip slowly drift left without stopping, because the box's width was recalculated every frame based on its own position.","The box now has a fixed width based on its text, so it stays put no matter how long you hover."]}},{id:"2026-09-23-gold-delivery-repair",date:"2026-09-23",time:"05:14",title:"อุดรอยรั่ว: จ่ายเงินแล้วต้องได้จดหมาย Gold ทุกครั้ง",lines:["พบว่าช่วงชั่วโมงแรกที่ร้านเปิด มีการเติมเงินที่บันทึกยอดไว้แล้วแต่จดหมาย Gold ไม่ถูกเขียนลงกล่องจดหมาย เพราะการบันทึกยอดกับการเขียนจดหมายเป็นสองจังหวะแยกกัน ถ้าเซิร์ฟเวอร์รีสตาร์ทคาบเกี่ยวตรงกลาง จดหมายจะหายไปและระบบจะเข้าใจว่าจ่ายของไปแล้ว","ตอนนี้บันทึกยอดกับเขียนจดหมายอยู่ในจังหวะเดียวกันแล้ว แยกกันไม่ได้อีก และถ้าเจอยอดที่ยังไม่เคยส่งของ ระบบจะเขียนจดหมายที่ค้างให้เอง — ยังกันจ่ายซ้ำเหมือนเดิม ใบที่กดรับไปแล้วจะไม่ถูกส่งใหม่","ใครที่เติมเงินในช่วงนั้นแล้วยังไม่ได้ Gold ทีมงานตามส่งให้ครบแล้ว ถ้ายังไม่ได้ทักแอดมินในดิสคอร์ดได้เลย มีบันทึกยอดทุกรายการไว้อยู่"],en:{title:"Closed a gap: every payment must now produce Gold mail",lines:["We found that during the shop's first hour, some top-ups had their amount recorded but never got a Gold mail written, because recording the amount and writing the mail were two separate steps. If a server restart landed in between, the mail was lost and the system assumed it had already been delivered.","Recording the amount and writing the mail now happen in the same step and can no longer be split apart. If the system finds an amount that was never delivered, it writes the missing mail itself — duplicate payments are still prevented as before, and mail already claimed will never be resent.","If you topped up during that window and never got Gold, the team has already sent it to everyone affected. If you still haven't received it, message an admin on Discord — every top-up amount is on record."]}},{id:"2026-09-23-market-tile-premium-only",date:"2026-09-23",time:"05:17",title:"แก้ปุ่มตลาดกลางในเมนูที่โผล่ให้คนไม่มี Premium",lines:["ปุ่ม Market ในเมนูควรขึ้นเฉพาะผู้ที่มี Premium แต่รอบก่อนมันโผล่ให้ทุกคนและกดเปิดกระดานจากนอกเมืองได้ (ซื้อขายจริงยังถูกปฏิเสธอยู่แล้ว) ตอนนี้ซ่อนถูกต้องแล้ว","ถ้าเปิดหน้าตลาดค้างไว้นอกระยะนายหน้าโดยไม่มี Premium หน้าต่างจะปิดให้เอง"],en:{title:"Fixed the Market button in the menu showing for non-Premium players",lines:["The Market button in the menu is meant to show only for Premium players, but the last update showed it to everyone and let them open the board from outside town (actual trades were still rejected). It's now hidden correctly.","If the Market window is left open outside the Broker's range without Premium, it will now close itself."]}},{id:"2026-09-23-premium-buff-chip",date:"2026-09-23",time:"04:59",title:"Premium ขึ้นเป็นบัฟบนหน้าจอแล้ว",lines:["ระหว่างที่ Premium ยังไม่หมดอายุ จะมีไอคอนบัฟ Premium อยู่ในแถบสถานะข้างการ์ดตัวละคร พร้อมเวลาที่เหลือ","ชี้หรือกดที่ไอคอนเพื่อดูสิ่งที่ได้รับทั้งหมด: Base/Job EXP +50% · น้ำหนักบรรทุก +50% · ภาษีขายในตลาด -50% · เปิดตลาดจากเมนูได้ทุกที่","นาฬิกาบนไอคอนบัฟนับเป็นวันได้แล้ว บัฟยาว ๆ จะไม่ขึ้นเป็นชั่วโมงหลักร้อยอีกต่อไป"],en:{title:"Premium now shows as an on-screen buff",lines:["While Premium is active, a Premium buff icon sits in the status bar next to your character card, showing the time left.","Hover or tap the icon to see everything it grants: Base/Job EXP +50% · carry weight +50% · market sales tax -50% · open the Market from the menu anywhere.","The clock on the buff icon now counts in days, so a long buff no longer shows as hundreds of hours."]}},{id:"2026-09-23-gold-letter-instant",date:"2026-09-23",time:"05:02",title:"เติม Gold แล้วจดหมายเด้งทันที ไม่ต้องรอ",lines:["เมื่อก่อนจ่ายเงินเสร็จแล้วจดหมาย Gold อาจใช้เวลาถึงครึ่งนาทีกว่าป้ายจดหมายจะขึ้น ทำให้บางคนเปิดกล่องจดหมายทันทีแล้วเห็นว่าว่าง คิดว่าเงินหาย ตอนนี้จดหมายจะแจ้งเตือนทันทีที่ชำระเงินสำเร็จ","ย้ำอีกครั้ง: Gold ที่เติมมาจะไม่เข้าตัวละครเอง ต้องเปิดกล่องจดหมายแล้วกดรับก่อน จดหมายที่ยังไม่กดรับจะไม่หายไปไหน ไม่มีวันหมดอายุตราบใดที่ยังมีของอยู่ในซอง"],en:{title:"Top up Gold and the letter pops up instantly, no more waiting",lines:["After paying, the Gold letter used to take up to half a minute to show its notification, so some players opened the mailbox right away, saw it empty, and thought their money was gone. The letter now notifies you the instant payment succeeds.","Reminder: purchased Gold does not go to your character automatically — you still have to open the mailbox and claim it. An unclaimed letter never disappears; it never expires as long as it still holds something."]}},{id:"2026-09-23-premium-market-menu",date:"2026-09-23",time:"04:52",title:"Premium เปิดตลาดกลางจากเมนูได้ทุกที่",lines:["ผู้เล่นที่มี Premium จะเห็นปุ่ม Market เพิ่มขึ้นมาในเมนู (อยู่ในปุ่ม ☰ เมนูเพิ่มเติม) กดเปิดตลาดกลางได้จากทุกแผนที่ ซื้อ ขาย ตั้งราคา และเก็บของคืน ได้เหมือนยืนอยู่หน้านายหน้า","ตลาดแลกเปลี่ยน Gold ก็ใช้ได้จากทุกที่เช่นกันเมื่อมี Premium","ปุ่มจะหายไปเองเมื่อ Premium หมดอายุ และผู้เล่นทั่วไปยังต้องเดินไปหานายหน้าตลาดที่ Aurelia Forum เหมือนเดิม","ระหว่างเปิดหน้าตลาดตัวละครจะยืนอยู่กับที่เหมือนตอนคุยกับ NPC กด Esc เพื่อปิดแล้วเดินต่อได้ทันที"],en:{title:"Premium opens the Market from the menu, anywhere",lines:["Players with Premium now see a Market button in the menu (inside the ☰ More menu). Press it to open the central Market from any map — buy, sell, set prices and withdraw listings, just like standing in front of the broker.","The Gold exchange also works from anywhere while Premium is active.","The button disappears on its own once Premium expires, and regular players still need to walk to the market broker at Aurelia Forum as before.","While the Market window is open your character stands still, just like talking to an NPC. Press Esc to close it and move again right away."]}},{id:"2026-09-23-shop-opens",date:"2026-09-23",time:"04:11",title:"ร้านค้าเปิดขายจริงแล้ว เติม Gold ด้วยเงินบาทผ่านบัตรได้",lines:['ปุ่มราคาบาทในหน้าร้านที่เคยขึ้นว่า "เร็ว ๆ นี้" กดได้จริงแล้ว ชำระผ่าน Stripe ด้วยบัตรเครดิต/เดบิต ราคาทุกแพ็กคิดเป็นเงินบาทและคำนวณจากฝั่งเซิร์ฟเวอร์เสมอ',"ก่อนจ่ายต้องติ๊กยอมรับข้อกำหนดและนโยบายคืนเงินก่อน กดอ่านได้จากในหน้าร้านเลย","จ่ายเสร็จแล้ว Gold จะส่งมาทางจดหมายในกล่องจดหมาย เปิดรับได้จากทุกแผนที่ ถ้าจ่ายแล้วของยังไม่มาภายในไม่กี่นาที ทักแอดมินในดิสคอร์ดได้เลย","Gold ใช้แลก Premium หรือเอาไปขายแลก Silver ที่กระดานแลกเปลี่ยนก็ได้เหมือนเดิม และยังเล่นได้ครบทุกอย่างโดยไม่ต้องจ่ายเงินสักบาท"],en:{title:"The shop is now live — top up Gold in Baht by card",lines:[`The Baht-price buttons in the shop that used to say "coming soon" now actually work. Pay through Stripe with a credit/debit card; every pack's price is in Baht and always calculated server-side.`,"Before paying you must tick that you accept the Terms and the Refund Policy, both readable right from the shop page.","After payment, Gold is sent by mail to your mailbox, which you can open and claim from any map. If it hasn't arrived within a few minutes of paying, message an admin on Discord.","Gold can still be spent on Premium or sold for Silver on the exchange board as before, and you can still play the whole game without spending a single Baht."]}},{id:"2026-09-23-google-sans-ui-font",date:"2026-09-23",time:"04:06",title:"เปลี่ยนฟอนต์ในเกมเป็น Google Sans",lines:["เมนูด้านบน กล่องแชท หน้าสกิล หน้าอันดับ และปุ่มบนจอมือถือ เปลี่ยนจากฟอนต์มะลิมาเป็น Google Sans อ่านง่ายขึ้นทั้งไทยและอังกฤษ","ถ้าฟอนต์โหลดไม่ทัน เกมจะใช้ฟอนต์เดิมของเครื่องแทนเหมือนเดิม"],en:{title:"Switched the in-game font to Google Sans",lines:["The top menu, chat box, skill window, ranking page and mobile on-screen buttons switched from the Mali font to Google Sans, easier to read in both Thai and English.","If the font doesn't load in time, the game still falls back to your device's own font as before."]}},{id:"2026-09-23-launch-wipe",date:"2026-09-23",time:"03:33",title:"ระบบล้างข้อมูลวันเปิดจริงพร้อมแล้ว (ยังไม่สั่งล้าง)",lines:["วางระบบสำหรับวันเปิดเซิร์ฟเวอร์จริงไว้ล่วงหน้า วันนั้นจะล้าง: ตัวละครทุกตัวพร้อมกระเป๋า คลัง Silver Gold และ Premium · ชื่อตัวละคร (ทุกคนตั้งใหม่ ชื่อที่เคยจองจะว่างหมด) · กล่องจดหมาย · ตลาดกลางทั้งกระดาน · อันดับ · รายชื่อเพื่อน","สิ่งที่ไม่ถูกล้าง: บัญชีและการผูก Google ของคุณ และประวัติการเติมเงิน","Gold ที่เติมด้วยเงินจริงก่อนวันเปิด จะถูกส่งกลับมาให้ใหม่เต็มจำนวนในกล่องจดหมาย ตอนล็อกอินครั้งแรกหลังเปิดจริง — นับจากเวลาที่ล้างข้อมูลจริง ๆ ไม่ใช่วันที่ตั้งไว้ในโค้ด","ตัวละครทุกตัวพกเลขรุ่นของโลกติดตัวไว้แล้ว ตัวที่มาจากโลกเก่าจะถูกทิ้งทันทีที่โหลด ต่อให้ย้อนกลับมาจากแบ็กอัปหรือจากแมพที่หลับอยู่","รอบนี้ยังไม่ล้างอะไรทั้งสิ้น — ระบบถูกปิดไว้ (WORLD_WIPE = 0) จนกว่าจะประกาศวันเปิดจริง"],en:{title:"The launch-day wipe system is ready (not triggered yet)",lines:["The system for the real server-launch day is built and staged in advance. On that day it will wipe: every character along with their inventory, storage, Silver, Gold and Premium · character names (everyone picks a new one; all reserved names become free again) · mailboxes · the entire Market board · rankings · friend lists","What is not wiped: your account and Google link, and your payment history.","Gold bought with real money before launch will be sent back to you in full, by mail, the first time you log in after launch — counted from the moment the wipe actually runs, not the date set in the code.","Every character now carries the world's generation number. Any character from the old world is discarded the moment it loads, even if it resurfaces from a backup or a dormant map.","Nothing is being wiped this time — the system is switched off (WORLD_WIPE = 0) until the real launch date is announced."]}},{id:"2026-09-23-early-access-gold-is-kept",date:"2026-09-23",time:"03:04",title:"Gold ที่เติมช่วงทดสอบ จะได้รับอีกครั้งเต็มจำนวนในวันเปิดจริง",lines:["วันเปิดเซิร์ฟเวอร์จริง ข้อมูลตัวละคร ไอเทม Silver และ Gold จะถูกล้างทั้งหมด เพื่อให้ทุกคนเริ่มพร้อมกัน","แต่ทุกบาทที่เติมช่วงทดสอบจะถูกบันทึกไว้กับบัญชี Google ที่ใช้ซื้อ และระบบจะส่ง Gold จำนวนเท่าเดิมเข้ากล่องจดหมายให้ใหม่ทันทีที่ล็อกอินครั้งแรกหลังเปิดจริง","ด้วยเหตุนี้ การเติมเงินจึงทำได้เฉพาะบัญชี Google เท่านั้น บัญชี Guest เติมไม่ได้ เพราะเป็นบัญชีชั่วคราวที่อาจหายไปจนไม่มีตัวตนให้คืนของ","ร้านค้าปรับใหม่: เงินจริงใช้ซื้อได้เฉพาะ Gold ส่วน Premium แลกด้วย Gold ในเกมอย่างเดียว (เดิมมีปุ่มจ่ายบาทค้างอยู่ในแท็บ Premium)","เขียนเงื่อนไขทั้งหมดนี้ลงในข้อตกลงการใช้บริการและนโยบายคืนเงินแล้ว · ยังไม่เปิดรับชำระเงินจริงในรอบนี้"],en:{title:"Gold bought during testing will be returned in full on launch day",lines:["On the real launch day, character data, items, Silver and Gold will all be wiped, so everyone starts together.","But every Baht spent during testing is recorded against the Google account that bought it, and the system will send the same amount of Gold to your mailbox the first time you log in after launch.","Because of this, top-ups only work on Google accounts. Guest accounts cannot top up, since they're temporary and could vanish, leaving nobody to return the Gold to.","The shop has been adjusted: real money can only buy Gold, and Premium is only bought with in-game Gold (there used to be a leftover Baht-payment button on the Premium tab).","All of this is now written into the Terms of Service and the Refund Policy · real payments are still not open this round."]}},{id:"2026-09-23-rollback-cannot-hide-itself",date:"2026-09-23",time:"02:46",title:"อุดรูที่ทำให้ตัวละครซึ่งเคยย้อนเลเวล ถูกย้อนซ้ำได้เรื่อย ๆ",lines:['วันนี้เราเพิ่งปิดช่องที่ทำให้ตัวละครแตกเป็นสองชุด และเพิ่มด่านกันไว้ตอนล็อกอิน คือถ้าข้อมูลในแมพที่กำลังจะวางคุณลง ตามหลังเลเวลล่าสุดที่ระบบจำได้ จะไล่หาตัวจริงให้ก่อน แต่ "เลเวลล่าสุดที่ระบบจำได้" นั้นถูกเขียนทับด้วยรายงานจากแมพที่คุณยืนอยู่ล่าสุด',"แปลว่าถ้าโดนวางลงบนชุดเก่าแล้วเล่นต่อสักห้านาที ตัวเลขนั้นจะร่วงลงมาเท่าชุดเก่าทันที ด่านกันก็หมดความหมาย และการล็อกอินครั้งต่อ ๆ ไปจะพาคุณกลับไปที่ชุดเก่านั้นเงียบ ๆ การย้อนครั้งแรกจึงลบหลักฐานที่จะใช้กันครั้งถัดไปไปด้วย",'ตอนนี้ระบบเก็บ "เลเวลสูงสุดที่บัญชีนี้เคยไปถึง" แยกไว้อีกที่หนึ่ง ตัวเลขนี้ขึ้นได้อย่างเดียว ไม่ลดตามรายงานของชุดเก่า ด่านกันตอนล็อกอินจึงยังทำงานอยู่เสมอ ถึงเคยโดนย้อนไปแล้วก็ตาม ส่วนอันดับและตารางจัดอันดับยังใช้เลเวลจริงปัจจุบันเหมือนเดิม',"ใครยังรู้สึกว่าตัวละครหายไปบางส่วน ทักทีมงานได้เลย ข้อมูลทุกชุดที่เคยเล่นถึงยังอยู่ในระบบ กู้กลับให้ได้"],en:{title:"Closed the hole that let a rolled-back character keep getting rolled back",lines:['Earlier today we closed the gap that split a character into two copies, and added a login safeguard: if the data on the map about to place you is behind the latest level the system remembers, it now tracks down the real copy first. But "the latest level the system remembers" was itself being overwritten by whatever the map you last stood on reported.',"That meant if you got placed on the old copy and played on for even five minutes, that remembered number dropped straight down to match the old copy — the safeguard became meaningless, and every login after that would quietly send you back to that same old copy. The first rollback was erasing the very evidence the next safeguard needed.",'The system now keeps "the highest level this account has ever reached" in a separate place. That number can only go up — it never drops just because an old copy reports a lower one — so the login safeguard keeps working even after a rollback has already happened once. Rankings and leaderboards still use your actual current level as before.',"If your character still feels like it's missing something, message the team. Every copy you ever played is still in the system, and we can restore it."]}},{id:"2026-09-23-market-no-double-hold",date:"2026-09-23",time:"02:29",title:"แก้ของที่ตั้งขายในตลาดแล้ว แต่ยังอยู่ในกระเป๋า",lines:["มีรายงานว่าตั้งขายของในตลาดกลางสำเร็จ แต่ของชิ้นนั้นยังอยู่ในกระเป๋าเหมือนเดิม สาเหตุคือเซิร์ฟเวอร์แมพจะหักของออกจากกระเป๋าก่อนแล้วค่อยส่งคำสั่งไปตลาดกลาง ถ้าตลาดกลางงานหนักจนไม่ตอบกลับ ฝั่งแมพจะเข้าใจว่าคำสั่งไม่ผ่านแล้วคืนของให้ทันที ทั้งที่ตลาดกลางรับคำสั่งไปแล้วจริง ๆ ของเลยไปโผล่ทั้งบนกระดานและในกระเป๋า",'ตอนนี้ "ไม่ตอบ" ไม่ได้แปลว่า "ไม่ผ่าน" อีกแล้ว ถ้าตลาดกลางเงียบ ระบบจะพักคำสั่งไว้พร้อมของที่หักไป แล้วส่งถามซ้ำด้วยเลขคำสั่งเดิมทุกวินาทีจนกว่าจะได้คำตอบจริง จากนั้นจึงจ่ายผลหรือคืนของให้ตามคำตอบนั้น ระหว่างรอจะขึ้นข้อความว่า "ตลาดกลางตอบช้า กำลังยืนยันรายการให้" แทนการคืนของมั่ว',"ตลาดกลางเองก็จดคำตอบของทุกคำสั่งลงฐานข้อมูลแล้ว (เดิมจำไว้ในหน่วยความจำ หายเมื่อรีสตาร์ต) การถามซ้ำหลังอัปเดตเซิร์ฟเวอร์จึงได้คำตอบเดิม ไม่ถูกตั้งขายซ้ำเป็นสองรายการ","ครอบคลุมทั้งตั้งขาย ยกเลิกคำสั่ง ตั้งขายอุปกรณ์ เก็บอุปกรณ์คืน ซื้ออุปกรณ์จากกระดาน และคำสั่งซื้อขาย Gold · ใครมีของค้างอยู่ทั้งสองที่ตอนนี้ ทักทีมงานได้เลย"],en:{title:"Fixed items that were listed on the Market but stayed in your inventory too",lines:["There were reports of items listing successfully on the central Market while the item itself stayed in the inventory. The cause: the map server deducted the item from the inventory first, then sent the listing order to the Market. If the Market was too busy to reply, the map assumed the order had failed and returned the item right away — even when the Market had actually accepted it — so the item ended up both on the board and back in the bag.",`"No reply" no longer means "failed". If the Market stays silent, the system now holds the order along with the deducted item and re-asks with the same order number every second until it gets a real answer, then settles or refunds based on that answer. While waiting, you'll see "Market is slow to respond, confirming your order" instead of the item just being returned by guesswork.`,"The Market itself now records the outcome of every order in the database (it used to keep this only in memory, lost on a restart), so a repeated question after a server update gets the same answer instead of creating a duplicate listing.","This covers listing, canceling an order, listing gear, withdrawing gear, buying gear from the board, and Gold buy/sell orders · if you currently have an item stuck in both places, message the team."]}},{id:"2026-09-23-add-friend-from-chat",date:"2026-09-23",time:"02:14",title:"คลิกชื่อในแชทแล้วเพิ่มเพื่อนได้เลย",lines:['เมนูที่เด้งขึ้นตอนคลิกขวา (หรือกดค้างบนมือถือ) ที่ชื่อคนพูดในแชท เพิ่มปุ่ม "เพิ่มเพื่อน" แล้ว จากเดิมที่มีแค่กระซิบ ชวนเข้าปาร์ตี้ และขอเข้าปาร์ตี้',"ส่งคำขอได้แม้อีกฝ่ายอยู่คนละแมพหรือคนละห้อง เพราะระบบตามหาจากชื่อให้ ไม่ต้องเดินไปคลิกขวาที่ตัวเหมือนเมื่อก่อน","ถ้าเป็นเพื่อนกันอยู่แล้ว จะบอกในแชทแทนการส่งคำขอซ้ำ"],en:{title:"Click a name in chat to add them as a friend",lines:[`The menu that pops up when you right-click (or long-press on mobile) a speaker's name in chat now has an "Add Friend" button, alongside the existing Whisper, Invite to Party and Request to Join Party.`,"You can send the request even if they're on a different map or channel, since the system looks them up by name — no need to walk over and right-click their character like before.","If you're already friends, it tells you in chat instead of sending a duplicate request."]}},{id:"2026-09-23-no-rolled-back-characters",date:"2026-09-23",time:"00:49",title:"ปิดช่องที่ทำให้ตัวละครย้อนกลับไปเลเวลเก่า",lines:["มีรายงานว่าตัวละครเล่นอยู่เลเวล 84 แล้วจู่ ๆ ย้อนกลับไปเลเวล 79 พร้อมสกิลพาสซีฟที่เก็บไว้หายไปด้วย สาเหตุคือตอนเดินข้ามแมพ ข้อมูลตัวละครถูกส่งไปเซิร์ฟเวอร์ปลายทางสำเร็จ แต่คำตอบกลับหล่นหาย ฝั่งต้นทางเลยเก็บสำเนาเก่าไว้ต่อ กลายเป็นตัวละครสองชุดที่เดินคนละทาง และการล็อกอินครั้งถัดไปอาจไปโผล่ที่ชุดเก่า","ตอนนี้ถ้าคำตอบหล่นหาย ต้นทางจะถามปลายทางก่อนว่ารับตัวละครไปแล้วหรือยัง จึงไม่เกิดสำเนาซ้ำอีก และตอนล็อกอิน ถ้าข้อมูลในแมพนั้นตามหลังเลเวลล่าสุดที่ระบบจำได้ จะไล่หาตัวจริงให้ก่อนแทนที่จะให้เล่นชุดเก่า","การกู้ข้อมูลอัตโนมัติจากไฟล์สำรองประจำวันก็เข้มขึ้น ถ้าไฟล์สำรองตามหลังเลเวลล่าสุดเกินหนึ่งเลเวล ระบบจะไม่กู้เองแล้ว แต่จะให้ทีมงานตรวจก่อน จะได้ไม่ทับของจริงที่ยังอยู่","ใครเจออาการตัวละครย้อนเลเวลอยู่ตอนนี้ ทักทีมงานได้เลย ข้อมูลชุดที่เล่นไปถึงยังอยู่ในระบบ กู้กลับให้ได้"],en:{title:"Closed the gap that rolled characters back to an old level",lines:["There were reports of a character playing at level 84 who suddenly rolled back to level 79, losing saved passive skill points along with it. The cause: when crossing maps, the character data reached the destination server successfully, but the reply back got lost, so the origin server kept its own old copy running — creating two copies of the character heading in different directions, and the next login could land you on the old one.","Now, if that reply is lost, the origin server checks with the destination first to see if it already received the character, so no duplicate copy forms. And on login, if the data on that map is behind the latest level the system remembers, it now tracks down the real copy first instead of letting you play the old one.","Automatic recovery from the daily backup is also stricter now: if a backup is more than one level behind the latest, the system no longer restores it automatically — the team checks it first, so it doesn't overwrite real, still-existing progress.","If your character is currently rolled back, message the team. The data from where you actually reached is still in the system, and we can restore it."]}},{id:"2026-09-23-operator-details",date:"2026-09-23",time:"00:44",title:"หน้าข้อกำหนดและนโยบายคืนเงิน ขึ้นชื่อผู้ให้บริการจริงแล้ว",lines:["หน้าข้อกำหนด นโยบายคืนเงิน และประกาศความเป็นส่วนตัว (PDPA) แสดงชื่อ ที่อยู่ และอีเมลติดต่อของผู้ให้บริการจริงแล้ว จากเดิมที่ยังเป็นข้อความตัวอย่าง","มีปัญหาเรื่องการคืนเงิน ขอใช้สิทธิ์ตาม PDPA หรือร้องเรียน ส่งเมลมาที่ gamezxz@gmail.com ได้โดยตรง หรือทักในดิสคอร์ดก็ได้เหมือนเดิม","ร้านค้ายังไม่เปิดขาย ปุ่มเติมเงินบาทยังปิดอยู่ตามเดิม ส่วนการแลกทองเป็นพรีเมียมและกระดานแลกเปลี่ยนใช้ได้ปกติ"],en:{title:"Terms and Refund Policy pages now show the real service provider",lines:["The Terms, Refund Policy and Privacy Notice (PDPA) pages now show the real service provider's name, address and contact email, replacing the earlier placeholder text.","For a refund issue, to exercise your PDPA rights, or to file a complaint, email gamezxz@gmail.com directly, or message us on Discord as before.","The shop is still not open for sale — the Baht top-up button remains closed as before — while exchanging Gold for Premium and the exchange board work normally."]}},{id:"2026-09-23-bag-weight-on-hover",date:"2026-09-23",time:"00:21",title:"ชี้ของในกระเป๋าแล้วเห็นน้ำหนักทุกชิ้น ไม่ใช่แค่อุปกรณ์",lines:["เดิมมีแต่อุปกรณ์ที่บอกน้ำหนักตอนเอาเมาส์ชี้ ตอนนี้ยา ม้วนคัมภีร์ วัตถุดิบ และการ์ด บอกน้ำหนักครบทุกชิ้นแล้ว",'ถ้ามีหลายชิ้นจะบอกทั้งน้ำหนักต่อชิ้นและน้ำหนักรวมของกองนั้น เช่น "น้ำหนัก 10 ต่อชิ้น · รวม 230" รู้ทันทีว่าอะไรกินน้ำหนักกระเป๋าไปเท่าไร',"การ์ดรายละเอียดไอเทม (กดที่ของในกระเป๋า) ก็เพิ่มบรรทัดน้ำหนักให้แล้วเหมือนกัน"],en:{title:"Hovering an item now shows weight for every item, not just gear",lines:["Previously only gear showed its weight on hover. Now potions, scrolls, materials and cards all show it too.",`For a stack, it shows both the weight per item and the stack's total, e.g. "Weight 10 each · Total 230", so you can see at a glance what's eating up your carry weight.`,"The item detail card (opened by clicking an item in the inventory) now has a weight line too."]}},{id:"2026-09-22-chat-box-hide",date:"2026-09-22",time:"23:52",title:"พับกล่องแชทเก็บได้ กดปุ่ม ▾ ทีเดียว",lines:["มุมขวาบนของกล่องแชทมีปุ่ม ▾ เพิ่มมา กดแล้วแชททั้งกล่องจะพับเหลือไอคอน 💬 เม็ดเดียว เปิดจอโล่ง ๆ ไว้ตีบอสหรือเก็บเลเวลได้เต็มที่","กดที่ไอคอน 💬 เพื่อกางแชทกลับมา ขนาด ตำแหน่ง และแท็บที่เลือกไว้อยู่ครบเหมือนเดิม","ถ้ามีข้อความเข้ามาตอนที่พับอยู่ ไอคอนจะขึ้นจุดสีเหลืองเรืองแสงเตือนให้ ไม่พลาดคนทักแน่นอน","เกมจำไว้ให้ว่าพับหรือกางอยู่ ออกแล้วเข้าใหม่ก็ยังเป็นแบบที่ตั้งไว้"],en:{title:"Collapse the chat box with a single ▾ button",lines:["The chat box's top-right corner now has a ▾ button. Press it and the whole chat box folds down to a single 💬 icon, freeing up the screen for boss fights or grinding.","Press the 💬 icon to expand it back; its size, position and selected tab are all kept exactly as they were.","If a message comes in while it's collapsed, the icon shows a glowing yellow dot so you never miss someone messaging you.","The game remembers whether it was collapsed or open, so it stays that way even after you log out and back in."]}},{id:"2026-09-22-market-drop-level-filter",date:"2026-09-22",time:"23:25",title:"ตลาด: เอาช่องกรองเลเวลออก",lines:['ช่องเลือก "Lv. ทั้งหมด" ที่แถบค้นหาในตลาดถูกเอาออกแล้ว เพราะซ้ำกับช่องค้นหาและตัวกรองคุณภาพ/อาชีพที่มีอยู่',"ยังดูเลเวลที่ของแต่ละชิ้นต้องใช้ได้จากคอลัมน์ Lv. ในตาราง และเรียงจากเลเวลสูงไปต่ำได้เหมือนเดิม"],en:{title:"Market: removed the level filter",lines:['The "All Lv." dropdown in the Market search bar has been removed, since it duplicated the existing search box and quality/class filters.',"You can still see each item's required level in the Lv. column of the table, and still sort from highest to lowest level as before."]}},{id:"2026-09-22-update-notice-folds-away",date:"2026-09-22",time:"23:14",title:"ป้ายแจ้งอัปเดตเหลือแถบเดียว กดดูรายละเอียดเองได้ ไม่บังจออีกแล้ว",lines:["เดิมป้ายกางรายละเอียดเต็มกลางจอทันทีจนบังเกม ตอนนี้เหลือแถบเดียวบอกแค่หัวข้ออัปเดต","อยากรู้ว่ามีอะไรใหม่ กดที่แถบ รายละเอียดจะเลื่อนลงมาให้อ่าน กดซ้ำเพื่อพับเก็บ",'ยังไม่พร้อมอัปเดตตอนนี้ กด ✕ ปิดป้ายไว้ก่อนได้ แล้วค่อยกดปุ่ม "อัปเดต" ตอนที่สะดวก · มือถือเรียกป้ายกลับมาได้จากปุ่มแจ้งเตือนในเมนู'],en:{title:"The update banner is now one bar you expand yourself, no longer blocking the screen",lines:["The banner used to spread its full details across the middle of the screen right away, blocking the game. Now it's just one bar showing the update's headline.","Want to know what's new? Tap the bar and the details slide down to read; tap again to collapse it.",`Not ready to update right now? Press ✕ to dismiss the banner, then press the "Update" button whenever it's convenient · on mobile, bring the banner back from the notification button in the menu.`]}},{id:"2026-09-22-boost-scrolls-stack",date:"2026-09-22",time:"23:02",title:"ม้วนคัมภีร์: ตายแล้วบัฟไม่หาย และใช้ซ้ำต่อเวลาได้ถึง 5 ชั่วโมง",lines:["บัฟ EXP x2 และ Drop x2 ไม่หายเมื่อหมดสติอีกต่อไป — เวลาที่จ่ายไปแล้วเป็นของคุณ ส่วนสถานะผิดปกติยังหลุดตอนตายเหมือนเดิม","ใช้ม้วนคัมภีร์ซ้ำได้เลย เวลาจะบวกเพิ่มทีละ 1 ชั่วโมง สะสมได้สูงสุด 5 ชั่วโมง","ถ้าเวลาเต็มเพดาน 5 ชั่วโมงแล้ว ระบบจะไม่ให้ใช้ และเก็บม้วนคัมภีร์ไว้ในกระเป๋าให้ ไม่เสียฟรี"],en:{title:"Scrolls: buffs survive death, and stack up to 5 hours",lines:["The EXP x2 and Drop x2 buffs no longer disappear when you're knocked out — the time you've already spent is yours to keep. Status ailments still clear on death as before.","Use another scroll any time; each one adds 1 more hour, stacking up to a maximum of 5 hours.","Once you hit the 5-hour cap, the system won't let you use another one, and keeps the scroll in your inventory — it's never wasted."]}},{id:"2026-09-22-one-machine-three-accounts",date:"2026-09-22",time:"22:45",title:"จำกัด 1 เครื่อง (1 IP) เข้าเกมพร้อมกันได้ไม่เกิน 3 ไอดี",lines:["ตั้งแต่อัปเดตนี้ เครื่องเดียวกัน — นับจากหมายเลข IP ที่ต่อเข้าเซิร์ฟเวอร์ — เข้าเกมพร้อมกันได้สูงสุด 3 ไอดี ไอดีที่ 4 จะเข้าไม่ได้ และมีข้อความบอกเหตุผลให้เห็นชัด ๆ","นับเฉพาะไอดีที่ออนไลน์อยู่ในขณะนั้น ออกจากเกมไอดีใดไอดีหนึ่งแล้วไอดีถัดไปเข้าได้ทันที ส่วนไอดีเดิมที่รีเฟรชหน้าเว็บหรือหลุดแล้วต่อใหม่ ไม่ถูกนับเพิ่ม","บ้านที่เล่นหลายคนด้วยเน็ตเส้นเดียวกัน หรือเล่นผ่านเน็ตมือถือที่ผู้ให้บริการใช้ IP ร่วมกัน อาจถูกนับรวมเป็นเครื่องเดียว ถ้าเข้าไม่ได้ทั้งที่ไม่ได้เปิดหลายไอดี แจ้งแอดมินได้เลย"],en:{title:"Limited to 3 accounts online at once per machine (per IP)",lines:["As of this update, the same machine — counted by the IP address connecting to the server — can have at most 3 accounts online at once. A 4th account will be blocked, with a clear message explaining why.","Only accounts online at that moment count. Log one out and the next one can log in right away, and the same account refreshing the page or reconnecting after a drop is not counted twice.","A household with several people playing on the same internet line, or on mobile data where the carrier shares IPs, may get counted as one machine. If you're blocked without actually running multiple accounts, let an admin know."]}},{id:"2026-09-22-boost-scrolls-for-everyone",date:"2026-09-22",time:"22:31",title:"แจกม้วนคัมภีร์ EXP x2 และ Drop x2 ให้ผู้เล่นทุกคน",lines:["ผู้เล่นทุกคนได้ม้วนคัมภีร์ EXP x2 และ Drop x2 อย่างละ 5 ม้วน ส่งเข้ากล่องจดหมาย (กดเปิดเมลแล้วรับของได้เลย) ใครยังไม่เห็น ลองออกแล้วเข้าเกมใหม่อีกครั้ง","ใช้แล้วได้บัฟนาน 1 ชั่วโมง: EXP x2 คูณทั้ง Base EXP และ Job EXP ส่วน Drop x2 คูณโอกาสดรอปของทุกชนิด","ม้วนคัมภีร์ผูกกับตัวละคร จึงขายคืนพ่อค้า ตั้งขายในตลาดกลาง และเทรดให้กันไม่ได้","ขอบคุณที่เข้ามาเล่นด้วยกันนะ"],en:{title:"EXP x2 and Drop x2 scrolls for every player",lines:["Every player gets 5 EXP x2 scrolls and 5 Drop x2 scrolls, sent to your mailbox (open your mail and claim them). If you don't see them yet, try logging out and back in.","Using one grants a 1-hour buff: EXP x2 multiplies both Base EXP and Job EXP, while Drop x2 multiplies the drop chance of every item type.","The scrolls are bound to your character, so they cannot be sold back to a merchant, listed on the Market, or traded to other players.","Thanks for playing with us."]}},{id:"2026-09-22-boost-scrolls",date:"2026-09-22",time:"22:21",title:"ม้วนคัมภีร์ EXP x2 และ Drop x2 — อยู่ระหว่างทดสอบ",lines:["เพิ่มไอเทมใหม่สองชิ้น: ม้วนคัมภีร์ EXP x2 และม้วนคัมภีร์ Drop x2 ใช้แล้วได้บัฟนาน 1 ชั่วโมง เห็นเป็นชิปบัฟข้างการ์ดข้อมูลเหมือนบัฟอื่น","EXP x2 คูณทั้ง Base EXP และ Job EXP ส่วน Drop x2 คูณโอกาสดรอปของทุกชนิด ทั้งของใช้ อุปกรณ์ การ์ด กล่อง และหินตีบวก","ม้วนคัมภีร์ทั้งสองผูกกับตัวละคร: ไม่มีขายที่ร้าน ขายคืนพ่อค้าไม่ได้ ตั้งขายในตลาดกลางไม่ได้ และเทรดให้กันไม่ได้","ตอนนี้ยังอยู่ในช่วงทดสอบ ยังไม่เปิดให้หาได้ทั่วไป"],en:{title:"EXP x2 and Drop x2 scrolls — currently in testing",lines:["Added two new items: the EXP x2 Scroll and the Drop x2 Scroll. Using one grants a 1-hour buff, shown as a buff chip next to your info card like other buffs.","EXP x2 multiplies both Base EXP and Job EXP, while Drop x2 multiplies the drop chance of everything — supplies, gear, cards, boxes and refine stones.","Both scrolls are bound to your character: not sold in the shop, cannot be sold back to a merchant, cannot be listed on the Market, and cannot be traded.","They're still in testing for now and not yet available to find in general."]}},{id:"2026-09-22-channel-head-count",date:"2026-09-22",time:"22:13",title:"หน้าเลือกเซิร์ฟเวอร์บอกแล้วว่าแต่ละช่องมีคนอยู่กี่คน",lines:["ก่อนหน้านี้รายชื่อช่อง (CH) บอกแค่เลขช่อง ต้องเข้าไปดูเองถึงจะรู้ว่าช่องไหนคนแน่นช่องไหนว่าง ตอนนี้แต่ละแถวขึ้นจำนวนคนในช่องนั้นให้เลย เหมือนที่แถวภูมิภาคทำอยู่แล้ว","ตัวเลขอัปเดตตามข้อมูลที่เซิร์ฟเวอร์ส่งอยู่แล้วทุก 5 วินาที จึงไม่ได้เพิ่มภาระให้เซิร์ฟเวอร์ และจะส่งเฉพาะแผนที่ที่มีมากกว่าหนึ่งช่องเท่านั้น"],en:{title:"The server select screen now shows how many players are in each channel",lines:["The channel (CH) list used to show only the channel number, so you had to go in yourself to see which one was crowded or empty. Now each row shows that channel's player count, the same way the region rows already do.","The number updates from data the server was already sending every 5 seconds, so it adds no extra load, and it's only sent for maps that have more than one channel."]}},{id:"2026-09-22-party-roster-shows-the-map",date:"2026-09-22",time:"22:09",title:"สมาชิกปาร์ตี้ที่ไม่ได้อยู่ด้วยกัน บอกแล้วว่าอยู่แมพไหน ช่องไหน",lines:['เดิมใครก็ตามที่ไม่ได้อยู่แมพเดียวกับเรา ขึ้นว่า "ออฟไลน์" หมด ทั้งที่บางคนแค่วาร์ปกลับเมืองหรืออยู่คนละช่อง — ตอนนี้แผงปาร์ตี้บอกเลยว่า "Aurelia CH2", "Frostfang CH1" ตามจริง','คำว่า "ออฟไลน์" เหลือไว้ให้คนที่ออกจากเกมไปแล้วจริง ๆ เท่านั้น',"ใช้ได้ทั้งแผงปาร์ตี้มุมซ้ายและหน้าต่างปาร์ตี้ (ในหน้าต่างขึ้นชื่อแมพเต็ม) · ข้อมูลอัปเดตทุก 5 วินาที"],en:{title:"The party roster now shows which map and channel absent members are on",lines:[`Previously, anyone not on your map showed as "Offline", even if they'd simply warped back to town or were on a different channel — now the party panel shows exactly where, like "Aurelia CH2" or "Frostfang CH1".`,'"Offline" is now reserved for members who have actually logged out.',"This works in both the left-corner party panel and the party window (the window shows the full map name) · updates every 5 seconds."]}},{id:"2026-09-22-gear-listing-transit",date:"2026-09-22",time:"22:04",title:'ตั้งขายอุปกรณ์แล้วของหายจากตัว แต่ไม่ขึ้นใน "รายการของฉัน" — แก้แล้ว',lines:["ถ้ากดตั้งขายอุปกรณ์จังหวะที่กระดานตลาดตอบช้า แล้วเปลี่ยนแผนที่ เปลี่ยนแชนแนล หรือหลุดออกจากเกมพอดี อุปกรณ์ชิ้นนั้นจะหายไปจากกระเป๋าโดยไม่ขึ้นบนกระดานเลย ตอนนี้แก้แล้ว","อุปกรณ์ที่กำลังส่งขึ้นกระดานจะถูกจดไว้และส่งซ้ำจนกว่ากระดานจะรับ — ถึงเซิร์ฟเวอร์รีสตาร์ตกลางคันก็ยังไปต่อให้จนขึ้นขายสำเร็จในชื่อของคุณ","ถ้ากระดานรับไม่ได้จริง ๆ (เช่นตั้งขายครบ 100 ชิ้นแล้ว) ระบบจะคืนของเข้ากระเป๋าให้ทันทีที่คุณกลับเข้าเกมและมีที่ว่างพอ","ของที่ถอดคืนจากกระดานตอนที่ออกจากเกมพอดี จะถูกวางกลับบนกระดานในชื่อของคุณแทนที่จะหายไป ถอดคืนได้ที่นายหน้าตลาดทุกภูมิภาค","ใครที่เคยเจออาการนี้ ลองเปิดกระดานอุปกรณ์ที่นายหน้าตลาดดู ของจะอยู่ในรายการของคุณตามเดิม"],en:{title:'Fixed gear vanishing after listing without showing in "My Listings"',lines:["If you listed a piece of gear right as the Market board was slow to respond, then happened to change map, switch channel, or disconnect at that exact moment, the item would vanish from your inventory without ever appearing on the board. This is now fixed.","Gear being sent to the board is now recorded and retried until the board accepts it — even a mid-listing server restart won't stop it from eventually going up for sale under your name.","If the board genuinely cannot accept it (for example, you've already hit the 100-listing limit), the system returns the item to your inventory the moment you're back in the game with enough space.","An item you withdrew from the board right as you disconnected is put back on the board under your name instead of disappearing; you can withdraw it at the market broker in any region.","If you've run into this before, open the gear board at the market broker — the item will be in your listings as expected."]}},{id:"2026-09-22-mail-claim-silver",date:"2026-09-22",time:"21:50",title:"กดรับเงินจากจดหมายขายของแล้วเงินไม่เข้า — แก้แล้ว",lines:['จดหมายจากตลาดกลางที่เพิ่งขายได้ บางครั้งยังส่งไปไม่ถึงกล่องจดหมายกลางตอนที่กด "รับของทั้งหมด" ทำให้จดหมายฉบับนั้นหายไปจากกล่องทั้งที่ยังไม่ได้รับเงิน ตอนนี้ระบบจะส่งจดหมายที่ค้างอยู่ให้ถึงก่อนเสมอ แล้วจึงจ่ายเงินให้ครบทุกฉบับในครั้งเดียว',"จดหมายที่ยังส่งไม่ถึงกล่องกลางจะไม่ถูกลบออกจากหน้าจอและตัวเลขแจ้งเตือนอีก — ของที่ยังไม่ได้รับจะยังเห็นอยู่จนกว่าจะรับจริง","Silver/Gold/ไอเทมที่เพิ่งกดรับ จะถูกบันทึกลงตัวละครทันที ไม่ต้องรอรอบบันทึกปกติ จึงไม่มีทางหายถ้าเซิร์ฟเวอร์รีสตาร์ตพอดีในจังหวะนั้น","ใครที่เคยกดรับแล้วเงินไม่เข้า ลองเปิดกล่องจดหมายดูอีกครั้ง จดหมายที่ยังไม่ได้รับจะกลับมาแสดงพร้อมของครบ"],en:{title:"Fixed claiming a sold-item letter that didn't pay out",lines:[`A letter for an item you'd just sold on the Market sometimes hadn't reached your mailbox yet when you pressed "Claim All", so that letter would disappear from the box without ever paying out. The system now always delivers any pending letters first, then pays out every one of them in a single pass.`,"A letter that hasn't reached the mailbox yet is no longer removed from the screen and the notification count — anything unclaimed keeps showing until it's actually claimed.","Silver/Gold/items you just claimed are now saved to your character immediately, without waiting for the regular save cycle, so nothing is lost even if the server happens to restart at that exact moment.","If you've claimed before and the payout never arrived, open your mailbox again — the unclaimed letter will show back up with everything intact."]}},{id:"2026-09-22-exp-event-x2-1200-players",date:"2026-09-22",time:"21:34",title:"ฉลองผู้เล่น 1,200 คน! EXP x2 ทุกคน 8 ชั่วโมง",lines:["ตั้งแต่ 21:35 น. คืนนี้ ถึง 05:35 น. เช้าวันพรุ่งนี้ (เวลาไทย) ทุกคนได้ EXP x2 ทั้ง Base EXP และ Job EXP ไม่ต้องกดรับอะไร ไม่ต้องเป็น Premium","ตัวคูณนี้คูณทับโบนัสปาร์ตี้และโบนัส Premium ตามปกติ — ล่ารวมปาร์ตี้ในแผนที่เดียวกันยิ่งคุ้ม","ดูเวลาที่เหลือได้จากป้ายบัฟ EXP x2 บนหน้าจอ · ขอบคุณทุกคนที่เข้ามาเล่นด้วยกันจนถึง 1,200 คนนะ"],en:{title:"Celebrating 1,200 players! EXP x2 for everyone, 8 hours",lines:["From 21:35 tonight until 05:35 tomorrow morning (Thai time), everyone gets EXP x2 on both Base EXP and Job EXP — nothing to claim, no Premium required.","This multiplier stacks on top of the party bonus and Premium bonus as usual — grinding together in a party on the same map pays off even more.","Check the time remaining on the EXP x2 buff icon on screen · thanks to everyone who's helped us reach 1,200 players together."]}},{id:"2026-09-22-support-mail",date:"2026-09-22",time:"21:32",title:"ทีมงานส่งของชดเชยทางจดหมายได้แล้ว",lines:["เวลามีปัญหาแล้วต้องชดเชยของหรือ Silver ทีมงานส่งให้ทางกล่องจดหมายได้โดยตรงแล้ว — เปิดหน้าต่าง Mail กดรับได้จากทุกแมพ และจดหมายจะค้างไว้เป็นหลักฐานหลังกดรับด้วย",'ของที่ส่งจะมาในนามผู้ส่ง "ทีมงาน" เสมอ · ถ้าได้จดหมายที่อ้างว่าเป็นทีมงานจากชื่ออื่น ให้สงสัยไว้ก่อน'],en:{title:"The team can now send compensation by mail",lines:["When something goes wrong and needs compensating with items or Silver, the team can now send it directly to your mailbox — open the Mail window and claim it from any map, and the letter stays as a record even after you claim it.",'Anything sent this way always comes from the sender "The Team" · if you get a letter claiming to be from the team under a different name, be suspicious of it.']}},{id:"2026-09-22-class-guide-smaller",date:"2026-09-22",time:"21:32",title:"กล่องแนะนำเปลี่ยนอาชีพเล็กลง 30%",lines:['กล่อง "Job Lv.10 แล้ว! เปลี่ยนอาชีพได้แล้ว" ย่อลง 30% บังหน้าจอน้อยลง ยังเลื่อนดูและกด × ปิดได้เหมือนเดิม'],en:{title:"The class-change guide box shrunk by 30%",lines:['The "Job Lv.10 reached! You can change class now" box is now 30% smaller and blocks less of the screen; you can still scroll through it and close it with ✕ as before.']}},{id:"2026-09-22-changelog-page",date:"2026-09-22",time:"21:32",title:"มีหน้ารวมอัปเดตย้อนหลังแล้วที่ /changelog",lines:["เดิมรายละเอียดอัปเดตขึ้นในแชทระบบครั้งเดียวแล้วหายไปกับประวัติแชท ตอนนี้เปิดดูย้อนหลังได้ทุกครั้งที่ lumivaraonline.com/changelog เรียงจากใหม่ไปเก่าครบทุกแพตช์","มีช่องค้นหาในหน้า (พิมพ์ชื่อสกิล ระบบ หรืออาชีพก็ได้) และกดที่หัวข้ออัปเดตเพื่อคัดลอกลิงก์ตรงไปยังแพตช์นั้นได้เลย",'เข้าได้จากลิงก์ "บันทึกการอัปเดต" บนหัวหน้า Wiki และหน้าข้อตกลง โดยไม่ต้องล็อกอิน'],en:{title:"Added a patch note history page at /changelog",lines:["Update details used to appear once in system chat and then vanish with the chat history. Now you can look them up any time at lumivaraonline.com/changelog, listing every patch newest first.","The page has a search box (type a skill name, system or class), and clicking an update's headline copies a link straight to that patch.",'Reachable from the "Patch Notes" link at the top of the Wiki and the Terms page, no login required.']}},{id:"2026-09-22-channel-spread-and-switch",date:"2026-09-22",time:"21:30",title:"กลับเมืองแล้วสุ่มช่องให้ · กดเปลี่ยนช่องแล้วเปลี่ยนจริง",lines:["เดิมทุกคนที่กลับเมืองหรือเดินออกจากพอร์ทัลจะถูกยัดเข้าช่องที่ 1 จนเต็มก่อนถึงจะขยับไปช่องถัดไป เมืองเลยหน่วงและปิงพุ่งทั้งที่ช่องอื่นยังโล่ง ตอนนี้ระบบจะสุ่มช่องให้ โดยช่องที่คนน้อยกว่ามีโอกาสถูกเลือกมากกว่าตามที่ว่างจริง — คนในแต่ละช่องจะไล่เลี่ยกันแทนที่จะกองอยู่ช่องเดียว","กดเปลี่ยนช่องเองแล้วไม่ขยับ แก้แล้ว: เดิมถ้ามีเพื่อนร่วมปาร์ตี้ยืนอยู่ในช่องเดิม ระบบจะดึงกลับช่องเดิมเงียบ ๆ ตอนนี้ช่องที่กดเองมาก่อนทุกกฎ ยกเว้นช่องนั้นเต็ม 30 คนจริง ๆ","ถ้าช่องที่กดเต็มพอดี จะมีข้อความบอกในแชทว่าเต็มแล้วให้ลองช่องอื่น ไม่ใช่กดแล้วเงียบเหมือนเดิม"],en:{title:"Returning to town now spreads you across channels · switching channels actually switches",lines:["Previously, everyone returning to town or stepping out of a portal was crammed into channel 1 until it filled up before moving to the next one, so town lagged and ping spiked while other channels sat empty. The system now assigns a channel at random, weighted so an emptier channel is more likely to be picked based on real availability — players end up spread evenly instead of piling into one channel.","Fixed switching channels yourself and not actually moving: previously, if a party member was standing in the old channel, the system would quietly pull you back into it. Now the channel you picked yourself takes priority over every other rule, unless that channel is genuinely full at 30 players.","If the channel you picked happens to be full, chat now tells you it's full and to try another one, instead of pressing it and getting silence as before."]}},{id:"2026-09-22-party-hud-drops-the-roster",date:"2026-09-22",time:"21:26",title:"แผงปาร์ตี้มุมซ้ายเหลือแค่ปุ่มที่ใช้จริง",lines:["แผงปาร์ตี้ที่ HUD ไม่แสดงรายชื่อสมาชิกทีละคนแล้ว — หน้าจอโล่งขึ้นมาก โดยเฉพาะปาร์ตี้ใหญ่ที่แถวยาวจนบังจอ",'ที่ยังอยู่ครบ: หัวแผงบอกจำนวนสมาชิก x/12 กับโบนัส EXP/Drop, ติ๊ก "แบ่งของในปาร์ตี้", ติ๊ก "รับสมาชิกอัตโนมัติ" และปุ่ม "ออกจากปาร์ตี้"',"อยากดูรายชื่อสมาชิก เลเวล หลอดเลือด หรือเชิญใครออก ให้เปิดหน้าต่างปาร์ตี้จากแถบเมนูเหมือนเดิม"],en:{title:"The party HUD panel now shows only the buttons you actually use",lines:["The party panel on the HUD no longer lists members one by one — the screen is much cleaner now, especially for large parties whose long list used to block the view.",'Still there: the panel header showing member count x/12 with the EXP/Drop bonus, the "Share loot" checkbox, the "Auto-accept members" checkbox, and the "Leave Party" button.',"To see member names, levels, health bars, or to kick someone, open the party window from the menu bar as before."]}},{id:"2026-09-22-revive-lands-in-town",date:"2026-09-22",time:"21:26",title:"ตายแล้วกดกลับเมือง ไม่ไปโผล่กลางดงไม้อีกแล้ว",lines:['บางครั้งกดปุ่ม "กลับเมือง" หลังหมดสติแล้วตัวละครไปยืนอยู่กลางต้นไม้ในแมพเดิม — เกิดจากตอนส่งตัวข้ามแมพไม่สำเร็จ ระบบดึงตัวกลับแมพเดิมแต่ยังใช้พิกัดของเมือง ทำให้ไปโผล่จุดแปลก ๆ',"ตอนนี้ถ้าส่งตัวไม่สำเร็จ ตัวละครจะกลับไปยืนที่เดิมที่ยืนอยู่ก่อนหน้า (หรือจุดเริ่มของแมพนั้นถ้าจุดเดิมใช้ไม่ได้) แล้วค่อยกดกลับเมืองใหม่ได้ตามปกติ"],en:{title:"Returning to town after death no longer drops you in the middle of the trees",lines:[`Sometimes pressing "Return to Town" after being knocked out would leave your character standing among trees on the same map — caused by a failed cross-map transfer that pulled you back to the same map but still used the town's coordinates, dropping you in a strange spot.`,"Now, if the transfer fails, your character returns to wherever you were standing before (or that map's starting point if that spot is unusable), and you can press Return to Town again normally."]}},{id:"2026-09-22-shop-stocks-every-weapon",date:"2026-09-22",time:"21:19",title:"ร้านค้าขายอาวุธครบทุกชนิดแล้ว",lines:["เดิม Falchion, Blade, Dagger Pair และ Staff ไม่มีขายในร้าน ต้องรอดรอปอย่างเดียว — Thief กับ Mage จึงติดอยู่กับอาวุธเริ่มต้นไปนาน ตอนนี้พ่อค้าขายอาวุธครบทั้ง 10 ชนิดแล้ว","ราคาใหม่: Falchion 300 · Dagger Pair 250 · Staff 500 · Blade 800 Silver (ขายคืนได้ครึ่งราคาเหมือนของร้านทุกชิ้น · พาสซีฟ Haggler ลดราคาได้ตามเดิม)",'ของที่ซื้อจากร้านเป็น "ขั้นต้น" เสมอ — ได้สเตตัสพื้นฐานตายตัว ไม่มี tier และไม่มีสเตตัสสุ่มติดมา ส่วนอาวุธชื่อเดียวกันที่ดรอปจากมอนสเตอร์ยังสุ่มสเตตัสตาม tier เหมือนเดิม ยิ่งมอนลึกยิ่งแรง'],en:{title:"The shop now stocks every weapon type",lines:["Falchion, Blade, Dagger Pair and Staff used to have no shop listing at all — you had to rely purely on drops, which left Thief and Mage stuck with their starting weapon for a long time. The merchant now sells all 10 weapon types.","New prices: Falchion 300 · Dagger Pair 250 · Staff 500 · Blade 800 Silver (sells back for half price like every other shop item · the Haggler passive still lowers the price as before).",'Anything bought from the shop is always "Basic" — fixed base stats, no tier and no random stat rolls. The same-named weapon dropped from monsters still rolls random stats by tier as before, and stronger the deeper the monster.']}},{id:"2026-09-22-channel-cap-25",date:"2026-09-22",time:"21:14",title:"ลดคนต่อแชนแนลเหลือ 30 — เมืองจะไม่หน่วงและปิงไม่พุ่งอีก",lines:["แชนแนลหนึ่งรับได้สูงสุด 30 คน (เดิม 39) และเริ่มส่งคนที่เข้ามาใหม่ไปแชนแนลถัดไปตั้งแต่ 25 คน (เดิม 32) — แผนที่เมืองที่คนแน่นจะกระจายไปอยู่หลายแชนแนลที่โล่งกว่าแทนที่จะยัดรวมกันจนภาพกระตุกและปิงขึ้น","ปาร์ตี้ยังตามกันเข้าแชนแนลเดียวกันได้เหมือนเดิม แต่จะไม่ดันแชนแนลเกิน 30 คน","แชนแนลที่คนเหลือน้อยจะยุบเองเร็วขึ้น (เดิมต้องเหลือต่ำกว่า 28 คนทั้งแผนที่ ตอนนี้ 21 คน) และระบบจะย้ายคนไปแชนแนลที่โล่งกว่าได้ไวขึ้น","ใครอยากอยู่แชนแนลไหนยังปักหมุดเองได้ตามเดิมจากหน้าต่างเลือกแชนแนล"],en:{title:"Channel cap lowered to 30 — town stops lagging, ping stops spiking",lines:["A channel now holds a maximum of 30 players (was 39), and starts sending new arrivals to the next channel from 25 players onward (was 32) — a crowded town map now spreads across several emptier channels instead of piling up until it stutters and ping climbs.","Parties can still follow each other into the same channel as before, but it will never push a channel past 30 players.","A near-empty channel now closes itself sooner (previously the whole map had to drop below 28 players, now it's 21), and the system moves people into emptier channels faster.","You can still pin yourself to whichever channel you want from the channel select window, as before."]}},{id:"2026-09-22-rebalance-vitals-vigor-frost",date:"2026-09-22",time:"20:46",title:"ปรับสมดุล: HP/SP ตามอาชีพ · Vigor · Frost Area",lines:["HP/SP สูงสุดที่ได้จากการเลือกอาชีพปรับใหม่ทั้งหมด — Swordsman HP +95% / SP +15%, Mage HP +45% / SP +85%, Archer HP +55% / SP +35%, Cleric HP +65% / SP +65%, Merchant HP +75% / SP +25%, Thief HP +60% / SP +10% (ทุกตัวละครได้ผลทันทีที่เข้าเกม ไม่ต้องเปลี่ยนอาชีพใหม่)","Vigor (Swordsman) เพิ่มของใหม่: ATK เพิ่มเท่ากับ 2% ของ HP สูงสุด ต่อระดับ สูงสุด 20% ที่ Lv.10 — ยิ่งสร้างสายเลือดหนา ยิ่งตีแรง (ของเดิมเรื่องฟื้น HP และยาแรงขึ้นยังอยู่ครบ)","Frost Area (Mage) โอกาสแช่แข็งขึ้นจาก 50% เป็น 77% และแช่นานขึ้นจาก 3 เป็น 5 วินาที · ระหว่างแช่แข็งยังขยับไม่ได้และรับดาเมจเวทแรงขึ้น 20% ตามเดิม"],en:{title:"Rebalance: class HP/SP · Vigor · Frost Area",lines:["Max HP/SP from choosing a class has been fully rebalanced — Swordsman HP +95% / SP +15%, Mage HP +45% / SP +85%, Archer HP +55% / SP +35%, Cleric HP +65% / SP +65%, Merchant HP +75% / SP +25%, Thief HP +60% / SP +10% (every character gets this the moment they log in, no need to change class again).","Vigor (Swordsman) gains a new effect: ATK increases by 2% of Max HP per rank, up to 20% at Lv.10 — the tankier your build, the harder you hit (the existing HP regen and stronger potion effects are all still there).","Frost Area (Mage) freeze chance is up from 50% to 77%, and duration is up from 3 to 5 seconds · while frozen, targets still can't move and still take 20% more magic damage, as before."]}},{id:"2026-09-22-map-window-close-fix",date:"2026-09-22",time:"20:20",title:"ปิดแผนที่ใหญ่ด้วยปุ่ม × แล้วจอค้างเป็นแถบยาว แก้แล้ว",lines:["ตอนเปิดแผนที่ใหญ่แล้วกดปุ่ม × (ซ่อนแผนที่) แผนที่จะยืดเป็นแถบยาวกลางจอและฉากหลังยังหรี่ค้างอยู่ ตอนนี้กด × จะปิดหน้าต่างแผนที่และเก็บแผนที่ย่อให้เรียบร้อยในครั้งเดียว","ใครที่ค้างอยู่ในสถานะนี้ พอรีโหลดเกมจะกลับมาปกติเอง"],en:{title:"Fixed the screen freezing as a long bar when closing the big map with ✕",lines:["Opening the big map and then pressing ✕ (hide map) used to stretch the map into a long bar across the middle of the screen, with the dimmed background stuck behind it. Now pressing ✕ closes the map window and tidies away the mini-map in one go.","If you're currently stuck in this state, reloading the game will fix it on its own."]}},{id:"2026-09-22-map-window",date:"2026-09-22",time:"20:07",title:"กดขยายแผนที่แล้วไม่ทับปุ่มสกิลอีกต่อไป",lines:["แผนที่ย่อตอนกดขยาย เคยบานลงมาทับปุ่มสกิล 8 / 9 และปุ่ม AUTO จนกดไม่โดน ตอนนี้เปิดเป็นหน้าต่างกลางจอแทน ปิดด้วยปุ่มเดิม แตะนอกหน้าต่าง หรือกด Esc","ระหว่างเปิดแผนที่ ปุ่มเดิน/โจมตี/สกิลจะหรี่ลงและกดไม่ติด กันกดโดนโดยไม่ตั้งใจ","แผนที่ย่อมุมขวาบนเล็กลงเล็กน้อย และแถบด้านล่างบางลง เหลือแค่ช่อง จำนวนคน และพิกัด (ชื่อภูมิภาคไปอยู่บนหัวหน้าต่างแผนที่ใหญ่แทน)"],en:{title:"Expanding the map no longer covers the skill buttons",lines:["The mini-map used to expand downward over skill buttons 8/9 and the AUTO button, making them impossible to tap. It now opens as a window in the middle of the screen instead, closed with the same button, by tapping outside it, or with Esc.","While the map is open, the move/attack/skill buttons dim and stop responding, to prevent accidental taps.","The top-right mini-map is now slightly smaller, and its bottom bar is thinner, showing only channel, player count and coordinates (the region name has moved to the header of the big map window instead)."]}},{id:"2026-09-22-auto-sp-potion-at-zero",date:"2026-09-22",time:"20:05",title:"บอทกินยาน้ำเงินตอน SP หมดเกลี้ยงแล้ว",lines:["เดิมถ้า SP ลงไปถึง 0 พอดี บอทจะไม่ยอมกินยาน้ำเงินเลย ทั้งที่มียาอยู่ในกระเป๋า — สายฮิลที่ตั้งสกิลไว้จึงค้างอยู่เฉย ๆ จนกว่า SP จะฟื้นเอง",'ตอนนี้ SP = 0 ถือเป็นจังหวะที่ต้องกินยาที่สุด บอทจะจิบยาน้ำเงินทันที (อย่าลืมติ๊ก "ใช้ยาน้ำเงิน SP อัตโนมัติ" ในหน้าตั้งค่าบอท ค่าเริ่มต้นยังปิดอยู่)'],en:{title:"The bot now drinks blue potions when SP hits zero",lines:["Previously, if SP hit exactly 0, the bot would refuse to drink a blue potion even with plenty in the inventory — a healer relying on a set skill would just sit idle until SP recovered on its own.",`SP = 0 is now treated as exactly when you need a potion most, so the bot drinks a blue potion immediately (remember to tick "Auto-use SP blue potion" in the bot settings — it's still off by default).`]}},{id:"2026-09-22-chat-fanout-targeted",date:"2026-09-22",time:"19:46",title:"ส่งแชทเฉพาะแมปที่มีคนอยู่",lines:["เมื่อก่อนทุกข้อความในแชทโลกถูกส่งไปทุกแมปทุกช่องในภูมิภาคนั้น รวมถึงแมปที่ไม่มีใครอยู่เลย ตอนนี้ส่งเฉพาะแมปที่มีคนยืนอยู่จริง","สิ่งที่คุณเห็นเหมือนเดิมทุกอย่าง แต่เซิร์ฟเวอร์ทำงานเบาลงมากเวลาคนเยอะ"],en:{title:"Chat now only sends to maps with players on them",lines:["Every world chat message used to be sent to every map and channel in that region, including maps with nobody on them. It's now only sent to maps that actually have someone standing on them.","Everything you see is exactly the same, but the server works far lighter when there are a lot of players."]}},{id:"2026-09-22-more-menu-badge-count",date:"2026-09-22",time:"19:46",title:'ปุ่ม "เพิ่มเติม" โชว์ตัวเลขแจ้งเตือนแล้ว',lines:["เมนูที่ซ่อนอยู่หลังปุ่ม ☰ เพิ่มเติม (เมล เควส ภารกิจเปลี่ยนคลาส ฯลฯ) เคยมีจุดแดงแต่ไม่เคยขึ้นจริง เพราะโดนกรอบไอคอนตัดทิ้ง ตอนนี้ย้ายมาไว้บนตัวปุ่มและรวมเป็นตัวเลขจำนวนที่รออยู่","ถ้าเป็นการเตือนที่ไม่มีจำนวน จะขึ้นเป็นเครื่องหมาย ! แทน"],en:{title:'The "More" button now shows a notification count',lines:["The menu hidden behind the ☰ More button (Mail, Quests, the class change task, etc.) had a red dot that never actually showed, since it was clipped by the icon frame. It now sits on the button itself and shows the total count waiting.","For a notification with no count, it shows a ! mark instead."]}},{id:"2026-09-22-party-sync-targeted",date:"2026-09-22",time:"19:34",title:"ปาร์ตี้ตอบสนองไวขึ้นตอนเซิร์ฟเวอร์คนเยอะ",lines:["เมื่อก่อนทุกครั้งที่มีคนเข้า-ออกปาร์ตี้ เซิร์ฟเวอร์จะกระจายข้อมูลไปทุกแมปทุกช่องทั่วโลก แม้แมปนั้นจะไม่มีสมาชิกปาร์ตี้อยู่เลย ตอนนี้ส่งเฉพาะแมปที่มีสมาชิกยืนอยู่จริง","ยิ่งคนเยอะยิ่งเห็นผล การชวน เข้า ออก และเตะออกจากปาร์ตี้จะตอบสนองไวขึ้น"],en:{title:"Party actions respond faster when the server is busy",lines:["Every time someone joined or left a party, the server used to broadcast it to every map and channel worldwide, even maps with no party member on them. It's now only sent to maps that actually have a member standing on them.","The busier the server, the more noticeable it is — inviting, joining, leaving and kicking from a party all respond faster."]}},{id:"2026-09-22-trade-gear-icon",date:"2026-09-22",time:"19:25",title:"ธนูในหน้าต่างเทรดไม่ขึ้นรูปดาบแล้ว",lines:["ของที่เสนอในหน้าต่างเทรดเคยใช้รูปตามช่องสวมใส่ ธนู คทา ค้อน และอาวุธอื่นที่ใส่ช่องเดียวกับดาบจึงขึ้นเป็นรูปดาบหมด","ตอนนี้แต่ละชิ้นใช้รูปของตัวเอง ตรงกับที่เห็นในกระเป๋าและในตลาด"],en:{title:"A bow in the trade window no longer shows a sword icon",lines:["Items offered in the trade window used to use an icon based on their equip slot, so a bow, rod, hammer or any other weapon sharing the sword's slot all showed as a sword.","Now each item uses its own icon, matching what you see in the inventory and the Market."]}},{id:"2026-09-22-sixteen-channels",date:"2026-09-22",time:"19:21",title:"แมปเปิดช่องได้ถึง 16 ช่อง",lines:["ขยายเพดานจาก 8 เป็น 16 ช่องต่อหนึ่งแมป รองรับช่วงที่คนเข้าพร้อมกันเยอะ ๆ ช่องใหม่เปิดเองเมื่อคนแน่นและปิดเองเมื่อคนออกหมดเหมือนเดิม","ช่องที่เลือกไว้เองยังติดตามข้ามแมปเหมือนเดิม แต่ถ้าแมปปลายทางคนน้อยจะพาไปช่อง 1 ก่อน แล้วค่อยกลับเข้าช่องที่เลือกไว้เมื่อแมปนั้นเริ่มแน่น"],en:{title:"Maps can now open up to 16 channels",lines:["The cap is raised from 8 to 16 channels per map, to handle spikes when a lot of players log in at once. New channels still open on their own when crowded and close on their own once empty, as before.","A channel you picked still follows you across maps as before, but if the destination map is nearly empty it puts you on channel 1 first, then returns you to your chosen channel once that map starts filling up."]}},{id:"2026-09-22-more-channels-per-map",date:"2026-09-22",time:"18:44",title:"แมปยอดฮิตเปิดช่องได้ถึง 8 ช่อง หายกระตุก",lines:["เมื่อก่อนหนึ่งแมปเปิดได้แค่ 4 ช่อง พอเต็มทั้ง 4 คนที่เข้ามาใหม่จะถูกยัดเข้าช่องที่ว่างที่สุด ทำให้ช่องนั้นคนล้นจนภาพเริ่มกระตุก ตอนนี้ขยายเป็น 8 ช่องแล้ว","ช่องใหม่จะเปิดเองเมื่อคนเยอะ และปิดเองเมื่อคนออกหมด เลือกช่องเองได้จากป้ายมุมจอเหมือนเดิม"],en:{title:"Popular maps can now open up to 8 channels — no more stutter",lines:["A map used to be capped at 4 channels; once all 4 filled up, new arrivals were crammed into whichever was emptiest, overloading it until the game started to stutter. It's now expanded to 8 channels.","New channels open on their own when crowded and close on their own once empty; you can still pick your own channel from the corner tag as before."]}},{id:"2026-09-22-first-login-unstuck",date:"2026-09-22",time:"18:27",title:"ผู้เล่นใหม่ที่ล็อกอินครั้งแรกแล้วเข้าไม่ได้ เข้าได้แล้ว",lines:['บางบัญชีที่เพิ่งสมัครครั้งแรกติดหน้า "Failed to connect" วนไปเรื่อย ๆ เพราะเซิร์ฟเวอร์จำผิดว่าเคยมีตัวละครอยู่แล้ว ตอนนี้ระบบตรวจซ้ำก่อน ถ้าไม่มีข้อมูลตัวละครจริง ๆ ที่ไหนเลย จะสร้างตัวละครใหม่ให้ทันที',"ตัวละครเก่าที่มีข้อมูลอยู่จริงยังได้รับการปกป้องเหมือนเดิม ไม่มีการรีเซ็ตเป็น Lv.1"],en:{title:"Fixed new players getting stuck on their very first login",lines:[`Some brand-new accounts got stuck looping on a "Failed to connect" screen, because the server wrongly assumed a character already existed. The system now double-checks first, and if there's truly no character data anywhere, it creates a new character right away.`,"Existing characters with real data are still protected as before — none get reset to Lv.1."]}},{id:"2026-09-22-share-link-preview-card",date:"2026-09-22",time:"18:15",title:"แชร์ลิงก์เกมแล้วขึ้นรูปการ์ดสวย ๆ",lines:["ส่งลิงก์ lumivaraonline.com ใน Facebook, Messenger, X/Twitter, LINE หรือ Discord แล้วจะขึ้นภาพเมืองของเกม พร้อมชื่อและคำอธิบายให้เอง ไม่ใช่ลิงก์เปล่า ๆ อีกต่อไป","หน้า Wiki และหน้าข้อตกลงก็มีการ์ดของตัวเองเหมือนกัน"],en:{title:"Sharing the game's link now shows a nice preview card",lines:["Sharing the lumivaraonline.com link on Facebook, Messenger, X/Twitter, LINE or Discord now shows a picture of the game's town, along with a title and description of its own — no longer just a bare link.","The Wiki and the Terms pages have their own preview cards too."]}},{id:"2026-09-22-two-domains-both-work",date:"2026-09-22",time:"17:56",title:"เข้าได้ทั้ง lumivaraonline.com และ dev.cointh.com",lines:["ตอนนี้ทั้งสองลิงก์เข้าเกมได้ตามปกติ ไม่มีการเด้งข้ามโดเมนแล้ว ใครใช้ลิงก์ไหนอยู่ก็ใช้ต่อได้เลย","ตัวละครผูกกับโดเมนที่ล็อกอินไว้ ถ้าเล่นแบบ Guest ให้เข้าลิงก์เดิมที่เคยเล่น จะเจอตัวละครเดิม ส่วนล็อกอิน Google เข้าได้ทั้งสองลิงก์"],en:{title:"Both lumivaraonline.com and dev.cointh.com work",lines:["Both links now open the game normally, with no redirect between domains anymore — whichever link you've been using, you can keep using it.","Your character is tied to the domain you logged in with. If you play as Guest, use the same link you always have to find your character; if you're logged in with Google, both links reach it."]}},{id:"2026-09-22-new-home-lumivaraonline",date:"2026-09-22",time:"17:51",title:"ย้ายบ้านใหม่: lumivaraonline.com",lines:["เกมย้ายมาอยู่ที่ https://lumivaraonline.com แล้ว ใครบุ๊กมาร์ก dev.cointh.com ไว้ เข้าลิงก์เดิมได้ตามปกติ ระบบจะพามาที่โดเมนใหม่ให้เอง","ตัวละครทั้งที่ล็อกอิน Google และที่เล่นแบบ Guest ถูกพาข้ามมาด้วย ไม่ต้องสร้างใหม่ ถ้าหน้าจอค้างที่ลิงก์เก่าให้กดรีเฟรชหนึ่งครั้ง"],en:{title:"New home: lumivaraonline.com",lines:["The game has moved to https://lumivaraonline.com. If you bookmarked dev.cointh.com, that link still works as normal — the system carries you over to the new domain automatically.","Characters logged in with Google and those playing as Guest have both been carried over — no need to create a new one. If the screen gets stuck on the old link, refresh once."]}},{id:"2026-09-22-class-vitals-and-mage-mastery",date:"2026-09-22",time:"17:22",title:"อาชีพเพิ่ม MaxHP/MaxSP เป็น % และ Mage Mastery แรงขึ้น",lines:["เลือกอาชีพแล้วได้ MaxHP/MaxSP เพิ่มเป็นเปอร์เซ็นต์ทันที: Swordsman HP +40% SP +5%, Mage HP +10% SP +40%, Archer HP +15% SP +20%, Cleric HP +25% SP +25%, Merchant HP +30% SP +10%, Thief HP +20% SP +5%","Mage Mastery แรงขึ้น: MATK +2% ต่อระดับ (สูงสุด +20%) และลด SP ที่สกิลใช้ 1% ต่อระดับ (สูงสุด 10%)"],en:{title:"Classes now add MaxHP/MaxSP as a % and Mage Mastery is stronger",lines:["Choosing a class now instantly grants MaxHP/MaxSP as a percentage: Swordsman HP +40% SP +5%, Mage HP +10% SP +40%, Archer HP +15% SP +20%, Cleric HP +25% SP +25%, Merchant HP +30% SP +10%, Thief HP +20% SP +5%.","Mage Mastery is stronger: MATK +2% per rank (up to +20%), and skills cost 1% less SP per rank (up to 10%)."]}},{id:"2026-09-22-monitor-online-chart",date:"2026-09-22",time:"17:18",title:"กราฟผู้เล่นออนไลน์ย้อนหลัง 24 ชั่วโมง",lines:["หน้า /monitor.html มีกราฟจำนวนผู้เล่นออนไลน์ย้อนหลัง 24 ชั่วโมง เก็บตัวอย่างทุก 5 นาที เห็นได้ว่าช่วงไหนคนเยอะช่วงไหนคนน้อย","ช่วงที่ไม่มีข้อมูลจะเว้นเป็นช่องว่างจริง ๆ ไม่ลากเส้นข้ามให้เข้าใจผิด"],en:{title:"24-hour online player chart",lines:["The /monitor.html page now has a chart of online players over the last 24 hours, sampled every 5 minutes, so you can see which hours are busy and which are quiet.","A period with no data is left as a real gap, not stretched over with a misleading line."]}},{id:"2026-09-22-class-guide-fits-phone",date:"2026-09-22",time:"17:08",title:"กล่องแนะนำเปลี่ยนอาชีพไม่ล้นจอมือถืออีกแล้ว",lines:['กล่อง "Job Lv.10 แล้ว! เปลี่ยนอาชีพได้แล้ว" เคยสูงเกินจอมือถือแนวนอน จนปุ่มด้านล่างหายไปและกดปิดไม่ได้',"ตอนนี้กล่องสูงไม่เกินจอ เลื่อนดูเนื้อหาข้างในได้ และมีปุ่ม × มุมขวาบน (หรือกด Esc) ปิดได้ตลอด"],en:{title:"The class-change guide box no longer overflows on mobile",lines:[`The "Job Lv.10 reached! You can change class now" box used to be taller than a landscape mobile screen, pushing its bottom button off-screen so you couldn't close it.`,"The box is now no taller than the screen, its content scrolls, and the ✕ button in the top-right corner (or Esc) always closes it."]}},{id:"2026-09-22-monitor-player-stats",date:"2026-09-22",time:"17:05",title:"หน้า Monitor มีสถิติผู้เล่นแล้ว",lines:["หน้า /monitor.html เพิ่มแถบสถิติ: จำนวนบัญชีทั้งหมด (แยก Google กับ guest) คนที่เข้าเล่นวันนี้ / 7 วัน / 30 วัน และบัญชีที่สมัครใหม่ในช่วงเดียวกัน","มีพีคผู้เล่นพร้อมกันของวันนี้และสถิติสูงสุดตลอดกาล พร้อมวันเวลาที่ทำได้ เซิร์ฟเวอร์รีสตาร์ทก็ไม่ลืม"],en:{title:"The Monitor page now has player stats",lines:["The /monitor.html page has a new stats bar: total accounts (split into Google and Guest), players active today / in 7 days / in 30 days, and new accounts registered over the same periods.","It also shows today's concurrent player peak and the all-time record, with the date and time it was set — a server restart won't forget it."]}},{id:"2026-09-22-login-keyart",date:"2026-09-22",time:"16:54",title:"หน้าเข้าสู่ระบบโฉมใหม่ ภาพเมืองเต็มจอ",lines:["ชื่อเกม Lumivara วางกลางจอเป็นตัวอักษรสีขาวใต้ดาวทอง พร้อมเส้นทอง O N L I N E และคำโปรย YOUR ADVENTURE AWAITS","ปุ่ม Sign in with Google ใช้โลโก้ Google ตัวจริง ส่วน Guest Login เป็นปุ่มน้ำเงินพร้อมไอคอนผู้เล่น กดเข้าเกมได้ทันที","แถบล่างรวมลิงก์ Support ข้อตกลงการใช้บริการ และความเป็นส่วนตัวไว้ให้กดได้ตั้งแต่ยังไม่ล็อกอิน · สถานะเซิร์ฟเวอร์และโหมดออฟไลน์ย้ายไปอยู่ในปุ่ม ⚙ มุมขวาล่าง"],en:{title:"Redesigned login screen with a full-screen town backdrop",lines:["The game's name, Lumivara, sits centered in white letters under a gold star, with a gold O N L I N E line and the tagline YOUR ADVENTURE AWAITS.","The Sign in with Google button now uses the real Google logo, while Guest Login is a blue button with a player icon that gets you straight into the game.","The bottom bar now gathers the Support, Terms of Service and Privacy links so you can open them before even logging in · server status and offline mode have moved into the ⚙ button in the bottom right."]}},{id:"2026-09-22-status-window-bigger",date:"2026-09-22",time:"16:51",title:"หน้าต่างค่าสถานะใหญ่ขึ้น 10%",lines:["ขยายหน้าต่างค่าสถานะขึ้นอีก 10% ตัวหนังสือและไอคอนโตตามทั้งกรอบ อ่านค่า ATK MATK HIT FLEE ได้สบายตาขึ้น","ถ้าจอเล็กหน้าต่างจะย่อให้พอดีจอเหมือนเดิม ไม่ล้นออกนอกขอบ"],en:{title:"The Stats window is 10% bigger",lines:["The Stats window is enlarged by another 10%, with its text and icons scaling up too, making ATK, MATK, HIT and FLEE easier on the eyes.","On a small screen it still shrinks to fit as before, never overflowing the edge."]}},{id:"2026-09-22-gear-hover-compare-color",date:"2026-09-22",time:"16:43",title:"บรรทัดเทียบอุปกรณ์ตอนชี้ ใส่สีเขียวแดงแล้ว",lines:["ค่าที่เพิ่มขึ้นเป็นสีเขียว ค่าที่ลดลงเป็นสีแดง เหมือนในการ์ดไอเทม กวาดตาทีเดียวรู้เลยว่าชิ้นไหนคุ้มกว่า"],en:{title:"The gear comparison line on hover now uses green and red",lines:["A stat that goes up is green, and one that goes down is red, matching the item card, so you can tell which piece is better at a glance."]}},{id:"2026-09-22-chat-flood-guard",date:"2026-09-22",time:"16:44",title:"กันสแปมแชท ข้อความซ้ำ ๆ ไม่ท่วมห้องอีกแล้ว",lines:["ข้อความเดิมซ้ำจะส่งไม่ได้ภายใน 90 วินาที ต้องเปลี่ยนข้อความก่อน ประกาศหาปาร์ตี้ยังทำได้ แค่เว้นช่วงหรือเปลี่ยนคำ","เว้นระยะระหว่างข้อความเป็น 1.5 วินาที และถ้าพิมพ์รัวเกิน 6 ข้อความใน 15 วินาที จะถูกพักแชท 30 วินาที","ตอนที่ส่งไม่ผ่าน ระบบจะบอกเหตุผลให้คนส่งเห็นเองคนเดียว ไม่ไปโผล่ในห้องแชท"],en:{title:"Anti-spam for chat — repeated messages no longer flood the room",lines:["The exact same message can't be sent again within 90 seconds — you'll need to change it first. Party-recruitment spam is still allowed, just space it out or change the wording.","There's now a 1.5-second gap required between messages, and sending more than 6 messages within 15 seconds gets you a 30-second chat timeout.","When a message fails to send, the system tells only the sender why — it never shows up in the chat room."]}},{id:"2026-09-22-gear-hover-compare",date:"2026-09-22",time:"16:37",title:"ชี้อุปกรณ์แล้วเห็นเลยว่าดีขึ้นหรือแย่ลงกว่าที่สวมอยู่",lines:["เอาเมาส์ชี้อุปกรณ์ในกระเป๋า คลัง ร้านค้า หรือหน้าตีบวก จะมีบรรทัดเทียบกับของที่สวมอยู่ในช่องนั้น บอกชื่อของที่ใส่อยู่และค่าสถานะที่เปลี่ยน เช่น ATK +12 · DEF -3","ถ้าช่องนั้นยังว่างจะบอกว่าช่องว่าง และถ้าโบนัสเท่ากันก็บอกว่าเท่ากัน ไม่ต้องกดเปิดการ์ดไอเทมเพื่อเทียบอีกต่อไป"],en:{title:"Hovering gear now shows if it's better or worse than what you're wearing",lines:["Hovering a piece of gear in your inventory, storage, the shop or the Refine window now shows a comparison line against whatever's equipped in that slot, naming the equipped item and the stat changes, e.g. ATK +12 · DEF -3.","If the slot is empty, it says so, and if the bonuses are identical, it says they're equal — no more opening the item card just to compare."]}},{id:"2026-09-22-menu-keep-class-bot",date:"2026-09-22",time:"16:28",title:"ปุ่มอาชีพกับบอทกลับมาอยู่นอกปุ่ม ☰",lines:['ปุ่ม "อาชีพ" และ "บอท" ย้ายกลับออกมาอยู่ในแถบเมนูตามเดิม ไม่ต้องกด ☰ ก่อนแล้ว',"แถบเมนูตอนนี้มี 7 ปุ่ม: สถานะ · สกิล · อุปกรณ์ · อาชีพ · แผนที่ · กระเป๋า · บอท · ที่เหลืออยู่ในปุ่ม ☰ เหมือนเดิม"],en:{title:"Class and Bot buttons moved back out of the ☰ menu",lines:['The "Class" and "Bot" buttons have moved back into the menu bar itself, so you no longer need to open ☰ first.',"The menu bar now has 7 buttons: Status · Skills · Gear · Class · Map · Inventory · Bot · everything else stays in ☰ as before."]}},{id:"2026-09-22-menu-overflow",date:"2026-09-22",time:"16:12",title:"แถบเมนูเหลือ 5 ปุ่ม ที่เหลือย้ายเข้าปุ่ม ☰",lines:["แถบไอคอนมุมขวาบนเคยมี 15 ปุ่มจนล้นลงมาหลายแถวและบังแผนที่ ตอนนี้เหลือแค่ 5 ปุ่มที่ใช้บ่อยที่สุด: สถานะ · สกิล · อุปกรณ์ · แผนที่ · กระเป๋า","ที่เหลือทั้งหมดอยู่ในปุ่ม ☰ เพิ่มเติม ท้ายแถว กดแล้วดรอปลงมาเป็นตาราง — เควส ตั้งค่า จดหมาย รางวัล Premium อาชีพ Discord Wiki อันดับ ปาร์ตี้ เพื่อน บอท · กดปุ่มไหนก็ปิดเมนูให้เอง หรือกดที่อื่น / กด Esc ก็ปิด","ปุ่ม ☰ จะมีจุดแดงเตือนเมื่อมีของรอรับในปุ่มที่ซ่อนอยู่ เช่น เควสที่รับรางวัลได้ จดหมายใหม่ หรือตอนถึง Job Lv.10 แล้วเปลี่ยนอาชีพได้","จอมือถือได้พื้นที่เกมคืนมาเห็นชัดที่สุด เพราะแถบเมนูเหลือแถวเดียว"],en:{title:"The menu bar is down to 5 buttons; the rest moved into ☰",lines:["The top-right icon bar used to have 15 buttons, spilling into several rows and blocking the map. It's now down to the 5 most-used buttons: Status · Skills · Gear · Map · Inventory.","Everything else lives behind the ☰ More button at the end of the row; press it to drop down a grid — Quests, Settings, Mail, Rewards, Premium, Class, Discord, Wiki, Rankings, Party, Friends, Bot · pressing any of them closes the menu on its own, and tapping elsewhere or pressing Esc closes it too.","The ☰ button shows a red dot when something in the hidden buttons is waiting — like a quest ready to turn in, new mail, or reaching Job Lv.10 and being able to change class.","Mobile screens gain back the most visible game space, since the menu bar is now a single row."]}},{id:"2026-09-22-legal-docs",date:"2026-09-22",time:"16:12",title:"เปิดหน้าข้อตกลง นโยบายคืนเงิน และความเป็นส่วนตัวแล้ว",lines:["อ่านได้ที่ /legal/ หรือกดลิงก์ใต้หน้าโหลดเกมและบนหัว Wiki · มีสามฉบับ: ข้อตกลงการใช้บริการ นโยบายการชำระเงินและการคืนเงิน และนโยบายความเป็นส่วนตัวตาม พ.ร.บ.คุ้มครองข้อมูลส่วนบุคคล","ข้อสำคัญที่อยากให้อ่าน: Gold, Silver และไอเทมทั้งหมดเป็นสิทธิ์การใช้งานในเกม ไม่ใช่ทรัพย์สิน ไม่มีมูลค่านอกเกม และถอนออกเป็นเงินจริงหรือคริปโตไม่ได้ · ห้ามซื้อขายแลกเปลี่ยนด้วยเงินจริง (RMT) ทั้งฝ่ายซื้อและฝ่ายขาย รวมถึงขายบัญชีและรับจ้างเล่น ฝ่าฝืนมีสิทธิ์ถูกยึดของและแบนถาวรโดยไม่คืนเงิน","ร้านค้า Premium แสดงเรื่องภาษีและเงื่อนไขคืนเงินไว้ใต้ราคาแล้ว · Gold ขอคืนเงินได้ใน 7 วันถ้ายังไม่ใช้และยังไม่แตะตลาด Gold ส่วน Premium เริ่มนับเวลาทันทีที่กดรับจากเมล และเมื่อเริ่มใช้แล้วจะคืนเงินไม่ได้ · ตอนนี้ยังไม่เปิดรับชำระเงินจริง"],en:{title:"The Terms, Refund Policy and Privacy pages are now live",lines:["Read them at /legal/ or via the links under the loading screen and at the top of the Wiki · there are three documents: the Terms of Service, the Payment and Refund Policy, and the Privacy Policy under the Personal Data Protection Act.","The key point worth reading: Gold, Silver and all items are an in-game usage right, not property — they have no value outside the game and cannot be cashed out as real money or crypto · real-money trading (RMT) is banned for both buyer and seller, including selling accounts and playing for hire; violating this can mean losing the items and a permanent ban with no refund.","The Premium shop now shows tax and refund terms right under the price · Gold can be refunded within 7 days if unused and untouched on the Gold exchange, while Premium starts counting the moment you claim it from mail and cannot be refunded once it's started · real payments are still not open right now."]}},{id:"2026-09-22-skill-cast-level",date:"2026-09-22",time:"14:30",title:"เลือกระดับสกิลตอนใช้ได้แล้ว ประหยัด SP",lines:["สกิลที่อัพสูงแล้วใช้ SP มากขึ้นตามระดับ ตอนนี้ปรับลดระดับที่ใช้ได้เอง เช่น เรียน Lv.10 แต่ใช้ที่ Lv.5 จะจ่าย SP และแรงตามระดับ 5",'ตั้งได้ในหน้าสกิล ที่ช่อง "ใช้ที่ Lv." ข้างปุ่มใช้สกิล กด − / + เพื่อเลือกระดับ 1 ถึงระดับที่เรียนไว้ ค่าที่ตั้งจำไว้ให้ตลอด',"ระดับที่ใช้มีผลกับดาเมจ จำนวนฮิตของบอลต์ เวลาร่าย ฮีล บัฟ และ SP ที่จ่าย ส่วนแถบทางลัดและคำอธิบายสกิลจะแสดงระดับที่ใช้จริง"],en:{title:"You can now pick a skill's cast rank to save SP",lines:["A skill's SP cost rises with its rank. You can now cast it at a lower rank than you've learned — for example, learn Lv.10 but cast at Lv.5, and you pay SP and deal damage as if it were rank 5.",`Set it in the Skill window, in the "Cast at Lv." field next to the use button — press − / + to pick anywhere from rank 1 up to the rank you've learned, and the choice is remembered from then on.`,"The rank you cast at affects damage, the bolt's hit count, cast time, healing, buff strength and the SP cost. The hotkey bar and skill description both show the rank actually being used."]}},{id:"2026-09-22-aura-perf",date:"2026-09-22",time:"15:41",title:"ลดอาการหน่วงตอนเจอผู้เล่น Lv.99 หลายคน",lines:["ออร่าทองของผู้เล่น Lv.99 เบาลงครึ่งหนึ่ง และในจอจะวาดออร่าของคนอื่นพร้อมกันมากสุด 2 คน (จากเดิม 4) โดยเลือกคนที่อยู่ใกล้ที่สุด","คู่ดวล คู่เทรด และผู้เล่นที่เลือกอยู่ ยังเห็นออร่าเต็มเสมอ และออร่าของตัวเองไม่หายไปไหน",'ถ้ายังหน่วงในเมืองที่คนเยอะ ตั้งค่า "ผู้เล่นคนอื่น" เป็น "ซ่อนชื่อและเอฟเฟกต์" จะช่วยได้อีก'],en:{title:"Reduced lag around several Lv.99 players",lines:["The gold aura for Lv.99 players is now half as heavy to render, and the screen draws at most 2 other players' auras at once (down from 4), picking whoever is closest.","Your duel opponent, trade partner and currently selected player always still show their full aura, and your own aura never disappears.",'If a crowded town still lags, setting "Other Players" to "Hide names and effects" will help further.']}},{id:"2026-09-22-bag-bigger",date:"2026-09-22",time:"15:36",title:"หน้าต่างกระเป๋าใหญ่ขึ้น 20%",lines:["หน้าต่างกระเป๋าถูกขยายขึ้นอีก 20% ตัวหนังสือ ไอคอนของ และช่องไอเทมอ่านง่ายขึ้น โดยเฉพาะบนจอใหญ่","ถ้าจอเล็กจนกระเป๋าล้นขอบ ระบบยังย่อให้พอดีจออัตโนมัติเหมือนเดิม"],en:{title:"The Inventory window is 20% bigger",lines:["The Inventory window has been enlarged by another 20%, making text, item icons and slots easier to read, especially on a big screen.","If the screen is small enough that it would overflow, the system still auto-shrinks it to fit, as before."]}},{id:"2026-09-22-window-open-pop",date:"2026-09-22",time:"15:20",title:"หน้าต่างไม่เด้งใหญ่ตอนเปิดและตอนลากแล้ว",lines:["เปิดกระเป๋าหรือหน้าต่างอื่น ๆ จะขึ้นมาขนาดปกติทันที ไม่แวบใหญ่เกินจริงแล้วค่อยหดลงเหมือนเดิม","ลากหน้าต่างไปวางแล้วปล่อยเมาส์ ก็ไม่เด้งใหญ่ตอนปล่อยอีกต่อไป"],en:{title:"Windows no longer pop oversized on open or after dragging",lines:["Opening the inventory or any other window now appears at its normal size right away, instead of briefly flashing oversized and then shrinking down as before.","Dragging a window and releasing the mouse no longer makes it pop oversized on release either."]}},{id:"2026-09-22-glacier-sight-range",date:"2026-09-22",time:"15:20",title:"ลดระยะสายตามอนดุร้ายในธารน้ำแข็ง",lines:["มอนสเตอร์ดุร้ายใน Frostfang Glacier เคยเห็นเราไกลถึงประมาณ 320 พิกเซล ตอนนี้ลดเหลือประมาณ 100 พิกเซล ต้องเดินเข้าไปใกล้จริง ๆ มันถึงจะวิ่งเข้าใส่","เดินเลี่ยงผ่านเป็นทางได้ง่ายขึ้นมาก ไม่โดนทั้งฝูงรุมตั้งแต่ยังไม่ทันเข้าใกล้"],en:{title:"Reduced the aggressive monsters' sight range in the glacier",lines:["Aggressive monsters in Frostfang Glacier used to spot you from about 320 pixels away; that's now down to about 100 pixels, so you need to actually walk in close before they charge you.","It's now much easier to walk around them, instead of the whole pack swarming you before you're even close."]}},{id:"2026-09-22-glacier-aggressive-monsters",date:"2026-09-22",time:"15:03",title:"Frostfang Glacier: มอนสเตอร์ดุร้าย เดินเข้าใส่เอง",lines:["มอนสเตอร์ในธารน้ำแข็ง Frostfang Glacier เปลี่ยนเป็นโหมดดุร้ายแล้ว เดินเข้าระยะประมาณ 320 พิกเซลเมื่อไหร่ มันจะวิ่งเข้าโจมตีเองทันที ไม่ต้องรอให้เราตีก่อน","มันจะเล็งผู้เล่นที่ใกล้ที่สุด และยังเลิกไล่เมื่อเราวิ่งหนีจนห่างเกินระยะเดิม ส่วนสกิลซ่อนตัวยังหลบสายตามันได้อยู่","แมพอื่นทุกแมพยังเหมือนเดิม มอนจะโกรธก็ต่อเมื่อโดนโจมตีเท่านั้น"],en:{title:"Frostfang Glacier: monsters are now aggressive and attack on sight",lines:["Monsters in Frostfang Glacier are now aggressive. Walk within about 320 pixels and one will charge in to attack immediately, without waiting for you to hit it first.","It targets whichever player is closest, and gives up the chase once you run far enough away to clear that same range. Stealth skills can still avoid its sight.","Every other map is unchanged — monsters there still only turn aggressive after being attacked."]}},{id:"2026-09-22-skill-rebalance-2",date:"2026-09-22",time:"14:32",title:"ปรับสมดุลสกิล Cleric, Swordsman และ Mage รอบใหม่",lines:["Cleric · Radiant Light เป็นสกิลรอบตัวระยะ 150 แล้ว ดาเมจ 52% ต่อระดับ (Lv.10 = 520%) ใช้ SP 6 ต่อระดับ คูลดาวน์ 0.5 วิ · มีโอกาสตีต่อเนื่องเป็น 2 ฮิต 57% / 3 ฮิต 37% / 4 ฮิต 27% / 5 ฮิต 17% และโอกาส 25% ทำให้ตาบอด ลด Hit 35% นาน 3 วิ","Cleric · Sacred Ward ให้ DEF และ MDEF +2 ต่อระดับ (Lv.10 = +20) · Fiend Slayer ให้ ATK และ MATK +2% ต่อระดับ (Lv.10 = +20%)","Swordsman · Power Strike โอกาสสตัน 37% นาน 2.5 วิ · Blade Mastery ATK +4% ต่อระดับ (สูงสุด +40%) และตีศัตรูที่ติดสตันหรือไฟไหม้แรงขึ้น 40% เฉพาะกายภาพ · Flame Burst โอกาสเผาไหม้ 37%","Mage · Ember Bolt ใช้ SP 4 ต่อระดับ (Lv.10 = 40) โอกาสเผาไหม้ 7% · Frost Lance เปลี่ยนเป็น Frost Area โจมตีรอบตัวระยะ 150 ดาเมจ 68% ต่อระดับ (Lv.10 = 680%) ใช้ SP 5 ต่อระดับ คูลดาวน์ 1.7 วิ ร่าย 0.42 วิ · โอกาส 50% แช่แข็ง 3 วิ และระหว่างแช่แข็งโดนเวทแรงขึ้น 20%","Mage · Stormbreak ดาเมจ 105% ต่อฮิต ร่าย 0.7 วิ ระยะ 100 ใช้ SP 7 ต่อระดับ (Lv.10 = 70) คูลดาวน์ 1.1 วิ โอกาสสตัน 7% นาน 1.7 วิ","ดูตัวเลขทั้งหมดได้ที่หน้าต่าง Skill (กด K)"],en:{title:"New skill rebalance for Cleric, Swordsman and Mage",lines:["Cleric · Radiant Light is now an area skill with a 150 range, dealing 52% damage per rank (Lv.10 = 520%), costing 6 SP per rank, with a 0.5s cooldown · it has a chance to chain hits — 2 hits 57% / 3 hits 37% / 4 hits 27% / 5 hits 17% — and a 25% chance to blind, lowering Hit by 35% for 3 seconds.","Cleric · Sacred Ward grants DEF and MDEF +2 per rank (Lv.10 = +20) · Fiend Slayer grants ATK and MATK +2% per rank (Lv.10 = +20%).","Swordsman · Power Strike has a 37% stun chance for 2.5 seconds · Blade Mastery gives ATK +4% per rank (up to +40%) and deals 40% more physical damage to stunned or burning enemies · Flame Burst has a 37% burn chance.","Mage · Ember Bolt costs 4 SP per rank (Lv.10 = 40), with a 7% burn chance · Frost Lance is now Frost Area, an area attack with 150 range dealing 68% damage per rank (Lv.10 = 680%), costing 5 SP per rank, with a 1.7s cooldown and a 0.42s cast time · it has a 50% chance to freeze for 3 seconds, and frozen targets take 20% more magic damage.","Mage · Stormbreak deals 105% damage per hit, with a 0.7s cast time, 100 range, costing 7 SP per rank (Lv.10 = 70), a 1.1s cooldown and a 7% stun chance for 1.7 seconds.","See every number in the Skill window (press K)."]}},{id:"2026-09-22-novice-class-guide",date:"2026-09-22",time:"14:29",title:"Novice ถึง Job Lv.10 มีบทสอนเปลี่ยนอาชีพแล้ว",lines:['ครั้งแรกที่ Novice ขึ้น Job Lv.10 จะมีหน้าต่างบอกทันทีว่าเปลี่ยนอาชีพได้แล้ว พร้อมสอนทีละขั้น: กดปุ่ม "อาชีพ" ที่แถบเมนูมุมขวาบน เลือกอาชีพในช่อง TARGET แล้วกดเปลี่ยนอาชีพ','ปุ่ม "อาชีพ" จะกะพริบจนกว่าจะกดเข้าไปดู ปิดหน้าต่างไปก่อนก็ยังหาปุ่มเจอ และหน้าต่างแสดงโบนัสค่าสถานะของทั้ง 6 อาชีพให้เทียบก่อนเลือก','ข้อความในแชทและคำใบ้เควส "สู่อาชีพที่แท้จริง" แก้ให้ชี้ไปที่ปุ่ม อาชีพ แทนหน้าต่าง Status ที่ไม่มีปุ่มเปลี่ยนอาชีพ'],en:{title:"Novices reaching Job Lv.10 now get a class-change tutorial",lines:['The first time a Novice reaches Job Lv.10, a window immediately tells them a class change is available, walking through it step by step: press the "Class" button in the top-right menu bar, pick a class in the TARGET slot, then press Change Class.','The "Class" button flashes until you open it, so you can still find it even after closing the window; the window also shows the stat bonuses of all 6 classes to compare before choosing.','The chat message and the quest hint "Toward Your True Class" now point to the Class button, instead of the Status window, which has no class-change button.']}},{id:"2026-09-22-channel-follows",date:"2026-09-22",time:"14:23",title:"ย้ายช่อง (CH) แล้วอยู่ช่องนั้นทุกแผนที่",lines:["เมื่อกดป้าย CH ย้ายช่องแล้ว ช่องที่เลือกจะติดตัวไปทุกแผนที่ เดินผ่านประตูไปแผนที่ไหนก็ยังอยู่ช่องเดิม ไม่ถูกดีดกลับไปช่อง 1 อีก","แผนที่ที่ยังไม่มีช่องนั้น ระบบจะเปิดช่องให้ทันทีเมื่อเดินไปถึง ส่วนคนที่ไม่ได้กดเลือกช่องเอง ระบบยังจัดช่องให้ตามความหนาแน่นเหมือนเดิม","ช่องที่เลือกไว้จะจำจนกว่าจะออกจากเกม ถ้าย้ายภูมิภาคจะเริ่มใหม่ที่ช่อง 1 ของภูมิภาคนั้น · บอสประจำแผนที่ยังเกิดที่ช่อง 1 เท่านั้น"],en:{title:"Switching channels (CH) now keeps you on that channel across every map",lines:["Once you switch channels using the CH tag, your chosen channel follows you to every map — walk through any portal and you'll stay on that same channel, no longer bounced back to channel 1.","If a map doesn't have that channel yet, the system opens it the moment you arrive. Anyone who hasn't chosen a channel is still assigned one based on crowd density as before.","Your chosen channel is remembered until you log out; switching region resets you to channel 1 of that region · a map's boss still only spawns on channel 1."]}},{id:"2026-09-22-crowd-frame-relief",date:"2026-09-22",time:"14:15",title:"ลื่นขึ้นตอนคนเยอะในเมือง",lines:["ผู้เล่นที่อยู่นอกจอไม่ถูกวาดและคำนวณทุกเฟรมอีกต่อไป — บนมือถือจอเห็นแค่ส่วนหนึ่งของคนรอบตัว จึงเบาลงมาก","ออร่าเลเวล 99 แสดงเฉพาะ 4 คนที่ใกล้คุณที่สุด (คู่ดวล คู่เทรด และคนที่เลือกอยู่แสดงเสมอ) เพราะออร่าแต่ละอันคือแสง 26 ชิ้นที่วาดใหม่ทุกเฟรม",'ถ้ายังหนัก ตั้งค่า "ผู้เล่นคนอื่น" ในหน้าตั้งค่าเป็น "ซ่อนชื่อและเอฟเฟกต์" ได้เหมือนเดิม'],en:{title:"Smoother in a crowded town",lines:["Players outside your view are no longer drawn and computed every frame — on mobile, where the screen only shows a fraction of the people around you, this is a big saving.","Level 99 auras now only render for the 4 closest players to you (your duel opponent, trade partner and selected player always still show), since each aura is 26 pieces of light redrawn every frame.",`If it's still heavy, you can still set "Other Players" in the settings to "Hide names and effects" as before.`]}},{id:"2026-09-22-party-level-gap",date:"2026-09-22",time:"14:10",title:"โบนัสปาร์ตี้นับเฉพาะคนที่เลเวลใกล้กัน",lines:["EXP/Drop +2% ต่อสมาชิกในแผนที่เดียวกัน นับเฉพาะคนที่เลเวลห่างจากคุณไม่เกิน 10 — แต่ละคนนับจากเลเวลตัวเอง","พาตัวเลเวลต่ำมายืนเฉย ๆ ในแผนที่ไม่ได้โบนัสอีกต่อไป ต้องล่าร่วมกับคนที่เลเวลใกล้เคียงกันจริง ๆ","หน้าต่างปาร์ตี้และ Wiki แสดงกติกาใหม่นี้แล้ว"],en:{title:"The party bonus now only counts members close in level",lines:["EXP/Drop +2% per member on the same map now only counts members whose level is within 10 of yours — each person counts it from their own level.","Bringing a low-level character to just stand on the map no longer grants a bonus — you actually need to hunt with people close to your own level.","The party window and Wiki now both show this new rule."]}},{id:"2026-09-22-caster-no-luk",date:"2026-09-22",time:"14:01",title:"คทาเลิกสุ่มติด LUK และ HIT แล้ว",lines:["Rod, Staff และแหวนเวท (แหวนขวา) สุ่มออฟจาก INT / DEX / VIT / AGI ไม่ติด LUK ที่เพิ่มแค่คริซึ่งสายเวทไม่ได้ใช้อีกแล้ว","ของสายเวทไม่ติด HIT อีกต่อไป เพราะเวทไม่มีพลาดอยู่แล้ว ส่วน FLEE ยังติดเหมือนเดิม","ของที่ดรอปก่อนหน้านี้ยังเป็นค่าเดิม มีผลกับของที่ดรอปใหม่ตั้งแต่นี้ไป"],en:{title:"Casting weapons no longer roll LUK or HIT",lines:["Rod, Staff and magic rings (the right-hand ring) now roll their bonus stat from INT / DEX / VIT / AGI, no longer LUK, which only adds crit — something casters no longer use.","Casting gear also no longer rolls HIT, since magic can never miss anyway; FLEE still can, as before.","Items that already dropped keep their existing rolls; this only affects items dropping from now on."]}},{id:"2026-09-22-arrows-removed",date:"2026-09-22",time:"13:48",title:"นักธนูไม่ต้องใช้ลูกธนูอีกต่อไป",lines:["ลูกธนูเหล็กถูกถอดออกจากเกมแล้ว — ยิงธนูและใช้สกิลนักธนูได้ไม่จำกัด ไม่ต้องพกและไม่ต้องซื้อเพิ่มอีก","ลูกธนูที่ค้างอยู่ในกระเป๋า คลัง หรือตั้งขายในตลาด คืนเป็นเงินให้ลูกละ 1 silver อัตโนมัติตอนเข้าเกม","พ่อค้าเลิกขายลูกธนู และมอนสเตอร์เลิกดรอปกองลูกธนูแล้ว"],en:{title:"Archers no longer need arrows",lines:["Iron Arrows have been removed from the game — you can now shoot your bow and use Archer skills without limit, with nothing to carry or buy anymore.","Any arrows left in your inventory, storage, or listed on the Market are automatically refunded for 1 Silver each the next time you log in.","Merchants no longer sell arrows, and monsters no longer drop stacks of them."]}},{id:"2026-09-22-patch-notes",date:"2026-09-22",time:"13:22",title:"บอกทุกครั้งว่าอัปเดตอะไร",lines:["ตอนมีอัปเดตใหม่ ป้ายด้านบนจะบอกหัวข้อที่เปลี่ยนก่อนกดโหลดใหม่ ไม่ต้องเดาว่าอัปเดตอะไรอีกแล้ว","หลังโหลดใหม่ รายละเอียดของอัปเดตจะขึ้นในแชทระบบให้อ่านย้อนได้ และจะขึ้นครั้งเดียวต่ออัปเดตหนึ่งครั้ง"],en:{title:"Every update now tells you what changed",lines:["When a new update is out, a banner at the top now lists what changed before you reload — no more guessing what got updated.","After reloading, the update's details appear in system chat where you can scroll back to read them, showing up exactly once per update."]}}],p=()=>i[0]??null,h=(t,e)=>!e&&t.en?t.en:t;function c(t){if(!t)return i.slice(0,1);const e=i.findIndex(a=>a.id===t);return e<0?i.slice(0,1):i.slice(0,e)}const l="pixelrpg.changelog-seen",s="pixelrpg.changelog-read",m=3;function w(t){let e=null;try{e=localStorage.getItem(l)}catch{}const a=c(e);if(!a.length)return;const o=d()==="th";for(const n of a.slice(0,m).reverse())t(`📢 ${n.date}${n.time?" "+n.time:""} · ${h(n,o).title}`);t("📢 อ่านรายละเอียดและแพตช์โน้ตย้อนหลังทั้งหมดได้ที่หน้า /changelog/");try{localStorage.setItem(l,a[0].id)}catch{}}function u(){try{i[0]&&localStorage.setItem(s,i[0].id)}catch{}}function y(){const t=document.getElementById("changelog-cta");if(!t||document.getElementById("changelog-badge"))return;const e=document.createElement("i");e.id="changelog-badge",e.setAttribute("data-no-translate",""),e.setAttribute("aria-hidden","true"),t.append(e);const a=()=>{let o=null;try{o=localStorage.getItem(s)}catch{o=i[0]?.id??null}const n=!!i[0]&&o!==i[0].id;e.hidden=!n;const r=n?"ใหม่":"";e.textContent!==r&&(e.textContent=r),t.title=n?"มีแพตช์ใหม่! กดอ่านบันทึกการอัปเดต":"บันทึกการอัปเดต"};t.addEventListener("click",()=>{u(),a()}),addEventListener("storage",o=>{o.key===s&&a()}),addEventListener("focus",a),a()}export{i as C,y as a,w as b,h as c,p as l,u as m};
